local _1lua_logpath = "/storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Logs/skins.log"
local function _1lua_wlog(m)
    pcall(function()
        local f = io.open(_1lua_logpath, "a")
        if f then
            local ts = ""
            pcall(function() ts = tostring(os.date("%Y-%m-%d %H:%M:%S")) .. " " end)
            f:write(ts .. tostring(m) .. "\n")
            f:close()
        end
    end)
end
