local function _masterNameToString(name)
    if name == nil then return "" end
    if type(name) == "string" then return name end
    if type(name) == "userdata" then
        local s = nil
        pcall(function() if name.ToString then s = name:ToString() end end)
        if s and type(s) == "string" then return s end
        pcall(function() if name.ToWString then s = name:ToWString() end end)
        if s and type(s) == "string" then return s end
    end
    if type(name) == "table" and name.SourceString then return name.SourceString end
    return tostring(name)
end

local _MASTER_WEAPON_CLASS_SUFFIXES = {
    { keywords = { "kar98", "awm", "m24", "amr", "mosin", "win94", "mk14" }, suffixes = { "(Snipers)", "(Sniper Rifles)" } },
    { keywords = { "m249", "mg3", "dp-28", "dp28" }, suffixes = { "(Machine Guns)" } },
    { keywords = { "ump", "p90", "vector", "bizon", "uzi", "thompson", "mp5", "mp5k", "tommy" }, suffixes = { "(SMG)", "(SMG, Pistols)", "(Rifles, SMG)" } },
    { keywords = { "p1911", "p92", "p18c", "deagle", "r1895", "r45", "skorpion", "g18" }, suffixes = { "(Pistols)", "(SMG, Pistols)" } },
    { keywords = { "akm", "m762", "scar", "famas", "m16a4", "aug", "groza", "qbz", "m416", "mk47", "g36c", "ace32", "k2", "m4" }, suffixes = { "(AR)", "(Rifles, SMG)" } },
}
local function _masterClassSuffixesFromSkinName(skinName)
    if type(skinName) ~= "string" or skinName == "" then return {} end
    local low = string.lower(skinName)
    for _, entry in ipairs(_MASTER_WEAPON_CLASS_SUFFIXES) do
        for _, kw in ipairs(entry.keywords) do
            if string.find(low, kw, 1, true) then return entry.suffixes end
        end
    end
    return {}
end

_G.BuildMasterAttachmentMaps = function(force)
    if _G._MasterAttachMaps and not force then
        if next(_G._MasterAttachMaps.skinAttachments) then return _G._MasterAttachMaps end
        if _G._MasterAttachMapsBuilt and not force then return _G._MasterAttachMaps end
    end
    _G._MasterAttachMaps = { skinAttachments = {}, skinBases = {}, attachToSkin = {}, skinToBaseWeapon = {} }
    _G._MasterAttachDebug = {}
    if not CDataTable then _G._MasterAttachDebug.error = "CDataTable not available" _G._MasterAttachMapsBuilt = true return _G._MasterAttachMaps end
    local function safeGetTable(name)
        if CDataTable.GetTable then local ok, tbl = pcall(CDataTable.GetTable, name) if ok and tbl then return tbl end end
        if CDataTable.GetTableByFilter then local ok, tbl = pcall(CDataTable.GetTableByFilter, name, nil, nil) if ok and tbl then return tbl end end
        return nil
    end
    local function safeGetTableData(name, id)
        if CDataTable.GetTableData then local ok, row = pcall(CDataTable.GetTableData, name, id) if ok then return row end end
        return nil
    end
    local groupToParts = {}
    pcall(function()
        local unlockTbl = safeGetTable("ItemUpgradeUnLockConfig")
        if not unlockTbl then _G._MasterAttachDebug.unlockTable = "nil" return end
        local count = 0
        for _, row in pairs(unlockTbl) do
            local gid = tonumber(row.GroupID) local part = tonumber(row.PartId or row.PartID)
            if gid and part then if not groupToParts[gid] then groupToParts[gid] = {} end groupToParts[gid][#groupToParts[gid]+1] = part count = count + 1 end
        end
        _G._MasterAttachDebug.unlockRows = count
    end)
    local skinToGroup = {}
    pcall(function()
        local upTbl = safeGetTable("ItemUpgradeConfig")
        if not upTbl then _G._MasterAttachDebug.upgradeTable = "nil" return end
        local count = 0
        for _, row in pairs(upTbl) do
            local gid = tonumber(row.GroupID) local itm = tonumber(row.ItemID)
            if gid and itm and itm >= 1000000000 then
                skinToGroup[itm] = gid
                local baseWeaponID = math.floor(itm / 1000) % 1000000
                if baseWeaponID >= 100000 and baseWeaponID <= 999999 then _G._MasterAttachMaps.skinToBaseWeapon[itm] = baseWeaponID end
                count = count + 1
            end
        end
        _G._MasterAttachDebug.upgradeRows = count
    end)
    local baseNameToIds = {}
    pcall(function()
        local itemTbl = safeGetTable("Item")
        if not itemTbl then _G._MasterAttachDebug.itemTable = "nil" return end
        local count = 0
        for k, row in pairs(itemTbl) do
            local id = tonumber(k) or tonumber(row and row.ItemID)
            if id and id >= 1000 and id < 10000000 then
                local nm = row and row.ItemName
                if type(nm) ~= "string" then nm = _masterNameToString(nm) end
                if type(nm) == "string" and nm ~= "" then
                    if not baseNameToIds[nm] then baseNameToIds[nm] = {} end
                    baseNameToIds[nm][#baseNameToIds[nm]+1] = id count = count + 1
                end
            end
        end
        _G._MasterAttachDebug.itemRows = count
    end)
    local resolvedCount = 0
    for weaponSkinId, gid in pairs(skinToGroup) do
        local parts = groupToParts[gid]
        if parts and #parts > 0 then
            local bases = {}
            local wc = safeGetTableData("Item", weaponSkinId)
            local weaponSkinName = ""
            if wc then local nm = wc.ItemName if type(nm) ~= "string" then nm = _masterNameToString(nm) end weaponSkinName = nm or "" end
            local suffixes = _masterClassSuffixesFromSkinName(weaponSkinName)
            for _, partId in ipairs(parts) do
                local baseId = 0
                local partRow = safeGetTableData("Item", partId)
                if partRow then
                    local nm = partRow.ItemName
                    if type(nm) ~= "string" then nm = _masterNameToString(nm) end
                    if type(nm) == "string" and nm ~= "" then
                        local list = baseNameToIds[nm]
                        if type(list) == "table" and #list >= 1 then baseId = list[1] for _, v in ipairs(list) do if v < baseId then baseId = v end end end
                        if baseId == 0 then
                            for _, suf in ipairs(suffixes) do
                                local trial = nm .. " " .. suf local lst = baseNameToIds[trial]
                                if type(lst) == "table" and #lst >= 1 then baseId = lst[1] for _, v in ipairs(lst) do if v < baseId then baseId = v end end break end
                            end
                        end
                    end
                end
                bases[#bases+1] = baseId
                _G._MasterAttachMaps.attachToSkin[partId] = { weaponSkinId, baseId }
            end
            _G._MasterAttachMaps.skinAttachments[weaponSkinId] = parts
            _G._MasterAttachMaps.skinBases[weaponSkinId] = bases
            resolvedCount = resolvedCount + 1
        end
    end
    _G._MasterAttachDebug.resolvedSkins = resolvedCount
    _G._MasterAttachDebug.totalAttachEntries = 0
    for _ in pairs(_G._MasterAttachMaps.attachToSkin) do _G._MasterAttachDebug.totalAttachEntries = _G._MasterAttachDebug.totalAttachEntries + 1 end
    _G._MasterAttachMapsBuilt = true
    return _G._MasterAttachMaps
end

_G.ApplyMasterAttachmentSkins = function(AttachmentArray, selectedSkinID)
    if not AttachmentArray or not slua.isValid(AttachmentArray) then return false end
    selectedSkinID = tonumber(selectedSkinID) or 0
    if selectedSkinID == 0 then return false end
    local maps = _G.BuildMasterAttachmentMaps()
    local attachments = maps.skinAttachments[selectedSkinID]
    local bases = maps.skinBases[selectedSkinID]
    local numSlots = 0
    pcall(function() numSlots = AttachmentArray:Num() end)
    if numSlots <= 0 then return false end
    local changed = false
    -- P23-OLD parity: NEVER touch master skin slot 7, only attachment slots
    local MASTER = 7
    if not attachments or #attachments == 0 then
        for slotIdx = 0, numSlots - 1 do
            if slotIdx ~= MASTER then
                local slotData = AttachmentArray:Get(slotIdx)
                if slotData then
                    local curID = 0
                    pcall(function() curID = slua.IndexReference(slotData, "defineID").TypeSpecificID or 0 end)
                    curID = tonumber(curID) or 0
                    if curID > 0 then
                        local rIt = maps.attachToSkin[curID]
                        if rIt then
                            local baseId = rIt[2]
                            if baseId ~= 0 and baseId ~= curID then
                                pcall(function()
                                    local defRef = slua.IndexReference(slotData, "defineID")
                                    defRef.TypeSpecificID = baseId
                                    slotData.operationType = 0
                                    AttachmentArray:Set(slotIdx, slotData)
                                end)
                                changed = true
                            end
                        end
                    end
                end
            end
        end
        return changed
    end
    local validSkinIds = {}
    for _, id in ipairs(attachments) do validSkinIds[tonumber(id) or 0] = true end
    for slotIdx = 0, numSlots - 1 do
        if slotIdx ~= MASTER then
            local slotData = AttachmentArray:Get(slotIdx)
            if slotData then
                local curID = 0
                pcall(function() curID = slua.IndexReference(slotData, "defineID").TypeSpecificID or 0 end)
                curID = tonumber(curID) or 0
                if curID > 0 then
                    if validSkinIds[curID] then
                    else
                        local baseId = 0
                        local rIt = maps.attachToSkin[curID]
                        if rIt then baseId = rIt[2]
                        elseif curID < 10000000 then baseId = curID
                        else baseId = 0 end
                        if baseId ~= 0 then
                            local srcIdx = 0
                            for k, b in ipairs(bases) do
                                if b ~= 0 and b == baseId then
                                    local candidate = tonumber(attachments[k]) or 0
                                    if candidate ~= 0 and candidate ~= curID then srcIdx = k break end
                                end
                            end
                            if srcIdx > 0 and srcIdx <= #attachments then
                                local newID = tonumber(attachments[srcIdx]) or 0
                                if newID ~= 0 and newID ~= curID then
                                    pcall(function()
                                        local defRef = slua.IndexReference(slotData, "defineID")
                                        defRef.TypeSpecificID = newID
                                        slotData.operationType = 0
                                        AttachmentArray:Set(slotIdx, slotData)
                                    end)
                                    changed = true
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    return changed
end

