-- Balo/nón sảnh: key BackpackMapping là *000xxx (không phải SkinItemIDLv1 *001xxx)
function F.equipToLobbyMappingID(resID)
    resID = tonumber(resID) or 0
    -- Balo: 1501001xxx → 1501000xxx
    if resID >= 1501001000 and resID < 1501002000 then
        return resID - 1000
    end
    -- Nón: 1502001xxx → 1502000xxx
    if resID >= 1502001000 and resID < 1502002000 then
        return resID - 1000
    end
    return resID
end
