function F.cfg(resID)
    if not resID or not CDataTable or not CDataTable.GetTableData then return nil end
    return CDataTable.GetTableData("Item", resID)
end

function F.subType(c)
    return c and (c.ItemSubType or c.itemSubType) or nil
end

function F.wardrobeTab(resID)
    local c = F.cfg(resID)
    return c and tonumber(c.WardrobeTab) or 0
end

function F.depotResID(v)
    return v and tonumber(v.resID or v.res_id) or nil
end

function F.resToCustSlot(resID, st)
    resID, st = tonumber(resID), tonumber(st)
    if not resID or resID <= 0 then return nil end
    st = st or F.subType(F.cfg(resID))
    if st == HAT_SUB or HAT_SUBS[st] then return F.CUST_SLOT.HatEquipemtSlot end
    if st == OUTFIT_SUB then return F.CUST_SLOT.ClothesEquipemtSlot end
    if st == PANTS_SUB then return F.CUST_SLOT.PantsEquipemtSlot end
    if st == SHOES_SUB then return F.CUST_SLOT.ShoesEquipemtSlot end
    if st == MASK_SUB then return F.CUST_SLOT.FaceEquipemtSlot end
    if st == GLASS_SUB then return F.CUST_SLOT.GlassEquipemtSlot end
    if st == GLOVES_SUB then return F.CUST_SLOT.HandEffectEquipemtSlot end
    if BAG_SUBS[st] then return F.CUST_SLOT.BackpackEquipemtSlot end
    if HELMET_SUBS[st] then return F.CUST_SLOT.HelmetEquipemtSlot end
    if F.isParachuteRes(resID) or st == PARACHUTE_SUB then return F.CUST_SLOT.ParachuteEquipemtSlot end
    if F.isGlideRes(resID) or GLIDER_SUBS[st] then return F.CUST_SLOT.GlideEquipemtSlot end
    return nil
end

function F.isSuitRes(resID)
    if F.subType(F.cfg(resID)) ~= OUTFIT_SUB then return false end
    return F.wardrobeTab(resID) ~= TAB_CLOTHES
end

function F.isTshirtRes(resID)
    return F.subType(F.cfg(resID)) == OUTFIT_SUB and F.wardrobeTab(resID) == TAB_CLOTHES
end

function F.weaponIdFromSkin(resID)
    local m = CDataTable and CDataTable.GetTableData and CDataTable.GetTableData("WeaponSkinMapping", resID)
    if not m then return nil end
    return m.WeaponID or m.WeaponId
end

function F.isValidWeaponId(weaponID)
    weaponID = tonumber(weaponID)
    if not weaponID or weaponID <= 0 then return false end
    if weaponID == MELEE_ID then return true end
    -- Per-melee base IDs: dao/chảo/dao quân đội each have their own 108xxx
    if weaponID >= 108000 and weaponID < 109000 then return true end
    return weaponID >= 101000 and weaponID < 108000
end

function F.isValidWeaponPersistEntry(weaponID, resID)
    weaponID, resID = tonumber(weaponID), tonumber(resID)
    if not F.isValidWeaponId(weaponID) or not resID or resID <= 0 then return false end
    if weaponID == resID then return false end
    if resID >= 1800000 and resID < 1810000 then return false end
    if resID >= 1900000 and resID < 2000000 then return false end
    -- Legacy single-key 108: migrate via sanitize; still accept subtype check
    if weaponID == MELEE_ID then
        return F.subType(F.cfg(resID)) == MELEE_ID
    end
    local wid = tonumber(F.weaponIdFromSkin(resID))
    return wid and wid == weaponID
end

function F.sanitizeConfigWeapons(wmap)
    if type(wmap) ~= "table" then return {} end
    local clean = {}
    for wid, res in pairs(wmap) do
        wid, res = tonumber(wid), tonumber(res)
        -- Migrate legacy MELEE_ID=108 → actual WeaponSkinMapping WeaponID
        if wid == MELEE_ID and res and F.subType(F.cfg(res)) == MELEE_ID then
            local mapped = tonumber(F.weaponIdFromSkin(res))
            if mapped and mapped > 0 then
                clean[mapped] = res
            end
        elseif F.isValidWeaponPersistEntry(wid, res) then
            clean[wid] = res
        end
    end
    return clean
end

function F.indexWeaponSkin(resID, insID)
    resID, insID = tonumber(resID), tonumber(insID)
    if not resID or not insID then return end
    local c = F.cfg(resID)
    local st = F.subType(c)
    if not (GUN_SUB[st] or st == MELEE_ID or GRENADE_SUB[st]) then return end
    if GRENADE_SUB[st] then
        local base = GRENADE_BASE_BY_SUB[st]
        if base then
            R.byWeapon[base] = R.byWeapon[base] or {}
            R.byWeapon[base][resID] = insID
        end
        return
    end
    local wid = F.weaponIdFromSkin(resID)
    wid = tonumber(wid)
    if not wid or wid <= 0 then return end
    R.byWeapon[wid] = R.byWeapon[wid] or {}
    R.byWeapon[wid][resID] = insID
end

function F.isInjectedIns(ins)
    return ins and R.insToRes[tonumber(ins)] ~= nil
end

function F.isInjectedRes(res)
    return res and R.resToIns[tonumber(res)] ~= nil
end

function F.isWeaponSkinRes(resID)
    resID = tonumber(resID)
    if not resID then return false end
    local st = F.subType(F.cfg(resID))
    return GUN_SUB[st] or st == MELEE_ID or GRENADE_SUB[st]
end

function F.isGrenadeSkinRes(resID)
    resID = tonumber(resID)
    if not resID then return false end
    return GRENADE_SUB[F.subType(F.cfg(resID))] == true
end

function F.grenadeBaseFromSkin(resID)
    resID = tonumber(resID)
    if not resID then return nil end
    local st = F.subType(F.cfg(resID))
    return st and GRENADE_BASE_BY_SUB[st] or nil
end

function F.saveGrenadeToCache(baseID, resID, insID)
    baseID, resID, insID = tonumber(baseID), tonumber(resID), tonumber(insID)
    if not baseID or not GRENADE_FIELD_BY_BASE[baseID] then return end
    if not resID or resID <= 0 then return end
    if not F.isGrenadeSkinRes(resID) then return end
    if F.grenadeBaseFromSkin(resID) ~= baseID then return end
    local cch = F.cache()
    cch.grenades = cch.grenades or {}
    cch.grenades[baseID] = { resID = resID, insID = insID or 0 }
    PERSIST.configGrenades = PERSIST.configGrenades or {}
    PERSIST.configGrenades[baseID] = resID
    MATCH_CONFIG.grenadeSkins = MATCH_CONFIG.grenadeSkins or {}
    MATCH_CONFIG.grenadeSkins[baseID] = resID
    _matchApplied = false
    F.perfInvalidateLobby()
    F.persistMarkDirty()
end

function F.getCachedGrenadeSkin(baseID)
    baseID = tonumber(baseID) or 0
    local cch = F.cache()
    local w = cch.grenades and cch.grenades[baseID]
    if w and tonumber(w.resID) and tonumber(w.resID) > 0 then return tonumber(w.resID) end
    local p = PERSIST.configGrenades and tonumber(PERSIST.configGrenades[baseID])
    if p and p > 0 then return p end
    local m = MATCH_CONFIG.grenadeSkins and tonumber(MATCH_CONFIG.grenadeSkins[baseID])
    if m and m > 0 then return m end
    return nil
end

function F.applyInitialConsumableAvatar()
    -- P23-FIX Task6 (old applyMatchThrowObjects + TRAIL setupPlayerGrenadeSkin logic):
    -- lobby cache (grenadeSkins base->skin) ko live PC par likho taaki lobby+inGame dono me show ho.
    -- Pehle stub tha isliye inGame me default grenade dikhta tha.
    pcall(function()
        local cch = F.cache()
        local pc = F.getPC()
        if not pc or not slua.isValid(pc) then return end
        local gs = cch and cch.grenadeSkins
        if not gs then return end
        -- grenadeSkins: base ItemID 60200x -> skin res (old cch.throwObjects sub 612/613/614/615)
        local map = { [602004] = "GrenadeAvatarShoulei", [602002] = "GrenadeAvatarSmoke", [602001] = "GrenadeAvatarStun", [602003] = "GrenadeAvatarBurn" }
        if slua.isValid(pc.InitialConsumableAvatar) then
            for base, field in pairs(map) do
                local sk = gs[base]
                if type(sk) == "table" then sk = sk.resID or sk.res end
                sk = tonumber(sk) or 0
                if sk > 0 then pcall(function() pc.InitialConsumableAvatar[field] = sk end) end
            end
        end
        -- grenade avatar list me injected skins add karo (old InitGrenadeAvatarList logic)
        pcall(function()
            if pc.InitGrenadeAvatarList and pc.AddToGrenadeAvatarItemList then
                for base, field in pairs(map) do
                    local sk = gs[base]
                    if type(sk) == "table" then sk = sk.resID or sk.res end
                    sk = tonumber(sk) or 0
                    if sk > 0 then pcall(function() pc:AddToGrenadeAvatarItemList(sk) end) end
                end
            end
        end)
    end)
    return true
end

-- class() forbid __newindex → chỉ patch __inner_impl; clear cache trên class table nếu có
local function F_patchGrenadeImpl(mod, key, wrapFn, flagKey)
    if not mod then return false end
    local impl = mod.__inner_impl or mod
    if type(impl) ~= "table" then return false end
    flagKey = flagKey or ("_KuttaCheatTG_" .. tostring(key))
    if impl[flagKey] then return true end
    local orig = impl[key]
    if type(orig) ~= "function" then return false end
    impl[flagKey] = true
    impl[key] = wrapFn(orig)
    -- Bỏ method cache trên class object (nếu đã rawset từ lần trước)
    pcall(function()
        if mod.__inner_impl and mod[key] ~= nil then
            rawset(mod, key, nil)
        end
    end)
    return true
end

function F.hookGrenadeAvatarLookup()
    -- Retry từng phần (không one-shot cả block khi EventID còn nil)

    -- GM path: CheckHasOverrideFx đọc GrenadeKillGunBindMap không cần server bind
    pcall(function()
        local AvatarUtil = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarUtil")
        if AvatarUtil then AvatarUtil.GM_GrenadeAvatarTest = true end
    end)

    -- Icon CircleChoose + lookup theo base 60200x (plain table — ok assign)
    pcall(function()
        local ADU = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
        if not ADU or not ADU.TryGetGrenadeAvatarID or ADU._KuttaCheatTGGrenadeHooked then return end
        ADU._KuttaCheatTGGrenadeHooked = true
        local o = ADU.TryGetGrenadeAvatarID
        ADU.TryGetGrenadeAvatarID = function(uPlayerController, ItemID)
            local base = tonumber(ItemID) or 0
            if base > 100000 then base = math.floor(base / 100) end
            if GRENADE_FIELD_BY_BASE[base] then
                local override = F.getCachedGrenadeSkin(base)
                if override and override > 0 then return override end
            end
            return o(uPlayerController, ItemID)
        end
    end)

    pcall(function()
        F.hookArmorInventoryAvatar()
        local ADU = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
        if ADU and not ADU._KuttaCheatTGConsumableApplyHooked then
            ADU._KuttaCheatTGConsumableApplyHooked = true
            if ADU.InitialEquipmentAvatar and not ADU._KuttaCheatTGWrapInitEquipForGrenade then
                ADU._KuttaCheatTGWrapInitEquipForGrenade = true
                local o = ADU.InitialEquipmentAvatar
                ADU.InitialEquipmentAvatar = function(PlayerInfo, uPlayerController)
                    o(PlayerInfo, uPlayerController)
                    pcall(F.applyInitialConsumableAvatar)
                end
            end
        end
    end)
end

function F.resolveGrenadeBaseFromItemId(itemId)
    itemId = tonumber(itemId) or 0
    if itemId <= 0 then return nil end
    if GRENADE_FIELD_BY_BASE[itemId] then return itemId end
    if itemId > 100000 then
        local asProto = math.floor(itemId / 100)
        if GRENADE_FIELD_BY_BASE[asProto] then return asProto end
    end
    local st = nil
    pcall(function() st = F.subType(F.cfg(itemId)) end)
    if st and GRENADE_BASE_BY_SUB[st] then return GRENADE_BASE_BY_SUB[st] end
    return nil
end

function F.resolveGrenadeSkinForProjectile(proj)
    if not proj then return nil end
    local skin = nil
    pcall(function()
        local tid = 0
        if proj.ItemDefineID then tid = tonumber(proj.ItemDefineID.TypeSpecificID) or 0 end
        local base = F.resolveGrenadeBaseFromItemId(tid)
        if base then skin = F.getCachedGrenadeSkin(base) end
        if (not skin or skin <= 0) and type(proj.GetAvatarID) == "function" then
            local pc = proj.GetInstigatorControllerSafety and proj:GetInstigatorControllerSafety()
            local avData = pc and pc.InitialConsumableAvatar
            if avData then
                local aid = tonumber(proj:GetAvatarID(avData)) or 0
                if aid > 0 then skin = aid end
            end
        end
        if (not skin or skin <= 0) and slua.isValid(proj.GrenadeAvatarComponent_BP) then
            local comp = proj.GrenadeAvatarComponent_BP
            if comp.GetCurGrenadeAvatarID then
                local cur = tonumber(comp:GetCurGrenadeAvatarID()) or 0
                if cur > 0 then skin = cur end
            end
        end
        if skin and skin > 0 then
            local b = F.resolveGrenadeBaseFromItemId(skin)
            if b then
                local cached = F.getCachedGrenadeSkin(b)
                if cached and cached > 0 then skin = cached end
            end
        end
    end)
    return skin
end

function F.getGrenadeBindCfg(skin)
    skin = tonumber(skin) or 0
    if skin <= 0 then return nil end
    local cfg = nil
    pcall(function() cfg = CDataTable.GetTableData("GrenadeKillGunBindMap", skin) end)
    if cfg then return cfg end
    pcall(function()
        local tbl = CDataTable.GetTable("GrenadeKillGunBindMap")
        if not tbl then return end
        for _, row in pairs(tbl) do
            if row and tonumber(row.GrenadeID) == skin then
                cfg = row
                break
            end
        end
    end)
    return cfg
end

function F.syncGrenadeExplodeAssetsFromHandle(proj, skin)
    skin = tonumber(skin) or 0
    if skin <= 0 or not proj then return false end
    local synced = false
    pcall(function()
        local comp = proj.GrenadeAvatarComponent_BP or proj.GrenadeAvatarComponent
        if not slua.isValid(comp) then return end
        local handle = nil
        pcall(function()
            if comp.GetItemAvatarHandle then handle = comp:GetItemAvatarHandle(skin) end
        end)
        pcall(function()
            if slua.isValid(handle) then return end
            local UBackpackUtils = import("BackpackUtils")
            local did = UBackpackUtils.GetItemDefineIDByItemID(skin)
            if did then handle = UBackpackUtils.CreateBattleItemHandle(did, comp, false) end
        end)
        if not slua.isValid(handle) then return end
        local UBackpackGrenadeAvatarHandle = import("BackpackGrenadeAvatarHandle")
        pcall(function()
            if Game and Game.IsClassOf and not Game:IsClassOf(handle, UBackpackGrenadeAvatarHandle) then
                handle = nil
            end
        end)
        if not slua.isValid(handle) then return end

        local function putAsset(key, obj)
            if not key or not slua.isValid(obj) then return end
            pcall(function()
                if comp.AssetObjectMap and comp.AssetObjectMap.Add then
                    comp.AssetObjectMap:Add(tostring(key), obj)
                end
            end)
            if key == "ExplodeParticleSystem" or tostring(key):find("Explode", 1, true) then
                proj.ExplodeParticleSystem = obj
            end
            synced = true
        end

        local function loadSoftParticle(entry)
            if not entry then return end
            local key = entry.Key or entry.Name
            local ps = entry.GrenadeParticleSystem
            if slua.isValid(ps) then
                putAsset(key, ps)
                return
            end
            pcall(function()
                local path = nil
                if entry.GrenadeParticleSystem and entry.GrenadeParticleSystem.AssetPathName then
                    path = entry.GrenadeParticleSystem.AssetPathName
                end
                if path and path ~= "" then
                    local UBusinessHelper = import("BusinessHelper")
                    local uAsset = UBusinessHelper.LoadAssetFromPath(path)
                    if slua.isValid(uAsset) then putAsset(key, uAsset) end
                end
            end)
        end

        if handle.GrenadeParticleSystemArray and handle.GrenadeParticleSystemArray.Num then
            for i = 0, handle.GrenadeParticleSystemArray:Num() - 1 do
                loadSoftParticle(handle.GrenadeParticleSystemArray:Get(i))
            end
        end

        local fxIdx = 0
        pcall(function() fxIdx = tonumber(comp.OverrideFXIndex) or tonumber(comp.OverrideFxIndex) or 0 end)
        if fxIdx > 0 and handle.GrenadeSkinFxSystemArray and handle.GrenadeSkinFxSystemArray.Num then
            for i = 0, handle.GrenadeSkinFxSystemArray:Num() - 1 do
                local set = handle.GrenadeSkinFxSystemArray:Get(i)
                if set and tonumber(set.Index) == fxIdx then
                    if set.FxList and set.FxList.Num then
                        for j = 0, set.FxList:Num() - 1 do
                            loadSoftParticle(set.FxList:Get(j))
                        end
                    end
                    pcall(function()
                        local seq = set.ExLevelSequence
                        local path = seq and (seq.AssetPathName or seq)
                        if type(path) == "string" and path ~= "" then
                            comp.ExLevelSeqPath = path
                            local UBusinessHelper = import("BusinessHelper")
                            comp.ExLevelSeqCache = UBusinessHelper.LoadAssetFromPath(path)
                        end
                    end)
                    pcall(function()
                        local seq = set.SkyExLevelSequence
                        local path = seq and (seq.AssetPathName or seq)
                        if type(path) == "string" and path ~= "" then
                            comp.SkyExLevelSeqPath = path
                            local UBusinessHelper = import("BusinessHelper")
                            comp.SkyExLevelSeqCache = UBusinessHelper.LoadAssetFromPath(path)
                        end
                    end)
                end
            end
        end
    end)
    return synced
end

function F.setGrenadeOverrideFxFromTable(comp, skin)
    skin = tonumber(skin) or 0
    if skin <= 0 or not comp or not slua.isValid(comp) then return false end
    local setOk = false
    pcall(function()
        local Cfg = F.getGrenadeBindCfg(skin)
        local FxGunID = 0
        if Cfg and Cfg.UnlockFxGunIDList_a and Cfg.UnlockFxGunIDList_a.Num and Cfg.UnlockFxGunIDList_a:Num() > 0 then
            FxGunID = Cfg.UnlockFxGunIDList_a:Get(0)
        end
        if FxGunID and FxGunID > 0 then
            if comp.SetOverrideFxIndex then comp:SetOverrideFxIndex(FxGunID) end
            if comp.SetOverrideSoundIndex then comp:SetOverrideSoundIndex(FxGunID) end
            pcall(function() if comp.OnRep_OverrideFXIndexChanged then comp:OnRep_OverrideFXIndexChanged() end end)
            pcall(function() if comp.OnRep_OverrideSoundIndexChanged then comp:OnRep_OverrideSoundIndexChanged() end end)
            setOk = true
        end
    end)
    return setOk
end

function F.spawnGrenadeSkinExplodeFx(proj)
    if not Client or not proj or not slua.isValid(proj) then return end
    local skin = F.resolveGrenadeSkinForProjectile(proj)
    if not skin or skin <= 0 then return end
    local loc = nil
    pcall(function() loc = proj:K2_GetActorLocation() end)
    if not loc then return end
    local scale = 1
    pcall(function() scale = (proj.DynamicModifier and proj.DynamicModifier.EffectRange) or 1 end)
    local comp = proj.GrenadeAvatarComponent_BP
    pcall(function()
        if slua.isValid(comp) and comp.UseHighLevelParticle and comp:UseHighLevelParticle() then
            comp:SpawnHighLevelParticleActor(loc)
            return
        end
    end)
    pcall(function()
        if slua.isValid(proj.ExplodeParticleSystem) then
            local UGameplayStatics = import("GameplayStatics")
            UGameplayStatics.SpawnEmitterAtLocation(proj, proj.ExplodeParticleSystem, loc, FRotator(0, 0, 0), FVector(1, 1, 1) * scale, true)
        end
    end)
end

-- Gọi ngay trước nổ: ép avatar + OverrideFx + copy ExplodeParticleSystem từ AssetObjectMap
function F.prepareGrenadeExplodeFx(proj)
    if not F.skinFeat("SkinMatchGrenade") then return end
    if not proj or not slua.isValid(proj) then return end
    F.applyGrenadeSkinToProjectile(proj)
    local skin = F.resolveGrenadeSkinForProjectile(proj)
    if not skin or skin <= 0 then return end
    local comp = proj.GrenadeAvatarComponent_BP or proj.GrenadeAvatarComponent
    if slua.isValid(comp) then
        F.forceGrenadeAvatarComp(comp, skin)
        F.setGrenadeOverrideFxFromTable(comp, skin)
        F.syncGrenadeExplodeAssetsFromHandle(proj, skin)
    end
    pcall(function()
        if type(proj.OnGrenadeFxOverride) == "function" then proj:OnGrenadeFxOverride() end
    end)
    pcall(function()
        if type(proj.ResetGrenadeAvatar) == "function" then proj:ResetGrenadeAvatar() end
    end)
    pcall(function()
        if type(proj.RefreshProjectileSkin) == "function" then proj:RefreshProjectileSkin(false) end
    end)
end

function F.forceGrenadeAvatarComp(av, skin)
    skin = tonumber(skin) or 0
    if skin <= 0 or not av or not slua.isValid(av) then return false end
    local ok = false
    pcall(function()
        if av.PreChangeGrenadeAvatar then
            av:PreChangeGrenadeAvatar(skin)
            ok = true
        end
    end)
    pcall(function()
        if av.ChangeItemAvatar then
            av:ChangeItemAvatar(skin, false)
            ok = true
        end
    end)
    pcall(function()
        if av.ChangeItemAvatar then
            av:ChangeItemAvatar(skin, true)
            ok = true
        end
    end)
    pcall(function()
        if av.SyncChangeItemAvatar then
            av:SyncChangeItemAvatar(skin)
            ok = true
        end
    end)
    pcall(function()
        F.setGrenadeOverrideFxFromTable(av, skin)
    end)
    pcall(function()
        if av.CheckHasOverrideFx then
            local pc = nil
            pcall(function()
                local GameplayData = require("GameLua.GameCore.Data.GameplayData")
                pc = GameplayData.GetPlayerController()
            end)
            if not pc then
                pcall(function()
                    pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                end)
            end
            if pc then av:CheckHasOverrideFx(pc, skin) end
        end
    end)
    return ok
end

function F.applyGrenadeSkinToProjectile(proj, typeSpecificID)
    if not F.skinFeat("SkinMatchGrenade") then return false end
    if not proj then return false end
    local applied = false
    pcall(function()
        if not slua.isValid(proj) then return end
        local tid = tonumber(typeSpecificID) or 0
        if tid <= 0 then
            pcall(function()
                if proj.ItemDefineID then
                    tid = tonumber(proj.ItemDefineID.TypeSpecificID) or 0
                end
            end)
        end
        local base = F.resolveGrenadeBaseFromItemId(tid)
        local skin = base and F.getCachedGrenadeSkin(base) or nil

        if not skin or skin <= 0 then
            pcall(function()
                local pc = proj.GetInstigatorControllerSafety and proj:GetInstigatorControllerSafety()
                local avData = pc and pc.InitialConsumableAvatar
                if type(proj.GetAvatarID) == "function" and avData then
                    local aid = tonumber(proj:GetAvatarID(avData)) or -1
                    if aid > 0 then
                        skin = aid
                        if not base then base = F.resolveGrenadeBaseFromItemId(aid) end
                        if base then
                            local c = F.getCachedGrenadeSkin(base)
                            if c and c > 0 then skin = c end
                        end
                    end
                end
            end)
        end
        -- Fallback theo field InitialConsumableAvatar theo loại (khi tid không resolve)
        if (not skin or skin <= 0) then
            pcall(function()
                local pc = proj.GetInstigatorControllerSafety and proj:GetInstigatorControllerSafety()
                local avData = pc and pc.InitialConsumableAvatar
                if not avData then return end
                for b, field in pairs(GRENADE_FIELD_BY_BASE) do
                    local cached = F.getCachedGrenadeSkin(b)
                    if cached and cached > 0 then
                        pcall(function() avData[field] = cached end)
                    end
                end
                if type(proj.GetAvatarID) == "function" then
                    local aid = tonumber(proj:GetAvatarID(avData)) or -1
                    if aid > 0 then skin = aid end
                end
            end)
        end
        if not skin or skin <= 0 then return end

        local comp = proj.GrenadeAvatarComponent_BP or proj.GrenadeAvatarComponent
        if F.forceGrenadeAvatarComp(comp, skin) then applied = true end
        pcall(function()
            local pc = proj.GetInstigatorControllerSafety and proj:GetInstigatorControllerSafety()
            if pc and type(proj.CheckHasOverrideFxAndSound) == "function" then
                proj:CheckHasOverrideFxAndSound(pc, skin)
            end
        end)
        pcall(function()
            if type(proj.ResetGrenadeAvatar) == "function" then proj:ResetGrenadeAvatar() end
        end)
        pcall(function()
            if type(proj.RefreshProjectileSkin) == "function" then
                proj:RefreshProjectileSkin(false)
            end
        end)
    end)
    return applied
end

function F.matchApplyGrenadeSkin()
    if not F.skinFeat("SkinMatchGrenade") then return true end
    F.hookGrenadeAvatarLookup()
    pcall(F.hookProjectileGrenadeAvatar)
    F.applyInitialConsumableAvatar()
    -- P23-FIX Task6+7: inGame projectile + explosion FX + trail auto (no button, skin ke sath)
    pcall(F.hookP23TrailEffect)
    pcall(function() if _G.GoldenLeavesTrail then _G.GoldenLeavesTrail.Apply() end end)
    pcall(F.hookP23GrenadeFX)
    pcall(function() if _G.GrenadeFX and _G.GrenadeFX.BindMaxWeapon then _G.GrenadeFX.BindMaxWeapon(_G.GrenadeFX.FORCE_WEAPON_ID or 1101005098) end end)
    pcall(F.tickEliminationKingEffect)
    pcall(function()
        local char = F.getLocalChar()
        if not char then return end
        local w = char.GetCurrentWeapon and char:GetCurrentWeapon()
        if w and slua.isValid(w) then
            F.applyGrenadeSkinToHeldWeapon(w)
        end
        -- Quét mọi weapon trên người (đôi khi GetCurrentWeapon chưa là quả đang cầm)
        pcall(function()
            if not char.GetInventoryWeapons then return end
            local list = char:GetInventoryWeapons()
            if not list then return end
            local n = (list.Num and list:Num()) or #list or 0
            for i = 0, n - 1 do
                local ww = list.Get and list:Get(i) or list[i]
                if ww and slua.isValid(ww) then
                    F.applyGrenadeSkinToHeldWeapon(ww)
                end
            end
        end)
    end)
    return true
end

function F.applyGrenadeSkinToHeldWeapon(weapon)
    if not F.skinFeat("SkinMatchGrenade") then return end
    if not weapon or not slua.isValid(weapon) then return end
    pcall(function()
        local resId = 0
        pcall(function()
            if weapon.GetItemDefineID then
                local did = weapon:GetItemDefineID()
                resId = did and tonumber(did.TypeSpecificID) or 0
            end
        end)
        if resId <= 0 then
            pcall(function() resId = tonumber(weapon.ItemID) or tonumber(weapon.TypeSpecificID) or 0 end)
        end
        local base = F.resolveGrenadeBaseFromItemId(resId)
        -- Một số weapon throw gắn skinID trên tay thay vì base
        if not base then
            local st = nil
            pcall(function() st = F.subType(F.cfg(resId)) end)
            if st and GRENADE_BASE_BY_SUB[st] then base = GRENADE_BASE_BY_SUB[st] end
        end
        if not base then
            -- Thử map từ PC GrenadeAvatarItemList theo proto
            pcall(function()
                local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                if not pc then
                    local GameplayData = require("GameLua.GameCore.Data.GameplayData")
                    pc = GameplayData.GetPlayerController()
                end
                if not pc or not pc.GrenadeAvatarItemList then return end
                for b, _ in pairs(GRENADE_FIELD_BY_BASE) do
                    local proto = b * 100
                    local skin = nil
                    pcall(function() skin = pc.GrenadeAvatarItemList:Get(proto) end)
                    if tonumber(skin) and tonumber(skin) > 0 and F.getCachedGrenadeSkin(b) then
                        -- nếu weapon là loại này theo item subtype của mesh hiện tại
                    end
                end
            end)
        end
        if not base then return end
        local skin = F.getCachedGrenadeSkin(base)
        if not skin or skin <= 0 then return end

        local function applyTo(av)
            if F.forceGrenadeAvatarComp(av, skin) then
                pcall(function()
                    if weapon.DelayHandleAvatarMeshChanged then
                        weapon:DelayHandleAvatarMeshChanged()
                    end
                end)
                return true
            end
            return false
        end

        local av = nil
        pcall(function()
            if weapon.GetGrenadeAvatar then av = weapon:GetGrenadeAvatar() end
        end)
        pcall(function()
            if not av then av = weapon.GrenadeAvatarComponent_BP or weapon.GrenadeAvatarComponent end
        end)
        local did = applyTo(av)
        -- Scan components nếu getter miss
        if not did then
            pcall(function()
                if not weapon.GetComponentsByClass then return end
                local UGrenadeAvatarComponent = import("GrenadeAvatarComponent")
                if not UGrenadeAvatarComponent then return end
                local comps = weapon:GetComponentsByClass(UGrenadeAvatarComponent)
                if not comps then return end
                local n = (comps.Num and comps:Num()) or 0
                for i = 0, n - 1 do
                    local c = comps:Get(i)
                    if applyTo(c) then did = true end
                end
            end)
        end

        if did then
            pcall(function()
                local char = F.getLocalChar()
                if not char or not char.AddGameTimer then return end
                for _, d in ipairs({0.05, 0.2, 0.5, 1.0, 2.0}) do
                    char:AddGameTimer(d, false, function()
                        if weapon and slua.isValid(weapon) then
                            local a = nil
                            pcall(function()
                                if weapon.GetGrenadeAvatar then a = weapon:GetGrenadeAvatar() end
                            end)
                            pcall(function()
                                if not a then a = weapon.GrenadeAvatarComponent_BP or weapon.GrenadeAvatarComponent end
                            end)
                            applyTo(a)
                        end
                    end)
                end
            end)
        end
    end)
end

-- Equip skin lựu ở sảnh giống dù: fashionbag + cache + put_on_rsp
function F.putOnGrenade(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
        resID = d and tonumber(d.resID)
    end
    if not resID or not F.isGrenadeSkinRes(resID) then return false end
    local base = F.grenadeBaseFromSkin(resID)
    if not base then return false end
    local st = F.subType(F.cfg(resID))
    if not R.insToRes[insID] then
        R.insToRes[insID] = resID
        R.resToIns[resID] = insID
    end
    F.ensureDepotItemValid(insID, resID)
    F.saveGrenadeToCache(base, resID, insID)
    F.ensureInjectedItemAlive(nil, resID, insID)
    local ready = F.isResourcesReady(resID)
    if not ready then F.requestResourceDownload(resID) end
    pcall(function()
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        if fbd.PutOnThrowObjectSkin then fbd:PutOnThrowObjectSkin(insID) end
    end)
    pcall(F.applyInitialConsumableAvatar)
    pcall(function()
        local lw = require("client.slua.logic.wardrobe.logic_wardrobe_new")
        if lw and lw.ShowGrenadeModel then lw:ShowGrenadeModel(resID, true) end
    end)
    if ready then
        local item = {
            res_id = resID, resID = resID,
            instid = insID, ins_id = insID, insID = insID,
            expire_ts = 0, expireTS = 0, count = 1,
            itemSubType = st,
        }
        local WRH = require("client.network.Protocol.WardRobeHandler")
        WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
    end
    return true
end

function F.isWeaponSkinIns(insID)
    insID = tonumber(insID)
    if not insID then return false end
    local res = R.insToRes[insID]
    return res and F.isWeaponSkinRes(res)
end

function F.cleanArmoryPollution()
    pcall(function()
        local Arm = require("client.logic.armory.logic_armory")
        if not Arm.rsp_list then return end
        if Arm.rsp_list.install_list then
            for wid, entry in pairs(Arm.rsp_list.install_list) do
                local ins = tonumber(entry and entry.skin_id)
                if ins and not F.isWeaponSkinIns(ins) then
                    Arm.rsp_list.install_list[wid] = nil
                end
            end
        end
        if Arm.rsp_list.skin_list then
            for wid, skins in pairs(Arm.rsp_list.skin_list) do
                if type(skins) == "table" then
                    for resID in pairs(skins) do
                        if not F.isWeaponSkinRes(tonumber(resID)) then
                            skins[resID] = nil
                        end
                    end
                end
            end
        end
    end)
end

function F.depotSubType(insID, resID)
    resID = tonumber(resID) or tonumber(R.insToRes[insID])
    local st = F.subType(F.cfg(resID))
    if st then return st end
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local d = wd:GetHallDepotItemDataByInsID(insID)
    return d and tonumber(d.itemSubType)
end

function F.tryLocalWearByIns(insID)
    insID = tonumber(insID)
    if not insID then return false end
    -- FreeLobbyShop vẫn mặc local (XSuit/hộp) dù ModSkin tắt
    if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModSkin == false
        and not (_G.KuttaVaiConfig.FreeLobbyShop == true) then
        return false
    end
    local resID = R.insToRes[insID]
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local d = wd:GetHallDepotItemDataByInsID(insID)
    if not resID and d then resID = tonumber(d.resID or d.res_id) end
    if not resID or resID <= 0 then return false end
    local st = F.depotSubType(insID, resID)

    local function mapLocal()
        if not R.insToRes[insID] then
            R.insToRes[insID] = resID
            R.resToIns[resID] = insID
        end
    end

    if st == GLOVES_SUB then mapLocal(); F.putOnGloves(insID) return true end
    F.clearItemExpire(d, insID, resID)
    F.ensureDepotItemValid(insID, resID)
    if F.isParachuteRes(resID) then mapLocal(); return F.putOnParachute(insID) end
    if F.isGlideRes(resID) or GLIDER_SUBS[st] then mapLocal(); return F.putOnGlider(insID) end

    if st == OUTFIT_SUB then
        mapLocal()
        -- XSuit: ghi nhánh (skip event) → putOn → refresh dấu tích
        local xsuitMeta = nil
        pcall(function()
            if type(FLS) == "table" and FLS.IsEnabled and FLS.IsEnabled()
                and FLS.resolveXSuitMeta and FLS.setXSuitWardrobeBranch then
                local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                if LogicXSuit and LogicXSuit.IsXSuit and LogicXSuit.IsXSuit(resID) then
                    xsuitMeta = FLS.resolveXSuitMeta(resID)
                    if xsuitMeta then
                        FLS.rememberXSuitWorkshopUnlock(xsuitMeta)
                        FLS._xsuitWardrobeBranchPrefer = FLS._xsuitWardrobeBranchPrefer or {}
                        FLS._xsuitWardrobeBranchPrefer[xsuitMeta.period] = xsuitMeta
                        FLS.setXSuitWardrobeBranch(xsuitMeta, { skipEvent = true })
                    end
                end
            end
        end)
        if F.isSuitRes(resID) or F.wardrobeTab(resID) == TAB_SUIT then
            F.putOnOutfit(insID)
        else
            F.putOnRoleWear(insID)
        end
        if xsuitMeta then
            pcall(function()
                if EventSystem and EVENTTYPE_GOLDEN_SUIT and EVENTID_GOLDEN_SUIT_UPDATE_DRESS_BRANCH then
                    EventSystem:postEvent(EVENTTYPE_GOLDEN_SUIT, EVENTID_GOLDEN_SUIT_UPDATE_DRESS_BRANCH,
                        xsuitMeta.period, xsuitMeta.branchId or 0, resID)
                end
                if FLS.refreshXSuitWardrobeWearFlags then
                    FLS.refreshXSuitWardrobeWearFlags(xsuitMeta.period, resID, insID)
                end
            end)
        end
        return true
    end
    if st == HAT_SUB or HEAD_SUBS[st] then mapLocal(); F.putOnHat(insID) return true end
    if FACE_SUBS[st] then mapLocal(); F.putOnFaceAccessory(insID) return true end
    if BODY_SUBS[st] or HELMET_SUBS[st] then mapLocal(); F.putOnRoleWear(insID) return true end

    if not F.isInjectedIns(insID) then return false end
    if GUN_SUB[st] then
        local wid = F.weaponIdFromSkin(resID)
        if wid then F.equipWeaponSkin(wid, insID) end
        return true
    end
    if st == MELEE_ID then
        local mapped = tonumber(F.weaponIdFromSkin(resID))
        F.equipWeaponSkin((mapped and mapped > 0) and mapped or MELEE_ID, insID)
        return true
    end
    if GRENADE_SUB[st] then
        mapLocal()
        return F.putOnGrenade(insID)
    end
    if F.isHallThemeRes(resID) and (F.isInjectedIns(insID) or F.isInjectedRes(resID)) then
        mapLocal()
        return F.putOnHallTheme(insID)
    end
    if F.isVehicleRes(resID) and (F.isInjectedIns(insID) or F.isInjectedRes(resID)) then
        mapLocal()
        return F.putOnVehicle(insID)
    end
    return false
end

function F.isHallThemeRes(resID)
    -- P23-FIX Task3 (old logic): ENUM fallback + tonumber
    local c = F.cfg(tonumber(resID))
    if not c then return false end
    local t = tonumber(c.ItemType or c.itemType or 0) or 0
    pcall(function()
        local E = _G.ENUM_ITEM_TYPE
        if E and E.Hall_Theme and tonumber(E.Hall_Theme) then
            HALL_THEME_TYPE = tonumber(E.Hall_Theme)
        end
    end)
    if t == 202 or t == HALL_THEME_TYPE then return true end
    return t == HALL_THEME_TYPE
end

function F.isResourcesReady(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    if not F.isInjectedRes(resID) then return true end
    local ready = false
    pcall(function()
        local PufferConst = require("client.slua.logic.download.puffer_const")
        local mgr = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.puffer_odpak_manager)
        if mgr and mgr.GetStateByItemID then
            local st = mgr:GetStateByItemID(resID)
            ready = st == PufferConst.ENUM_DownloadState.Done
        end
    end)
    return ready
end

function F.isOdPakReady(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    local ready = false
    pcall(function()
        local PufferConst = require("client.slua.logic.download.puffer_const")
        local Done = PufferConst.ENUM_DownloadState.Done
        local mgr = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.puffer_odpak_manager)
        if mgr and mgr.GetStateByItemID then
            ready = mgr:GetStateByItemID(resID) == Done
            if ready then return end
        end
        local PM = require("client.slua.logic.download.puffer.puffer_manager")
        if PM and PM.GetState then
            ready = PM.GetState(PufferConst.ENUM_DownloadType.ODPAK, { resID }) == Done
        end
    end)
    return ready
end

-- Download ODPAK cho mọi item (kể cả vành/mạ không inject depot)
function F.requestOdPakDownload(resID, onDone)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return end
    if F.isOdPakReady(resID) then
        if onDone then pcall(onDone) end
        return
    end
    _G.AddOutfitDownloadQueued = _G.AddOutfitDownloadQueued or {}
    _G.AddOutfitDownloadCbs = _G.AddOutfitDownloadCbs or {}
    local key = "odpak_" .. tostring(resID)
    if onDone then
        _G.AddOutfitDownloadCbs[key] = _G.AddOutfitDownloadCbs[key] or {}
        _G.AddOutfitDownloadCbs[key][#_G.AddOutfitDownloadCbs[key] + 1] = onDone
    end
    if _G.AddOutfitDownloadQueued[key] then return end
    _G.AddOutfitDownloadQueued[key] = true
    pcall(function()
        local PM = require("client.slua.logic.download.puffer.puffer_manager")
        local PufferConst = require("client.slua.logic.download.puffer_const")
        PM.Download(PufferConst.ENUM_DownloadType.ODPAK, { resID }, "AddOutfitVehPart", function()
            _G.AddOutfitDownloadQueued[key] = nil
            local cbs = _G.AddOutfitDownloadCbs[key]
            _G.AddOutfitDownloadCbs[key] = nil
            if type(cbs) == "table" then
                for _, cb in ipairs(cbs) do pcall(cb) end
            end
        end)
    end)
end

function F.requestResourceDownload(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return end
    -- Injected skin: giữ hành vi cũ; vehicle mod parts: luôn cho tải ODPAK
    if F.isInjectedRes(resID) then
        if F.isResourcesReady(resID) then return end
        _G.AddOutfitDownloadQueued = _G.AddOutfitDownloadQueued or {}
        if _G.AddOutfitDownloadQueued[resID] then return end
        _G.AddOutfitDownloadQueued[resID] = true
        pcall(function()
            local PM = require("client.slua.logic.download.puffer.puffer_manager")
            local PufferConst = require("client.slua.logic.download.puffer_const")
            PM.Download(PufferConst.ENUM_DownloadType.ODPAK, { resID }, "AddOutfit", function()
                _G.AddOutfitDownloadQueued[resID] = nil
            end)
        end)
        return
    end
    F.requestOdPakDownload(resID)
end

function F.ensureInjectedResources()
    for res in pairs(R.resToIns) do
        F.requestResourceDownload(tonumber(res))
    end
end

function F.restorePufferHooks()
    pcall(function()
        local mgr = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.puffer_odpak_manager)
        if mgr and _G.AddOutfitPufferOrig then
            mgr.GetStateByItemID = _G.AddOutfitPufferOrig
        end
    end)
    pcall(function()
        local PM = require("client.slua.logic.download.puffer.puffer_manager")
        if PM and _G.AddOutfitPufferGetStateOrig then
            PM.GetState = _G.AddOutfitPufferGetStateOrig
        end
    end)
    pcall(function()
        local VAC = require("GameLua.GameCore.Module.Vehicle.Component.VehicleAvatarComponent")
        local vacImpl = VAC and VAC.__inner_impl
        if vacImpl and _G.AddOutfitVehOrigAssets then
            vacImpl.LuaIsAssetsAlreadyAvailable = _G.AddOutfitVehOrigAssets
        end
    end)
end

function F.invalidateSocialWearCache()
    local s = _G.AddOutfitSocialState
    if s then
        s.wearPatchKey, s.snapshotKey, s.fullSnapshot, s.lastHandSkin = nil, nil, nil, nil
    end
end

function F.clearWeaponEquippedMark(weaponID)
    _G.AddOutfitWeaponEquipped = _G.AddOutfitWeaponEquipped or {}
    if weaponID then
        _G.AddOutfitWeaponEquipped[tonumber(weaponID)] = nil
    else
        for k in pairs(_G.AddOutfitWeaponEquipped) do _G.AddOutfitWeaponEquipped[k] = nil end
    end
end

function F.isWeaponVisuallyEquipped(weaponID, insID)
    weaponID, insID = tonumber(weaponID), tonumber(insID)
    if not weaponID or not insID then return false end
    return _G.AddOutfitWeaponEquipped and _G.AddOutfitWeaponEquipped[weaponID] == insID
end

function F.saveWeaponToCache(weaponID, resID, insID)
    F.clearWeaponEquippedMark(weaponID)
    weaponID, resID, insID = tonumber(weaponID), tonumber(resID), tonumber(insID)
    if not F.isValidWeaponPersistEntry(weaponID, resID) then return end
    local cch = F.cache()
    cch.weapons[weaponID] = { resID = resID, insID = insID or 0 }
    PERSIST.configWeapons = PERSIST.configWeapons or {}
    PERSIST.configWeapons[weaponID] = resID
    _G.AddOutfitLastAppliedSkin = {}
    _matchApplied = false
    F.perfInvalidateLobby()
    F.invalidateSocialWearCache()
    F.persistMarkDirty()
    F.log("ذاكرة سكن", weaponID, "→", resID)
end

function F.cacheWeaponSkinFromIns(weaponID, insID)
    weaponID, insID = tonumber(weaponID), tonumber(insID)
    if not weaponID or not insID or insID <= 0 then return end
    if F.isInjectedIns(insID) then
        local res = R.insToRes[insID]
        if res and F.subType(F.cfg(res)) == MELEE_ID then
            local mapped = tonumber(F.weaponIdFromSkin(res))
            if mapped and mapped > 0 then weaponID = mapped end
        end
        F.saveWeaponToCache(weaponID, res, insID)
        return
    end
    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
        if d and d.resID and tonumber(d.resID) > 0 then
            local res = tonumber(d.resID)
            if F.subType(F.cfg(res)) == MELEE_ID then
                local mapped = tonumber(F.weaponIdFromSkin(res))
                if mapped and mapped > 0 then weaponID = mapped end
            end
            F.saveWeaponToCache(weaponID, res, insID)
        end
    end)
end

function F.saveEquip(resID, insID)
    resID, insID = tonumber(resID), tonumber(insID)
    if not resID or not insID then return end
    local c = F.cfg(resID)
    local st = F.subType(c)
    local cch = F.cache()
    if st == OUTFIT_SUB then
        if F.wardrobeTab(resID) == TAB_CLOTHES then
            cch.tshirtRes, cch.tshirtIns = resID, insID
            _G.AddOutfitLastLobbyTshirtRes = resID
            F.persistRememberSlot("tshirt", resID)
        else
            cch.outfitRes, cch.outfitIns = resID, insID
            _G.AddOutfitLastLobbyOutfitRes = resID
            F.persistRememberSlot("outfit", resID)
            F.invalidateSocialWearCache()
        end
    elseif st == HAT_SUB then
        cch.hatRes, cch.hatIns = resID, insID
        _G.AddOutfitLastLobbyHatRes = resID
        F.persistRememberSlot("hat", resID)
    elseif st == MASK_SUB then
        cch.maskRes, cch.maskIns = resID, insID
        _G.AddOutfitLastLobbyMaskRes = resID
        F.persistRememberSlot("mask", resID)
    elseif st == GLASS_SUB then
        cch.glassRes, cch.glassIns = resID, insID
        _G.AddOutfitLastLobbyGlassRes = resID
        F.persistRememberSlot("glass", resID)
    elseif st == PANTS_SUB then
        cch.pantsRes, cch.pantsIns = resID, insID
        _G.AddOutfitLastLobbyPantsRes = resID
        F.persistRememberSlot("pants", resID)
    elseif st == SHOES_SUB then
        cch.shoesRes, cch.shoesIns = resID, insID
        _G.AddOutfitLastLobbyShoesRes = resID
        F.persistRememberSlot("shoes", resID)
    elseif BAG_SUBS[st] then
        resID = F.equipToLobbyMappingID(resID)
        cch.bagRes, cch.bagIns = resID, insID
        _G.AddOutfitLastLobbyBagRes = resID
        _G.BackpackSkin = resID
        F.persistRememberSlot("bag", resID)
    elseif HELMET_SUBS[st] then
        resID = F.equipToLobbyMappingID(resID)
        cch.helmetRes, cch.helmetIns = resID, insID
        _G.AddOutfitLastLobbyHelmetRes = resID
        _G.HelmetSkin = resID
        F.persistRememberSlot("helmet", resID)
    elseif st == PARACHUTE_SUB then
        cch.parachuteRes, cch.parachuteIns = resID, insID
        _G.AddOutfitLastLobbyParachuteRes = resID
        F.persistRememberSlot("parachute", resID)
    elseif F.isGlideRes(resID) then
        cch.gliderRes, cch.gliderIns = resID, insID
        _G.AddOutfitLastLobbyGliderRes = resID
        F.persistRememberSlot("glider", resID)
    elseif st == GLOVES_SUB then
        cch.glovesRes, cch.glovesIns = resID, insID
        _G.AddOutfitLastLobbyGlovesRes = resID
        F.persistRememberSlot("gloves", resID)
    elseif GUN_SUB[st] then
        local wid = F.weaponIdFromSkin(resID)
        if wid then F.saveWeaponToCache(wid, resID, insID) end
    elseif st == MELEE_ID then
        local wid = tonumber(F.weaponIdFromSkin(resID))
        if wid and wid > 0 then
            F.saveWeaponToCache(wid, resID, insID)
        else
            F.saveWeaponToCache(MELEE_ID, resID, insID)
        end
    elseif GRENADE_SUB[st] then
        local base = F.grenadeBaseFromSkin(resID)
        if base then F.saveGrenadeToCache(base, resID, insID) end
    end
    _matchApplied = false
    F.perfInvalidateLobby()
    F.persistMarkDirty()
end

function F.findWornInsBySubType(st, filterFn)
    st = tonumber(st)
    if not st then return nil end
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local AvatarData = require("client.logic.data.AvatarData")
    for _, ins in pairs(AvatarData.GetRoleWear()) do
        ins = tonumber(ins)
        if ins and ins > 0 then
            local d = wd:GetHallDepotItemDataByInsID(ins)
            if d and tonumber(d.itemSubType) == st then
                local res = tonumber(d.resID)
                if not filterFn or filterFn(res, d) then
                    return ins, res
                end
            end
        end
    end
    return nil
end

function F.syncHatCacheFromLobby()
    local cch = F.cache()
    pcall(function()
        local ins, res = F.findWornInsBySubType(HAT_SUB)
        if ins and res and tonumber(res) > 0 then
            cch.hatRes, cch.hatIns = tonumber(res), ins
            return
        end
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
        local headIns = tonumber(bag and bag.head_show) or 0
        if headIns <= 0 then return end
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetValidHallDepotItemDataByInsID(headIns) or wd:GetHallDepotItemDataByInsID(headIns)
        if not d or not d.resID or tonumber(d.resID) <= 0 then return end
        local st = tonumber(d.itemSubType or F.subType(F.cfg(d.resID)))
        if HEAD_SUBS[st] then
            cch.hatRes, cch.hatIns = tonumber(d.resID), headIns
        end
    end)
end

function F.syncFaceCacheFromLobby()
    local cch = F.cache()
    pcall(function()
        local ins, res = F.findWornInsBySubType(MASK_SUB)
        if ins and res and tonumber(res) > 0 then
            cch.maskRes, cch.maskIns = tonumber(res), ins
            _G.AddOutfitLastLobbyMaskRes = tonumber(res)
        end
    end)
    pcall(function()
        local ins, res = F.findWornInsBySubType(GLASS_SUB)
        if ins and res and tonumber(res) > 0 then
            cch.glassRes, cch.glassIns = tonumber(res), ins
            _G.AddOutfitLastLobbyGlassRes = tonumber(res)
        end
    end)
end

function F.syncBodyCacheFromLobby()
    local cch = F.cache()
    pcall(function()
        local ins, res = F.findWornInsBySubType(OUTFIT_SUB, function(r) return F.wardrobeTab(r) == TAB_CLOTHES end)
        if ins and res and tonumber(res) > 0 then
            cch.tshirtRes, cch.tshirtIns = tonumber(res), ins
            _G.AddOutfitLastLobbyTshirtRes = tonumber(res)
        end
    end)
    pcall(function()
        local ins, res = F.findWornInsBySubType(PANTS_SUB)
        if ins and res and tonumber(res) > 0 then
            cch.pantsRes, cch.pantsIns = tonumber(res), ins
            _G.AddOutfitLastLobbyPantsRes = tonumber(res)
        end
    end)
    pcall(function()
        local ins, res = F.findWornInsBySubType(SHOES_SUB)
        if ins and res and tonumber(res) > 0 then
            cch.shoesRes, cch.shoesIns = tonumber(res), ins
            _G.AddOutfitLastLobbyShoesRes = tonumber(res)
        end
    end)
    pcall(function()
        local ins, res = F.findWornInsBySubType(GLOVES_SUB)
        if ins and res and tonumber(res) > 0 then
            cch.glovesRes, cch.glovesIns = tonumber(res), ins
            _G.AddOutfitLastLobbyGlovesRes = tonumber(res)
        end
    end)
    pcall(function()
        for st in pairs(BAG_SUBS) do
            local ins, res = F.findWornInsBySubType(st)
            if ins and res and tonumber(res) > 0 then
                cch.bagRes, cch.bagIns = tonumber(res), ins
                _G.AddOutfitLastLobbyBagRes = tonumber(res)
                break
            end
        end
    end)
    pcall(function()
        for st in pairs(HELMET_SUBS) do
            local ins, res = F.findWornInsBySubType(st)
            if ins and res and tonumber(res) > 0 then
                cch.helmetRes, cch.helmetIns = tonumber(res), ins
                _G.AddOutfitLastLobbyHelmetRes = tonumber(res)
                break
            end
        end
    end)
    pcall(function()
        local ins, res = F.findWornInsBySubType(OUTFIT_SUB, function(r) return F.isSuitRes(r) end)
        if ins and res and tonumber(res) > 0 then
            cch.outfitRes, cch.outfitIns = tonumber(res), ins
            _G.AddOutfitLastLobbyOutfitRes = tonumber(res)
        end
    end)
end

function F.syncAirborneCacheFromLobby(saveToConfig)
    local cch = F.cache()
    local cfgPara = tonumber(PERSIST.configSlots and PERSIST.configSlots.parachute)
    local cfgGlide = tonumber(PERSIST.configSlots and PERSIST.configSlots.glider)
    local changed = false

    local function maybeSave(slotName, res)
        if not saveToConfig or not res or res <= 0 then return end
        if slotName == "parachute" and res == DEFAULT_PARACHUTE_RES
            and cfgPara and cfgPara > 0 and cfgPara ~= DEFAULT_PARACHUTE_RES then
            return
        end
        F.persistRememberSlot(slotName, res)
        changed = true
    end

    local function applyPara(res, ins)
        res, ins = tonumber(res), tonumber(ins)
        if not res or not ins or not F.isParachuteRes(res) then return end
        if cfgPara and cfgPara > 0 and not saveToConfig then
            if res == cfgPara then cch.parachuteIns = ins end
            return
        end
        if res == DEFAULT_PARACHUTE_RES and not saveToConfig then return end
        if cch.parachuteRes ~= res or cch.parachuteIns ~= ins then
            cch.parachuteRes, cch.parachuteIns = res, ins
            _G.AddOutfitLastLobbyParachuteRes = res
            maybeSave("parachute", res)
        end
    end

    local function applyGlide(res, ins)
        res, ins = tonumber(res), tonumber(ins)
        if not res or not ins or not F.isGlideRes(res) then return end
        if cfgGlide and cfgGlide > 0 and not saveToConfig then
            if res == cfgGlide then cch.gliderIns = ins end
            return
        end
        if cch.gliderRes ~= res or cch.gliderIns ~= ins then
            cch.gliderRes, cch.gliderIns = res, ins
            _G.AddOutfitLastLobbyGliderRes = res
            maybeSave("glider", res)
        end
    end

    pcall(function()
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local paraIns = tonumber(fbd.GetParachute and fbd:GetParachute()) or 0
        if paraIns > 0 then
            local d = wd:GetValidHallDepotItemDataByInsID(paraIns) or wd:GetHallDepotItemDataByInsID(paraIns)
            applyPara(d and tonumber(d.resID), paraIns)
        end
        local glideIns = tonumber(fbd.GetAircraftOrGliding and fbd:GetAircraftOrGliding()) or 0
        if glideIns > 0 then
            local d = wd:GetValidHallDepotItemDataByInsID(glideIns) or wd:GetHallDepotItemDataByInsID(glideIns)
            applyGlide(d and tonumber(d.resID), glideIns)
        end
    end)
    pcall(function()
        for st in pairs(GLIDER_SUBS) do
            local ins, res = F.findWornInsBySubType(st)
            if ins and res then applyGlide(res, ins) break end
        end
        local ins, res = F.findWornInsBySubType(PARACHUTE_SUB)
        if ins and res then applyPara(res, ins) end
    end)
    if changed then F.persistMarkDirty() end
end

function F.syncWeaponCacheFromLobby(force)
    if LOBBY.lobbySynced and not force then return end
    LOBBY.lobbySynced = true
    PERF.mappingsDirty = true
    PERF.desiredSkins = nil
    for k in pairs(PERF.skinTarget) do PERF.skinTarget[k] = nil end
    local cch = F.cache()
    local function putWeapon(weaponID, res, insID)
        weaponID, res, insID = tonumber(weaponID), tonumber(res), tonumber(insID)
        if not weaponID or not res or res <= 0 then return end
        if weaponID == MELEE_ID and F.subType(F.cfg(res)) == MELEE_ID then
            local mapped = tonumber(F.weaponIdFromSkin(res))
            if mapped and mapped > 0 then weaponID = mapped end
        end
        if not F.isValidWeaponPersistEntry(weaponID, res) then return end
        cch.weapons[weaponID] = { resID = res, insID = insID or 0 }
    end
    pcall(function()
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
        if bag and bag.weapon_skin_list then
            for weaponID, entry in pairs(bag.weapon_skin_list) do
                weaponID = tonumber(weaponID)
                local insID = tonumber(entry and (entry.skin_id or entry.skinId)) or 0
                if weaponID and weaponID > 0 and insID > 0 then
                    local res
                    if F.isInjectedIns(insID) then
                        res = tonumber(R.insToRes[insID])
                    else
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        res = d and tonumber(d.resID)
                    end
                    putWeapon(weaponID, res, insID)
                end
            end
        end
    end)
    pcall(function()
        local Arm = require("client.logic.armory.logic_armory")
        if Arm.rsp_list and Arm.rsp_list.install_list then
            for weaponID, entry in pairs(Arm.rsp_list.install_list) do
                weaponID = tonumber(weaponID)
                local insID = tonumber(entry and entry.skin_id) or 0
                if weaponID and weaponID > 0 and insID > 0 then
                    local res
                    if F.isInjectedIns(insID) then
                        res = tonumber(R.insToRes[insID])
                    else
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetValidHallDepotItemDataByInsID(insID)
                            or wd:GetHallDepotItemDataByInsID(insID)
                        res = d and tonumber(d.resID)
                    end
                    putWeapon(weaponID, res, insID)
                end
            end
        end
    end)
    F.syncHatCacheFromLobby()
    F.syncFaceCacheFromLobby()
    F.syncBodyCacheFromLobby()
end

function F.getCachedWeaponSkin(weaponID)
    weaponID = tonumber(weaponID) or 0
    if weaponID <= 0 then return nil end
    F.syncWeaponCacheFromLobby()
    local w = F.cache().weapons[weaponID]
    if w and w.resID and w.resID > 0 then return w.resID end
    return nil
end

function F.getMatchWeaponSkin(weaponID)
    weaponID = tonumber(weaponID) or 0
    local fromCache = F.getCachedWeaponSkin(weaponID)
    if fromCache then return fromCache end
    if MATCH_CONFIG.weaponSkins then
        local fixed = tonumber(MATCH_CONFIG.weaponSkins[weaponID])
        if fixed and fixed > 0 then return fixed end
    end
    return nil
end

-- Patch WeaponAvatar trong ItemListNet (balo) để skin hiện đúng trong inventory
-- (súng + balo/nón — icon balo đọc WeaponAvatar AdditionalData giống súng)
-- Cấp balo/nón từ TypeSpecificID (501/502 hoặc skin 150x)
function F.levelFromEquipArmorID(equipID)
    equipID = tonumber(equipID) or 0
    if equipID >= 501001 and equipID <= 501199 then
        local rem = equipID % 10
        if rem >= 1 and rem <= 6 then return math.min(rem, 3) end
        return 1
    end
    if equipID >= 502001 and equipID <= 502199 then
        local rem = equipID % 10
        if rem >= 1 and rem <= 6 then return math.min(rem, 3) end
        return 1
    end
    if equipID >= 1501000000 and equipID < 1503000000 then
        local lvDigit = math.floor(equipID / 1000) % 10
        if lvDigit >= 1 and lvDigit <= 3 then return lvDigit end
    end
    return 1
end

-- Icon inventory balo/nón: ArmorSlot dùng InitialEquipmentAvatar, list item dùng WeaponAvatar
function F.resolveInvArmorSkinID(currentID)
    currentID = tonumber(currentID) or 0
    if currentID <= 0 then return 0 end
    local isBag = (currentID >= 501001 and currentID <= 501199)
        or (currentID >= 1501000000 and currentID < 1502000000)
    local isHelmet = (currentID >= 502001 and currentID <= 502199)
        or (currentID >= 1502000000 and currentID < 1503000000)
    if not isBag and not isHelmet then
        pcall(function()
            local cfg = CDataTable.GetTableData("Item", currentID)
            local ist = cfg and tonumber(cfg.ItemSubType) or 0
            if ist == 501 or ist == 504 then isBag = true end
            if ist == 502 or ist == 505 then isHelmet = true end
        end)
    end
    if isBag then
        local bagRes = tonumber(_G.BackpackSkin)
            or tonumber(F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes", F.syncBodyCacheFromLobby))
            or 0
        if bagRes <= 0 then return 0 end
        return tonumber(F.levelSkinID(bagRes, F.levelFromEquipArmorID(currentID))) or 0
    end
    if isHelmet then
        local helmetRes = tonumber(_G.HelmetSkin)
            or tonumber(F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes", F.syncBodyCacheFromLobby))
            or 0
        if helmetRes <= 0 then return 0 end
        return tonumber(F.levelSkinID(helmetRes, F.levelFromEquipArmorID(currentID))) or 0
    end
    return 0
end

-- Slot armor UI đọc PC.InitialEquipmentAvatar (BagAvatar/HelmetAvatar), không đọc ItemListNet
-- CHỈ Broadcast OnEquipmentAvatarChange khi Bag/Helmet THẬT SỰ đổi (tránh giật backpack UI)
function F.applyInitialEquipmentAvatar()
    local bagRes = tonumber(_G.BackpackSkin)
        or tonumber(F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes", F.syncBodyCacheFromLobby))
        or 0
    local helmetRes = tonumber(_G.HelmetSkin)
        or tonumber(F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes", F.syncBodyCacheFromLobby))
        or 0
    if bagRes <= 0 and helmetRes <= 0 then return false end
    if bagRes > 0 and F.resolveBackpackMappingBase then
        bagRes = F.resolveBackpackMappingBase(bagRes)
        _G.BackpackSkin = bagRes
    end
    if helmetRes > 0 and F.resolveBackpackMappingBase then
        helmetRes = F.resolveBackpackMappingBase(helmetRes)
        _G.HelmetSkin = helmetRes
    end

    local changed = false
    pcall(function()
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if not pc or not slua.isValid(pc) then
            pcall(function()
                local GameplayData = require("GameLua.GameCore.Data.GameplayData")
                pc = GameplayData.GetPlayerController()
            end)
        end
        if not pc or not slua.isValid(pc) then return end

        local av = pc.InitialEquipmentAvatar
        local useTable = (av == nil) or (type(av) == "table")
        if useTable then
            av = (type(av) == "table") and av or {}
            if bagRes > 0 and tonumber(av.BagAvatar) ~= bagRes then
                av.BagAvatar = bagRes
                av.BagAvatarList = {
                    [1] = F.levelSkinID(bagRes, 1),
                    [2] = F.levelSkinID(bagRes, 2),
                    [3] = F.levelSkinID(bagRes, 3),
                }
                changed = true
            end
            if helmetRes > 0 and tonumber(av.HelmetAvatar) ~= helmetRes then
                av.HelmetAvatar = helmetRes
                av.HelmetAvatarList = {
                    [1] = F.levelSkinID(helmetRes, 1),
                    [2] = F.levelSkinID(helmetRes, 2),
                    [3] = F.levelSkinID(helmetRes, 3),
                }
                changed = true
            end
            if changed then pc.InitialEquipmentAvatar = av end
        else
            if bagRes > 0 then
                local curBag = nil
                pcall(function() curBag = tonumber(av.BagAvatar) end)
                if curBag ~= bagRes then
                    pcall(function() av.BagAvatar = bagRes end)
                    pcall(function()
                        av.BagAvatarList = {
                            [1] = F.levelSkinID(bagRes, 1),
                            [2] = F.levelSkinID(bagRes, 2),
                            [3] = F.levelSkinID(bagRes, 3),
                        }
                    end)
                    changed = true
                end
            end
            if helmetRes > 0 then
                local curHelm = nil
                pcall(function() curHelm = tonumber(av.HelmetAvatar) end)
                if curHelm ~= helmetRes then
                    pcall(function() av.HelmetAvatar = helmetRes end)
                    pcall(function()
                        av.HelmetAvatarList = {
                            [1] = F.levelSkinID(helmetRes, 1),
                            [2] = F.levelSkinID(helmetRes, 2),
                            [3] = F.levelSkinID(helmetRes, 3),
                        }
                    end)
                    changed = true
                end
            end
        end

        if changed then
            pcall(function()
                if slua.isValid(pc.PlayerState) and pc.PlayerState.MetroPlayerStateAvatarFeature then
                    pc.PlayerState.MetroPlayerStateAvatarFeature.InitialEquipmentAvatar = pc.InitialEquipmentAvatar
                end
            end)
            -- Lag hotspot (dump): Broadcast → BackPackPanelUI:UpdateScrollItemListEvent
            pcall(function()
                if pc.Broadcast and pc.OnEquipmentAvatarChange then
                    pc:Broadcast("OnEquipmentAvatarChange")
                end
            end)
        end
    end)
    return changed
end

function F.hookArmorInventoryAvatar()
    if _G.AddOutfitArmorInvAvatarHooked then return end
    _G.AddOutfitArmorInvAvatarHooked = true

    pcall(function()
        local M = require("GameLua.Mod.BaseMod.Client.Backpack.BackPackArmorSlotUI")
        local impl = M and (M.__inner_impl or M)
        if not impl or not impl.GetEquipmentAvatarRes or impl._AddOutfitArmorAvatarHooked then return end
        impl._AddOutfitArmorAvatarHooked = true
        local o = impl.GetEquipmentAvatarRes
        impl.GetEquipmentAvatarRes = function(self, BattleItemData)
            local override = 0
            pcall(function()
                if not BattleItemData then return end
                local DefineID = BattleItemData.DefineID or slua.IndexReference(BattleItemData, "DefineID")
                local tid = DefineID and tonumber(DefineID.TypeSpecificID) or 0
                override = F.resolveInvArmorSkinID(tid) or 0
            end)
            if override and override > 0 then return override end
            return o(self, BattleItemData)
        end
    end)

    pcall(function()
        local M = require("GameLua.Mod.BaseMod.Client.Backpack.BackPackItemUI")
        local impl = M and (M.__inner_impl or M)
        if not impl or not impl.GetAvatarID or impl._AddOutfitItemAvatarHooked then return end
        impl._AddOutfitItemAvatarHooked = true
        local o = impl.GetAvatarID
        impl.GetAvatarID = function(self, inData)
            local override = 0
            pcall(function()
                if not inData then return end
                local DefineID = inData.DefineID or slua.IndexReference(inData, "DefineID")
                local tid = DefineID and tonumber(DefineID.TypeSpecificID) or 0
                override = F.resolveInvArmorSkinID(tid) or 0
            end)
            if override and override > 0 then return override end
            return o(self, inData)
        end
    end)

    pcall(function()
        local ADU = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
        if not ADU or not ADU.InitialEquipmentAvatar or ADU._AddOutfitInitEquipAvHooked then return end
        ADU._AddOutfitInitEquipAvHooked = true
        local o = ADU.InitialEquipmentAvatar
        ADU.InitialEquipmentAvatar = function(PlayerInfo, uPlayerController)
            o(PlayerInfo, uPlayerController)
            pcall(F.applyInitialEquipmentAvatar)
        end
    end)
end

function _G.Inventure_KuttaCheatTG(Backpack)
    if not Backpack or not slua.isValid(Backpack) then return end
    if not _G.KuttaVaiConfig or not _G.KuttaVaiConfig.ModSkin or not _G.KuttaVaiConfig.InventureKuttaCheatTG then return end

    pcall(function()
        local bagRes = tonumber(F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes", F.syncBodyCacheFromLobby)) or 0
        local helmetRes = tonumber(F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes", F.syncBodyCacheFromLobby)) or 0
        if bagRes > 0 then _G.BackpackSkin = bagRes end
        if helmetRes > 0 then _G.HelmetSkin = helmetRes end
    end)
    -- Chi set InitialEquipmentAvatar khi doi — khong Broadcast moi lan
    pcall(F.applyInitialEquipmentAvatar)
    pcall(F.applyInitialConsumableAvatar)
    pcall(F.hookArmorInventoryAvatar)
    pcall(F.hookGrenadeAvatarLookup)

    if not Backpack.ItemListNet or not Backpack.ItemListNet.IncArray then return end

    local BagArray = Backpack.ItemListNet.IncArray
    local ItemCount = BagArray:Num()
    if ItemCount <= 0 or ItemCount > 500 then return end

    -- Fingerprint: so item + id dau/cuoi — skip scan neu da sync gan day
    local fpFirst, fpLast = 0, 0
    pcall(function()
        local a = BagArray:Get(0)
        fpFirst = a and a.Unit and a.Unit.DefineID and tonumber(a.Unit.DefineID.TypeSpecificID) or 0
        if ItemCount > 1 then
            local b = BagArray:Get(ItemCount - 1)
            fpLast = b and b.Unit and b.Unit.DefineID and tonumber(b.Unit.DefineID.TypeSpecificID) or 0
        end
    end)
    local fp = string.format("%d:%d:%d:%s:%s", ItemCount, fpFirst, fpLast, tostring(_G.BackpackSkin or 0), tostring(_G.HelmetSkin or 0))
    local now = os.clock()
    if _G._KuttaCheatTG_InvFP == fp and _G._KuttaCheatTG_InvSynced and _G._KuttaCheatTG_InvSyncAt
        and (now - _G._KuttaCheatTG_InvSyncAt) < 12.0 then
        return
    end

    local bNeedRefreshBag = false
    local EBattleItemAdditionalDataType = nil
    pcall(function() EBattleItemAdditionalDataType = import("EBattleItemAdditionalDataType") end)
    local EDataType_WeaponAvatar = (EBattleItemAdditionalDataType and EBattleItemAdditionalDataType.WeaponAvatar) or 7

    local function resolveInvSkin(currentID)
        currentID = tonumber(currentID) or 0
        if currentID <= 0 then return 0 end
        local armorSkin = F.resolveInvArmorSkinID(currentID)
        if armorSkin and armorSkin > 0 then return armorSkin end

        if GRENADE_FIELD_BY_BASE[currentID] then
            local g = F.getCachedGrenadeSkin(currentID)
            if g and g > 0 then return g end
        end
        -- Skin res chính là lựu đã chọn
        if F.isGrenadeSkinRes(currentID) then return currentID end

        local skin = F.getMatchWeaponSkin(currentID)
        if skin and skin > 0 then return tonumber(skin) or 0 end
        if F.resolveWeaponTypeID then
            local typeId = F.resolveWeaponTypeID(currentID)
            if typeId and typeId > 0 and typeId ~= currentID then
                skin = F.getMatchWeaponSkin(typeId)
                if skin and skin > 0 then return tonumber(skin) or 0 end
            end
        end
        if F.get_skin_id then
            local sid = tonumber(F.get_skin_id(currentID, currentID)) or 0
            if sid > 0 and sid ~= currentID then return sid end
        end
        return 0
    end

    local function writeWeaponAvatar(AdditionalData, NewSkinID)
        if not AdditionalData then return false end
        local bFoundAvatar = false
        local dataCount = 0
        pcall(function() dataCount = AdditionalData:Num() end)
        local changed = false

        for k = 0, dataCount - 1 do
            local Data = AdditionalData:Get(k)
            if Data and Data.EDataType == EDataType_WeaponAvatar then
                if Data.IntData ~= NewSkinID then
                    Data.IntData = NewSkinID
                    AdditionalData:Set(k, Data)
                    changed = true
                end
                bFoundAvatar = true
                break
            end
        end

        if not bFoundAvatar and dataCount > 0 then
            local TD = AdditionalData:Get(0)
            if TD then
                TD.EDataType = EDataType_WeaponAvatar
                TD.IntData = NewSkinID
                TD.StringData = ""
                AdditionalData:Add(TD)
                changed = true
            end
        elseif not bFoundAvatar then
            local okAdd = pcall(function()
                AdditionalData:Add({
                    EDataType = EDataType_WeaponAvatar,
                    IntData = NewSkinID,
                    StringData = ""
                })
            end)
            if okAdd then changed = true end
        end
        return changed
    end

    local function patchUnitAdditional(Unit, NewSkinID)
        if not Unit then return false end
        local AdditionalData = Unit.AdditionalData
        if not AdditionalData then
            pcall(function() AdditionalData = slua.IndexReference(Unit, "AdditionalData") end)
        end
        return writeWeaponAvatar(AdditionalData, NewSkinID)
    end

    for j = 0, ItemCount - 1 do
        local Item = BagArray:Get(j)
        if Item and Item.Unit and Item.Unit.DefineID then
            local CurrentID = Item.Unit.DefineID.TypeSpecificID
            local NewSkinID = resolveInvSkin(CurrentID)
            if NewSkinID > 0 then
                -- Chi Set khi AdditionalData thật sự đổi (BagArray:Set moi lan = hitch)
                if patchUnitAdditional(Item.Unit, NewSkinID) then
                    BagArray:Set(j, Item)
                    bNeedRefreshBag = true
                end
            end
        end
    end

    pcall(function()
        local BackpackUtils = import("BackpackUtils")
        local arr = BackpackUtils.GetEuqippedArmorInBackpack(Backpack)
        if not arr then return end
        for _, BattleItemData in pairs(arr) do
            local DefineID = BattleItemData and (slua.IndexReference(BattleItemData, "DefineID") or BattleItemData.DefineID)
            local tid = DefineID and tonumber(DefineID.TypeSpecificID) or 0
            local NewSkinID = resolveInvSkin(tid)
            if NewSkinID > 0 and patchUnitAdditional(BattleItemData, NewSkinID) then
                bNeedRefreshBag = true
            end
        end
    end)

    if bNeedRefreshBag then
        pcall(function()
            if type(Backpack.OnRep_ItemListNet) == "function" then
                Backpack:OnRep_ItemListNet()
            elseif type(Backpack.OnRep_ItemListNet) == "userdata" then
                Backpack.OnRep_ItemListNet()
            end
        end)
    end

    _G._KuttaCheatTG_InvFP = fp
    _G._KuttaCheatTG_InvSynced = true
    _G._KuttaCheatTG_InvSyncAt = now
end
_G.Inventure_BangJO = _G.Inventure_KuttaCheatTG

function _G.InventureInit()
    if not _G.KuttaVaiConfig or not _G.KuttaVaiConfig.ModSkin or not _G.KuttaVaiConfig.InventureKuttaCheatTG then
        _G._KuttaCheatTG_InvSynced = false
        return
    end
    -- Throttle: hook UI da du; scan ItemListNet khong can moi 1-3s
    local now = os.clock()
    if _G._KuttaCheatTG_InvInitAt and (now - _G._KuttaCheatTG_InvInitAt) < 6.0 and _G._KuttaCheatTG_InvSynced then
        return
    end
    _G._KuttaCheatTG_InvInitAt = now
    pcall(F.hookArmorInventoryAvatar)
    pcall(F.applyInitialEquipmentAvatar)
    pcall(function()
        local PlayerController = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if not PlayerController or not slua.isValid(PlayerController) then return end
        local BC = (PlayerController.GetBackpackComponent and PlayerController:GetBackpackComponent())
            or (PlayerController.GetBackPackComponent and PlayerController:GetBackPackComponent())
        if BC and slua.isValid(BC) then
            _G.Inventure_KuttaCheatTG(BC)
        end
    end)
end

function F.removeRoleWearBySubType(st, filterFn)
    st = tonumber(st)
    if not st then return end
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local AvatarData = require("client.logic.data.AvatarData")
    for _, ins in pairs(AvatarData.GetRoleWear()) do
        ins = tonumber(ins)
        if ins and ins > 0 then
            local d = wd:GetHallDepotItemDataByInsID(ins)
            if d and tonumber(d.itemSubType) == st then
                local res = tonumber(d.resID)
                if not filterFn or filterFn(res, d) then
                    AvatarData.RemoveRoleWearDataByValue(ins)
                end
            end
        end
    end
end

