function F.mergeInjectedVehicleSkinTable(serverTable)
    serverTable = serverTable or {}
    local cfg = PERSIST.configVehicleSlots
    if not cfg then return serverTable end
    for subType, slotMap in pairs(cfg) do
        subType = tonumber(subType)
        if subType and type(slotMap) == "table" then
            local res = tonumber(slotMap[1] or slotMap["1"])
            local ins = res and R.resToIns[res]
            if ins and F.isInjectedIns(ins) then
                serverTable[subType] = ins
            end
        end
    end
    local cch = F.cache()
    for subType, slots in pairs(cch.vehicleSlots or {}) do
        subType = tonumber(subType)
        local e = slots and (slots[1] or slots["1"])
        local insID = e and tonumber(e.insID)
        if subType and insID and insID > 0 and F.isInjectedIns(insID) then
            serverTable[subType] = insID
        end
    end
    return serverTable
end

function F.equipVehicleTypesFromConfig(slotMap)
    slotMap = slotMap or PERSIST.configVehicleSlots
    if not slotMap or not next(slotMap) then return false end
    DataMgr.vehicleSkinInsIDTable = DataMgr.vehicleSkinInsIDTable or {}
    local subTypes = {}
    for st in pairs(slotMap) do
        local n = tonumber(st)
        if n then subTypes[#subTypes + 1] = n end
    end
    table.sort(subTypes)
    local any, lobbyRes, lobbyIns = false, nil, nil
    for _, subType in ipairs(subTypes) do
        local slots = slotMap[subType] or slotMap[tostring(subType)]
        if type(slots) == "table" then
            local res = tonumber(slots[1] or slots["1"])
            local ins = res and R.resToIns[res]
            if ins and F.isInjectedIns(ins) then
                DataMgr.vehicleSkinInsIDTable[subType] = ins
                any = true
                if not lobbyIns then
                    lobbyRes, lobbyIns = res, ins
                end
            end
        end
    end
    if any then
        pcall(function()
            local TabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
            TabSurveillance.VehicleChange()
        end)
    end
    return any, lobbyRes, lobbyIns
end

function F.applyLobbyVehicleDisplay(resID, insID, showVehicle)
    insID = tonumber(insID)
    resID = tonumber(resID)
    if not insID or insID <= 0 then return end
    _G.AddOutfitApplyingConfig = true
    pcall(function() DataMgr.vst_skin = insID end)
    pcall(function()
        local HallThemeUtils = require("client.logic.lobby.hall_theme_utils")
        HallThemeUtils.ProcPutOnVehicle({ res_id = resID, instid = insID }, showVehicle ~= false)
    end)
    pcall(F.applyVehicleSkinsToPC)
    _G.AddOutfitApplyingConfig = false
end

function F.setLobbyVehicleManual(subType, resID, insID)
    insID = tonumber(insID)
    resID = tonumber(resID)
    subType = tonumber(subType)
    if not insID then return end
    if F.isChassisLightId(resID) or subType == CHASSIS_LIGHT_SUB then return end
    if resID and not F.isVehicleRes(resID) then return end
    if not F.isInjectedIns(insID) and not F.isVehicleRes(resID) then return end
    if not resID then resID = R.insToRes[insID] end
    if not subType and resID then subType = tonumber(F.vehicleSlotSubType(resID) or F.vehicleSubType(resID)) end
    _G.AddOutfitLobbyVeh = _G.AddOutfitLobbyVeh or {}
    _G.AddOutfitLobbyVeh.manual = true
    _G.AddOutfitLobbyVeh.subType = subType
    _G.AddOutfitLobbyVeh.resID = resID
    _G.AddOutfitLobbyVeh.insID = insID
    PERSIST.lobbyVehicleSubType = subType
    PERSIST.lobbyVehicleIns = insID
    PERSIST.lobbyVehicleResID = resID
    F.rememberVehicleSkinMap(resID, insID)
    F.persistMarkDirty()
end

function F.resolveLobbyVehicle(slotMap)
    slotMap = slotMap or PERSIST.configVehicleSlots
    local L = _G.AddOutfitLobbyVeh or {}
    local st = tonumber(PERSIST.lobbyVehicleSubType) or tonumber(L.subType)
    local res = tonumber(PERSIST.lobbyVehicleResID) or tonumber(L.resID)
    if res and res > 0 then
        local ins = R.resToIns[res]
        if ins then
            if not st then st = tonumber(F.vehicleSubType(res)) end
            return res, ins, st
        end
    end
    local ins = tonumber(PERSIST.lobbyVehicleIns) or tonumber(L.insID)
    if ins and F.isInjectedIns(ins) then
        res = R.insToRes[ins] or res
        if not st and res then st = tonumber(F.vehicleSubType(res)) end
        return res, ins, st
    end
    if st and slotMap then
        local slots = slotMap[st] or slotMap[tostring(st)]
        local res = slots and tonumber(slots[1] or slots["1"])
        ins = res and R.resToIns[res]
        if ins then return res, ins, st end
    end
    local subTypes = {}
    for s in pairs(slotMap or {}) do
        local n = tonumber(s)
        if n then subTypes[#subTypes + 1] = n end
    end
    table.sort(subTypes)
    if subTypes[1] then
        st = subTypes[1]
        local slots = slotMap[st] or slotMap[tostring(st)]
        local res = slots and tonumber(slots[1] or slots["1"])
        ins = res and R.resToIns[res]
        if ins then return res, ins, st end
    end
    return nil, nil, nil
end

function F.syncLobbyVehicleResFromIns()
    if PERSIST.lobbyVehicleResID and PERSIST.lobbyVehicleResID > 0 then return end
    local ins = tonumber(PERSIST.lobbyVehicleIns)
    if ins and R.insToRes[ins] then
        PERSIST.lobbyVehicleResID = R.insToRes[ins]
        F.persistMarkDirty()
    end
end

function F.hasExplicitLobbyVehicle()
    local res = tonumber(PERSIST.lobbyVehicleResID)
    local st = tonumber(PERSIST.lobbyVehicleSubType)
    if F.isChassisLightId(res) or st == CHASSIS_LIGHT_SUB then return false end
    if res and res > 0 and not F.isVehicleRes(res) then return false end
    if res and res > 0 then return true end
    if (tonumber(PERSIST.lobbyVehicleIns) or 0) > 0 then return true end
    local L = _G.AddOutfitLobbyVeh
    if L and L.manual and ((tonumber(L.resID) or 0) > 0 or (tonumber(L.insID) or 0) > 0) then return true end
    return false
end

function F.shouldApplyLobbyFromConfig(silent)
    if not F.hasExplicitLobbyVehicle() then return false end
    local _, lobbyIns = F.resolveLobbyVehicle(PERSIST.configVehicleSlots)
    if not lobbyIns then return false end
    local cur = tonumber(DataMgr.vst_skin)
    if cur == lobbyIns then return false end
    return true
end

function F.reapplyVehicleSlotsFromConfig(silent)
    local slotMap = PERSIST.configVehicleSlots
    if not slotMap or not next(slotMap) then return false end
    if not F.applyVehicleSlotsFromConfigMap(slotMap) then return false end
    F.syncVehicleSlotsToDataMgr()
    F.notifyVehicleSlotUI()
    F.equipVehicleTypesFromConfig(slotMap)
    if F.shouldApplyLobbyFromConfig(silent) then
        local lobbyRes, lobbyIns = F.resolveLobbyVehicle(slotMap)
        if lobbyIns then
            F.applyLobbyVehicleDisplay(lobbyRes, lobbyIns, not silent)
        elseif not silent then
            pcall(F.applyVehicleSkinsToPC)
            F.perfInvalidateLobby()
        end
    end
    return true
end

function F.applyHallThemeDisplay(resID, insID)
    -- P23-FIX: OLD hall theme method (old/6.lua) - ProcPutOnHallTheme se glitch tha, on_puton_rsp use karo
    insID = tonumber(insID)
    resID = tonumber(resID)
    if not insID or not resID then return false end
    if not F.isInjectedIns(insID) then return false end
    if not F.isHallThemeRes(resID) then return false end
    if not F.isResourcesReady(resID) then
        F.requestResourceDownload(resID)
        -- old me bina resource check ke bhi on_puton_rsp chalta tha taaki lobby me turant lage; yahi rakho:
    end
    local item = { res_id = resID, count = 1, instid = insID }
    _G.AddOutfitApplyingTheme = true
    pcall(function()
        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
        -- old signature: on_puton_rsp(NET_OK, item, nil, 1, insID, 0)
        wl:on_puton_rsp(NET_OK, item, nil, 1, insID, 0)
    end)
    -- fallback: agar wardrobe_new na mile to hall_theme_utils (glitch kam ho)
    pcall(function()
        local HT = require("client.logic.lobby.hall_theme_utils")
        -- sirf display sync ke liye, logic_wardrobe_new already laga chuka hai
        if HT and HT.GetThemeInstId and tonumber(HT.GetThemeInstId()) ~= insID then
            -- old me direct Proc nahi tha, isliye yaha kuch nahi karte (glitch fix)
        end
    end)
    _G.AddOutfitApplyingTheme = false
    local cch = F.cache()
    cch.hallThemeRes, cch.hallThemeIns = resID, insID
    return true
end

function F.setHallThemeManual(resID, insID)
    insID = tonumber(insID)
    resID = tonumber(resID)
    if not insID or not F.isInjectedIns(insID) then return end
    if not resID then resID = R.insToRes[insID] end
    _G.AddOutfitLobbyTheme = _G.AddOutfitLobbyTheme or {}
    _G.AddOutfitLobbyTheme.manual = true
    _G.AddOutfitLobbyTheme.resID = resID
    _G.AddOutfitLobbyTheme.insID = insID
    PERSIST.hallThemeResID = resID
    PERSIST.hallThemeIns = insID
    local cch = F.cache()
    cch.hallThemeRes, cch.hallThemeIns = resID, insID
    F.persistMarkDirty()
end

function F.resolveHallTheme()
    local L = _G.AddOutfitLobbyTheme or {}
    local res = tonumber(PERSIST.hallThemeResID) or tonumber(L.resID)
    if res and R.resToIns[res] then return res, R.resToIns[res] end
    local ins = tonumber(PERSIST.hallThemeIns) or tonumber(L.insID)
    if ins and F.isInjectedIns(ins) then return R.insToRes[ins], ins end
    return nil, nil
end

function F.shouldApplyHallThemeFromConfig(silent)
    local _, ins = F.resolveHallTheme()
    if not ins then return false end
    local cur = nil
    pcall(function()
        local HT = require("client.logic.lobby.hall_theme_utils")
        cur = tonumber(HT.GetThemeInstId())
    end)
    if cur == ins then return false end
    if _G.AddOutfitLobbyTheme and _G.AddOutfitLobbyTheme.manual then return true end
    if silent and cur and cur > 0 and F.isInjectedIns(cur) then return false end
    return true
end

function F.putOnHallTheme(insID)
    insID = tonumber(insID)
    if not insID or not F.isInjectedIns(insID) then return false end
    local resID = R.insToRes[insID]
    if F.applyHallThemeDisplay(resID, insID) then
        F.setHallThemeManual(resID, insID)
        return true
    end
    return false
end

function F.reapplyHallThemeFromConfig(silent)
    if not F.shouldApplyHallThemeFromConfig(silent) then return false end
    local res, ins = F.resolveHallTheme()
    if not res or not ins then return false end
    return F.applyHallThemeDisplay(res, ins)
end

function F.syncVehicleCacheFromDataMgr()
    local cch = F.cache()
    cch.vehicleSlots = cch.vehicleSlots or {}
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    for subType, slots in pairs(DataMgr.VehicleSlotList or {}) do
        subType = tonumber(subType)
        if subType and type(slots) == "table" then
            cch.vehicleSlots[subType] = cch.vehicleSlots[subType] or {}
            for idx, insID in pairs(slots) do
                idx, insID = tonumber(idx), tonumber(insID)
                if idx and insID and insID > 0 then
                    local res = R.insToRes[insID]
                    if not res then
                        pcall(function()
                            local d = wd:GetHallDepotItemDataByInsID(insID)
                            res = d and tonumber(d.resID)
                        end)
                    end
                    if res and res > 0 then
                        cch.vehicleSlots[subType][idx] = { resID = res, insID = insID }
                    end
                end
            end
        end
    end
end

function F.vehicleSubType(resID)
    local c = F.cfg(resID)
    return c and (c.ItemSubType or c.itemSubType)
end

-- Combat vehicle slots key by base vehicle ItemSubType (not skin-only / wrong table values)
function F.vehicleSlotSubType(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return nil end
    if F.isChassisLightId and F.isChassisLightId(resID) then return nil end

    local function validSt(st)
        st = tonumber(st)
        if not st or st == CHASSIS_LIGHT_SUB then return nil end
        if st >= 2200 and st < 2300 then return nil end -- emote, not vehicle
        if (st >= 900 and st < 2000) or (st >= 9100 and st < 10000) or st == 1101 then return st end
        return nil
    end
    if resID >= 12200000 and resID < 12300000 then return nil end

    -- 1) Subtype of original/base vehicle (VehiclePlaneSkinMapping)
    local orig = F.vehicleOriginalID and F.vehicleOriginalID(resID) or resID
    local st = validSt(F.vehicleSubType(orig))
    if st then return st end

    -- 2) Match DataMgr.defaultVehicleSkinResIDTable by original/default id
    pcall(function()
        local t = DataMgr and DataMgr.defaultVehicleSkinResIDTable
        if type(t) ~= "table" then return end
        for sub, defRes in pairs(t) do
            defRes = tonumber(defRes)
            if defRes and (defRes == orig or defRes == resID) then
                st = validSt(sub)
                if st then return end
            end
        end
    end)
    if st then return st end

    -- 2b) wardrobe_macro.DefaultVehiclesId (901=Moto, 907=Buggy, ...)
    pcall(function()
        local wm = require("client.slua.umg.Wardrobe.wardrobe_macro")
        local t = wm and wm.DefaultVehiclesId
        if type(t) ~= "table" then return end
        for sub, defRes in pairs(t) do
            defRes = tonumber(defRes)
            if defRes and (defRes == orig or defRes == resID) then
                st = validSt(sub)
                if st then return end
            end
        end
    end)
    if st then return st end

    -- 3) Fallback: skin's own ItemSubType
    st = validSt(F.vehicleSubType(resID))
    if st then return st end

    -- 4) Shape -> default skin -> subtype
    pcall(function()
        local UAvatarUtils = import("AvatarUtils")
        local shape = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(resID))
        if not shape or shape < 0 then return end
        local function matchTable(t)
            if type(t) ~= "table" then return end
            for sub, defRes in pairs(t) do
                defRes = tonumber(defRes)
                if defRes and defRes > 0 then
                    local s = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(defRes))
                    if s == shape then
                        st = validSt(sub)
                        if st then return true end
                    end
                end
            end
        end
        if matchTable(DataMgr and DataMgr.defaultVehicleSkinResIDTable) then return end
        local wm = require("client.slua.umg.Wardrobe.wardrobe_macro")
        matchTable(wm and wm.DefaultVehiclesId)
    end)
    return st
end

-- Wardrobe vehicle sub-tab (may be number or string enum). Never treat missing as "all tabs".
function F.tabsEqual(a, b)
    if a == b then return true end
    if a == nil or b == nil then return false end
    local na, nb = tonumber(a), tonumber(b)
    if na and nb then return na == nb end
    return tostring(a) == tostring(b)
end

function F.vehicleWardrobeTab(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return nil end
    local function fromCfg(id)
        local c = F.cfg(id)
        if not c then return nil end
        local t = c.WardrobeTab
        if t == nil or t == 0 or t == "" then return nil end
        return t
    end
    local tab = fromCfg(resID)
    if tab ~= nil then return tab end
    local orig = F.vehicleOriginalID(resID) or resID
    if tonumber(orig) ~= resID then
        tab = fromCfg(orig)
        if tab ~= nil then return tab end
    end
    local st = tonumber(F.vehicleSlotSubType(resID) or F.vehicleSubType(resID))
    if st then
        pcall(function()
            local TabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
            local wt = TabSurveillance.GetWardrobeTabByItemSubType(st)
            if wt ~= nil and wt ~= "" then tab = wt end
        end)
        if tab ~= nil then return tab end
        pcall(function()
            local wm = require("client.slua.umg.Wardrobe.wardrobe_macro")
            local def = wm and wm.DefaultVehiclesId and wm.DefaultVehiclesId[st]
            if def then tab = fromCfg(tonumber(def)) end
        end)
    end
    return tab
end

function F.fixInjectedVehicleDepotTabs(entity)
    entity = entity or F.getEntity()
    if not entity or not entity._data then return end
    for i = 1, (entity._DataCount or #entity._data) do
        local d = entity._data[i]
        if d then
            local res = tonumber(d.resID or d.res_id)
            if res and F.isInjectedRes(res) and F.isVehicleRes(res) then
                local c = F.cfg(res)
                local mainCfg = tonumber(c and c.WardrobeMainTab)
                -- Plane/wingman thuộc trang Parachute — không ép sang trang Xe
                if mainCfg == PAGE_PARACHUTE then
                    d.mainTabType = PAGE_PARACHUTE
                    local tab = (c and c.WardrobeTab) or F.wardrobeTab(res)
                    if tab and tab ~= 0 and tab ~= "" then d.subTabType = tab end
                else
                    local tab = F.vehicleWardrobeTab(res)
                    if tab ~= nil and tab ~= 0 and tab ~= "" then
                        d.subTabType = tab
                        d.mainTabType = PAGE_VEHICLE
                    end
                    local st = F.vehicleSlotSubType(res)
                    if st then d.itemSubType = st end
                end
            end
        end
    end
end

-- Khôi phục emote bị ghi nhầm tab (xe / avatar). Hành động nằm ở trang Parachute (5).
function F.fixInjectedEmoteDepotTabs(entity)
    entity = entity or F.getEntity()
    if not entity or not entity._data then return end
    local MOTION_TAB = 21 -- ENUM_WardrobeSubTabString_character_MVP_MOTION
    for i = 1, (entity._DataCount or #entity._data) do
        local d = entity._data[i]
        if d then
            local res = tonumber(d.resID or d.res_id)
            if res and F.isInjectedRes(res) and F.isEmoteRes(res) then
                local c = F.cfg(res)
                local main = tonumber(c and c.WardrobeMainTab) or PAGE_PARACHUTE
                local tab = c and c.WardrobeTab
                if tab == nil or tab == 0 or tab == "" then
                    tab = F.wardrobeTab(res)
                end
                if tab == nil or tab == 0 or tab == "" then tab = MOTION_TAB end
                d.mainTabType = main
                d.subTabType = tab
                if d.resID == nil and d.res_id ~= nil then d.resID = res end
                if c and c.ItemSubType then d.itemSubType = c.ItemSubType end
                if c and c.ItemType then d.itemType = c.ItemType end
                d.expire_ts = 0
                d.expireTS = 0
            end
        end
    end
end
-- Khôi phục dù/glider (trang Parachute) nếu bị ghi nhầm tab/expire
function F.fixInjectedParachuteDepotTabs(entity)
    entity = entity or F.getEntity()
    if not entity or not entity._data then return end
    for i = 1, (entity._DataCount or #entity._data) do
        local d = entity._data[i]
        if d then
            local res = tonumber(d.resID or d.res_id)
            if res and F.isInjectedRes(res) and (F.isParachuteRes(res) or F.isGlideRes(res)) then
                local c = F.cfg(res)
                d.mainTabType = tonumber(c and c.WardrobeMainTab) or PAGE_PARACHUTE
                local tab = (c and c.WardrobeTab) or F.wardrobeTab(res)
                if tab and tab ~= 0 and tab ~= "" then d.subTabType = tab end
                if d.resID == nil then d.resID = res end
                d.expire_ts = 0
                d.expireTS = 0
            end
        end
    end
end
function F.modifyInjectedVehicleSlot(insID, slotIndex, equip)
    insID = tonumber(insID)
    slotIndex = tonumber(slotIndex)
    if not insID or not slotIndex then return false end
    local resID = R.insToRes[insID]
    if not resID and insID >= INS_BASE then
        pcall(function()
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d = wd:GetHallDepotItemDataByInsID(insID)
            resID = d and tonumber(d.resID or d.res_id)
        end)
    end
    if not resID then return false end
    if not F.isVehicleRes(resID) then return false end
    local st = F.vehicleSlotSubType(resID)
    if not st then return false end
    local cch = F.cache()
    cch.vehicleSlots = cch.vehicleSlots or {}
    cch.vehicleSlots[st] = cch.vehicleSlots[st] or {}
    if equip then
        for _, slots in pairs(cch.vehicleSlots) do
            for i, e in pairs(slots) do
                if e and tonumber(e.insID) == insID then slots[i] = nil end
            end
        end
        cch.vehicleSlots[st][slotIndex] = { resID = resID, insID = insID }
        PERSIST.configVehicleSlots = PERSIST.configVehicleSlots or {}
        PERSIST.configVehicleSlots[st] = PERSIST.configVehicleSlots[st] or {}
        PERSIST.configVehicleSlots[st][slotIndex] = resID
    else
        local e = cch.vehicleSlots[st][slotIndex]
        if e and tonumber(e.insID) == insID then
            cch.vehicleSlots[st][slotIndex] = nil
            if PERSIST.configVehicleSlots and PERSIST.configVehicleSlots[st] then
                PERSIST.configVehicleSlots[st][slotIndex] = nil
            end
        end
    end
    F.syncVehicleSlotsToDataMgr()
    if equip and slotIndex == 1 then
        DataMgr.vehicleSkinInsIDTable = DataMgr.vehicleSkinInsIDTable or {}
        DataMgr.vehicleSkinInsIDTable[st] = insID
        pcall(function()
            local TabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
            TabSurveillance.VehicleChange()
        end)
    end
    F.persistMarkDirty()
    F.notifyVehicleSlotUI()
    return true
end

function F.buildVstInBattleFromSlots()
    local vst = {}
    local function insToRes(insID)
        insID = tonumber(insID)
        if not insID or insID <= 0 then return nil end
        local res = R.insToRes[insID]
        if res and res > 0 then return res end
        pcall(function()
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d = wd:GetHallDepotItemDataByInsID(insID)
            res = d and tonumber(d.resID)
        end)
        if res and res > 0 then return res end
        if insID >= 1000000 and F.cfg(insID) then return insID end
        return nil
    end
    local function fillFromSlots(subType, slots)
        subType = tonumber(subType)
        if not subType or type(slots) ~= "table" then return end
        local resList = {}
        for idx = 1, 8 do
            local val = slots[idx] or slots[tostring(idx)]
            local res = insToRes(val)
            if not res and type(val) == "table" then
                res = tonumber(val.resID or val.res_id)
            end
            if res and res > 0 then resList[#resList + 1] = res end
        end
        if #resList > 0 then vst[subType] = resList end
    end
    for subType, slots in pairs(DataMgr.VehicleSlotList or {}) do
        fillFromSlots(subType, slots)
    end
    if not next(vst) then
        local cch = F.cache()
        for subType, slots in pairs(cch.vehicleSlots or {}) do
            local resList = {}
            for idx = 1, 8 do
                local e = slots[idx]
                local res = e and tonumber(e.resID)
                if res and res > 0 then resList[#resList + 1] = res end
            end
            if #resList > 0 then vst[tonumber(subType)] = resList end
        end
    end
    if not next(vst) then
        local bySub = {}
        for res, _ in pairs(R.resToIns) do
            res = tonumber(res)
            local c = F.cfg(res)
            local st = c and tonumber(F.subType(c))
            if res and st and st >= 900 then
                bySub[st] = bySub[st] or {}
                bySub[st][#bySub[st] + 1] = res
            end
        end
        for st, list in pairs(bySub) do
            table.sort(list)
            vst[st] = list
        end
    end
    return vst
end

function F.isVehicleSkinAllowed(skinId)
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 then return false end
    if F.isInjectedRes(skinId) then return true end
    for _, list in pairs(F.buildVstInBattleFromSlots()) do
        for _, res in ipairs(list or {}) do
            if tonumber(res) == skinId then return true end
        end
    end
    return false
end
function F.isSkinInVehiclePCList(skinId)
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 then return false end
    local pc = F.getPC()
    if not slua.isValid(pc) or not pc.VehicleAvatarSkinList then return false end
    local UAvatarUtils = import("AvatarUtils")
    local shape = UAvatarUtils.GetVehicleShapeBySkinID(skinId)
    if shape and shape >= 0 then
        local entry = pc.VehicleAvatarSkinList:Get(shape)
        if entry and entry.SkinList then
            for _, id in pairs(entry.SkinList) do
                if tonumber(id) == skinId then return true end
            end
        end
    end
    return false
end

function F.shouldHandleVehicleSkinClick(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    return F.isVehicleSkinAllowed(resID) or F.isSkinInVehiclePCList(resID)
end

function F.getMatchVehicle()
    local found = nil
    pcall(function()
        local subs = SubsystemMgr:Get("VehicleControlUISubSystem")
        if subs and subs.GetVehicleUserComponent then
            local uuc = subs:GetVehicleUserComponent()
            if slua.isValid(uuc) and slua.isValid(uuc.Vehicle) then found = uuc.Vehicle end
        end
    end)
    if slua.isValid(found) then return found end
    local pc = F.getPC()
    if slua.isValid(pc) and pc.GetPlayerCharacterSafety then
        local char = pc:GetPlayerCharacterSafety()
        if slua.isValid(char) then
            if char.GetCurrentVehicle then
                local v = char:GetCurrentVehicle()
                if slua.isValid(v) then return v end
            end
            if char.CurrentVehicle and slua.isValid(char.CurrentVehicle) then
                return char.CurrentVehicle
            end
        end
    end
    return nil
end

function F.applyClientVehicleSkin(skinId, vehicle, pc)
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 then return false end
    pc = pc or F.getPC()
    vehicle = vehicle or F.getMatchVehicle()
    if not slua.isValid(vehicle) then return false end

    local UAvatarUtils = import("AvatarUtils")
    pcall(function()
        if slua.isValid(pc) then
            pc.ShowVehicleSkin = skinId
            local shapeType = UAvatarUtils.GetVehicleShapeBySkinID(skinId)
            if shapeType and shapeType >= 0 and pc.VehicleAvatarList then
                pc.VehicleAvatarList:Add(shapeType, skinId)
            end
        end
    end)

    local applied = false
    local av = nil
    pcall(function()
        if vehicle.GetAvatarComponent then av = vehicle:GetAvatarComponent() end
        if not slua.isValid(av) then av = vehicle.VehicleAvatarComponent_BP end
    end)

    if slua.isValid(av) then
        pcall(function() if av.bIsLobbyAvatar ~= nil then av.bIsLobbyAvatar = false end end)
        pcall(function() if av.CanChangeAvatar ~= nil then av.CanChangeAvatar = true end end)
        pcall(function()
            if slua.isValid(pc) and av.SetVehicleNetAvatarData then
                av:SetVehicleNetAvatarData(pc)
            end
        end)
        pcall(function()
            if av.ChangeItemAvatar then
                av:ChangeItemAvatar(skinId, false)
                applied = true
            elseif av.PreChangeVehicleAvatar then
                av:PreChangeVehicleAvatar(skinId)
                applied = true
            end
        end)
        pcall(function()
            if av.PostChangeItemAvatar then av:PostChangeItemAvatar(false) end
        end)
    end

    pcall(function()
        local battleCls = import("VehicleAvatarComponentBattleBase")
        local battleAv = vehicle:GetComponentByClass(battleCls)
        if slua.isValid(battleAv) then
            if battleAv.ChangeVehicleAvatar then
                battleAv:ChangeVehicleAvatar(skinId, false)
                applied = true
            end
            pcall(function()
                local VehiclePlateLicenseUtil = require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
                local uid = pc and pc.PlayerUID or 0
                local bTire = VehiclePlateLicenseUtil.NeedOpenHighTire(tonumber(uid), skinId)
                if battleAv.PreChangeHighTireLight then
                    battleAv:PreChangeHighTireLight(skinId, bTire)
                end
            end)
        end
    end)

    pcall(function()
        if vehicle.ChangeVehicleAvatar and slua.isValid(pc) then
            vehicle:ChangeVehicleAvatar(pc)
            applied = true
        end
    end)

    pcall(function() if vehicle.ForceNetUpdate then vehicle:ForceNetUpdate() end end)
    pcall(function() if slua.isValid(pc) and pc.ForceNetUpdate then pc:ForceNetUpdate() end end)
    return applied
end

function F.getVehicleSkinIds()
    local out, seen = {}, {}
    local function add(res)
        res = tonumber(res)
        if res and res > 0 and not seen[res] then
            seen[res] = true
            out[#out + 1] = res
        end
    end
    for _, list in pairs(F.buildVstInBattleFromSlots()) do
        for _, res in ipairs(list) do add(res) end
    end
    for res in pairs(R.resToIns) do
        local c = F.cfg(tonumber(res))
        local st = c and tonumber(F.subType(c))
        if st and st >= 900 then add(res) end
    end
    return out
end
function F.buildVehVst(skinIds)
    local bySub = {}
    for _, skinId in ipairs(skinIds or {}) do
        local subType = 961
        local ok, c = pcall(function() return CDataTable.GetTableData("Item", skinId) end)
        if ok and c and c.ItemSubType then subType = c.ItemSubType end
        bySub[subType] = bySub[subType] or {}
        bySub[subType][#bySub[subType] + 1] = skinId
    end
    return bySub
end

function F.directInjectVehicleSkinList(pc, skinIds)
    if not slua.isValid(pc) or not pc.VehicleAvatarSkinList then return end
    local UAvatarUtils = import("AvatarUtils")
    for _, skinId in ipairs(skinIds or {}) do
        local shapeType = nil
        pcall(function() shapeType = UAvatarUtils.GetVehicleShapeBySkinID(skinId) end)
        if shapeType and shapeType >= 0 then
            pcall(function() pc.VehicleAvatarList:Add(shapeType, skinId) end)
            local entry = pc.VehicleAvatarSkinList:Get(shapeType)
            if entry and entry.SkinList then
                pcall(function() entry.SkinList:Add(skinId) end)
            end
        end
    end
end

function F.mergeVstIntoPlayerInfo(playerInfo)
    if not playerInfo then return end
    F.syncVehicleCacheFromDataMgr()
    local vst = F.buildVehVst(F.getVehicleSkinIds())
    if not next(vst) then return end
    playerInfo.vst_in_battle = playerInfo.vst_in_battle or {}
    for subType, list in pairs(vst) do
        playerInfo.vst_in_battle[subType] = list
    end
    local first
    for _, list in pairs(vst) do first = list[1]; break end
    if first and first > 0 then playerInfo.vst_skin = first end
end

function F.applyVehicleSkinsToPC(pc)
    pc = pc or F.getPC()
    if not slua.isValid(pc) then return false end
    local skinIds = F.getVehicleSkinIds()
    if #skinIds == 0 then return false end
    local vst = F.buildVehVst(skinIds)
    local avatarList, avatarSkinList = {}, {}
    for _, skinList in pairs(vst) do
        local itemArray = {}
        for _, resid in ipairs(skinList) do
            if resid and resid > 0 then
                itemArray[#itemArray + 1] = { ItemTableID = resid, Count = 1 }
                avatarList[#avatarList + 1] = { ItemTableID = resid, Count = 1 }
            end
        end
        if #itemArray > 0 then
            avatarSkinList[#avatarSkinList + 1] = { Items = itemArray }
        end
    end
    pcall(function() pc.bEnableFuzzyAvatarOnClient = false end)
    pcall(function() pc.ShowVehicleSkin = skinIds[1] end)
    if #avatarList > 0 then
        pcall(function()
            pc.InitialVehicleAvatarList = avatarList
            pc:InitVehicleAvatarList()
        end)
    end
    if #avatarSkinList > 0 then
        pcall(function()
            pc.InitialVehicleAvatarSkinList = avatarSkinList
            pc:InitVehicleAvatarSkinList()
        end)
    end
    F.directInjectVehicleSkinList(pc, skinIds)
    pcall(function() F.applyVehiclePartDataToPC(pc, skinIds[1]) end)
    return true
end
function F.serverChangeVehicleAvatar(skinId, pc)
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 then return false end
    pc = pc or F.getPC()
    if not slua.isValid(pc) then return false end

    F.applyVehicleSkinsToPC(pc)

    pcall(function()
        pc.ShowVehicleSkin = skinId
        local UAvatarUtils = import("AvatarUtils")
        local shapeType = UAvatarUtils.GetVehicleShapeBySkinID(skinId)
        if shapeType and shapeType >= 0 and pc.VehicleAvatarList then
            pc.VehicleAvatarList:Add(shapeType, skinId)
        end
        F.directInjectVehicleSkinList(pc, { skinId })
    end)

    local ok = false
    pcall(function()
        if pc.ServerChangeVehicleAvatar then
            pc:ServerChangeVehicleAvatar(skinId)
            ok = true
        end
    end)

    pcall(function()
        if pc.PlayerState and slua.isValid(pc.PlayerState) then
            pc.PlayerState.nVst_skin = skinId
        end
    end)

    pcall(function() pc:ForceNetUpdate() end)
    return ok
end

_G.AddOutfitVehSel = _G.AddOutfitVehSel or { override = nil, overrideVehicle = nil, byShape = {} }
local VEHSEL = _G.AddOutfitVehSel
_G.AddOutfitLobbyVeh = _G.AddOutfitLobbyVeh or { manual = false, subType = nil, resID = nil, insID = nil }
local _vehTickLastApply = 0
local VEH_SWITCH_EFFECT_ID = 7303001

function F.prepVehicleSwitchEffect(av, vehicle)
    if not slua.isValid(av) then return end
    if not F.isInRealMatch() then
        pcall(function() av.curSwitchEffectId = 0 end)
        return
    end
    pcall(function()
        local effectId = VEH_SWITCH_EFFECT_ID
        local m = PERSIST.configVehicleMod
        if m and tonumber(m.switchEffect) and tonumber(m.switchEffect) > 0 then
            effectId = tonumber(m.switchEffect)
        else
            pcall(function()
                local LVF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
                if LVF and tonumber(LVF.equip_switch_effect) and tonumber(LVF.equip_switch_effect) > 0 then
                    effectId = tonumber(LVF.equip_switch_effect)
                end
            end)
        end
        av.curSwitchEffectId = effectId
        F.requestResourceDownload(effectId)
        local defaultId = 0
        pcall(function() defaultId = tonumber(av:GetDefaultAvatarID()) or 0 end)
        local curId = 0
        if slua.isValid(vehicle) then
            pcall(function() curId = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId()) or 0 end)
            if curId <= 0 then
                pcall(function() curId = tonumber(vehicle.ClientUsedAvatarID) or 0 end)
            end
        end
        if curId <= 0 then curId = defaultId end
        if not av.lastEquipedAvatarId or av.lastEquipedAvatarId <= 0 then
            av.lastEquipedAvatarId = curId > 0 and curId or defaultId
        end
    end)
end

-- Slot: BrakeCaliper=1, Canopy=3 — WheelHub (2) bỏ apply trong trận (không ổn định / gây lag)
function F.getVehiclePartSlots()
    local brake, canopy = 1, 3
    pcall(function()
        local E = import("EVehiclePartSlot")
        if not E then return end
        brake = E.BrakeCaliper or E.EVehiclePartSlot__BrakeCaliper or brake
        canopy = E.Canopy or E.EVehiclePartSlot__Canopy or canopy
    end)
    return brake, canopy
end

-- Chỉ brake + canopy (không vành)
function F.getDesiredMultiSlotPartsForSkin(skinId)
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 then return {} end
    pcall(F.applyVehicleModPersistToLVF)
    local m = F.vehicleModPersist and F.vehicleModPersist() or (PERSIST.configVehicleMod or {})
    local LVF = nil
    pcall(function()
        LVF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
    end)
    local SLOT_BRAKE, SLOT_CANOPY = F.getVehiclePartSlots()
    local brakeMap = F.expandVehicleFeatureMap and F.expandVehicleFeatureMap(m.brakeCaliper) or (m.brakeCaliper or {})
    local canopyMap = F.expandVehicleFeatureMap and F.expandVehicleFeatureMap(m.canopy) or (m.canopy or {})
    local function pick(mapPersist, mapLvf)
        local id = mapPersist and tonumber(mapPersist[skinId])
        if id and id > 0 then return id end
        id = mapLvf and tonumber(mapLvf[skinId])
        if id and id > 0 then return id end
        local gid = nil
        pcall(function()
            local cfg = CDataTable.GetTableData("VehicleRefitInfo", skinId)
            gid = cfg and tonumber(cfg.vehicle_group_id)
        end)
        if not gid then return nil end
        local function scan(map)
            if type(map) ~= "table" then return nil end
            for vid, resid in pairs(map) do
                vid, resid = tonumber(vid), tonumber(resid)
                if vid and resid and resid > 0 then
                    local ok, g2 = pcall(function()
                        local c = CDataTable.GetTableData("VehicleRefitInfo", vid)
                        return c and tonumber(c.vehicle_group_id)
                    end)
                    if ok and g2 == gid then return resid end
                end
            end
            return nil
        end
        return scan(mapPersist) or scan(mapLvf)
    end
    local brake = pick(brakeMap, LVF and LVF.equip_brake_caliper)
    local canopy = pick(canopyMap, LVF and LVF.equip_sunroof)
    local parts = {}
    if brake then parts[SLOT_BRAKE] = brake; parts[1] = brake end
    if canopy then parts[SLOT_CANOPY] = canopy; parts[3] = canopy end
    return parts
end

function F.getDesiredRefitStyleListForSkin(skinId)
    skinId = tonumber(skinId)
    if not skinId then return {} end
    pcall(F.applyVehicleModPersistToVRH)
    -- Map persist theo vehicle_group nếu skinId khác level với key đã lưu
    pcall(function()
        local m = F.vehicleModPersist and F.vehicleModPersist() or PERSIST.configVehicleMod
        if not m or type(m.refit) ~= "table" or m.refit[skinId] then return end
        local gid = nil
        pcall(function()
            local cfg = CDataTable.GetTableData("VehicleRefitInfo", skinId)
            gid = cfg and tonumber(cfg.vehicle_group_id)
        end)
        if not gid then return end
        for vid, st in pairs(m.refit) do
            local g2 = nil
            pcall(function()
                local c = CDataTable.GetTableData("VehicleRefitInfo", tonumber(vid))
                g2 = c and tonumber(c.vehicle_group_id)
            end)
            if g2 == gid and type(st) == "table" then
                local VRH = require("client.network.Protocol.VehicleRefitHandler")
                if VRH then
                    VRH.resCarInfoList = VRH.resCarInfoList or {}
                    VRH.resCarInfoList.car_list = VRH.resCarInfoList.car_list or {}
                    VRH.resCarInfoList.car_list[skinId] = VRH.resCarInfoList.car_list[skinId] or {}
                    for partId, styleId in pairs(st) do
                        partId, styleId = tonumber(partId) or partId, tonumber(styleId)
                        if styleId then VRH.resCarInfoList.car_list[skinId][partId] = styleId end
                    end
                end
                break
            end
        end
    end)
    local list = {}
    pcall(function()
        local VRH = require("client.network.Protocol.VehicleRefitHandler")
        local fromHandler = VRH and VRH.GetCarStyleList and VRH.GetCarStyleList(skinId)
        if type(fromHandler) == "table" then
            for _, sid in ipairs(fromHandler) do
                sid = tonumber(sid)
                if sid and sid > 0 then list[#list + 1] = sid end
            end
        end
    end)
    if #list > 0 then return list end
    local m = PERSIST.configVehicleMod
    local styles = m and m.refit and m.refit[skinId]
    if type(styles) == "table" then
        for _, sid in pairs(styles) do
            sid = tonumber(sid)
            if sid and sid > 0 then list[#list + 1] = sid end
        end
    end
    return list
end

function F.getDesiredVehicleModChassisLight(skinId)
    skinId = tonumber(skinId)
    if not skinId then return nil end
    local m = F.vehicleModPersist and F.vehicleModPersist() or PERSIST.configVehicleMod
    local id = m and m.chassisLight and tonumber(m.chassisLight[skinId])
    if id and id > 0 then return id end
    pcall(function()
        local LVF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
        if LVF and LVF.equip_chassis_light then
            id = tonumber(LVF.equip_chassis_light[skinId])
        end
    end)
    if id and id > 0 then return id end
    local gid = nil
    pcall(function()
        local cfg = CDataTable.GetTableData("VehicleRefitInfo", skinId)
        gid = cfg and tonumber(cfg.vehicle_group_id)
    end)
    if gid and m and type(m.chassisLight) == "table" then
        for vid, resid in pairs(m.chassisLight) do
            vid, resid = tonumber(vid), tonumber(resid)
            if vid and resid and resid > 0 then
                local g2 = nil
                pcall(function()
                    local c = CDataTable.GetTableData("VehicleRefitInfo", vid)
                    g2 = c and tonumber(c.vehicle_group_id)
                end)
                if g2 == gid then return resid end
            end
        end
    end
    local map = PERSIST.configChassisLightMap
    id = map and tonumber(map[skinId])
    if id and id > 0 then return id end
    return nil
end

-- Apply brake/canopy/chassis/refit (không vành) — 1 lần trên 1 avatar comp
function F.applyVehicleModPartsToVehicle(vehicle, skinId)
    if not (F.vehicleModUnlockOn and F.vehicleModUnlockOn()) then return false end
    if not slua.isValid(vehicle) then return false end
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 then
        pcall(function() skinId = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId()) end)
    end
    if not skinId or skinId <= 0 then
        pcall(function() skinId = tonumber(vehicle.ClientUsedAvatarID) end)
    end
    if not skinId or skinId <= 0 then return false end

    local parts = F.getDesiredMultiSlotPartsForSkin(skinId)
    local av = F.getVehicleAvatarComp(vehicle)
    local applied = false
    if next(parts) and slua.isValid(av) then
        pcall(function() av.bEnableMultiSlot = true end)
        pcall(function()
            if av.SetLobbyMultiSlotEquipData then av:SetLobbyMultiSlotEquipData(parts) end
        end)
        pcall(function()
            if av.SetNetMultiSlotData then av:SetNetMultiSlotData(parts); applied = true end
        end)
        pcall(function()
            if av.EquipSlots then av:EquipSlots(parts, false); applied = true end
        end)
        pcall(function() if av.ApplyMultiSlotMeshes then av:ApplyMultiSlotMeshes() end end)
    end
    local SLOT_BRAKE, SLOT_CANOPY = F.getVehiclePartSlots()
    pcall(function()
        local bid = parts[SLOT_BRAKE] or parts[1]
        if vehicle.SetBrakeCaliperShowData and bid then
            vehicle:SetBrakeCaliperShowData(bid); applied = true
        end
    end)
    pcall(function()
        local cid = parts[SLOT_CANOPY] or parts[3]
        if vehicle.SetCanopyShowData and cid then
            vehicle:SetCanopyShowData(cid); applied = true
        end
    end)
    pcall(function()
        local lightId = F.getDesiredVehicleModChassisLight(skinId)
        if lightId and lightId > 0 then
            F.applyVehicleChassisLight(vehicle, skinId, lightId)
            applied = true
        end
    end)
    return applied
end

function F.scheduleVehicleModPartsApply(vehicle, skinId)
    skinId = tonumber(skinId)
    local vref = slua.isValid(vehicle) and vehicle or nil
    local function try()
        local v = slua.isValid(vref) and vref or F.getCurrentVehicleForSkin()
        if not slua.isValid(v) then return end
        local sid = skinId
        if not sid or sid <= 0 then
            pcall(function() sid = tonumber(v.GetAvatarId and v:GetAvatarId()) end)
        end
        F.applyVehicleModPartsToVehicle(v, sid)
    end
    -- Chỉ 1 retry sau khi mesh sẵn — tránh spam timer
    F.later(0.8, try)
end

function F.isParachuteRes(resID)
    return F.subType(F.cfg(tonumber(resID))) == PARACHUTE_SUB
end

function F.isGlideRes(resID)
    resID = tonumber(resID)
    if not resID then return false end
    local st = F.subType(F.cfg(resID))
    if GLIDER_SUBS[st] then return true end
    local ok, r = pcall(function()
        local MDH = require("client.logic.avatar.ModelDisplayTypeHelper")
        if MDH.IsGlideByItemID and MDH.IsGlideByItemID(resID) then return true end
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        return wd.IsGlideType(st)
    end)
    return ok and r == true
end

function F.vehicleOriginalID(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return nil end
    local original = nil
    pcall(function()
        local m = CDataTable and CDataTable.GetTableData
            and CDataTable.GetTableData("VehiclePlaneSkinMapping", resID)
        original = tonumber(m and (m.OrginalID or m.OriginalID))
    end)
    if original and original > 0 then return original end
    local st = tonumber(F.vehicleSubType(resID))
    if st and st >= 900 and st < 7000 then
        local def = nil
        pcall(function()
            def = tonumber(DataMgr.defaultVehicleSkinResIDTable and DataMgr.defaultVehicleSkinResIDTable[st])
        end)
        if def and def > 0 then return def end
        pcall(function()
            local wm = require("client.slua.umg.Wardrobe.wardrobe_macro")
            def = tonumber(wm and wm.DefaultVehiclesId and wm.DefaultVehiclesId[st])
        end)
        if def and def > 0 then return def end
    end
    return resID
end

function F.rememberVehicleSkinMap(resID, insID)
    resID = tonumber(resID)
    if not resID or not F.isVehicleRes(resID) then return end
    _G.AddOutfitLastVehicleSkinRes = resID
    local base = F.vehicleOriginalID(resID) or resID
    _G.VehicleSkinMap = _G.VehicleSkinMap or {}
    _G.VehicleSkinMap[base] = resID
    if tonumber(base) ~= resID then _G.VehicleSkinMap[resID] = resID end
    if insID then
        pcall(function()
            DataMgr.vst_skin = tonumber(insID)
            local st = F.vehicleSlotSubType(resID) or F.vehicleSubType(resID)
            DataMgr.vehicleSkinInsIDTable = DataMgr.vehicleSkinInsIDTable or {}
            if st then DataMgr.vehicleSkinInsIDTable[st] = tonumber(insID) end
        end)
    end
end

function F.resolveVehicleSkinForAvatar(defaultID)
    defaultID = tonumber(defaultID)
    if not defaultID or defaultID <= 0 then return nil end
    local base = F.vehicleOriginalID(defaultID) or defaultID
    local map = _G.VehicleSkinMap
    if map then
        local skin = tonumber(map[base]) or tonumber(map[defaultID]) or tonumber(map[tostring(base)])
        if skin and skin > 0 then return skin end
    end
    local lobby = tonumber(PERSIST.lobbyVehicleResID) or tonumber((_G.AddOutfitLobbyVeh or {}).resID)
        or tonumber(_G.AddOutfitLastVehicleSkinRes)
    if lobby and lobby > 0 then
        local lobbyBase = F.vehicleOriginalID(lobby) or lobby
        if lobbyBase == base or lobby == defaultID then return lobby end
    end
    return nil
end

function F.resolveLobbyVehicleSkinRes()
    local last = tonumber(_G.AddOutfitLastVehicleSkinRes)
        or tonumber(PERSIST.lobbyVehicleResID)
        or tonumber((_G.AddOutfitLobbyVeh or {}).resID)
    if last and last > 0 then return last end
    local res = F.resolveLobbyVehicle(PERSIST.configVehicleSlots)
    return tonumber(res)
end

function F.isVehicleRes(resID)
    resID = tonumber(resID)
    if not resID or F.isChassisLightId(resID) then return false end
    -- Emote ItemSubType 22xx nằm trong 900-7000 cũ → bị nhận nhầm là xe (mất khỏi kho đồ)
    if resID >= 12200000 and resID < 12300000 then return false end
    local c = F.cfg(resID)
    local itemType = tonumber(c and (c.ItemType or c.itemType))
    if itemType == 22 then return false end
    local st = tonumber(F.subType(c))
    if st and st >= 2200 and st < 2300 then return false end
    -- Vehicle subtypes: 9xx…, Wingman 1101, bus/sedan 91xx (không dùng <7000 rộng)
    if st and st ~= CHASSIS_LIGHT_SUB then
        if (st >= 900 and st < 2000) or (st >= 9100 and st < 10000) or st == 1101 then
            return true
        end
    end
    local ok, hasMap = pcall(function()
        return CDataTable and CDataTable.GetTableData
            and CDataTable.GetTableData("VehiclePlaneSkinMapping", resID) ~= nil
    end)
    return ok and hasMap == true
end

function F.ensureInjectedItemAlive(entity, resID, insID)
    entity = entity or F.getEntity()
    insID = tonumber(insID) or (resID and R.resToIns[tonumber(resID)])
    resID = tonumber(resID) or (insID and R.insToRes[insID])
    if not entity or not insID then return end
    pcall(function()
        local d = entity:GetDataByInsID(insID)
        if d then
            d.expire_ts = 0
            d.expireTS = 0
            d.valid_hours = 0
        end
    end)
end

function F.ensureAllInjectedAlive()
    local entity = F.getEntity()
    if not entity then return end
    for res, ins in pairs(R.resToIns) do
        F.ensureInjectedItemAlive(entity, res, ins)
    end
end

function F.putOnVehicle(insID)
    insID = tonumber(insID)
    if not insID then return false end
    local resID = R.insToRes[insID]
    if not resID or not F.isVehicleRes(resID) then return false end
    F.ensureInjectedItemAlive(nil, resID, insID)
    if not F.isResourcesReady(resID) then
        F.requestResourceDownload(resID)
        return false
    end
    local st = F.vehicleSlotSubType(resID) or F.vehicleSubType(resID)
    pcall(function()
        DataMgr.vst_skin = insID
        DataMgr.vehicleSkinInsIDTable = DataMgr.vehicleSkinInsIDTable or {}
        if st then DataMgr.vehicleSkinInsIDTable[st] = insID end
    end)
    local item = {
        res_id = resID, resID = resID,
        instid = insID, ins_id = insID, insID = insID,
        expire_ts = 0, expireTS = 0, count = 1,
    }
    pcall(function()
        local HT = require("client.logic.lobby.hall_theme_utils")
        HT.ProcPutOnVehicle(item, true)
        if HT.ShowThemeVehicle then HT.ShowThemeVehicle() end
    end)
    pcall(function()
        local WRH = require("client.network.Protocol.WardRobeHandler")
        WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
    end)
    F.setLobbyVehicleManual(st, resID, insID)
    F.rememberVehicleSkinMap(resID, insID)
    pcall(function()
        local TabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
        TabSurveillance.VehicleChange()
    end)
    pcall(function()
        if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_ITEM_LIST then
            EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
        end
    end)
    return true
end
function F.isChassisLightId(id)
    return CHASSIS_LIGHT_IDS[tonumber(id)] == true
end

function F.getDesiredChassisLight(vehicleSkinId)
    vehicleSkinId = tonumber(vehicleSkinId)
    if F.getDesiredVehicleModChassisLight then
        local fromMod = F.getDesiredVehicleModChassisLight(vehicleSkinId)
        if fromMod and fromMod > 0 then return fromMod end
    end
    local map = PERSIST.configChassisLightMap
    if vehicleSkinId and map and map[vehicleSkinId] then
        local v = tonumber(map[vehicleSkinId])
        if F.isChassisLightId(v) then return v end
    end
    local def = tonumber(PERSIST.configChassisLight) or DEFAULT_CHASSIS_LIGHT
    return F.isChassisLightId(def) and def or DEFAULT_CHASSIS_LIGHT
end

function F.saveChassisLight(vehicleSkinId, lightId)
    vehicleSkinId = tonumber(vehicleSkinId)
    lightId = tonumber(lightId)
    if not F.isChassisLightId(lightId) then return end
    PERSIST.configChassisLightMap = PERSIST.configChassisLightMap or {}
    if vehicleSkinId and vehicleSkinId > 0 then
        PERSIST.configChassisLightMap[vehicleSkinId] = lightId
    else
        PERSIST.configChassisLight = lightId
    end
    F.requestResourceDownload(lightId)
    F.persistMarkDirty()
end

function F.getVehicleLicenseComp(vehicle)
    if not slua.isValid(vehicle) then return nil end
    local lic = nil
    pcall(function()
        if vehicle.GetLicenseComponent then lic = vehicle:GetLicenseComponent() end
    end)
    if slua.isValid(lic) then return lic end
    pcall(function() lic = vehicle.BP_Lobby_VehicleLicenseComponent end)
    if slua.isValid(lic) then return lic end
    pcall(function()
        local cls = import("VehicleLicenseNumberComponent")
        lic = vehicle:GetComponentByClass(cls)
    end)
    return slua.isValid(lic) and lic or nil
end

function F.applyVehicleChassisLight(vehicle, skinId, lightId)
    -- ModSkin hoặc FreeLobbyShop (Vehicle Mod) đều được áp đèn gầm đã equip
    if not (F.vehicleModUnlockOn and F.vehicleModUnlockOn()) then
        if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModSkin == false then return false end
    end

    skinId = tonumber(skinId)
    lightId = tonumber(lightId) or F.getDesiredChassisLight(skinId)
    if not F.isChassisLightId(lightId) then return false end
    if not slua.isValid(vehicle) then return false end
    if skinId and skinId > 0 then
        F.requestResourceDownload(skinId)
    end
    F.requestResourceDownload(lightId)
    local applied = false
    pcall(function()
        if vehicle.SetChassisLightShowData then
            vehicle:SetChassisLightShowData(lightId)
            applied = true
        end
    end)
    local lic = F.getVehicleLicenseComp(vehicle)
    if not slua.isValid(lic) then return applied end
    pcall(function()
        local vid = skinId
        if not vid or vid <= 0 then
            pcall(function()
                if vehicle.GetAvatarId then vid = tonumber(vehicle:GetAvatarId()) end
            end)
        end
        if not vid or vid <= 0 then
            pcall(function() vid = tonumber(lic.LicensePlate and lic.LicensePlate.ItemID) end)
        end
        if vid and vid > 0 then
            lic.curVehicleAvatarId = vid
            if lic.ChangeNetData_ItemID then
                lic:ChangeNetData_ItemID(vid)
            elseif lic.LicensePlate then
                lic.LicensePlate.ItemID = vid
            end
        end
        if lic.LicensePlate then
            lic.LicensePlate.ChassisLightId = lightId
        end
        if lic.SetChassisLightData and vid and vid > 0 then
            lic:SetChassisLightData(vid, lightId)
        elseif lic.PreChangeChassisLight then
            lic:PreChangeChassisLight()
        end
        applied = true
    end)
    return applied
end

function F.scheduleChassisLightApply(vehicle, skinId)
    skinId = tonumber(skinId)
    local vref = slua.isValid(vehicle) and vehicle or nil
    local function try()
        local v = slua.isValid(vref) and vref or F.getCurrentVehicleForSkin()
        if slua.isValid(v) then
            F.applyVehicleChassisLight(v, skinId)
        end
    end
    F.later(0.4, try)
    F.later(1.1, try)
end

function F.getVehicleShape(vehicle)
    if not slua.isValid(vehicle) then return nil end
    local shape = vehicle.VehicleShapeType
    if shape and tonumber(shape) >= 0 then return tonumber(shape) end
    pcall(function()
        local UAvatarUtils = import("AvatarUtils")
        local defId = vehicle.AvatarDefaultCfg and vehicle.AvatarDefaultCfg.TypeSpecificID
        if defId and tonumber(defId) > 0 then
            shape = UAvatarUtils.GetVehicleShapeBySkinID(tonumber(defId))
        end
    end)
    return shape and tonumber(shape) >= 0 and tonumber(shape) or nil
end

function F.getDesiredVehicleSkinForShape(shape, defaultId)
    shape = tonumber(shape)
    if not shape or shape < 0 then return nil end
    F.syncVehicleCacheFromDataMgr()
    local UAvatarUtils = import("AvatarUtils")
    if defaultId then
        local mapped = F.resolveVehicleSkinForAvatar(defaultId)
        if mapped and mapped > 0 then return mapped end
    end
    local map = _G.VehicleSkinMap
    if map then
        for baseId, skin in pairs(map) do
            skin = tonumber(skin)
            if skin and skin > 0 then
                local s = nil
                pcall(function() s = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(skin)) end)
                if s == shape then return skin end
                local b = tonumber(baseId)
                if b then
                    pcall(function() s = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(b)) end)
                    if s == shape then return skin end
                end
            end
        end
    end
    local vst = F.buildVstInBattleFromSlots()
    for _, list in pairs(vst) do
        local skin = list and tonumber(list[1])
        if skin and skin > 0 then
            local s = UAvatarUtils.GetVehicleShapeBySkinID(skin)
            if s == shape then return skin end
        end
    end
    local pc = F.getPC()
    if slua.isValid(pc) and pc.VehicleAvatarList then
        local skin = tonumber(pc.VehicleAvatarList:Get(shape))
        if skin and skin > 0 then return skin end
    end
    return nil
end
function F.getVehicleAvatarComp(vehicle)
    if not slua.isValid(vehicle) then return nil end
    local av = nil
    pcall(function() av = vehicle.VehicleAvatar end)
    if slua.isValid(av) then return av end
    pcall(function() if vehicle.GetAvatarComponent then av = vehicle:GetAvatarComponent() end end)
    if slua.isValid(av) then return av end
    pcall(function() av = vehicle.VehicleAvatarComponent_BP end)
    if slua.isValid(av) then return av end
    return nil
end

function F.getCurrentVehicleForSkin()
    local char = F.getLocalChar()
    if char and slua.isValid(char) then
        local v = nil
        pcall(function() v = char.CurrentVehicle end)
        if slua.isValid(v) then return v end
    end
    return F.getMatchVehicle()
end

function F.forceVehicleAvatar(skinId, vehicle)
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 then return false end
    if not F.isResourcesReady(skinId) then
        F.requestResourceDownload(skinId)
        return false
    end
    vehicle = slua.isValid(vehicle) and vehicle or F.getCurrentVehicleForSkin()
    if not slua.isValid(vehicle) then return false end
    local av = F.getVehicleAvatarComp(vehicle)
    if not slua.isValid(av) then return false end
    local applied = false
    F.prepVehicleSwitchEffect(av, vehicle)
    pcall(function() if av.CanChangeAvatar ~= nil then av.CanChangeAvatar = true end end)
    pcall(function()
        -- Prefill multi-slot trước ChangeItemAvatar (tránh SyncMultiSlot từ server xóa trống)
        local parts = F.getDesiredMultiSlotPartsForSkin and F.getDesiredMultiSlotPartsForSkin(skinId) or {}
        if next(parts) then
            pcall(function() av.bEnableMultiSlot = true end)
            pcall(function() if av.SetLobbyMultiSlotEquipData then av:SetLobbyMultiSlotEquipData(parts) end end)
            pcall(function() if av.SetNetMultiSlotData then av:SetNetMultiSlotData(parts) end end)
        end
        av:ChangeItemAvatar(skinId, true)
        applied = true
        _G.CurrentEquipVehicleID = skinId
    end)
    if applied then
        F.scheduleChassisLightApply(vehicle, skinId)
        pcall(function() F.applyVehicleModPartsToVehicle(vehicle, skinId) end)
        if F.scheduleVehicleModPartsApply then F.scheduleVehicleModPartsApply(vehicle, skinId) end
    end
    return applied
end

function F.vehicleAvatarTemper()
    local vehicle = F.getCurrentVehicleForSkin()
    if not slua.isValid(vehicle) then return end
    local av = F.getVehicleAvatarComp(vehicle)
    if not slua.isValid(av) then return end

    local defaultId = 0
    pcall(function() defaultId = tonumber(av:GetDefaultAvatarID()) or 0 end)
    if defaultId <= 0 then return end

    local shape = nil
    pcall(function() shape = tonumber(import("AvatarUtils").GetVehicleShapeBySkinID(defaultId)) end)

    local skinId = nil
    if VEHSEL.override and slua.isValid(VEHSEL.overrideVehicle) and VEHSEL.overrideVehicle == vehicle then
        skinId = VEHSEL.override
    end
    if not skinId and shape then skinId = VEHSEL.byShape[shape] end
    if not skinId then skinId = F.resolveVehicleSkinForAvatar(defaultId) end
    if not skinId and shape then skinId = F.getDesiredVehicleSkinForShape(shape, defaultId) end
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 or skinId == defaultId then return end

    local cur = 0
    pcall(function() cur = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId()) or 0 end)
    if cur <= 0 then
        pcall(function() cur = tonumber(vehicle.GetVehicleSkinItemID and vehicle:GetVehicleSkinItemID()) or 0 end)
    end
    if cur == skinId then return end

    F.forceVehicleAvatar(skinId, vehicle)
end
function F.vehicleSkinTick()
    if not F.skinFeat("SkinMatchVehicle") then return end
    -- Chỉ temper khi đang trên xe — không đụng face/outfit mỗi tick (gây giật trong trận)
    local vehicle = F.getCurrentVehicleForSkin and F.getCurrentVehicleForSkin()
    if not slua.isValid(vehicle) then return end
    F.vehicleAvatarTemper()
    local now = os.clock()
    if now - _vehTickLastApply < 5.0 then return end
    _vehTickLastApply = now
    F.applyVehicleSkinsToPC()
end

function F.startVehicleSkinTicker()
    pcall(function()
        if not F.skinFeat("SkinMatchVehicle") then
            if _G.AddOutfitVehTickerId and _ticker and _ticker.RemoveTimer then
                pcall(function() _ticker.RemoveTimer(_G.AddOutfitVehTickerId) end)
                _G.AddOutfitVehTickerId = nil
                _G.AddOutfitVehTickerVer = nil
            end
            return
        end
        if not _ticker then return end
        -- Ver 2: bỏ face-wear mỗi 1s → chỉ temper xe mỗi 2.5s
        if _G.AddOutfitVehTickerVer == 2 and _G.AddOutfitVehTickerId then return end
        if _G.AddOutfitVehTickerId and _ticker.RemoveTimer then
            pcall(function() _ticker.RemoveTimer(_G.AddOutfitVehTickerId) end)
            _G.AddOutfitVehTickerId = nil
        end
        if _ticker.AddTimerLoop then
            _G.AddOutfitVehTickerId = _ticker.AddTimerLoop(2.5, function()
                local fn = _G.AddOutfit and _G.AddOutfit.vehicleSkinTick
                if fn then pcall(fn) end
            end, -1, 2.5)
            _G.AddOutfitVehTickerVer = 2
        end
    end)
end

function F.matchApplyVehicleSkin(skinId)
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 then return false end

    local vehicle = F.getCurrentVehicleForSkin()

    VEHSEL.override = skinId
    VEHSEL.overrideVehicle = slua.isValid(vehicle) and vehicle or nil

    pcall(function()
        local UAvatarUtils = import("AvatarUtils")
        local shape = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(skinId))
        if shape and shape >= 0 then VEHSEL.byShape[shape] = skinId end
        local av = F.getVehicleAvatarComp(vehicle)
        if slua.isValid(av) then
            local defaultId = tonumber(av:GetDefaultAvatarID()) or 0
            if defaultId > 0 then
                local defShape = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(defaultId))
                if defShape and defShape >= 0 then VEHSEL.byShape[defShape] = skinId end
            end
        end
    end)

    F.applyVehicleSkinsToPC(F.getPC())
    local ok = F.forceVehicleAvatar(skinId, vehicle)
    F.startVehicleSkinTicker()
    return ok
end

function F.autoApplyVehicleSkinOnEnter(vehicle)
    if not slua.isValid(vehicle) then return end
    F.syncVehicleCacheFromDataMgr()
    F.applyVehicleSkinsToPC(F.getPC())
    F.startVehicleSkinTicker()
    pcall(function()
        local av = F.getVehicleAvatarComp(vehicle)
        if not slua.isValid(av) then return end
        local defId = 0
        pcall(function() defId = tonumber(av:GetDefaultAvatarID()) or 0 end)
        local currentId = 0
        pcall(function() currentId = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId()) or 0 end)
        local vehTarget = F.resolveVehicleSkinForAvatar(defId)
        if (not vehTarget or vehTarget <= 0) and _G.VehicleSkinMap then
            local defStr = tostring(defId)
            for baseId, targetSkin in pairs(_G.VehicleSkinMap) do
                if defStr:find(tostring(baseId), 1, true) then
                    vehTarget = tonumber(targetSkin)
                    break
                end
            end
        end
        if vehTarget and vehTarget > 0 and currentId ~= vehTarget then
            F.requestResourceDownload(vehTarget)
            F.forceVehicleAvatar(vehTarget, vehicle)
            _G.CurrentEquipVehicleID = vehTarget
        end
    end)
    F.later(0.6, function()
        pcall(F.vehicleAvatarTemper)
        local skinId = nil
        pcall(function() skinId = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId()) end)
        pcall(function() F.applyVehiclePartDataToPC(F.getPC(), skinId) end)
        F.scheduleChassisLightApply(vehicle, skinId)
        pcall(function() F.applyVehicleModPartsToVehicle(vehicle, skinId) end)
    end)
end
local function GetOutfitConfigPaths(fileName)
    local paths = {
        "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
        "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
        "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
        "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
        "/Documents/ShadowTrackerExtra/Saved/Paks/puffer_temp/" .. fileName,
        "ShadowTrackerExtra/Saved/Paks/" .. fileName,
        "../../ShadowTrackerExtra/Saved/Paks/" .. fileName
    }
    pcall(function()
        if os and os.getenv then
            local homeDir = os.getenv("HOME")
            if homeDir and homeDir ~= "" then
                table.insert(paths, 1, homeDir .. "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
            end
        end
    end)
    return paths
end

-- 2 chế độ UseScriptSkins → 2 file config riêng (không chồng lấn)
-- true  → KuttaVai_cfg453_outfit_script.json  (ITEMS trong script)
-- false → KuttaVai_cfg453_outfit_custom.json  (dump / Free Shop)
-- Không migrate từ KuttaCheatTG_outfit*.json cũ → setting mới hoàn toàn
local LEGACY_CONFIG_PATHS = {}
local CONFIG_PATHS = GetOutfitConfigPaths("KuttaVai_cfg453_outfit_script.json")

function F.outfitConfigFileName()
    if _G.KuttaVaiConfig and _G.KuttaVaiConfig.UseScriptSkins == false then
        return "KuttaVai_cfg453_outfit_custom.json"
    end
    return "KuttaVai_cfg453_outfit_script.json"
end

function F.refreshOutfitConfigPaths()
    CONFIG_PATHS = GetOutfitConfigPaths(F.outfitConfigFileName())
    return CONFIG_PATHS
end

function F.onUseScriptSkinsChanged()
    local useScript = not (_G.KuttaVaiConfig and _G.KuttaVaiConfig.UseScriptSkins == false)
    if PERSIST._modeBound and PERSIST._modeUseScript == useScript then return end
    -- Lưu file chế độ cũ trước khi đổi
    if PERSIST._modeBound and PERSIST.dirty then
        pcall(F.persistFlush)
    end
    PERSIST._modeUseScript = useScript
    PERSIST._modeBound = true
    PERSIST.path = nil
    PERSIST.lastWritten = nil
    PERSIST.loaded = nil
    PERSIST.dirty = false
    PERSIST.scheduled = false
    PERSIST.configSlots = {}
    PERSIST.configWeapons = {}
    PERSIST.configDepotItems = {}
    PERSIST.configVehicleSlots = {}
    PERSIST.configMotionSlots = {}
    PERSIST.configChassisLight = nil
    PERSIST.configChassisLightMap = {}
    PERSIST.configVehicleMod = nil
    PERSIST.configPetResID = nil
    PERSIST.lobbyVehicleSubType = nil
    PERSIST.lobbyVehicleIns = nil
    PERSIST.lobbyVehicleResID = nil
    PERSIST.hallThemeResID = nil
    PERSIST.hallThemeIns = nil
    _G.KuttaCheatTG_DumpExtraSkins = {}
    F.refreshOutfitConfigPaths()
    pcall(F.persistLoadFromDisk)
    pcall(F.syncDepotItemsFromPersist)
    pcall(F.applyPersistSlotsToCache)
    pcall(F.syncGlobalWearSkins)
    pcall(function()
        local entity = F.getEntity and F.getEntity()
        if entity then F.injectAll(entity) end
    end)
    pcall(function() if F.reapplyVehicleModPersist then F.reapplyVehicleModPersist(true) end end)
end

local PERSIST_SLOTS = {
    { "outfit", "outfitRes", "outfitIns", "AddOutfitLastLobbyOutfitRes" },
    { "tshirt", "tshirtRes", "tshirtIns", "AddOutfitLastLobbyTshirtRes" },
    { "pants",  "pantsRes",  "pantsIns",  "AddOutfitLastLobbyPantsRes"  },
    { "shoes",  "shoesRes",  "shoesIns",  "AddOutfitLastLobbyShoesRes"  },
    { "hat",    "hatRes",    "hatIns",    "AddOutfitLastLobbyHatRes"    },
    { "mask",   "maskRes",   "maskIns",   "AddOutfitLastLobbyMaskRes"   },
    { "glass",  "glassRes",  "glassIns",  "AddOutfitLastLobbyGlassRes"  },
    { "bag",    "bagRes",    "bagIns",    "AddOutfitLastLobbyBagRes"    },
    { "helmet", "helmetRes", "helmetIns", "AddOutfitLastLobbyHelmetRes" },
    { "parachute", "parachuteRes", "parachuteIns", "AddOutfitLastLobbyParachuteRes" },
    { "glider", "gliderRes", "gliderIns", "AddOutfitLastLobbyGliderRes" },
    { "gloves", "glovesRes", "glovesIns", "AddOutfitLastLobbyGlovesRes" },
}

function F.isPersistableWearRes(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    if F.isInjectedRes(resID) then return true end
    if F.isParachuteRes(resID) or F.isGlideRes(resID) then return true end
    if PERSIST.configSlots then
        for _, v in pairs(PERSIST.configSlots) do
            if tonumber(v) == resID then return true end
        end
    end
    return false
end

function F.persistRememberSlot(slotName, resID)
    slotName = slotName and tostring(slotName)
    resID = tonumber(resID)
    if not slotName or not resID or resID <= 0 then return end
    PERSIST.configSlots = PERSIST.configSlots or {}
    PERSIST.configSlots[slotName] = resID
end

function F.persistRememberDepotItem(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    if not F.shouldPersistDepotGrant or not F.shouldPersistDepotGrant(resID) then return false end
    PERSIST.configDepotItems = PERSIST.configDepotItems or {}
    PERSIST.configDepotItems[resID] = true
    if F.pruneDepotItemsUpgradeGroup then F.pruneDepotItemsUpgradeGroup(resID) end
    F.invalidateDepotGroupCache()
    return true
end

function F.syncDepotItemsFromPersist()
    if type(PERSIST.configDepotItems) ~= "table" then return end
    _G.KuttaCheatTG_DumpExtraSkins = _G.KuttaCheatTG_DumpExtraSkins or {}
    for res, on in pairs(PERSIST.configDepotItems) do
        if on then
            res = tonumber(res)
            if res and res > 0 then _G.KuttaCheatTG_DumpExtraSkins[res] = true end
        end
    end
end

function F.persistLoadDepotItemsFromSaved(saved)
    if type(saved) ~= "table" or type(saved.depotItems) ~= "table" then return end
    PERSIST.configDepotItems = PERSIST.configDepotItems or {}
    for _, res in ipairs(saved.depotItems) do
        res = tonumber(res)
        if res and res > 0 then PERSIST.configDepotItems[res] = true end
    end
    if F.collapsePersistedDepotUpgradeGroups then F.collapsePersistedDepotUpgradeGroups() end
    F.syncDepotItemsFromPersist()
end

function F.persistLoadXSuitUnlocksFromSaved(saved)
    if type(saved) ~= "table" or type(saved.xsuitUnlocks) ~= "table" then return end
    local fls = _G.KuttaCheatTG_FreeLobbyShop
    if type(fls) ~= "table" or not fls.rememberXSuitWorkshopUnlock then return end
    for _, u in ipairs(saved.xsuitUnlocks) do
        if type(u) == "table" and tonumber(u.period) and tonumber(u.itemId) then
            fls.rememberXSuitWorkshopUnlock({
                period = tonumber(u.period),
                branchId = tonumber(u.branchId) or 0,
                level = tonumber(u.current) or tonumber(u.level) or 1,
                itemId = tonumber(u.itemId),
            })
            pcall(function()
                if F.registerDumpExtraSkin then F.registerDumpExtraSkin(tonumber(u.itemId)) end
            end)
        end
    end
end

function F.getWeaponUpgradeLevel(resID)
    resID = tonumber(resID)
    if not resID then return nil, nil end
    F._weaponUpgradeCache = F._weaponUpgradeCache or {}
    local cached = F._weaponUpgradeCache[resID]
    if cached then return cached[1], cached[2] end
    local groupID, level = nil, nil
    pcall(function()
        local cfg = CDataTable.GetTableDataByFilter("ItemUpgradeConfig", "ItemID", resID)
        if cfg then
            groupID = tonumber(cfg.GroupID)
            level = tonumber(cfg.Level)
        end
    end)
    if groupID and groupID > 0 and level and level > 0 then
        F._weaponUpgradeCache[resID] = { groupID, level }
        return groupID, level
    end
    F._weaponUpgradeCache[resID] = { nil, nil }
    return nil, nil
end

function F.invalidateDepotGroupCache()
    F._depotGroupBest = nil
end

function F.buildDepotGroupBestCache()
    local cache = {}
    local function consider(res)
        res = tonumber(res)
        if not res then return end
        local gid, lvl = F.getWeaponUpgradeLevel(res)
        if gid and lvl then
            local cur = cache[gid]
            if not cur or lvl > cur.level then cache[gid] = { res = res, level = lvl } end
        end
    end
    for res, on in pairs(PERSIST.configDepotItems or {}) do
        if on then consider(res) end
    end
    for res, on in pairs(_G.KuttaCheatTG_DumpExtraSkins or {}) do
        if on then consider(res) end
    end
    pcall(function()
        local entity = F.getEntity()
        if entity and entity._data then
            for i = 1, (entity._DataCount or #entity._data) do
                local d = entity._data[i]
                if d and (tonumber(d.count) or 0) > 0 then
                    consider(d.resID or d.res_id)
                end
            end
        end
    end)
    F._depotGroupBest = cache
end

function F.persistForgetDepotItem(resID)
    resID = tonumber(resID)
    if not resID then return end
    if PERSIST.configDepotItems then PERSIST.configDepotItems[resID] = nil end
    if _G.KuttaCheatTG_DumpExtraSkins then _G.KuttaCheatTG_DumpExtraSkins[resID] = nil end
    F.invalidateDepotGroupCache()
end

function F.pruneDepotItemsUpgradeGroup(resID)
    local groupID, level = F.getWeaponUpgradeLevel(resID)
    if not groupID or not level then return end
    local toRemove = {}
    local function markRemove(r)
        r = tonumber(r)
        if not r or r == resID then return end
        local gid, lvl = F.getWeaponUpgradeLevel(r)
        if gid == groupID and lvl and lvl <= level then toRemove[r] = true end
    end
    for r, on in pairs(PERSIST.configDepotItems or {}) do
        if on then markRemove(r) end
    end
    for r, on in pairs(_G.KuttaCheatTG_DumpExtraSkins or {}) do
        if on then markRemove(r) end
    end
    for r in pairs(toRemove) do F.persistForgetDepotItem(r) end
end

function F.collapsePersistedDepotUpgradeGroups()
    if type(PERSIST.configDepotItems) ~= "table" then return end
    local bestByGroup = {}
    for res, on in pairs(PERSIST.configDepotItems) do
        if on then
            res = tonumber(res)
            local gid, lvl = F.getWeaponUpgradeLevel(res)
            if gid and lvl then
                local cur = bestByGroup[gid]
                if not cur or lvl > cur.level then bestByGroup[gid] = { res = res, level = lvl } end
            end
        end
    end
    for gid, best in pairs(bestByGroup) do
        for res, on in pairs(PERSIST.configDepotItems) do
            if on then
                res = tonumber(res)
                local g2, l2 = F.getWeaponUpgradeLevel(res)
                if g2 == gid and l2 and l2 < best.level then F.persistForgetDepotItem(res) end
            end
        end
    end
    F.syncDepotItemsFromPersist()
end

function F.getHighestDepotLevelForGroup(groupID)
    groupID = tonumber(groupID)
    if not groupID then return nil, nil end
    if not F._depotGroupBest then F.buildDepotGroupBestCache() end
    local best = F._depotGroupBest[groupID]
    if best then return best.res, best.level end
    return nil, nil
end

function F.shouldInjectDepotRes(resID)
    resID = tonumber(resID)
    if not resID then return false end
    local groupID, level = F.getWeaponUpgradeLevel(resID)
    if not groupID or not level then return true end
    local bestRes, bestLevel = F.getHighestDepotLevelForGroup(groupID)
    if not bestLevel or bestLevel <= 0 then return true end
    if bestLevel > level then return false end
    if bestLevel == level and bestRes and bestRes ~= resID then
        return F.isInjectedDepotAlive and F.isInjectedDepotAlive(bestRes) == true
    end
    return true
end

function F.persistReplaceDepotItem(oldResID, newResID)
    oldResID, newResID = tonumber(oldResID), tonumber(newResID)
    if oldResID and oldResID > 0 then F.persistForgetDepotItem(oldResID) end
    if newResID and newResID > 0 and F.shouldPersistDepotGrant and F.shouldPersistDepotGrant(newResID) then
        PERSIST.configDepotItems = PERSIST.configDepotItems or {}
        PERSIST.configDepotItems[newResID] = true
        _G.KuttaCheatTG_DumpExtraSkins = _G.KuttaCheatTG_DumpExtraSkins or {}
        _G.KuttaCheatTG_DumpExtraSkins[newResID] = true
        F.pruneDepotItemsUpgradeGroup(newResID)
    end
    F.invalidateDepotGroupCache()
end

function F.persistForgetSlot(slotName)
    if PERSIST.configSlots and slotName then
        PERSIST.configSlots[tostring(slotName)] = nil
    end
end

function F.persistRememberMotionSlot(slot, resID)
    slot = tonumber(slot)
    resID = tonumber(resID)
    if not slot or slot <= 0 then return end
    PERSIST.configMotionSlots = PERSIST.configMotionSlots or {}
    if resID and resID > 0 and F.isEmoteRes(resID) then
        PERSIST.configMotionSlots[slot] = resID
    else
        PERSIST.configMotionSlots[slot] = nil
    end
    F.persistMarkDirty()
end

function F.persistLoadMotionSlotsFromSaved(saved)
    if type(saved) ~= "table" or type(saved.motionSlots) ~= "table" then return end
    PERSIST.configMotionSlots = PERSIST.configMotionSlots or {}
    for idxStr, res in pairs(saved.motionSlots) do
        local idx, r = tonumber(idxStr), tonumber(res)
        if idx and idx > 0 and r and r > 0 and F.isEmoteRes(r) then
            PERSIST.configMotionSlots[idx] = r
        end
    end
end

function F.applyPersistedMotionSlots()
    if not PERSIST.configMotionSlots then return false end
    local any = false
    for slot, resID in pairs(PERSIST.configMotionSlots) do
        slot = tonumber(slot)
        resID = tonumber(resID)
        if slot and slot > 0 and resID and resID > 0 then
            local ins = F.resolveInsForRes(resID)
            if ins and ins > 0 then
                F.ensureMotionSlotCapacity(slot)
                DataMgr.MotionSlotList[slot] = ins
                _G.AddOutfitLocalMotionSlots = _G.AddOutfitLocalMotionSlots or {}
                _G.AddOutfitLocalMotionSlots[slot] = ins
                any = true
            end
        end
    end
    if any then
        F.invalidateInGameEmoteCache()
        F.postMotionSlotUpdate()
    end
    return any
end

function F.persistLoadSlotsFromSaved(saved)
    if type(saved) ~= "table" then return end
    PERSIST.configSlots = PERSIST.configSlots or {}
    for _, s in ipairs(PERSIST_SLOTS) do
        local res = tonumber(saved[s[1]])
        if res and res > 0 then PERSIST.configSlots[s[1]] = res end
    end
    F.persistLoadMotionSlotsFromSaved(saved)
    F.applyPersistSlotsToCache()
end

function F.resolveInsForRes(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return nil end
    if R.resToIns[resID] then return R.resToIns[resID] end
    local ins
    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local list = wd.GetHallDepotItemListByResID and wd:GetHallDepotItemListByResID(resID)
        if list then
            for _, v in pairs(list) do
                local id = tonumber(v.insID or v.instid or v.ins_id)
                if id and id > 0 then ins = id break end
            end
        end
        if not ins then
            local d = wd.GetValidHallDepotItemDataByInsID and wd:GetValidHallDepotItemDataByInsID(resID)
            if not d and wd.GetHallDepotItemDataByResID then
                d = wd:GetHallDepotItemDataByResID(resID)
            end
            if d then ins = tonumber(d.insID or d.instid or d.ins_id) end
        end
    end)
    return ins
end

function F.applyPersistSlotsToCache()
    if not PERSIST.configSlots then return end
    local cch = F.cache()
    for _, s in ipairs(PERSIST_SLOTS) do
        local slotName, cacheResKey, cacheInsKey, globalKey = s[1], s[2], s[3], s[4]
        local res = tonumber(PERSIST.configSlots[slotName])
        if res and res > 0 then
            cch[cacheResKey] = res
            _G[globalKey] = res
            local ins = F.resolveInsForRes(res)
            if ins and ins > 0 then cch[cacheInsKey] = ins end
        end
    end
end

function F.getDesiredGliderRes()
    F.applyPersistSlotsToCache()
    local r = tonumber(PERSIST.configSlots and PERSIST.configSlots.glider)
    if r and r > 0 then return r end
    F.syncAirborneCacheFromLobby()
    return F.getDesiredWear("gliderRes", "gliderRes", "AddOutfitLastLobbyGliderRes")
end

function F.getDesiredParachuteRes()
    F.applyPersistSlotsToCache()
    local r = tonumber(PERSIST.configSlots and PERSIST.configSlots.parachute)
    if r and r > 0 then return r end
    F.syncAirborneCacheFromLobby()
    return F.getDesiredWear("parachuteRes", "parachuteRes", "AddOutfitLastLobbyParachuteRes")
end

function F.getAvatarComp2(char)
    if not char or not slua.isValid(char) then return nil end
    local comp
    pcall(function()
        if char.getAvatarComponent2 then
            comp = char:getAvatarComponent2()
        end
        if (not comp or not slua.isValid(comp)) and char.AvatarComponent2 then
            comp = char.AvatarComponent2
        end
        if (not comp or not slua.isValid(comp)) and char.CharacterAvatarComp2_BP then
            comp = char.CharacterAvatarComp2_BP
        end
    end)
    return comp
end

function F.isCharacterAirborne(char)
    if not char or not slua.isValid(char) then return false end
    local ok, r = pcall(function()
        local EParachuteState = import("EParachuteState")
        local st = char.ParachuteState
        return st and st ~= EParachuteState.PS_None
    end)
    return ok and r == true
end

function F.reapplyWeaponsFromConfig()
    local wmap = F.sanitizeConfigWeapons(PERSIST.configWeapons)
    local dropped = false
    for k in pairs(PERSIST.configWeapons or {}) do
        if not wmap[tonumber(k) or k] then dropped = true break end
    end
    PERSIST.configWeapons = wmap
    if dropped then F.persistMarkDirty() end
    if not next(wmap) then return false end
    local cch = F.cache()
    local any = false
    for wid, res in pairs(wmap) do
        wid, res = tonumber(wid), tonumber(res)
        local ins = res and R.resToIns[res]
        if wid and ins and F.isInjectedIns(ins) then
            cch.weapons[wid] = { resID = res, insID = ins }
            -- Melee 108xxx: silent only — never SetGunID in mass reapply (avoids switching dao/chảo)
            if wid == MELEE_ID or (wid >= 108000 and wid < 109000) then
                F.syncWeaponArmorySilent(wid, ins)
            elseif F.equipWeaponSkin(wid, ins) then
                any = true
            else
                F.syncWeaponArmorySilent(wid, ins)
            end
        end
    end
    return any
end

function F.persistEncode()
    local cch = F.cache()
    local parts = {}
    for _, s in ipairs(PERSIST_SLOTS) do
        local res = tonumber(PERSIST.configSlots and PERSIST.configSlots[s[1]])
            or tonumber(cch[s[2]])
        if res and res > 0 and F.isPersistableWearRes(res) then
            parts[#parts + 1] = string.format('  "%s": %d', s[1], res)
        end
    end
    local wparts = {}
    local wmap = {}
    for wid, res in pairs(F.sanitizeConfigWeapons(PERSIST.configWeapons)) do
        wmap[wid] = res
    end
    for wid, w in pairs(cch.weapons or {}) do
        local res = w and tonumber(w.resID)
        wid = tonumber(wid)
        if F.isValidWeaponPersistEntry(wid, res) then wmap[wid] = res end
    end
    for wid, res in pairs(wmap) do
        wparts[#wparts + 1] = string.format('    "%d": %d', wid, res)
    end
    table.sort(wparts)
    parts[#parts + 1] = '  "weapons": {\n' .. table.concat(wparts, ",\n") .. "\n  }"
    local gparts = {}
    local gmap = {}
    for base, res in pairs(PERSIST.configGrenades or {}) do
        base, res = tonumber(base), tonumber(res)
        if base and GRENADE_FIELD_BY_BASE[base] and res and res > 0 and F.isGrenadeSkinRes(res) then
            gmap[base] = res
        end
    end
    local cchG = F.cache().grenades
    for base, w in pairs(cchG or {}) do
        local res = w and tonumber(w.resID)
        base = tonumber(base)
        if base and GRENADE_FIELD_BY_BASE[base] and res and res > 0 and F.isGrenadeSkinRes(res) then
            gmap[base] = res
        end
    end
    for base, res in pairs(gmap) do
        gparts[#gparts + 1] = string.format('    "%d": %d', base, res)
    end
    table.sort(gparts)
    parts[#parts + 1] = '  "grenades": {\n' .. table.concat(gparts, ",\n") .. "\n  }"
    local vparts = {}
    local function appendVehicleSlots(src)
        for subType, slots in pairs(src or {}) do
            local sparts = {}
            if type(slots) == "table" then
                for idx, val in pairs(slots) do
                    local res = type(val) == "table" and tonumber(val.resID) or tonumber(val)
                    if res and res > 0 then
                        sparts[#sparts + 1] = string.format('      "%d": %d', tonumber(idx), res)
                    end
                end
            end
            table.sort(sparts)
            if #sparts > 0 then
                vparts[#vparts + 1] = string.format('    "%d": {\n%s\n    }', tonumber(subType), table.concat(sparts, ",\n"))
            end
        end
    end
    local hasCacheSlots = false
    for _ in pairs(cch.vehicleSlots or {}) do hasCacheSlots = true; break end
    if hasCacheSlots then
        appendVehicleSlots(cch.vehicleSlots)
    elseif PERSIST.configVehicleSlots then
        appendVehicleSlots(PERSIST.configVehicleSlots)
    end
    table.sort(vparts)
    parts[#parts + 1] = '  "vehicleSlots": {\n' .. table.concat(vparts, ",\n") .. "\n  }"
    if PERSIST.lobbyVehicleSubType and PERSIST.lobbyVehicleSubType > 0
        and PERSIST.lobbyVehicleSubType ~= CHASSIS_LIGHT_SUB
        and not F.isChassisLightId(PERSIST.lobbyVehicleResID)
        and F.isVehicleRes(PERSIST.lobbyVehicleResID) then
        parts[#parts + 1] = string.format('  "lobbyVehicleSubType": %d', PERSIST.lobbyVehicleSubType)
    end
    if PERSIST.lobbyVehicleResID and PERSIST.lobbyVehicleResID > 0
        and F.isVehicleRes(PERSIST.lobbyVehicleResID) then
        parts[#parts + 1] = string.format('  "lobbyVehicleResID": %d', PERSIST.lobbyVehicleResID)
    end
    if PERSIST.lobbyVehicleIns and PERSIST.lobbyVehicleIns > 0
        and F.isVehicleRes(PERSIST.lobbyVehicleResID or R.insToRes[PERSIST.lobbyVehicleIns]) then
        parts[#parts + 1] = string.format('  "lobbyVehicleIns": %d', PERSIST.lobbyVehicleIns)
    end
    local hres = tonumber(cch.hallThemeRes) or tonumber(PERSIST.hallThemeResID)
    if hres and hres > 0 and F.isInjectedRes(hres) then
        parts[#parts + 1] = string.format('  "hallTheme": %d', hres)
    end
    local cl = tonumber(PERSIST.configChassisLight)
    if F.isChassisLightId(cl) then
        parts[#parts + 1] = string.format('  "chassisLight": %d', cl)
    end
    local cmap = PERSIST.configChassisLightMap
    if cmap and next(cmap) then
        local cparts = {}
        for vid, lid in pairs(cmap) do
            vid, lid = tonumber(vid), tonumber(lid)
            if vid and vid > 0 and F.isChassisLightId(lid) then
                cparts[#cparts + 1] = string.format('    "%d": %d', vid, lid)
            end
        end
        table.sort(cparts)
        if #cparts > 0 then
            parts[#parts + 1] = '  "chassisLightMap": {\n' .. table.concat(cparts, ",\n") .. "\n  }"
        end
    end
    -- Vehicle Mod System persist (wheel/brake/canopy/refit/accessory)
    do
        local vm = PERSIST.configVehicleMod
        if type(vm) == "table" then
            local function encMap(t)
                local arr = {}
                for k, v in pairs(t or {}) do
                    k, v = tonumber(k), tonumber(v)
                    if k and v and v > 0 then
                        arr[#arr + 1] = string.format('      "%d": %d', k, v)
                    end
                end
                table.sort(arr)
                return arr
            end
            local sections = {}
            for _, key in ipairs({ "wheelHub", "brakeCaliper", "canopy", "chassisLight", "plateBg" }) do
                local arr = encMap(vm[key])
                if #arr > 0 then
                    sections[#sections + 1] = string.format('    "%s": {\n%s\n    }', key, table.concat(arr, ",\n"))
                end
            end
            if tonumber(vm.switchEffect) and tonumber(vm.switchEffect) > 0 then
                sections[#sections + 1] = string.format('    "switchEffect": %d', tonumber(vm.switchEffect))
            end
            local refitParts = {}
            for carId, styles in pairs(vm.refit or {}) do
                carId = tonumber(carId)
                if carId and type(styles) == "table" then
                    local sarr = encMap(styles)
                    if #sarr > 0 then
                        refitParts[#refitParts + 1] = string.format('      "%d": {\n%s\n      }', carId, table.concat(sarr, ",\n"))
                    end
                end
            end
            table.sort(refitParts)
            if #refitParts > 0 then
                sections[#sections + 1] = '    "refit": {\n' .. table.concat(refitParts, ",\n") .. "\n    }"
            end
            local accParts = {}
            for carId, accs in pairs(vm.accessories or {}) do
                carId = tonumber(carId)
                if carId and type(accs) == "table" then
                    local aarr = {}
                    for accId, on in pairs(accs) do
                        accId = tonumber(accId)
                        if accId and on then aarr[#aarr + 1] = string.format('        "%d": 1', accId) end
                    end
                    table.sort(aarr)
                    if #aarr > 0 then
                        accParts[#accParts + 1] = string.format('      "%d": {\n%s\n      }', carId, table.concat(aarr, ",\n"))
                    end
                end
            end
            table.sort(accParts)
            if #accParts > 0 then
                sections[#sections + 1] = '    "accessories": {\n' .. table.concat(accParts, ",\n") .. "\n    }"
            end
            if #sections > 0 then
                parts[#parts + 1] = '  "vehicleMod": {\n' .. table.concat(sections, ",\n") .. "\n  }"
            end
        end
    end
    local msParts = {}
    for idx, res in pairs(PERSIST.configMotionSlots or {}) do
        idx, res = tonumber(idx), tonumber(res)
        if idx and idx > 0 and res and res > 0 and F.isEmoteRes(res) then
            msParts[#msParts + 1] = string.format('    "%d": %d', idx, res)
        end
    end
    table.sort(msParts)
    if #msParts > 0 then
        parts[#parts + 1] = '  "motionSlots": {\n' .. table.concat(msParts, ",\n") .. "\n  }"
    end
    local petRes = tonumber(PERSIST.configPetResID) or tonumber(_G.AddOutfitLastPetRes)
    if petRes and petRes >= 50001 and petRes < 50100 then
        parts[#parts + 1] = string.format('  "pet": %d', petRes)
    end
    local pcSrc = _G.KuttaCheatTG_ProfileCustomEquip or PERSIST.profileCustom
    if pcSrc and next(pcSrc) then
        local pcParts = {}
        for pk, pv in pairs(pcSrc) do
            if pv ~= nil and pv ~= "" then
                if type(pv) == "number" then
                    pcParts[#pcParts + 1] = string.format('    "%s": %d', pk, pv)
                elseif type(pv) == "string" then
                    local num = tonumber(pv)
                    if num and tostring(num) == pv then
                        pcParts[#pcParts + 1] = string.format('    "%s": %d', pk, num)
                    else
                        local esc = pv:gsub("\\", "\\\\"):gsub('"', '\\"')
                        pcParts[#pcParts + 1] = string.format('    "%s": "%s"', pk, esc)
                    end
                end
            end
        end
        table.sort(pcParts)
        if #pcParts > 0 then
            parts[#parts + 1] = '  "profileCustom": {\n' .. table.concat(pcParts, ",\n") .. "\n  }"
        end
    end
    local depotSeen, depotParts = {}, {}
    local depotBestByGroup = {}
    local depotBestXSuit = {}
    local function trackDepotRes(res)
        res = tonumber(res)
        if not res or res <= 0 then return end
        if F.shouldPersistDepotGrant and not F.shouldPersistDepotGrant(res) then return end
        local xsMeta = nil
        pcall(function()
            local fls = _G.KuttaCheatTG_FreeLobbyShop
            if type(fls) == "table" and fls.resolveXSuitMeta then xsMeta = fls.resolveXSuitMeta(res) end
        end)
        if xsMeta and xsMeta.period then
            local key = tostring(xsMeta.period) .. ":" .. tostring(xsMeta.branchId or 0)
            local cur = depotBestXSuit[key]
            if not cur or (tonumber(xsMeta.level) or 1) > (tonumber(cur.level) or 1) then
                depotBestXSuit[key] = { res = res, level = tonumber(xsMeta.level) or 1 }
            end
            return
        end
        local gid, lvl = F.getWeaponUpgradeLevel and F.getWeaponUpgradeLevel(res)
        if gid and lvl then
            local cur = depotBestByGroup[gid]
            if not cur or lvl > cur.level then depotBestByGroup[gid] = { res = res, level = lvl } end
        else
            depotSeen[res] = true
        end
    end
    for res, on in pairs(PERSIST.configDepotItems or {}) do
        if on then trackDepotRes(res) end
    end
    for res, on in pairs(_G.KuttaCheatTG_DumpExtraSkins or {}) do
        if on then trackDepotRes(res) end
    end
    -- XSuit trong depot entity: chỉ lưu level cao nhất / nhánh
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        local entity = F.getEntity and F.getEntity()
        if not LogicXSuit or not LogicXSuit.IsXSuit or not entity or not entity._data then return end
        for i = 1, (entity._DataCount or #entity._data) do
            local d = entity._data[i]
            local res = d and tonumber(d.resID or d.res_id)
            if res and (tonumber(d.count) or 0) > 0 and LogicXSuit.IsXSuit(res) then
                trackDepotRes(res)
            end
        end
    end)
    for _, best in pairs(depotBestByGroup) do depotSeen[best.res] = true end
    for _, best in pairs(depotBestXSuit) do depotSeen[best.res] = true end
    for res in pairs(depotSeen) do depotParts[#depotParts + 1] = tostring(res) end
    table.sort(depotParts, function(a, b) return tonumber(a) < tonumber(b) end)
    if #depotParts > 0 then
        parts[#parts + 1] = '  "depotItems": [' .. table.concat(depotParts, ", ") .. ']'
    end
    -- Unlock Workshop XSuit (nút đổi nhánh / đã sở hữu)
    pcall(function()
        local fls = _G.KuttaCheatTG_FreeLobbyShop
        local unlocks = (type(fls) == "table" and fls._xsuitWorkshopUnlocks) or {}
        local xu = {}
        for _, u in pairs(unlocks) do
            if type(u) == "table" and tonumber(u.period) and tonumber(u.itemId) then
                xu[#xu + 1] = string.format(
                    '    {"period":%d,"branchId":%d,"current":%d,"itemId":%d}',
                    tonumber(u.period),
                    tonumber(u.branchId) or 0,
                    tonumber(u.current) or 1,
                    tonumber(u.itemId)
                )
            end
        end
        table.sort(xu)
        if #xu > 0 then
            parts[#parts + 1] = '  "xsuitUnlocks": [\n' .. table.concat(xu, ",\n") .. "\n  ]"
        end
    end)
    return "{\n" .. table.concat(parts, ",\n") .. "\n}\n"
end

function F.persistWrite(txt)
    if not (io and io.open) then return false end
    if PERSIST.path then
        local f
        pcall(function() f = io.open(PERSIST.path, "w") end)
        if f then f:write(txt) f:close() return true end
        PERSIST.path = nil
    end
    for _, p in ipairs(CONFIG_PATHS) do
        local f
        pcall(function() f = io.open(p, "w") end)
        if not f then
            pcall(function()
                local dir = p:match("^(.*)/[^/]+$")
                if dir and os and os.execute then os.execute('mkdir -p "' .. dir .. '"') end
            end)
            pcall(function() f = io.open(p, "w") end)
        end
        if f then
            f:write(txt) f:close()
            PERSIST.path = p
            return true
        end
    end
    return false
end

function F.persistFlush()
    if not PERSIST.dirty then return end
    PERSIST.dirty = false
    pcall(function()
        local txt = F.persistEncode()
        if txt == PERSIST.lastWritten then return end
        if F.persistWrite(txt) then
            PERSIST.lastWritten = txt
        end
    end)
end

F.persistMarkDirty = function()
    PERSIST.dirty = true
    if PERSIST.scheduled then return end
    PERSIST.scheduled = true
    F.later(2.0, function()
        PERSIST.scheduled = false
        F.persistFlush()
    end)
end

function F.saveOutfitConfigToDisk()
    F.loadDumpExtraSkins()
    PERSIST.configDepotItems = PERSIST.configDepotItems or {}
    for res, on in pairs(_G.KuttaCheatTG_DumpExtraSkins or {}) do
        if on then
            res = tonumber(res)
            if res and res > 0 and F.shouldPersistDepotGrant and F.shouldPersistDepotGrant(res) then
                PERSIST.configDepotItems[res] = true
            end
        end
    end
    -- Đảm bảo mọi XSuit trong kho (cả 3 nhánh) được ghi vào JSON
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        local entity = F.getEntity and F.getEntity()
        if not LogicXSuit or not LogicXSuit.IsXSuit or not entity or not entity._data then return end
        for i = 1, (entity._DataCount or #entity._data) do
            local d = entity._data[i]
            local res = d and tonumber(d.resID or d.res_id)
            if res and (tonumber(d.count) or 0) > 0 and LogicXSuit.IsXSuit(res) then
                if F.registerDumpExtraSkin then F.registerDumpExtraSkin(res) end
                PERSIST.configDepotItems[res] = true
                local fls = _G.KuttaCheatTG_FreeLobbyShop
                if type(fls) == "table" and fls.rememberXSuitWorkshopUnlock and fls.resolveXSuitMeta then
                    local meta = fls.resolveXSuitMeta(res)
                    if meta then fls.rememberXSuitWorkshopUnlock(meta) end
                end
            end
        end
    end)
    if F.collapsePersistedDepotUpgradeGroups then F.collapsePersistedDepotUpgradeGroups() end
    PERSIST.dirty = true
    F.persistFlush()
    return PERSIST.path or (F.outfitConfigFileName and F.outfitConfigFileName()) or "KuttaVai_cfg453_outfit_script.json"
end

_G.SaveOutfitConfig = function()
    local ok, path = false, nil
    pcall(function()
        if F.refreshOutfitConfigPaths then F.refreshOutfitConfigPaths() end
        if F.saveOutfitConfigToDisk then
            path = F.saveOutfitConfigToDisk()
            ok = path ~= nil
        end
    end)
    if ok then
        Notify("Da luu config skin: " .. tostring(path or (F.outfitConfigFileName and F.outfitConfigFileName()) or "?"))
    else
        Notify("Luu config skin that bai")
    end
    return ok
end

function F.applyProfileCustomFromPersist()
