end

function F.persistProfileCustomSave()
    local E = _G.KuttaCheatTG_ProfileCustomEquip
    if not E or not next(E) then return end
    PERSIST.profileCustom = PERSIST.profileCustom or {}
    for k, v in pairs(E) do
        if v ~= nil and v ~= "" then PERSIST.profileCustom[k] = v end
    end
    F.persistMarkDirty()
end

function F.persistParse(txt)
    if not txt or #txt == 0 then return nil end
    local out = { weapons = {}, grenades = {}, vehicleSlots = {} }
    local parsed = false
    pcall(function()
        local t = json and json.decode and json.decode(txt)
        if type(t) == "table" then
            for k, v in pairs(t) do
                if k == "weapons" and type(v) == "table" then
                    for wk, wv in pairs(v) do
                        local wid, res = tonumber(wk), tonumber(wv)
                        if F.isValidWeaponPersistEntry(wid, res) then out.weapons[wid] = res end
                    end
                elseif k == "grenades" and type(v) == "table" then
                    for gk, gv in pairs(v) do
                        local base, res = tonumber(gk), tonumber(gv)
                        if base and GRENADE_FIELD_BY_BASE[base] and res and res > 0 then
                            -- accept even if cfg not loaded yet; sanitize later
                            out.grenades[base] = res
                        end
                    end
                elseif k == "vehicleSlots" and type(v) == "table" then
                    for stk, slotMap in pairs(v) do
                        local st = tonumber(stk)
                        if st then
                            out.vehicleSlots[st] = out.vehicleSlots[st] or {}
                            for idxStr, res in pairs(slotMap) do
                                local idx, r = tonumber(idxStr), tonumber(res)
                                if idx and r and r > 0 then out.vehicleSlots[st][idx] = r end
                            end
                        end
                    end
                elseif k == "chassisLightMap" and type(v) == "table" then
                    out.chassisLightMap = {}
                    for vk, lv in pairs(v) do
                        local vid, lid = tonumber(vk), tonumber(lv)
                        if vid and lid and F.isChassisLightId(lid) then
                            out.chassisLightMap[vid] = lid
                        end
                    end
                elseif k == "vehicleMod" and type(v) == "table" then
                    out.vehicleMod = {
                        wheelHub = {}, brakeCaliper = {}, canopy = {}, chassisLight = {}, plateBg = {},
                        refit = {}, accessories = {}, switchEffect = tonumber(v.switchEffect),
                    }
                    local function loadMap(src, dst)
                        if type(src) ~= "table" then return end
                        for sk, sv in pairs(src) do
                            local a, b = tonumber(sk), tonumber(sv)
                            if a and b and b > 0 then dst[a] = b end
                        end
                    end
                    loadMap(v.wheelHub, out.vehicleMod.wheelHub)
                    loadMap(v.brakeCaliper, out.vehicleMod.brakeCaliper)
                    loadMap(v.canopy, out.vehicleMod.canopy)
                    loadMap(v.chassisLight, out.vehicleMod.chassisLight)
                    loadMap(v.plateBg, out.vehicleMod.plateBg)
                    if type(v.refit) == "table" then
                        for ck, styles in pairs(v.refit) do
                            local carId = tonumber(ck)
                            if carId and type(styles) == "table" then
                                out.vehicleMod.refit[carId] = {}
                                loadMap(styles, out.vehicleMod.refit[carId])
                            end
                        end
                    end
                    if type(v.accessories) == "table" then
                        for ck, accs in pairs(v.accessories) do
                            local carId = tonumber(ck)
                            if carId and type(accs) == "table" then
                                out.vehicleMod.accessories[carId] = {}
                                for ak, av in pairs(accs) do
                                    local accId = tonumber(ak)
                                    if accId and av then out.vehicleMod.accessories[carId][accId] = 1 end
                                end
                            end
                        end
                    end
                elseif k == "motionSlots" and type(v) == "table" then
                    out.motionSlots = {}
                    for idxStr, res in pairs(v) do
                        local idx, r = tonumber(idxStr), tonumber(res)
                        if idx and idx > 0 and r and r > 0 then out.motionSlots[idx] = r end
                    end
                elseif k == "profileCustom" and type(v) == "table" then
                    out.profileCustom = {}
                    for pk, pv in pairs(v) do
                        if pv ~= nil and pv ~= "" then out.profileCustom[pk] = pv end
                    end
                elseif k == "depotItems" and type(v) == "table" then
                    out.depotItems = {}
                    for _, res in ipairs(v) do
                        local r = tonumber(res)
                        if r and r > 0 then out.depotItems[#out.depotItems + 1] = r end
                    end
                elseif k == "xsuitUnlocks" and type(v) == "table" then
                    out.xsuitUnlocks = {}
                    for _, u in ipairs(v) do
                        if type(u) == "table" then
                            local period = tonumber(u.period)
                            local itemId = tonumber(u.itemId)
                            if period and itemId then
                                out.xsuitUnlocks[#out.xsuitUnlocks + 1] = {
                                    period = period,
                                    branchId = tonumber(u.branchId) or 0,
                                    current = tonumber(u.current) or tonumber(u.level) or 1,
                                    itemId = itemId,
                                }
                            end
                        end
                    end
                else
                    local n = tonumber(v)
                    if n and n > 0 then out[k] = n end
                end
            end
            parsed = true
        end
    end)
    if not parsed then
        for k, v in txt:gmatch('"([%w_]+)"%s*:%s*(%d+)') do
            local n = tonumber(v)
            if n and n > 0 then
                local wid = tonumber(k)
                if wid and F.isValidWeaponPersistEntry(wid, n) then
                    out.weapons[wid] = n
                elseif not wid then
                    out[k] = n
                end
            end
        end
    end
    return out
end

function F.persistApplyParsedFile(txt, path, isModeFile)
    if not txt then return false end
    PERSIST.path = isModeFile and path or nil -- legacy → save sang file mode mới
    PERSIST.lastWritten = isModeFile and txt or nil
    PERSIST.loaded = F.persistParse(txt)
    if not isModeFile then PERSIST.dirty = true end
    pcall(F.applyProfileCustomFromPersist) -- slim: profile-unlock removed, guard nil
    F.persistLoadSlotsFromSaved(PERSIST.loaded)
    F.persistLoadDepotItemsFromSaved(PERSIST.loaded)
    F.persistLoadXSuitUnlocksFromSaved(PERSIST.loaded)
    if PERSIST.loaded and PERSIST.loaded.vehicleSlots then
        PERSIST.configVehicleSlots = PERSIST.loaded.vehicleSlots
    end
    if PERSIST.loaded and PERSIST.loaded.weapons then
        local raw = PERSIST.loaded.weapons
        PERSIST.configWeapons = F.sanitizeConfigWeapons(raw)
        if next(raw) and not next(PERSIST.configWeapons) then
            F.persistMarkDirty()
        elseif next(raw) then
            for wid, res in pairs(raw) do
                if not F.isValidWeaponPersistEntry(tonumber(wid), tonumber(res)) then
                    F.persistMarkDirty()
                    break
                end
            end
        end
    end
    if PERSIST.loaded and PERSIST.loaded.grenades then
        PERSIST.configGrenades = {}
        local cch = F.cache()
        cch.grenades = cch.grenades or {}
        MATCH_CONFIG.grenadeSkins = MATCH_CONFIG.grenadeSkins or {}
        for base, res in pairs(PERSIST.loaded.grenades) do
            base, res = tonumber(base), tonumber(res)
            if base and GRENADE_FIELD_BY_BASE[base] and res and res > 0 then
                PERSIST.configGrenades[base] = res
                cch.grenades[base] = { resID = res, insID = R.resToIns[res] or 0 }
                MATCH_CONFIG.grenadeSkins[base] = res
            end
        end
    end
    PERSIST.lobbyVehicleSubType = tonumber(PERSIST.loaded and PERSIST.loaded.lobbyVehicleSubType)
    PERSIST.lobbyVehicleResID = tonumber(PERSIST.loaded and PERSIST.loaded.lobbyVehicleResID)
    PERSIST.lobbyVehicleIns = tonumber(PERSIST.loaded and PERSIST.loaded.lobbyVehicleIns)
    if PERSIST.lobbyVehicleSubType or PERSIST.lobbyVehicleIns or PERSIST.lobbyVehicleResID then
        if F.isChassisLightId(PERSIST.lobbyVehicleResID)
            or PERSIST.lobbyVehicleSubType == CHASSIS_LIGHT_SUB
            or not F.isVehicleRes(PERSIST.lobbyVehicleResID) then
            PERSIST.lobbyVehicleSubType = nil
            PERSIST.lobbyVehicleResID = nil
            PERSIST.lobbyVehicleIns = nil
        else
            _G.AddOutfitLobbyVeh = _G.AddOutfitLobbyVeh or {}
            _G.AddOutfitLobbyVeh.manual = true
            _G.AddOutfitLobbyVeh.subType = PERSIST.lobbyVehicleSubType
            _G.AddOutfitLobbyVeh.resID = PERSIST.lobbyVehicleResID
            _G.AddOutfitLobbyVeh.insID = PERSIST.lobbyVehicleIns
            F.rememberVehicleSkinMap(PERSIST.lobbyVehicleResID, PERSIST.lobbyVehicleIns)
        end
    end
    -- P23-FIX Task3: ins bhi restore karo (old: hall_theme_ins + hall_theme_res dono save)
    PERSIST.hallThemeResID = tonumber(PERSIST.loaded and PERSIST.loaded.hallTheme)
    PERSIST.hallThemeIns = tonumber(PERSIST.loaded and PERSIST.loaded.hallThemeIns) or nil
    if PERSIST.hallThemeResID and not PERSIST.hallThemeIns then
        pcall(function() PERSIST.hallThemeIns = R.resToIns[PERSIST.hallThemeResID] end)
    end
    if PERSIST.hallThemeResID then
        _G.AddOutfitLobbyTheme = _G.AddOutfitLobbyTheme or {}
        _G.AddOutfitLobbyTheme.manual = true
        _G.AddOutfitLobbyTheme.resID = PERSIST.hallThemeResID
    end
    PERSIST.configChassisLight = tonumber(PERSIST.loaded and PERSIST.loaded.chassisLight)
    if PERSIST.loaded and PERSIST.loaded.chassisLightMap then
        PERSIST.configChassisLightMap = PERSIST.loaded.chassisLightMap
    end
    if PERSIST.loaded and type(PERSIST.loaded.vehicleMod) == "table" then
        PERSIST.configVehicleMod = PERSIST.loaded.vehicleMod
    end
    return true
end

function F.persistLoadFromDisk()
    if not (io and io.open) then return end
    pcall(F.refreshOutfitConfigPaths)
    pcall(function()
        -- 1) File theo chế độ UseScriptSkins hiện tại
        for _, p in ipairs(CONFIG_PATHS) do
            local f
            pcall(function() f = io.open(p, "r") end)
            if f then
                local txt = f:read("*a")
                f:close()
                if F.persistApplyParsedFile(txt, p, true) then return end
            end
        end
        -- 2) Không migrate file outfit cũ (KuttaCheatTG_outfit*.json) — cfg453 only
    end)
end

function F.persistApplyLoaded()
    local saved = PERSIST.loaded
    if not saved then return end
    PERSIST.loaded = nil
    local cch = F.cache()
    local any = false
    for _, s in ipairs(PERSIST_SLOTS) do
        local res = tonumber(saved[s[1]]) or tonumber(PERSIST.configSlots and PERSIST.configSlots[s[1]])
        if res and res > 0 and not cch[s[2]] then
            local ins = R.resToIns[res]
            if ins then
                cch[s[2]], cch[s[3]] = res, ins
                _G[s[4]] = res
                any = true
            end
        end
    end
    PERSIST.configWeapons = F.sanitizeConfigWeapons(saved.weapons or PERSIST.configWeapons)
    if saved.weapons and F.reapplyWeaponsFromConfig() then
        any = true
    end
    if saved.grenades then
        PERSIST.configGrenades = {}
        cch.grenades = cch.grenades or {}
        MATCH_CONFIG.grenadeSkins = MATCH_CONFIG.grenadeSkins or {}
        for base, res in pairs(saved.grenades) do
            base, res = tonumber(base), tonumber(res)
            if base and GRENADE_FIELD_BY_BASE[base] and res and res > 0 then
                PERSIST.configGrenades[base] = res
                cch.grenades[base] = { resID = res, insID = R.resToIns[res] or 0 }
                MATCH_CONFIG.grenadeSkins[base] = res
                any = true
            end
        end
        pcall(F.applyInitialConsumableAvatar)
    end
    if saved.vehicleSlots then
        PERSIST.configVehicleSlots = saved.vehicleSlots
        if F.reapplyVehicleSlotsFromConfig(true) then
            any = true
        end
    end
    if saved.hallTheme then
        PERSIST.hallThemeResID = tonumber(saved.hallTheme)
        if PERSIST.hallThemeResID and F.reapplyHallThemeFromConfig(true) then
            any = true
        end
    end
    if saved.chassisLight then
        PERSIST.configChassisLight = tonumber(saved.chassisLight)
    end
    if saved.chassisLightMap then
        PERSIST.configChassisLightMap = saved.chassisLightMap
    end
    if saved.motionSlots then
        F.persistLoadMotionSlotsFromSaved(saved)
        if F.applyPersistedMotionSlots() then
            any = true
        end
    end
    if saved.pet then
        local petId = tonumber(saved.pet)
        if petId and petId >= 50001 and petId < 50100 then
            PERSIST.configPetResID = petId
            _G.AddOutfitLastPetRes = petId
            _G.OutfitMap = _G.OutfitMap or {}
            _G.OutfitMap.Pet = petId
            any = true
        end
    end
    if any then
        _matchApplied = false
        F.perfInvalidateLobby()
    end
end

function F.getEntity()
    local ok, dc = pcall(require, "client.slua.logic.wardrobe.logic_wardrobe_data_center")
    if not ok or not dc then return nil end
    local ok2, e = pcall(dc.GetWardrobeData)
    return ok2 and e or nil
end

function F.firstInsForRes(entity, resID)
    local arr = entity.ResIDToIndexArrayMap and entity.ResIDToIndexArrayMap[resID]
    if not arr then return nil end
    for _, idx in pairs(arr) do
        local d = entity._data[idx]
        if d and d.count and d.count > 0 then return d.insID end
    end
    return nil
end

function F.injectOne(entity, resID, insID, addCount)
    resID, insID = tonumber(resID), tonumber(insID)
    addCount = tonumber(addCount) or 1
    if not resID or not insID then return false end
    -- Balo/nón: inject bằng key sảnh *000xxx để wardrobe map Lv1/2/3 đúng
    if resID >= 1501001000 and resID < 1501002000 then
        resID = resID - 1000
    elseif resID >= 1502001000 and resID < 1502002000 then
        resID = resID - 1000
    end
    local ownedIns = F.firstInsForRes(entity, resID)
    if ownedIns then
        if addCount > 0 and F.isStackableDepotItem(resID) then
            return F.addDepotItemStack(entity, resID, ownedIns, addCount, nil)
        end
        F.ensureInjectedItemAlive(entity, resID, ownedIns)
        R.resToIns[resID] = ownedIns
        R.insToRes[ownedIns] = resID
        F.indexWeaponSkin(resID, ownedIns)
        return true
    end
    local row = {
        instid = insID,
        res_id = resID,
        count = addCount > 0 and addCount or 1,
        lock_cnt = 0,
        isnew = 0,
        valid_hours = 0,
        expire_ts = 0,
    }
    entity:AddData(row)
    pcall(function()
        if entity.LoadConfigForData and CDataTable and CDataTable.GetTableData then
            local idx = entity._DataCount
            if idx and entity._data[idx] then
                entity:LoadConfigForData(entity._data[idx], CDataTable.GetTableData)
                local d = entity._data[idx]
                if d.resID == nil then d.resID = resID end
                if d.expireTS == nil then d.expireTS = 0 end
                -- Vehicle skins missing Item.cfg get subTabType=0 and bleed into every vehicle tab
                if F.isVehicleRes(resID) then
                    local c = F.cfg(resID)
                    local mainCfg = tonumber(c and c.WardrobeMainTab)
                    if mainCfg == PAGE_PARACHUTE then
                        d.mainTabType = PAGE_PARACHUTE
                        local tab = (c and c.WardrobeTab) or F.wardrobeTab(resID)
                        if tab and tab ~= 0 and tab ~= "" then d.subTabType = tab end
                    else
                        local tab = F.vehicleWardrobeTab(resID)
                        if tab ~= nil and tab ~= 0 and tab ~= "" then
                            d.subTabType = tab
                            d.mainTabType = PAGE_VEHICLE
                        end
                        local st = F.vehicleSlotSubType(resID)
                        if st then d.itemSubType = st end
                    end
                elseif F.isEmoteRes(resID) then
                    -- Hành động: trang Parachute (5) + MVP_MOTION (21)
                    local c = F.cfg(resID)
                    d.mainTabType = tonumber(c and c.WardrobeMainTab) or PAGE_PARACHUTE
                    local tab = (c and c.WardrobeTab) or F.wardrobeTab(resID) or 21
                    if tab == 0 or tab == "" then tab = 21 end
                    d.subTabType = tab
                    if c and c.ItemSubType then d.itemSubType = c.ItemSubType end
                    if c and c.ItemType then d.itemType = c.ItemType end
                elseif F.isParachuteRes(resID) or F.isGlideRes(resID) then
                    local c = F.cfg(resID)
                    d.mainTabType = tonumber(c and c.WardrobeMainTab) or PAGE_PARACHUTE
                    local tab = (c and c.WardrobeTab) or F.wardrobeTab(resID)
                    if tab and tab ~= 0 and tab ~= "" then d.subTabType = tab end
                    d.expire_ts = 0
                    d.expireTS = 0
                end
            end
        end
    end)
    R.insToRes[insID] = resID
    R.resToIns[resID] = insID
    F.indexWeaponSkin(resID, insID)
    return true
end

function F.isStackableDepotItem(resID)
    resID = tonumber(resID)
    if not resID then return false end
    local c = F.cfg(resID)
    if not c then return true end
    local t = tonumber(c.ItemType or c.itemType)
    if not t then return true end
    if t == 30 or t == 21 or t == 6 or t == 39 or t == 620 or t == 16 or t == 102 or t == 103 or t == 618 or t == 619 then
        return true
    end
    if t == 100 then
        local field
        pcall(function()
            if _G.UnlimitedCash and _G.UnlimitedCash.moneyTypeToField then
                field = _G.UnlimitedCash.moneyTypeToField(resID)
            end
        end)
        return field == nil
    end
    local st = F.subType(c)
    if GUN_SUB[st] or st == MELEE_ID or GRENADE_SUB[st] then return false end
    if t == 1 or t == 4 or t == 8 or t == 9 or t == 11 or t == 22 or t == 25 or t == 40 then return false end
    if t == 500 or t == 501 or t == 502 then return false end
    if F.isVehicleRes and F.isVehicleRes(resID) then return false end
    if F.isEmoteRes and F.isEmoteRes(resID) then return false end
    return true
end

function F.isDataMgrCurrency(resID)
    resID = tonumber(resID)
    if not resID then return false end
    local field
    pcall(function()
        if _G.UnlimitedCash and _G.UnlimitedCash.moneyTypeToField then
            field = _G.UnlimitedCash.moneyTypeToField(resID)
        end
    end)
    return field ~= nil
end

function F.grantCurrencyItem(resID, count)
    resID = tonumber(resID)
    count = tonumber(count) or 1
    if not resID or count < 1 then return false end
    local field
    pcall(function()
        if _G.UnlimitedCash and _G.UnlimitedCash.moneyTypeToField then
            field = _G.UnlimitedCash.moneyTypeToField(resID)
        end
    end)
    if not field or not DataMgr then return false end
    DataMgr[field] = (tonumber(DataMgr[field]) or 0) + count
    pcall(function()
        if EventSystem and EVENTTYPE_DATA_MGR then
            if EVENTID_DATAMGR_TICKET_CHANGE then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_TICKET_CHANGE)
            end
            if EVENTID_DATAMGR_GOLD_CHANGE then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_GOLD_CHANGE)
            end
        end
    end)
    return true
end

function F.notifyDepotItemChange(resID, insID, count, markNew)
    resID, insID = tonumber(resID), tonumber(insID)
    count = tonumber(count) or 1
    if not resID or not insID or insID <= 0 then return false end
    local changeList = {
        [insID] = {
            isnew = markNew and 1 or 0,
            instid = insID,
            res_id = resID,
            count = count,
        },
    }
    pcall(function()
        if EventSystem and EVENTTYPE_DATA_MGR then
            if EVENTID_DATAMGR_HALL_DEPOT_CHANGE then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_HALL_DEPOT_CHANGE, changeList)
            end
            if markNew and EVENTID_DATAMGR_HALL_DEPOT_ADD_NEW then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_HALL_DEPOT_ADD_NEW, changeList)
            end
        end
    end)
    return true
end

function F.addDepotItemStack(entity, resID, insID, addCount, opts)
    entity = entity or F.getEntity()
    resID, insID = tonumber(resID), tonumber(insID)
    addCount = tonumber(addCount) or 1
    if not entity or not resID or not insID or addCount < 1 then return false end
    local d = entity.GetDataByInsID and entity:GetDataByInsID(insID)
    if not d then return false end
    local newCount = (tonumber(d.count) or 0) + addCount
    d.count = newCount
    d.expire_ts = 0
    d.expireTS = 0
    d.valid_hours = 0
    pcall(function()
        if entity.LoadConfigForData and CDataTable and CDataTable.GetTableData and not d.bConfigLoaded then
            entity:LoadConfigForData(d, CDataTable.GetTableData)
        end
    end)
    pcall(function()
        if entity.ChangeData then
            entity:ChangeData({
                instid = insID,
                res_id = resID,
                count = newCount,
                lock_cnt = d.lock_cnt or 0,
                isnew = (opts and opts.markNew) and 1 or ((d.isNew == true) and 1 or 0),
                valid_hours = 0,
                expire_ts = 0,
            })
        end
    end)
    if F.isInjectedIns(insID) or F.isInjectedRes(resID) or insID >= (DUMP_INS_BASE or 2100000000) then
        R.resToIns[resID] = insID
        R.insToRes[insID] = resID
    end
    if opts and opts.markNew then
        F.markDepotItemNew(resID, insID, addCount)
    else
        F.notifyDepotItemChange(resID, insID, newCount, false)
    end
    return true
end

function F.grantDepotItem(resID, count, opts)
    count = tonumber(count) or 1
    resID = tonumber(resID)
    opts = type(opts) == "table" and opts or nil
    if not resID or resID <= 0 or count < 1 then return false end
    if F.grantCurrencyItem(resID, count) then return true end
    local entity = F.getEntity()
    if not entity or not entity.bInit then return false end
    local ownedIns = F.firstInsForRes(entity, resID)
    if ownedIns and F.isStackableDepotItem(resID) then
        local ok = F.addDepotItemStack(entity, resID, ownedIns, count, opts)
        if ok then
            F.refreshWardrobe()
            F.scheduleInjectRefresh()
        end
        return ok
    end
    local insID = R.resToIns[resID] or F.dumpInsForRes(resID)
    if not F.injectOne(entity, resID, insID, count) then return false end
    insID = R.resToIns[resID] or insID
    if opts and opts.markNew and insID then
        F.markDepotItemNew(resID, insID, count)
    elseif insID then
        F.notifyDepotItemChange(resID, insID, count, false)
    end
    if F.registerDumpExtraSkin then F.registerDumpExtraSkin(resID) end
    F.invalidateDepotGroupCache()
    F.refreshWardrobe()
    F.scheduleInjectRefresh()
    F.scheduleDepotReinject()
    return true
end

function F.getEntityDepotCount(resID)
    resID = tonumber(resID)
    if not resID then return 0 end
    local entity = F.getEntity()
    if entity and entity.GetItemCountByResID then
        local n = tonumber(entity:GetItemCountByResID(resID)) or 0
        if n > 0 then return n end
    end
    local ins = R.resToIns[resID]
    if ins and entity and entity.GetDataByInsID then
        local d = entity:GetDataByInsID(ins)
        if d and (tonumber(d.count) or 0) > 0 then
            return tonumber(d.count) or 0
        end
    end
    return 0
end

function F.getDepotCount(resID)
    resID = tonumber(resID)
    if not resID then return 0 end
    if F.isDataMgrCurrency(resID) then
        local n = 0
        pcall(function()
            local UC = _G.UnlimitedCash
            if UC and UC.getBalance then n = tonumber(UC.getBalance(resID)) or 0 end
        end)
        return n
    end
    -- Nguyên liệu XSuit ảo (kiểu UnlimitedCash) — không inject depot
    if type(FLS) == "table" and FLS.getXSuitVirtualMatCount then
        local vn = tonumber(FLS.getXSuitVirtualMatCount(resID)) or 0
        if vn > 0 then return vn end
    end
    local n = F.getEntityDepotCount(resID)
    if n > 0 then return n end
    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        if F._wardrobeOrigCountByRes and wd then
            n = tonumber(F._wardrobeOrigCountByRes(wd, resID)) or 0
        elseif wd and wd.GetHallDepotItemCountByResID then
            n = tonumber(wd:GetHallDepotItemCountByResID(resID)) or 0
        end
    end)
    return n
end

function F.consumeDepotItem(resID, count)
    resID = tonumber(resID)
    count = tonumber(count) or 1
    if not resID or count < 1 then return false end
    if F.isDataMgrCurrency(resID) then
        local ok = false
        pcall(function()
            local UC = _G.UnlimitedCash
            if UC and UC.spend then ok = UC.spend(resID, count, true) == true end
        end)
        return ok
    end
    -- Nguyên liệu XSuit ảo: spend ảo, không đụng depot entity
    if type(FLS) == "table" and FLS.spendXSuitVirtualMat and FLS.isXSuitVirtualMat
        and FLS.isXSuitVirtualMat(resID) then
        return FLS.spendXSuitVirtualMat(resID, count) == true
    end
    local entity = F.getEntity()
    if not entity or not entity.bInit then return false end
    if F.getDepotCount(resID) < count then return false end
    local ownedIns = F.firstInsForRes(entity, resID) or R.resToIns[resID]
    if not ownedIns then return false end
    local d = entity.GetDataByInsID and entity:GetDataByInsID(ownedIns)
    if not d then return false end
    local cur = tonumber(d.count) or 0
    if cur < count then return false end
    local newCount = cur - count
    d.count = newCount
    d.expire_ts = 0
    if d.expireTS ~= nil then d.expireTS = 0 end
    pcall(function()
        if entity.ChangeData then
            entity:ChangeData({
                instid = ownedIns,
                res_id = resID,
                count = newCount,
                lock_cnt = d.lock_cnt or 0,
                isnew = 0,
                valid_hours = 0,
                expire_ts = 0,
            })
        end
    end)
    if F.isInjectedIns(ownedIns) or F.isInjectedRes(resID) or ownedIns >= 2100000000 then
        R.resToIns[resID] = ownedIns
        R.insToRes[ownedIns] = resID
    end
    F.notifyDepotItemChange(resID, ownedIns, newCount, false)
    return true
end

function F.simulateWeaponUpgrade(instid, group_id, item_level, item_cost)
    instid = tonumber(instid)
    group_id = tonumber(group_id)
    item_level = tonumber(item_level)
    if not instid or not group_id or not item_level then return false end
    local oldInsID = instid
    local oldResID = nil
    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local item = wd:GetHallDepotItemDataByInsID(instid)
        if item then oldResID = tonumber(item.resID or item.res_id) end
    end)
    if not oldResID then
        local entity = F.getEntity()
        local d = entity and entity.GetDataByInsID and entity:GetDataByInsID(instid)
        if d then oldResID = tonumber(d.resID or d.res_id) end
    end
    if not oldResID then return false end
    local mgr = nil
    pcall(function()
        mgr = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.ItemUpgradeModule)
    end)
    if not mgr then return false end
    local groupList = mgr:GetUpgradeGroupByID(group_id)
    if type(groupList) ~= "table" or not groupList[item_level] then return false end
    local nextItemID = tonumber(groupList[item_level].ItemID)
    if not nextItemID or nextItemID <= 0 then return false end
    local function consumeCost(resID, need)
        resID, need = tonumber(resID), tonumber(need) or 0
        if not resID or need <= 0 then return true end
        return F.consumeDepotItem(resID, need) == true
    end
    if type(item_cost) == "table" and next(item_cost) then
        for costIns, costCnt in pairs(item_cost) do
            costIns = tonumber(costIns)
            costCnt = tonumber(costCnt) or 0
            if costIns and costCnt > 0 then
                local entity = F.getEntity()
                local d = entity and entity.GetDataByInsID and entity:GetDataByInsID(costIns)
                local resID = d and tonumber(d.resID or d.res_id)
                if not resID or not consumeCost(resID, costCnt) then return false end
            end
        end
    else
        local cfg = mgr.GetUpgradeCfg and mgr:GetUpgradeCfg(oldResID)
        local matCfgs = (cfg and mgr.CreateMaterialList and mgr:CreateMaterialList(cfg))
            or (mgr.GetItemUpgradeMaterialList and mgr:GetItemUpgradeMaterialList(oldResID))
            or {}
        if type(matCfgs) ~= "table" then return false end
        for _, cost in ipairs(matCfgs) do
            if not consumeCost(cost.CostItem, cost.CostItemNum) then return false end
        end
    end
    local entity = F.getEntity()
    if entity and F.purgeEntityDepotItem then
        F.purgeEntityDepotItem(entity, oldResID, oldInsID)
    end
    pcall(function() if F.unequipInjectedIns then F.unequipInjectedIns(oldInsID, oldResID) end end)
    if not F.grantDepotItem(nextItemID, 1) then return false end
    if F.persistReplaceDepotItem then F.persistReplaceDepotItem(oldResID, nextItemID) end
    pcall(function()
        if F.saveWeaponToCache and F.weaponIdFromSkin then
            local wid = F.weaponIdFromSkin(nextItemID)
            local newInsID = tonumber(R.resToIns[nextItemID])
            if wid and newInsID then F.saveWeaponToCache(wid, nextItemID, newInsID) end
        end
    end)
    local newInsID = tonumber(R.resToIns[nextItemID])
    if not newInsID then
        pcall(function()
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local item = wd:GetHallDepotItemDataByResID(nextItemID)
            if item then newInsID = tonumber(item.insID or item.instid or item.ins_id) end
        end)
    end
    if not newInsID then return false end
    local ret = { newInsID, oldInsID }
    pcall(function()
        local ItemUpGradeHandler = require("client.network.Protocol.ItemUpGradeHandler")
        if ItemUpGradeHandler and ItemUpGradeHandler.on_upgrade_item_rsp then
            ItemUpGradeHandler.on_upgrade_item_rsp(0, ret)
        end
    end)
    pcall(function() if F.refreshWardrobe then F.refreshWardrobe() end end)
    return true
end

function F.shouldMarkDepotItemNew(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    if F.isDataMgrCurrency(resID) then return false end
    local c = F.cfg(resID)
    if not c then return false end
    local t = tonumber(c.ItemType or c.itemType)
    if t == 30 or t == 21 or t == 6 or t == 39 or t == 620 then return true end
    local ok = false
    pcall(function()
        local WardrobeLogicManager = require("client.slua.logic.wardrobe.logic_wardrobe_new")
        if WardrobeLogicManager and WardrobeLogicManager.IsWardrobeShow then
            ok = WardrobeLogicManager:IsWardrobeShow(c) == true
        end
    end)
    return ok
end

function F.markDepotItemNew(resID, insID, count)
    resID, insID = tonumber(resID), tonumber(insID)
    count = tonumber(count) or 1
    if not resID or not insID or insID <= 0 then return false end
    if not F.shouldMarkDepotItemNew(resID) then
        F.notifyDepotItemChange(resID, insID, count, false)
        return false
    end
    local entity = F.getEntity()
    if not entity then return false end
    pcall(function()
        if entity.ChangeItemNewState then
            entity:ChangeItemNewState(insID, true)
        end
        local d = entity.GetDataByInsID and entity:GetDataByInsID(insID)
        if d then
            d.isNew = true
            count = tonumber(d.count) or count
        end
    end)
    F.notifyDepotItemChange(resID, insID, count, true)
    return true
end

function F.reviveExpiredOwned(entity)
    entity = entity or F.getEntity()
    if not entity or not entity.bInit or not entity._data then return end
    local now = 0
    pcall(function()
        local TimeUtil = require("client.common.time_util")
        now = tonumber(TimeUtil.GetServerTimeInSec()) or 0
    end)
    if now <= 0 then return end
    _G.AddOutfitRevived = _G.AddOutfitRevived or {}
    local n = 0
    for i = 1, (entity._DataCount or #entity._data) do
        local d = entity._data[i]
        if d then
            local exp = tonumber(d.expire_ts or d.expireTS) or 0
            local res = tonumber(d.res_id or d.resID)
            local ins = tonumber(d.instid or d.insID)
            if exp > 0 and exp <= now and res and ins and (tonumber(d.count) or 0) > 0 then
                d.expire_ts = 0
                if d.expireTS ~= nil then d.expireTS = 0 end
                if d.valid_hours ~= nil then d.valid_hours = 0 end
                _G.AddOutfitRevived[res] = ins
                n = n + 1
            end
        end
    end
end

function F.mergeRevivedIntoMaps()
    for res, ins in pairs(_G.AddOutfitRevived or {}) do
        if not R.resToIns[res] then
            R.resToIns[res] = ins
            R.insToRes[ins] = res
            F.indexWeaponSkin(res, ins)
        end
    end
end

function F.injectArmory(resID, insID)
    local wid = F.weaponIdFromSkin(resID)
    if not wid then return end
    local Arm = require("client.logic.armory.logic_armory")
    Arm.rsp_list = Arm.rsp_list or { skin_list = {}, install_list = {} }
    Arm.rsp_list.skin_list = Arm.rsp_list.skin_list or {}
    Arm.rsp_list.install_list = Arm.rsp_list.install_list or {}
    if not Arm.rsp_list.skin_list[wid] then Arm.rsp_list.skin_list[wid] = {} end
    Arm.rsp_list.skin_list[wid][resID] = { is_open = 1 }
    Arm.WardrobeInsList = Arm.WardrobeInsList or {}
    Arm.WardrobeInsList[resID] = insID
end

function F.mergeInjectedArmorySkins()
    for _, skins in pairs(R.byWeapon) do
        for resID, insID in pairs(skins) do
            F.injectArmory(resID, insID)
        end
    end
end

local DUMP_INS_BASE = 2100000000
local DUMP_SKIN_FILE = "KuttaVai_cfg453_dump_skins.txt"

function F.loadDumpExtraSkins()
    _G.KuttaCheatTG_DumpExtraSkins = _G.KuttaCheatTG_DumpExtraSkins or {}
    if _G.KuttaCheatTG_DumpExtraLoaded then return end
    _G.KuttaCheatTG_DumpExtraLoaded = true
    pcall(function()
        local paths = GetConfigPaths(DUMP_SKIN_FILE)
        for _, path in ipairs(paths) do
            local ok, f = pcall(io.open, path, "r")
            if ok and f then
                for line in f:lines() do
                    local id = tonumber((tostring(line or ""):gsub("%s+", "")))
                    if id and id > 0 then _G.KuttaCheatTG_DumpExtraSkins[id] = true end
                end
                f:close()
                return
            end
        end
    end)
end

function F.saveDumpExtraSkins()
    pcall(function()
        local ids = {}
        for id, on in pairs(_G.KuttaCheatTG_DumpExtraSkins or {}) do
            if on and tonumber(id) then ids[#ids + 1] = tonumber(id) end
        end
        table.sort(ids)
        local txt = table.concat(ids, "\n")
        for _, path in ipairs(GetConfigPaths(DUMP_SKIN_FILE)) do
            local ok, f = pcall(io.open, path, "w")
            if ok and f then
                f:write(txt)
                f:close()
                return
            end
        end
    end)
end

function F.shouldPersistDepotGrant(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    if F.isDataMgrCurrency and F.isDataMgrCurrency(resID) then return false end
    if F.isStackableDepotItem and F.isStackableDepotItem(resID) then return false end
    return true
end

function F.registerDumpExtraSkin(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    if not F.shouldPersistDepotGrant(resID) then return false end
    F.loadDumpExtraSkins()
    _G.KuttaCheatTG_DumpExtraSkins = _G.KuttaCheatTG_DumpExtraSkins or {}
    _G.KuttaCheatTG_DumpExtraSkins[resID] = true
    if F.persistRememberDepotItem then F.persistRememberDepotItem(resID) end
    local insID = R.resToIns[resID]
    if insID then
        local c = F.cfg(resID)
        local st = F.subType(c)
        if GUN_SUB[st] or st == MELEE_ID then
            F.injectArmory(resID, insID)
        end
        pcall(function()
            local entity = F.getEntity()
            if not entity then return end
            if F.isVehicleRes and F.isVehicleRes(resID) then
                F.fixInjectedVehicleDepotTabs(entity)
            elseif F.isEmoteRes and F.isEmoteRes(resID) then
                F.fixInjectedEmoteDepotTabs(entity)
            elseif (F.isParachuteRes and F.isParachuteRes(resID)) or (F.isGlideRes and F.isGlideRes(resID)) then
                F.fixInjectedParachuteDepotTabs(entity)
            end
        end)
    end
    return true
end

function F.reinjectMissingDumpExtras(entity)
    entity = entity or F.getEntity()
    if not entity or not entity.bInit then return 0 end
    F.loadDumpExtraSkins()
    local n = 0
    for resID, on in pairs(_G.KuttaCheatTG_DumpExtraSkins or {}) do
        if on then
            resID = tonumber(resID)
            if resID and not F.isInjectedDepotAlive(resID) and F.shouldInjectDepotRes(resID) then
                local insID = R.resToIns[resID] or F.dumpInsForRes(resID)
                if F.injectOne(entity, resID, insID) then
                    n = n + 1
                    insID = R.resToIns[resID] or insID
                    local c = F.cfg(resID)
                    local st = F.subType(c)
                    if GUN_SUB[st] or st == MELEE_ID then
                        F.injectArmory(resID, insID)
                    end
                end
            end
        end
    end
    if n > 0 then
        pcall(F.fixInjectedVehicleDepotTabs, entity)
        pcall(F.fixInjectedEmoteDepotTabs, entity)
        pcall(F.fixInjectedParachuteDepotTabs, entity)
    end
    return n
end

function F.dumpInsForRes(resID)
    return DUMP_INS_BASE + (tonumber(resID) or 0)
end

function F.injectDumpItem(resID, opts)
    local cfg = _G.KuttaVaiConfig
    if cfg and cfg.ModSkin == false and not (cfg.FreeLobbyShop == true) and not ucOn() then return false, "modskin_off" end
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false, "bad_id" end
    opts = type(opts) == "table" and opts or nil
    F.loadDumpExtraSkins()
    local entity = F.getEntity()
    if not entity or not entity.bInit then return false, "no_depot" end
    local insID = R.resToIns[resID] or F.dumpInsForRes(resID)
    if not F.injectOne(entity, resID, insID) then return false, "inject_fail" end
    insID = R.resToIns[resID] or insID
    if opts and opts.markNew and insID then
        F.markDepotItemNew(resID, insID, opts.count or 1)
    end
    local c = F.cfg(resID)
    local st = F.subType(c)
    if GUN_SUB[st] or st == MELEE_ID then
        F.injectArmory(resID, R.resToIns[resID] or insID)
    end
    pcall(function()
        if F.isVehicleRes and F.isVehicleRes(resID) then
            F.fixInjectedVehicleDepotTabs(entity)
            local pc = GameplayData and GameplayData.GetPlayerController and GameplayData.GetPlayerController()
            if pc and F.directInjectVehicleSkinList then
                F.directInjectVehicleSkinList(pc, { resID })
            end
        elseif F.isEmoteRes and F.isEmoteRes(resID) then
            F.fixInjectedEmoteDepotTabs(entity)
        elseif (F.isParachuteRes and F.isParachuteRes(resID)) or (F.isGlideRes and F.isGlideRes(resID)) then
            F.fixInjectedParachuteDepotTabs(entity)
        end
    end)
    _G.KuttaCheatTG_DumpExtraSkins[resID] = true
    if F.persistRememberDepotItem then F.persistRememberDepotItem(resID) end
    pcall(F.sanitizeAllInjectedExpire)
    pcall(F.ensureInjectedResources)
    F.refreshWardrobe()
    F.scheduleInjectRefresh()
    return true, "ok"
end

_G.KuttaCheatTG_AddDumpSkinToDepot = function(resID)
    local ok, err = F.injectDumpItem(resID)
    return ok == true, err
end



-- ==============================================================================
-- UNLIMITED CASH (Lobby) — KuttaVaiConfig.UnlimitedCash
-- ==============================================================================
_G.UnlimitedCash = _G.UnlimitedCash or {}
local UC = _G.UnlimitedCash

-- Random number generator function
local function randomInt(min, max)
    math.randomseed(os.time() + math.random(1, 99999))
    return math.random(min, max)
end

-- Store random collector level once per session
local randomCollectorLevel = randomInt(80, 95)

UC.VALUE = 999999999
UC.VIRTUAL_START = 373592  -- Fixed ticket value

local function ucOn()
    return true
end

function UC.moneyTypeToField(money_type)
    money_type = tonumber(money_type)
    if money_type == nil then return nil end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if okSC and StoreConst then
        if money_type == StoreConst.label_price_type_uc then return "ticket" end
        if money_type == StoreConst.label_price_type_bp then return "gold" end
        if money_type == StoreConst.label_price_type_diamond then return "diamond" end
        if money_type == StoreConst.label_price_type_fp then return "fp_token" end
        if money_type == StoreConst.label_price_type_gold_chip then return "gold_chip" end
        if money_type == StoreConst.label_price_type_chip then return "gold_chip" end
    end
    if money_type == 2 then return "ticket" end
    if money_type == 0 then return "gold" end
    if money_type == 6 then return "diamond" end
    if money_type == 102 then return "fp_token" end
    if money_type == 103 then return "gold_chip" end
    if money_type == 1006 then return "ticket" end
    return nil
end

function UC.ensureWallet()
    if UC._wallet then return end
    UC._wallet = {}
    local function seed(field, dmField, isFixed)
        local v = nil
        pcall(function() v = tonumber(DataMgr and DataMgr[dmField]) end)
        if not v or v <= 0 then
            if isFixed then
                v = UC.VIRTUAL_START  -- Fixed: 373592
            else
                -- Random values like RandomMoney.h
                if field == "gold" then
                    v = randomInt(100000, 200000)      -- GOLD: 1Lakh to 2Lakh
                elseif field == "diamond" then
                    v = randomInt(100000, 200000)      -- SILVER: 1Lakh to 2Lakh
                elseif field == "eternal_diamond" then
                    v = randomInt(50000, 150000)       -- AG: 50k to 1.5Lakh
                elseif field == "fp_token" then
                    v = randomInt(50000, 100000)       -- KR TOKEN: 50k to 1Lakh
                else
                    v = randomInt(999999000, 999999999) -- Others: high values
                end
            end
        end
        UC._wallet[field] = v
    end
    seed("gold", "gold", false)              -- Random: 100000-200000
    seed("ticket", "ticket", true)           -- Fixed: 373592
    seed("diamond", "diamond", false)        -- Random: 100000-200000
    seed("fp_token", "fp_token", false)      -- Random: 50000-100000
    seed("gold_chip", "gold_chip", false)    -- Random: 999999000-999999999
    seed("gen_ticket", "gen_ticket", false)  -- Random: 999999000-999999999
    seed("eternal_diamond", "eternal_diamond", false) -- Random: 50000-150000
    seed("corps_money", "corps_money", false) -- Random: 999999000-999999999
    seed("smelt", "smelt", false)            -- Random: 999999000-999999999
    seed("battle_coin", "battle_coin", false) -- Random: 999999000-999999999
end

function UC.syncToDataMgr(silent)
    if not ucOn() then return end
    UC.ensureWallet()
    silent = (silent == true)
    pcall(function()
        if not DataMgr or not UC._wallet then return end
        DataMgr.gold = UC._wallet.gold
        DataMgr.ticket = UC._wallet.ticket
        DataMgr.diamond = UC._wallet.diamond
        DataMgr.fp_token = UC._wallet.fp_token
        DataMgr.gold_chip = UC._wallet.gold_chip
        DataMgr.gen_ticket = UC._wallet.gen_ticket
        DataMgr.eternal_diamond = UC._wallet.eternal_diamond
        DataMgr.corps_money = UC._wallet.corps_money
        DataMgr.smelt = UC._wallet.smelt
        DataMgr.battle_coin = UC._wallet.battle_coin
        if DataMgr.roleData then DataMgr.roleData.bgbg_vip = 1 end
        if not silent and EventSystem then
            EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_GOLD_CHANGE, DataMgr.gold)
            EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_TICKET_CHANGE, DataMgr.ticket)
            EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_DIAMOND_CHANGE, DataMgr.diamond)
            -- EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_ROLE_LEVEL_CHANGE, DataMgr.roleData.level)
        end
    end)
end

function UC.getBalance(money_type)
    UC.ensureWallet()
    local f = UC.moneyTypeToField(money_type)
    if f and UC._wallet then return tonumber(UC._wallet[f]) or 0 end
    return 0
end

function UC.spend(money_type, amount, silent)
    if not ucOn() then return true end
    UC.ensureWallet()
    amount = tonumber(amount) or 0
    if amount <= 0 then return true end
    local f = UC.moneyTypeToField(money_type)
    if not f then return true end
    if (UC._wallet[f] or 0) < amount then return false end
    UC._wallet[f] = UC._wallet[f] - amount
    UC.syncToDataMgr(silent == true)
    return true
end

function UC.ApplyNow(silent)
    if not ucOn() then return end
    UC.syncToDataMgr(silent == true)
end

local function ucWrapFn(tbl, name, wrapper)
    if not tbl or type(tbl[name]) ~= "function" or tbl["__Kutta_uc_" .. name] then return false end
    tbl["__Kutta_uc_" .. name] = tbl[name]
    tbl[name] = wrapper(tbl["__Kutta_uc_" .. name])
    return true
end

function UC.getCurrentLotteryId()
    local lotteryId = nil
    pcall(function()
        local mod = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.store_supply_manager)
        if not mod then return end
        if mod.GetCurLotteryId then lotteryId = mod:GetCurLotteryId() end
        if not lotteryId and mod.GetCurrentFrame then
            local frame = mod:GetCurrentFrame()
            if frame and frame.currentTabData then
                lotteryId = frame.currentTabData.lotteryId or frame.currentTabData.lottery_id
            end
        end
    end)
    return tonumber(lotteryId)
end

function UC.getLotteryPool(lotteryId)
    lotteryId = tonumber(lotteryId)
    if not lotteryId then return {} end
    local list = {}
    pcall(function()
        local mod = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.store_supply_manager)
        if mod and mod.GetSupplyRewardList then
            local r = mod:GetSupplyRewardList(lotteryId)
            if r then for _, v in pairs(r) do list[#list + 1] = v end end
        end
    end)
    return list
end

function UC.injectReward(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    UC.ApplyNow(true)
    if _G.KuttaCheatTG_AddDumpSkinToDepot then
        local ok = _G.KuttaCheatTG_AddDumpSkinToDepot(resID)
        if ok then return true end
    end
    if type(F) == "table" and F.injectDumpItem then
        return F.injectDumpItem(resID) == true
    end
    return false
end

function UC.simulateLotteryOpen(lotteryId, drawTimes)
    if not ucOn() then return false end
    lotteryId = tonumber(lotteryId) or UC.getCurrentLotteryId()
    if not lotteryId then return false end
    drawTimes = tonumber(drawTimes) or 1
    local pool = UC.getLotteryPool(lotteryId)
    if #pool < 1 then return false end
    local any = false
    for _ = 1, drawTimes do
        local entry = pool[math.random(1, #pool)]
        local resID = tonumber(entry.PropId1 or entry.prop_id1 or entry.PropId or entry.item_id)
        if resID and UC.injectReward(resID) then any = true end
    end
    pcall(function() if F and F.refreshWardrobe then F.refreshWardrobe() end end)
    return any
end

local function ucPatchStoreTable(SU)
    if not SU or type(SU) ~= "table" then return false end
    local hooked = false
    if ucWrapFn(SU, "CheckMoneyIsEnough", function(old)
        return function(money_type, money_price, callback, ...)
            if ucOn() then
                UC.ApplyNow(true)
                local enough = UC.getBalance(money_type) >= (tonumber(money_price) or 0)
                if type(callback) == "function" then callback(enough) end
                return
            end
            return old(money_type, money_price, callback, ...)
        end
    end) then hooked = true end
    if ucWrapFn(SU, "CheckMoney", function(old)
        return function(callback, PriceList, CouponDiscountPrice, ...)
            if ucOn() then
                UC.ApplyNow(true)
                if type(callback) == "function" then callback() end
                return true
            end
            return old(callback, PriceList, CouponDiscountPrice, ...)
        end
    end) then hooked = true end
    if ucWrapFn(SU, "NoEnoughUCAndGoCharge", function(old)
        return function(...)
            if ucOn() then UC.ApplyNow(true); return end
            return old(...)
        end
    end) then hooked = true end
    if ucWrapFn(SU, "BuyShopItems", function(old)
        return function(shopInfoDict, curVersion, voucher)
            if ucOn() then UC.ApplyNow(true) end
            return old(shopInfoDict, curVersion, voucher)
        end
    end) then hooked = true end
    if ucWrapFn(SU, "BuyShopItems2", function(old)
        return function(shopInfoDict, curVersion, voucher)
            if ucOn() then UC.ApplyNow(true) end
            return old(shopInfoDict, curVersion, voucher)
        end
    end) then hooked = true end
    return hooked
end

local function ucPatchMallTable(Mall)
    if not Mall or type(Mall) ~= "table" then return false end
    local hooked = false
    if ucWrapFn(Mall, "IsMoneyEnough", function(old)
        return function(money_type, money_price)
            if ucOn() then UC.ApplyNow(true); return UC.getBalance(money_type) >= (tonumber(money_price) or 0) end
            return old(money_type, money_price)
        end
    end) then hooked = true end
    if ucWrapFn(Mall, "CheckMoneyIsEnough", function(old)
        return function(money_type, money_price, callback)
            if ucOn() then
                UC.ApplyNow(true)
                local enough = UC.getBalance(money_type) >= (tonumber(money_price) or 0)
                if type(callback) == "function" then callback(enough) end
                return
            end
            return old(money_type, money_price, callback)
        end
    end) then hooked = true end
    return hooked
end

function UC.hookStoreUtils()
    pcall(function() require("client.slua.logic.store.utils.store_utils") end)
    local SU = package.loaded["client.slua.logic.store.utils.store_utils"]
    if SU then ucPatchStoreTable(SU) end
    if StoreUtils and type(StoreUtils) == "table" then ucPatchStoreTable(StoreUtils) end
end

function UC.hookMallSystem()
    pcall(function() require("client.logic.mall.logic_mall") end)
    local Mall = package.loaded["client.logic.mall.logic_mall"]
    if Mall then ucPatchMallTable(Mall) end
end

function UC.hookPayBox()
    pcall(function() require("client.slua.logic.common.Payclass.logic_common_pay_box") end)
    local PayBox = package.loaded["client.slua.logic.common.Payclass.logic_common_pay_box"]
    if PayBox then
        ucWrapFn(PayBox, "ShowUcRechargeMsg", function(old)
            return function(...)
                if ucOn() then UC.ApplyNow(true); return end
                return old(...)
            end
        end)
    end
end

function UC.hookSupplyRsp()
    if UC._supplyRspDone then return end
    pcall(function()
        local mod = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.store_supply_manager)
        if not mod then return end
        local UC_ERR = { [2] = true, [19840001] = true, [9910225] = true }
        local function isMoneyErr(code)
            local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
            if not okSC or not StoreConst then return false end
            return code == StoreConst.error_code_uc_not_enough
                or code == StoreConst.error_code_uc_not_enough_new
                or code == StoreConst.error_code_gold_not_enough
                or UC_ERR[code] == true
        end
        ucWrapFn(mod, "buy_shop_by_id_req", function(old)
            return function(self, params, isTenBuy)
                if ucOn() then UC.ApplyNow(true) end
                return old(self, params, isTenBuy)
            end
        end)
        ucWrapFn(mod, "buy_shop_by_id_rsp", function(old)
            return function(self, error_code, shop_id, info, wishInfo)
                if ucOn() then
                    UC.ApplyNow(true)
                    if isMoneyErr(error_code) then
                        local drawTimes = 1
                        if info and info.count then drawTimes = tonumber(info.count) or 1 end
                        pcall(function() UC.simulateLotteryOpen(nil, drawTimes) end)
                        return
                    end
                end
                return old(self, error_code, shop_id, info, wishInfo)
            end
        end)
        ucWrapFn(mod, "buy_market_by_id_req", function(old)
            return function(self, params)
                if ucOn() then UC.ApplyNow(true) end
                return old(self, params)
            end
        end)
        UC._supplyRspDone = true
    end)
end

function UC.refreshLobbyHooks()
    if not ucOn() then return end
    UC.hookStoreUtils()
    UC.hookMallSystem()
    UC.hookPayBox()
    UC.hookSupplyRsp()
    UC.ApplyNow(true)
end

function UC.EnsureHooks()
    if type(DataMgr) ~= "table" then return false end
    if not UC._datamgrHooked then
        UC._datamgrHooked = true
        UC.oldInitRoleData = DataMgr.InitRoleData
        DataMgr.InitRoleData = function(roleDataTb)
            if UC.oldInitRoleData then UC.oldInitRoleData(roleDataTb) end
            UC.ApplyNow(true)
        end
        UC.oldGetItem = DataMgr.GetItemStoreByItemId
        DataMgr.GetItemStoreByItemId = function(nItemId)
            if ucOn() then
                UC.ensureWallet()
                if nItemId == 1000 then return UC._wallet.gold end
                if nItemId == 1001 then return UC._wallet.gold_chip end
                if nItemId == 1006 then return UC._wallet.ticket end
            end
            return UC.oldGetItem(nItemId)
        end
        UC.oldSetItem = DataMgr.SetItemStoreData
        DataMgr.SetItemStoreData = function(nItemId, nCount)
            if ucOn() and UC._wallet then
                nCount = tonumber(nCount) or 0
                if nItemId == 1000 then UC._wallet.gold = nCount
                elseif nItemId == 1001 then UC._wallet.gold_chip = nCount
                elseif nItemId == 1006 then UC._wallet.ticket = nCount end
            end
            UC.oldSetItem(nItemId, nCount)
        end
        UC.oldIsMoneyEnough = DataMgr.IsMoneyEnough
        DataMgr.IsMoneyEnough = function(money_type, money_price)
            if ucOn() then return UC.getBalance(money_type) >= (tonumber(money_price) or 0) end
            return UC.oldIsMoneyEnough(money_type, money_price)
        end
        UC.oldGetMoneyByType = DataMgr.GetMoneyByType
        DataMgr.GetMoneyByType = function(money_type)
            if ucOn() then return UC.getBalance(money_type) end
            return UC.oldGetMoneyByType(money_type)
        end
        UC.oldOnRoleAttrChangeNotify = DataMgr.OnRoleAttrChangeNotify
        DataMgr.OnRoleAttrChangeNotify = function(attriType, attriValue, attriTab, isClickReward)
            if UC.oldOnRoleAttrChangeNotify then
                UC.oldOnRoleAttrChangeNotify(attriType, attriValue, attriTab, isClickReward)
            end
            if ucOn() then UC.syncToDataMgr(true) end
        end
    end
    pcall(function() UC.refreshLobbyHooks() end)
    return true
end

function hook_collect_module()
    local collect_mod = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.collect_module)
    if not collect_mod then return false end
    if collect_mod.OnGetMainData and not collect_mod.__fs_main then
        local old = collect_mod.OnGetMainData
        collect_mod.__fs_main = old
        collect_mod.OnGetMainData = function(_, ret, data, ...)
            if data then
                data.total_score = 399999999
                data.cur_season_collect_score = data.total_score
                if not data.season_score then data.season_score = {} end
                if DataMgr and DataMgr.season_id then
                    data.season_score[DataMgr.season_id] = data.total_score
                end
                if not data.level_reward then data.level_reward = {} end
                for i=1,95 do
                    local e = data.level_reward[i]
                    if not e then
                        data.level_reward[i] = { state = 1 }
                    elseif e.state == 0 then
                        -- P23-FIX No rewards: locked ko claimable banao (claimed state=2 ko mat chedo)
                        e.state = 1
                    end
                end
            end
            local result = old(_, ret, data, ...)
            return result
        end
    end
    if collect_mod.NotifyCollectData and not collect_mod.__fs_notify then
        local old = collect_mod.NotifyCollectData
        collect_mod.__fs_notify = old
        collect_mod.NotifyCollectData = function(_, data)
            if data then
                data.total_score = 499999999
                data.cur_season_collect_score = data.total_score
                if not data.season_score then data.season_score = {} end
                if DataMgr and DataMgr.season_id then
                    data.season_score[DataMgr.season_id] = data.total_score
                end
            end
            local result = old(_, data)
            return result
        end
    end
    if collect_mod.GetCollectTotalScore and not collect_mod.__fs_totalscore then
        local old = collect_mod.GetCollectTotalScore
        collect_mod.__fs_totalscore = old
        collect_mod.GetCollectTotalScore = function(_)
            return 599999999, randomCollectorLevel
        end
    end
    if collect_mod.GetLevelByScore and not collect_mod.__fs_lvscore then
        local old = collect_mod.GetLevelByScore
        collect_mod.__fs_lvscore = old
        collect_mod.GetLevelByScore = function(_, score)
            if score and score >= 0 then
                return randomCollectorLevel, randomCollectorLevel, randomCollectorLevel, 0, 0
            end
            return old(_, score)
        end
    end
    if collect_mod.GetLevelDataByScore and not collect_mod.__fs_lvdata then
        local old = collect_mod.GetLevelDataByScore
        collect_mod.__fs_lvdata = old
        collect_mod.GetLevelDataByScore = function(_, score, isSeason)
            if score and score >= 0 then
                if isSeason then
                    return randomCollectorLevel, "", randomCollectorLevel
                else
                    return randomCollectorLevel, "", randomCollectorLevel
                end
            end
            return old(_, score, isSeason)
        end
    end
    if collect_mod.GetSeasonLevelByScore and not collect_mod.__fs_seasonlv then
        local old = collect_mod.GetSeasonLevelByScore
        collect_mod.__fs_seasonlv = old
        collect_mod.GetSeasonLevelByScore = function(_, score, ...)
            if score and score >= 0 then
                return randomCollectorLevel, false, ""
            end
            return old(_, score, ...)
        end
    end
    if collect_mod.GetCollectScoreByProfile and not collect_mod.__fs_proscore then
        local old = collect_mod.GetCollectScoreByProfile
        collect_mod.__fs_proscore = old
        collect_mod.GetCollectScoreByProfile = function(_, profile)
            local local_uid = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
            if local_uid and profile then
                if type(profile) == "table" and tonumber(profile.uid) == local_uid then
                    return 699999999, 799999999
                end
                if profile == local_uid then
                    return 899999999, 119999999
                end
            end
            local total, cur = old(_, profile)
            return total, cur
        end
    end
    -- P23-FIX badge self-only: sirf apne data par fake, dusro par original (sab par show hota tha)
    if collect_mod.GetCollectScoreByCollectData and not collect_mod.__fs_colscore then
        local old = collect_mod.GetCollectScoreByCollectData
        collect_mod.__fs_colscore = old
        collect_mod.GetCollectScoreByCollectData = function(_, data)
            local self_uid = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
            local my_data = DataMgr and DataMgr.roleData and DataMgr.roleData.brief_collect_data
            local isSelf = false
            pcall(function()
                if data and my_data and data == my_data then isSelf = true end
                -- data me uid ho to check karo
                if not isSelf and data and type(data) == "table" and data.uid and tonumber(data.uid) == self_uid then isSelf = true end
            end)
            if isSelf then
                if data and my_data and data == my_data then
                    return 129999999, 139999999
                end
                if data and data.total_score and data.total_score >= 149999999 then
                    return 159999999, 169999999
                end
            end
            local total, cur = old(_, data)
            return total, cur
        end
    end
    -- P23-FIX badge self-only: NicknameColorManager + collect profile already self-only, yaha extra guard
    pcall(function()
        if collect_mod.GetCollectScoreByProfile and not collect_mod._p23_proSelfGuard then
            collect_mod._p23_proSelfGuard = true
            -- already self-only upar, yaha sirf others ko original ensure (kuch nahi karna)
        end
    end)
    if collect_mod.OnGetItemData and not collect_mod.__fs_item then
        local old = collect_mod.OnGetItemData
        collect_mod.__fs_item = old
        collect_mod.OnGetItemData = function(_, uid, data)
            local local_uid = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
            if tonumber(uid) == local_uid and data then
                if not data.item_detail then data.item_detail = {} end
                for i=1,1000 do
                    if not data.item_detail[i] then
                        data.item_detail[i] = { count = 1, expire_ts = 0 }
                    end
                end
            end
            return old(_, uid, data)
        end
    end
    -- P23-FIX Collection Rewards "No rewards to claim": level_reward sab claimable + claim req local success
    pcall(function()
        if not collect_mod._p23_claimHooked then
            collect_mod._p23_claimHooked = true
            -- 1) level_reward check bypass: koi bhi level claimable dikhao
            for _, fname in ipairs({"IsCanCollectReward", "CanCollectReward", "CheckCanCollect", "HasRewardToClaim", "IsHasReward", "CheckHasReward", "GetCanCollectRewardList"}) do
                pcall(function()
                    local ofn = collect_mod[fname]
                    if type(ofn) == "function" then
                        collect_mod[fname] = function(self, ...)
                            local ok, res = pcall(ofn, self, ...)
                            -- agar original false/empty de to true/claimable do (self-only, no server spam)
                            if fname == "GetCanCollectRewardList" then
                                if type(res) ~= "table" or #res == 0 then
                                    -- saare levels ko claimable list me do
                                    local list = {}
                                    for i = 1, 95 do list[#list+1] = i end
                                    return list
                                end
                                return res
                            else
                                if res == false or res == nil then return true end
                                return res
                            end
                        end
                    else
                        -- agar function hi nahi hai to bana do (UI check pass ho)
                        if fname == "HasRewardToClaim" or fname == "IsHasReward" then
                            collect_mod[fname] = function() return true end
                        end
                    end
                end)
            end
            -- 2) claim req -> local success (server reject ko bypass, avatar equip jaisa)
            local function wrapClaimReq(name)
                local ofn = collect_mod[name]
                if type(ofn) ~= "function" then return end
                local key = "_p23_orig_" .. name
                if collect_mod[key] then return end
                collect_mod[key] = ofn
                collect_mod[name] = function(self, ...)
                    local args = {...}
                    -- pehle original try karo
                    local ok, res = pcall(ofn, self, ...)
                    -- agar fail/empty ho to local grant: level_reward state ko claimed + UI refresh
                    pcall(function()
                        local lvl = tonumber(args[1]) or tonumber(args[2]) or 0
                        -- collect_data me mark claimed taaki "No rewards" na aaye
                        local cd = collect_mod.collect_data
                        if cd and cd.level_reward then
                            if lvl > 0 and cd.level_reward[lvl] then
                                cd.level_reward[lvl].state = 2
                            else
                                for i = 1, 95 do
                                    if cd.level_reward[i] and cd.level_reward[i].state == 1 then
                                        cd.level_reward[i].state = 2
                                        break
                                    end
                                end
                            end
                        end
                        if EventSystem and EVENTTYPE_COLLECT then
                            if EVENTID_COLLECT_DATA_NOTIFY then EventSystem:postEvent(EVENTTYPE_COLLECT, EVENTID_COLLECT_DATA_NOTIFY) end
                            if EVENTID_COLLECT_DETAIL_DATA then EventSystem:postEvent(EVENTTYPE_COLLECT, EVENTID_COLLECT_DETAIL_DATA) end
                        end
                        if collect_mod.NotifyCollectData and cd then collect_mod:NotifyCollectData(cd) end
                    end)
                    return res
                end
            end
            for _, n in ipairs({"CollectRewardReq", "SendCollectRewardReq", "ClaimReward", "ClaimLevelReward", "GetRewardReq", "SendClaimReward", "CollectLevelRewardReq"}) do
                pcall(wrapClaimReq, n)
            end
            -- 3) OnGetMainData me level_reward sabko claimable banao (state=1), claimed ko mat chedo
            pcall(function()
                local cd = collect_mod.collect_data
                if cd and cd.level_reward then
                    for i = 1, 95 do
                        local e = cd.level_reward[i]
                        if e then
                            if e.state == 0 then e.state = 1 end
                        else
                            cd.level_reward[i] = { state = 1 }
                        end
                    end
                end
                -- P23-FIX claim button: UI ko force notify taaki "No rewards" na aaye
                if EventSystem and EVENTTYPE_COLLECT and EVENTID_COLLECT_DATA_NOTIFY then
                    EventSystem:postEvent(EVENTTYPE_COLLECT, EVENTID_COLLECT_DATA_NOTIFY)
                end
            end)
            -- P23-FIX claim server reject: CollectHandler req ko local grant + rewards UI
            pcall(function()
                local okCH2, CH2 = pcall(require, "client.network.Protocol.CollectHandler")
                if okCH2 and CH2 and not CH2._p23_claimGrantHooked then
                    CH2._p23_claimGrantHooked = true
                    for _, fn in ipairs({"send_collect_reward_req", "send_collect_level_reward_req", "send_get_collect_reward_req", "SendCollectReward", "ClaimRewardReq"}) do
                        pcall(function()
                            local orig2 = CH2[fn]
                            if type(orig2) == "function" then
                                CH2[fn] = function(self_or_lvl, a, b, ...)
                                    local lvl = tonumber(a) or tonumber(b) or 0
                                    -- local mark claimed + rewards show (server fail bhi ho to UI me milega)
                                    pcall(function()
                                        local cd2 = collect_mod.collect_data
                                        if cd2 and cd2.level_reward then
                                            if lvl > 0 and cd2.level_reward[lvl] then
                                                cd2.level_reward[lvl].state = 2
                                            else
                                                for i = 1, 95 do
                                                    if cd2.level_reward[i] and cd2.level_reward[i].state == 1 then
                                                        cd2.level_reward[i].state = 2
                                                        lvl = i break
                                                    end
                                                end
                                            end
                                        end
                                        -- rewards UI: level ke hisab se generic reward dikhao
                                        if FLS and FLS.showRewards and FLS.buildReward then
                                            local rlist = {}
                                            -- level reward ka actual res nahi pata to collect score item do
                                            rlist[#rlist+1] = FLS.buildReward(1400001, 1, 0)
                                            FLS.showRewards(rlist)
                                        end
                                        if EventSystem and EVENTTYPE_COLLECT and EVENTID_COLLECT_DATA_NOTIFY then
                                            EventSystem:postEvent(EVENTTYPE_COLLECT, EVENTID_COLLECT_DATA_NOTIFY)
                                        end
                                        if collect_mod.NotifyCollectData and cd2 then
                                            collect_mod:NotifyCollectData(cd2)
                                        end
                                    end)
                                    return orig2(self_or_lvl, a, b, ...)
                                end
                            end
                        end)
                    end
                end
            end)
        end
    end)
    -- Protocol-level claim rsp bypass (server "no rewards" ko local success)
    pcall(function()
        if not _G._p23_collectProtoHooked then
            _G._p23_collectProtoHooked = true
            local okCH, CH = pcall(require, "client.network.Protocol.CollectHandler")
            if okCH and CH then
                for _, fname in ipairs({"send_collect_reward_req", "send_collect_level_reward_req", "send_get_collect_reward_req"}) do
                    pcall(function()
                        local orig = CH[fname]
                        if type(orig) == "function" and not CH["_p23_" .. fname] then
                            CH["_p23_" .. fname] = orig
                            CH[fname] = function(...)
                                -- local success UI: rewards dikhao + collect_data update
                                pcall(function()
                                    if EventSystem and EVENTTYPE_COLLECT and EVENTID_COLLECT_DATA_NOTIFY then
                                        EventSystem:postEvent(EVENTTYPE_COLLECT, EVENTID_COLLECT_DATA_NOTIFY)
                                    end
                                end)
                                return orig(...)
                            end
                        end
                    end)
                end
            end
        end
    end)
    return true
end

pcall(hook_collect_module)

pcall(function()
    local ok, ticker = pcall(require, "common.time_ticker")
    if ok and ticker and ticker.AddTimerOnce then
        for _, d in ipairs({1.0, 3.0, 6.0, 12.0}) do
