-- ==============================================================================

-- FreeLobbyShop: bypass UC client + inject depot khi mua shop / mở hòm
-- Tham chiếu: LuaDump_Decompiled_Clean (store_utils_money, store_supply_manager)
-- ==============================================================================
_G.KuttaCheatTG_FreeLobbyShop = _G.KuttaCheatTG_FreeLobbyShop or {}

local FLS = _G.KuttaCheatTG_FreeLobbyShop
FLS.__hooked = FLS.__hooked or false
FLS.pendingShopBuy = FLS.pendingShopBuy or nil
FLS.pendingMarketBuy = FLS.pendingMarketBuy or nil
FLS.pendingMallBatch = FLS.pendingMallBatch or nil

function FLS.IsEnabled()
    return _G.KuttaVaiConfig and _G.KuttaVaiConfig.FreeLobbyShop == true
end

function FLS.UnlimitedCashOn()
    return true
end

function FLS.getCrateRareBoostPct()
    local v = nil
    if _G.KuttaVaiConfig then v = tonumber(_G.KuttaVaiConfig.CrateRareBoost) end
    if v == nil then v = tonumber(FLS._crateRareBoost) end
    if not v then return 0 end
    if v < 0 then return 0 end
    if v > 100 then return 100 end
    FLS._crateRareBoost = v
    return v
end

function FLS.getItemQuality(resId)
    resId = tonumber(resId)
    if not resId or resId <= 0 then return 0 end
    local q = 0
    pcall(function()
        local cfg = CDataTable.GetTableData("Item", resId)
        if cfg then q = tonumber(cfg.ItemQuality) or 0 end
    end)
    return q
end

function FLS.enrichAwardsMeta(awards)
    if type(awards) ~= "table" then return awards end
    for _, aw in ipairs(awards) do
        if aw and aw.DropItemID and aw.DropItemID > 0 then
            if not aw.ItemQuality or aw.ItemQuality <= 0 then
                aw.ItemQuality = FLS.getItemQuality(aw.DropItemID)
            end
        end
    end
    return awards
end

function FLS.getRareQualityThreshold(awards)
    local qualities = {}
    for _, aw in ipairs(awards or {}) do
        if aw and aw.DropItemID and aw.DropItemID > 0 then
            qualities[#qualities + 1] = tonumber(aw.ItemQuality) or FLS.getItemQuality(aw.DropItemID) or 0
        end
    end
    if #qualities < 1 then return 999 end
    table.sort(qualities)
    local idx = math.max(1, math.ceil(#qualities * 0.7))
    return qualities[idx]
end

function FLS.isRareAward(aw, threshold)
    if not aw then return false end
    local q = tonumber(aw.ItemQuality) or FLS.getItemQuality(aw.DropItemID) or 0
    aw.ItemQuality = q
    return q >= threshold
end

function FLS.checkMoney(money_type, money_price)
    if _G.UnlimitedCash and _G.UnlimitedCash.getBalance then
        return _G.UnlimitedCash.getBalance(money_type) >= (tonumber(money_price) or 0)
    end
    return true
end

function FLS.resolvePriceFromList(priceList, count, isTenBuy)
    if type(priceList) ~= "table" then return nil, 0 end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if not okSC or not StoreConst then return nil, 0 end
    count = tonumber(count) or 1
    isTenBuy = isTenBuy == true or count >= 10
    for _, pv in pairs(priceList) do
        if type(pv) == "table" then
            local ptype = pv[StoreConst.label_price_index_price_type]
            local pval = nil
            if isTenBuy then
                pval = pv[StoreConst.label_price_index_ten_discount_price] or pv[StoreConst.label_price_index_ten_original_price]
            end
            if not pval or pval <= 0 then
                pval = pv[StoreConst.label_price_index_one_discount_price] or pv[StoreConst.label_price_index_one_original_price]
                if isTenBuy and count >= 10 then pval = (pval or 0) * 10 end
            end
            if ptype ~= nil and pval and pval > 0 then
                if not isTenBuy then pval = pval * count end
                return ptype, pval
            end
        end
    end
    return nil, 0
end

function FLS.resolveBuyCost(params)
    if type(params) ~= "table" then return nil, 0 end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if not okSC or not StoreConst then return nil, 0 end
    local shopId = params[StoreConst.label_buy_param_id] or params[1]
    local count = tonumber(params[StoreConst.label_buy_param_count]) or 1
    local priceType = params[StoreConst.label_buy_param_price_type]
    local price = tonumber(params[StoreConst.label_buy_param_client_price])
    if priceType ~= nil and price and price > 0 then
        return priceType, price * count
    end
    local itemData = FLS.findStoreItemByMarketId(shopId)
    if itemData then
        local ptype, pval = FLS.resolvePriceFromList(itemData[StoreConst.label_item_index_price_list], count, count >= 10)
        if ptype and pval > 0 then return ptype, pval end
    end
    local tab = FLS.findSupplyTabEntry(shopId, params, true)
    if tab then
        local ptype, pval = FLS.resolvePriceFromList(tab[StoreConst.label_shop_index_price_list], count, count >= 10)
        if ptype and pval > 0 then return ptype, pval end
    end
    return StoreConst.label_price_type_uc, 0
end

function FLS.notifyNotEnoughMoney()
    pcall(function() Notify("Không đủ UC/BP (số dư ảo).") end)
end

function FLS.chargeForBuy(params)
    if not FLS.IsEnabled() then return true end
    local priceType, totalPrice = FLS.resolveBuyCost(params)
    totalPrice = tonumber(totalPrice) or 0
    if totalPrice <= 0 then return true end
    if _G.UnlimitedCash and _G.UnlimitedCash.spend then
        if _G.UnlimitedCash.spend(priceType, totalPrice, false) then return true end
        FLS.notifyNotEnoughMoney()
        return false
    end
    return true
end

function FLS.shouldLocalOnlyCrate()
    return FLS.IsEnabled()
end

function FLS.buildReward(resId, count, validHours)
    return {
        res_id = tonumber(resId) or 0,
        count = tonumber(count) or 1,
        valid_hours = tonumber(validHours) or 0,
        expire_ts = 0,
        ShowUseTime = true
    }
end

function FLS.showRewards(list)
    if not list or #list < 1 then return end
    pcall(function()
        local Logic_CommonItemGet = require("client.slua.logic.common.CommonItemGet.Logic_CommonItemGet")
        Logic_CommonItemGet.ShowPanel_DecomposeStyle(list, {})
    end)
end

function FLS.hadPermanentItemBefore(resId)
    resId = tonumber(resId)
    if not resId then return false end
    local had = false
    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        if wd and wd.CheckHavePermanentItemForCollect then
            had = wd:CheckHavePermanentItemForCollect(resId) == true
        end
    end)
    return had
end

function FLS.applyCollectScoreForItem(resId)
    if not FLS.IsEnabled() then return end
    resId = tonumber(resId)
    if not resId or resId <= 0 then return end
    FLS._collectCounted = FLS._collectCounted or {}
    if FLS._collectCounted[resId] then return end
    pcall(function()
        local collect_module = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.collect_module)
        if not collect_module or not collect_module.GetScoreByItemId then return end
        if collect_module.itemTb and collect_module.itemTb[resId] then
            FLS._collectCounted[resId] = true
            return
        end
        local addScore = collect_module:GetScoreByItemId(resId) or 0
        if addScore <= 0 then return end

        if not collect_module.collect_data then
            collect_module.collect_data = { total_score = 0, season_score = {}, privacy = 0 }
        end
        local cd = collect_module.collect_data
        local oldTotal = tonumber(cd.total_score) or 0
        local newTotal = oldTotal + addScore
        cd.total_score = newTotal

        local season = 1
        if collect_module.GetSeasonId then season = collect_module:GetSeasonId() or 1 end
        cd.season_score = cd.season_score or {}
        cd.season_score[season] = (tonumber(cd.season_score[season]) or 0) + addScore

        collect_module.itemTb = collect_module.itemTb or {}
        local now = os.time()
        pcall(function()
            local TimeUtil = require("client.common.time_util")
            if TimeUtil and TimeUtil.GetServerTimeInSec then
                now = TimeUtil.GetServerTimeInSec()
            end
        end)
        collect_module.itemTb[resId] = now
        FLS._collectCounted[resId] = true

        if collect_module.NotifyCollectData then
            collect_module:NotifyCollectData(cd)
        end
        if collect_module.SetCollectItemData then
            collect_module:SetCollectItemData(collect_module.itemTb)
        end
        if collect_module.UpdateCollectStatsData then
            collect_module:UpdateCollectStatsData()
        end
        pcall(function()
            local collect_up_level = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.collect_up_level)
            if collect_up_level and collect_up_level.ShowCollectProgressBar then
                collect_up_level:ShowCollectProgressBar(addScore, newTotal)
            end
        end)
        if EventSystem then
            EventSystem:postEvent(EVENTTYPE_COLLECT, EVENTID_COLLECT_DATA_NOTIFY)
            EventSystem:postEvent(EVENTTYPE_COLLECT, EVENTID_COLLECT_DETAIL_DATA)
        end
    end)
end

function FLS.grantResId(resId, count)
    resId = tonumber(resId)
    count = tonumber(count) or 1
    if not resId or resId <= 0 or count < 1 then return false end
    local hadBefore = FLS.hadPermanentItemBefore(resId)
    local ok = false
    if type(F) == "table" and F.grantDepotItem then
        ok = F.grantDepotItem(resId, count, { markNew = not hadBefore, count = count }) == true
    else
        for _ = 1, count do
            if F.injectDumpItem(resId, { markNew = not hadBefore, count = 1 }) then ok = true end
        end
    end
    if ok and not hadBefore then
        FLS.applyCollectScoreForItem(resId)
    end
    return ok
end

function FLS.scanItemList(list, marketId, StoreConst)
    if type(list) ~= "table" or not StoreConst then return nil end
    local midKey = StoreConst.label_item_index_market_id
    for sid, data in pairs(list) do
        if type(data) == "table" then
            if tonumber(sid) == marketId then return data end
            local mid = data[midKey]
            if mid and tonumber(mid) == marketId then return data end
        end
    end
    return nil
end

function FLS.findStoreItemByMarketId(marketId)
    marketId = tonumber(marketId)
    if not marketId then return nil end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if not okSC or not StoreConst or not StoreConst.store_data then return nil end
    local storeData = StoreConst.store_data

    local function scanTab(tab)
        if type(tab) ~= "table" then return nil end
        local listKey = StoreConst.label_market_index_market_list
        if listKey and tab[listKey] then
            local found = FLS.scanItemList(tab[listKey], marketId, StoreConst)
            if found then return found end
        end
        local subKey = StoreConst.label_market_index_sub_list
        if subKey and tab[subKey] then
            for _, sub in pairs(tab[subKey]) do
                if type(sub) == "table" and sub[listKey] then
                    local found = FLS.scanItemList(sub[listKey], marketId, StoreConst)
                    if found then return found end
                end
            end
        end
        return nil
    end

    if storeData.store_list then
        for _, tab in pairs(storeData.store_list) do
            local found = scanTab(tab)
            if found then return found end
        end
    end
    for tabId, tab in pairs(storeData) do
        if tabId ~= "store_list" then
            local found = scanTab(tab)
            if found then return found end
        end
    end
    return nil
end

function FLS.getContextSupplyTabId()
    local tabId = nil
    pcall(function()
        local mgr = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.store_supply_manager)
        if mgr and mgr.GetCurrentFrame then
            local frame = mgr:GetCurrentFrame()
            if frame and frame.currentTabData and frame.currentTabData.tabId then
                tabId = frame.currentTabData.tabId
            end
        end
    end)
    return tabId
end

function FLS.extractShopIdsFromParams(params)
    local ids = {}
    local seen = {}
    local function add(id)
        id = tonumber(id)
        if id and id > 0 and not seen[id] then
            seen[id] = true
            ids[#ids + 1] = id
        end
    end
    if type(params) ~= "table" then return ids end
    add(params[1])
    add(params[4])
    pcall(function()
        local StoreConst = require("client.logic.store.store_const")
        add(params[StoreConst.label_buy_param_id])
        add(params[StoreConst.label_buy_param_tab_id])
        add(params[StoreConst.label_buy_param_sub_id])
    end)
    return ids
end

function FLS.extractCrateContextIds(params, shopId)
    local ids = FLS.extractShopIdsFromParams(params)
    local seen = {}
    for _, id in ipairs(ids) do seen[id] = true end
    local function add(id)
        id = tonumber(id)
        if id and id > 0 and not seen[id] then
            seen[id] = true
            ids[#ids + 1] = id
        end
    end
    add(shopId)
    add(FLS._lastSupplyTabId)
    return ids
end

function FLS.isClassicCrateParams(params)
    local okSU, StoreUtils = pcall(require, "client.slua.logic.store.utils.store_utils")
    if not okSU or not StoreUtils or not StoreUtils.IsClassicCrate then return false end
    for _, id in ipairs(FLS.extractShopIdsFromParams(params)) do
        if StoreUtils.IsClassicCrate(id) then return true end
    end
    return false
end

function FLS.findSupplyTabEntry(shopId, params, useCrateContext)
    shopId = tonumber(shopId)
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if not okSC or not StoreConst or not StoreConst.supply_data then return nil, nil end
    local sd = StoreConst.supply_data
    local candidates = useCrateContext and FLS.extractCrateContextIds(params, shopId) or FLS.extractShopIdsFromParams(params)
    if shopId and shopId > 0 then
        local seen = {}
        for _, id in ipairs(candidates) do seen[id] = true end
        if not seen[shopId] then candidates[#candidates + 1] = shopId end
    end
    for _, tid in ipairs(candidates) do
        local tab = sd[tid]
        if type(tab) == "table" then return tab, tid end
    end
    for tid, tab in pairs(sd) do
        if type(tab) == "table" and tid ~= "supply_list" then
            local boxId = tab[StoreConst.label_shop_index_id_box]
            local itemBoxId = tab[StoreConst.label_shop_index_item_id_box]
            for _, sid in ipairs(candidates) do
                if sid == tid or sid == boxId or sid == itemBoxId then
                    return tab, tonumber(tid) or tid
                end
            end
        end
    end
    return nil, nil
end

function FLS.collectDropListsFromTab(tab)
    local lists = {}
    if type(tab) ~= "table" then return lists end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if not okSC or not StoreConst then return lists end
    local keys = {
        StoreConst.label_shop_index_drop_rate_list,
        StoreConst.label_shop_index_preview_items,
        StoreConst.label_shop_index_not_have_drop,
        StoreConst.label_shop_index_timing_drop_rate,
        StoreConst.label_shop_index_exchange_list,
        StoreConst.label_shop_index_item_list,
        StoreConst.label_shop_index_recomment_list
    }
    for i = 1, #keys do
        local lst = tab[keys[i]]
        if type(lst) == "table" and next(lst) then
            lists[#lists + 1] = lst
        end
    end
    return lists
end

function FLS.mergeDropEntries(tab)
    local merged = {}
    if type(tab) ~= "table" then return merged end
    for _, lst in ipairs(FLS.collectDropListsFromTab(tab)) do
        for _, v in pairs(lst) do
            if type(v) == "table" then
                merged[#merged + 1] = v
            end
        end
    end
    return merged
end

function FLS.rewardsToItemList(rewards)
    local item_list = {}
    if type(rewards) ~= "table" then return item_list end
    for i = 1, #rewards do
        local r = rewards[i]
        if r then
            local resid = r.res_id or r.resid or r.item_id
            item_list[#item_list + 1] = {
                resid = resid,
                res_id = resid,
                count = r.count or r.num or 1,
                valid_hours = r.valid_hours or 0,
                to_res_id = r.to_res_id or 0,
                to_res_cnt = r.to_res_cnt or 0
            }
        end
    end
    return item_list
end

function FLS.shouldPlayCrateAnimation(shopId, params, rewards, openCount)
    openCount = tonumber(openCount) or 1
    if openCount >= 10 then return true end
    if type(rewards) == "table" and #rewards > 1 then return true end
    if FLS.isClassicCrateParams(params) then return true end
    if FLS.isSupplyCrateShopId(shopId, params, true) then return true end
    local itemData = FLS.findStoreItemByMarketId(shopId)
    if itemData then
        local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
        local resId = okSC and StoreConst and itemData[StoreConst.label_item_index_id]
        if resId then
            local okSU, StoreUtils = pcall(require, "client.slua.logic.store.utils.store_utils")
            if okSU and StoreUtils and StoreUtils.CheckIsChest and StoreUtils.CheckIsChest(resId) then
                return true
            end
        end
    end
    return false
end

function FLS.playCrateOpenAnimation(rewards, openCount, opts)
    opts = opts or {}
    if type(rewards) ~= "table" or #rewards < 1 then return false end
    local item_list = FLS.rewardsToItemList(rewards)
    if #item_list < 1 then return false end
    local bDrawTen = opts.forceTen == true or (tonumber(openCount) or #item_list) >= 10
    local panelOpts = { needShowMovie = true }
    local played = false
    pcall(function()
        if not UIManager or not UIManager.UI_Config or not UIManager.UI_Config.new_supply_get_panel then return end
        if UIManager.IsUIShow(UIManager.UI_Config.new_supply_get_panel) then
            local boxUI = UIManager.GetUI(UIManager.UI_Config.new_supply_get_panel)
            if boxUI and boxUI.TryShowSupplyGetPanel then
                boxUI:TryShowSupplyGetPanel(item_list, bDrawTen, panelOpts)
                played = true
            end
        end
        if not played then
            UIManager.ShowUI(UIManager.UI_Config.new_supply_get_panel, item_list, bDrawTen, panelOpts)
            played = true
        end
    end)
    if not played then
        pcall(function()
            local ShopSystem = require("client.logic.shop.logic_shop")
            if not ShopSystem then return end
            if bDrawTen and ShopSystem.on_open_10chest_rsp then
                ShopSystem.on_open_10chest_rsp(0, item_list, {}, nil, nil, nil, opts.chestId)
                played = true
            elseif ShopSystem.on_open_pandora_chest_rsp then
                ShopSystem.on_open_pandora_chest_rsp(item_list, {}, {})
                played = true
            elseif ShopSystem.on_open_chest_rsp then
                ShopSystem.on_open_chest_rsp(0, opts.chestId or 0, item_list, 0, 0, 0, {}, nil, 0)
                played = true
            end
        end)
    end
    return played
end

function FLS.finishCrateOpen(shopId, rewards, openCount)
    FLS._lastCrateSimulated = shopId
    FLS.playCrateOpenAnimation(rewards, openCount)
end

function FLS.simulateClassicCrateOpen(params)
    if not FLS.IsEnabled() or type(params) ~= "table" then return false end
    if not FLS.chargeForBuy(params) then return false end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    local shopId = params[1]
    local openCount = params[8] or 1
    if okSC and StoreConst then
        shopId = params[StoreConst.label_buy_param_id] or shopId
        openCount = params[StoreConst.label_buy_param_count] or openCount
    end
    local granted, rewards = FLS.grantFromChestMarketId(shopId, openCount, params)
    if not granted then
        local tab = FLS.findSupplyTabEntry(shopId, params, true)
        if tab and okSC and StoreConst then
            local gid = tab[StoreConst.label_shop_index_guarantee_itemid]
            if gid and gid > 0 then
                rewards = {}
                granted = false
                for _ = 1, (tonumber(openCount) or 1) do
                    if FLS.grantResId(gid, 1) then
                        granted = true
                        rewards[#rewards + 1] = FLS.buildReward(gid, 1, 0)
                    end
                end
            end
        end
    end
    if granted then
        FLS.finishCrateOpen(shopId, rewards, openCount)
        FLS.pendingShopBuy = nil
    else
        pcall(function()
            Notify("Hòm Cổ Điển: chưa đọc được drop. Vào tab hòm xem preview 1 lần rồi mở lại.")
        end)
    end
    return granted
end

function FLS.resolveCrateTabIds(params, shopId)
    local ids = {}
    local seen = {}
    local function add(id)
        id = tonumber(id)
        if id and id > 0 and not seen[id] then
            seen[id] = true
            ids[#ids + 1] = id
        end
    end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if okSC and StoreConst and type(params) == "table" then
        add(params[StoreConst.label_buy_param_tab_id])
        add(params[StoreConst.label_buy_param_id])
    end
    add(shopId)
    add(FLS._lastSupplyTabId)
    return ids
end

function FLS.getSupplyTabData(shopId, params)
    shopId = tonumber(shopId)
    if not shopId then return nil, nil end
    local tab, tabId = FLS.findSupplyTabEntry(shopId, params, true)
    if tab then return tab, tabId end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if not okSC or not StoreConst or not StoreConst.supply_data then return nil, nil end
    return StoreConst.supply_data[shopId], shopId
end

function FLS.getSupplyDropListForTab(tabId, params)
    tabId = tonumber(tabId)
    if not tabId then return nil, nil end
    local tab, resolvedId = FLS.getSupplyTabData(tabId, params)
    if not tab then return nil, nil end
    local merged = FLS.mergeDropEntries(tab)
    if #merged > 0 then return merged, resolvedId or tabId end
    return nil, resolvedId or tabId
end

function FLS.getSupplyDropList(shopId, params)
    for _, tid in ipairs(FLS.resolveCrateTabIds(params, shopId)) do
        local drops, resolvedTab = FLS.getSupplyDropListForTab(tid, params)
        if drops and next(drops) then return drops, resolvedTab or tid end
    end
    local tab, tabId = FLS.findSupplyTabEntry(shopId, params, true)
    if tab then
        local merged = FLS.mergeDropEntries(tab)
        if #merged > 0 then return merged, tabId end
    end
    return nil, shopId
end

function FLS.buildAwardsFromDropList(dropList)
    if type(dropList) ~= "table" or not next(dropList) then return nil end
    local awards = nil
    pcall(function()
        local tcm = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.treasure_chest_manager)
        if tcm and tcm.GetChestAwards then
            awards = tcm:GetChestAwards(dropList)
        end
    end)
    if awards and #awards > 0 then return awards end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if not okSC or not StoreConst then return nil end
    awards = {}
    local idK = StoreConst.label_drop_index_item_id
    local numK = StoreConst.label_drop_index_item_num
    for _, v in pairs(dropList) do
        if type(v) == "table" then
            local rid = v[idK] or v.item_id or v.resid or v.id
            if rid and rid > 0 then
                table.insert(awards, {
                    DropItemID = rid,
                    DropItemNum = v[numK] or v.count or 1,
                    DropWeight = v[StoreConst.label_drop_index_weight] or 0,
                    DropRate = v[StoreConst.label_drop_index_chance],
                    DropItemSort = v[StoreConst.label_drop_index_item_sort] or 0,
                    is_owned = false
                })
            end
        end
    end
    return #awards > 0 and awards or nil
end

function FLS.isSupplyCrateShopId(shopId, params, useCrateContext)
    shopId = tonumber(shopId)
    if not shopId then return false end
    if FLS.findStoreItemByMarketId(shopId) then return false end
    local okSU, StoreUtils = pcall(require, "client.slua.logic.store.utils.store_utils")
    if okSU and StoreUtils then
        if StoreUtils.IsClassicCrate and StoreUtils.IsClassicCrate(shopId) then return true end
        if StoreUtils.IsPremiumCrate and StoreUtils.IsPremiumCrate(shopId) then return true end
        if StoreUtils.IsSupplyCrate and StoreUtils.IsSupplyCrate(shopId) then return true end
        if StoreUtils.IsActShopId and StoreUtils.IsActShopId(shopId) then return true end
        if StoreUtils.IsSkrTreasureBoxById and StoreUtils.IsSkrTreasureBoxById(shopId) then return true end
    end
    local tab = FLS.findSupplyTabEntry(shopId, params, useCrateContext == true)
    if tab then
        local merged = FLS.mergeDropEntries(tab)
        if #merged > 0 then return true end
    end
    return false
end

function FLS.cloneAwards(awards)
    if type(awards) ~= "table" or #awards < 1 then return nil end
    local out = {}
    for i, aw in ipairs(awards) do
        if aw and aw.DropItemID and aw.DropItemID > 0 then
            out[#out + 1] = {
                DropItemID = aw.DropItemID,
                DropItemNum = aw.DropItemNum or 1,
                DropWeight = aw.DropWeight or 0,
                DropRate = aw.DropRate,
                DropItemSort = aw.DropItemSort or 0,
                ItemQuality = aw.ItemQuality or 0,
                is_must_drop = aw.is_must_drop,
                is_owned = aw.is_owned or false
            }
        end
    end
    return #out > 0 and out or nil
end

function FLS.getAwardRarityNorm(aw, awards)
    local q = tonumber(aw and aw.ItemQuality) or FLS.getItemQuality(aw and aw.DropItemID) or 0
    if aw then aw.ItemQuality = q end
    local maxQ, minQ = q, q
    for _, a in ipairs(awards or {}) do
        if a and a.DropItemID and a.DropItemID > 0 then
            local aq = tonumber(a.ItemQuality) or FLS.getItemQuality(a.DropItemID) or 0
            a.ItemQuality = aq
            if aq > maxQ then maxQ = aq end
            if aq < minQ then minQ = aq end
        end
    end
    if maxQ <= minQ then return 0 end
    return (q - minQ) / (maxQ - minQ)
end

function FLS.getAwardWeight(aw, awards, baseOnly)
    if not aw then return 0 end
    local w = tonumber(aw.DropWeight) or 0
    if w <= 0 then
        local rate = tonumber(aw.DropRate) or 0
        if rate > 0 and rate < 1 then
            w = math.max(1, math.floor(rate * 100000 + 0.5))
        elseif rate >= 1 then
            return 0
        else
            w = 1
        end
    end
    if baseOnly then return w end
    local boost = FLS.getCrateRareBoostPct()
    if boost > 0 and awards then
        local rarity = FLS.getAwardRarityNorm(aw, awards)
        if rarity > 0 then
            w = w * (1 + (boost / 100) * rarity * 49)
        end
    end
    return w
end

function FLS.pickFromWeightPool(pool, total)
    if not pool or #pool < 1 or total <= 0 then return nil end
    local roll = math.random() * total
    local acc = 0
    for _, e in ipairs(pool) do
        acc = acc + e.w
        if roll <= acc then return e.aw end
    end
    return pool[#pool].aw
end

function FLS.pickChestAwardRandom(awards)
    if type(awards) ~= "table" or #awards < 1 then return nil end
    awards = FLS.enrichAwardsMeta(awards)
    local boost = FLS.getCrateRareBoostPct()

    local function buildPool(filterFn, baseOnly)
        local pool, total = {}, 0
        for _, aw in ipairs(awards) do
            if aw and aw.DropItemID and aw.DropItemID > 0 and (not filterFn or filterFn(aw)) then
                local w = FLS.getAwardWeight(aw, awards, baseOnly)
                if w > 0 then
                    pool[#pool + 1] = { aw = aw, w = w }
                    total = total + w
                end
            end
        end
        return pool, total
    end

    if boost > 0 then
        local threshold = FLS.getRareQualityThreshold(awards)
        local function isRare(aw) return FLS.isRareAward(aw, threshold) end
        if math.random(1, 100) <= boost then
            local rarePool, rareTotal = buildPool(isRare, true)
            if #rarePool > 0 then
                local pick = FLS.pickFromWeightPool(rarePool, rareTotal)
                if pick then return pick end
            end
        end
    end

    local pool, total = buildPool(nil, boost <= 0)
    if total <= 0 then return awards[math.random(1, #awards)] end
    return FLS.pickFromWeightPool(pool, total) or awards[1]
end

function FLS.grantFromChestMarketId(marketId, openCount, params)
    marketId = tonumber(marketId)
    openCount = tonumber(openCount) or 1
    if not marketId then return false, {} end
    local rewards = {}
    local dropList, resolvedTab = FLS.getSupplyDropList(marketId, params)
    local awards = FLS.buildAwardsFromDropList(dropList)
    if resolvedTab then FLS._lastSupplyTabId = resolvedTab end

    if not awards or #awards == 0 then
        for _, tid in ipairs(FLS.resolveCrateTabIds(params, marketId)) do
            pcall(function()
                local tcm = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.treasure_chest_manager)
                if tcm and tcm.chest_info and tcm.chest_info[tid] and tcm.chest_info[tid].data then
                    awards = tcm:GetChestAwards(tcm.chest_info[tid].data)
                end
            end)
            if awards and #awards > 0 then break end
        end
    end

    if not awards or #awards == 0 then
        pcall(function()
            local tcm = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.treasure_chest_manager)
            if tcm and tcm.GetChestInfo then
                for _, tid in ipairs(FLS.resolveCrateTabIds(params, marketId)) do
                    tcm:GetChestInfo(tid)
                end
            end
        end)
    end

    if not awards or #awards == 0 then return false, rewards end
    awards = FLS.cloneAwards(awards) or awards
    awards = FLS.enrichAwardsMeta(awards)

    local granted = false
    for _ = 1, openCount do
        local pick = FLS.pickChestAwardRandom(awards)
        if pick and pick.DropItemID and pick.DropItemID > 0 then
            local pickId = pick.DropItemID
            local pickCnt = pick.DropItemNum or 1
            if FLS.grantResId(pickId, pickCnt) then
                granted = true
                table.insert(rewards, FLS.buildReward(pickId, pickCnt, 0))
            end
        end
    end
    return granted, rewards
end

function FLS.grantFromShopParams(params)
    if type(params) ~= "table" then return false, {} end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if not okSC or not StoreConst then return false, {} end
    local shopId = params[StoreConst.label_buy_param_id] or params[1]
    local count = params[StoreConst.label_buy_param_count] or 1

    local itemData = FLS.findStoreItemByMarketId(shopId)
    if itemData then
        local resId = itemData[StoreConst.label_item_index_id]
        if resId and resId > 0 then
            local okSU, StoreUtils = pcall(require, "client.slua.logic.store.utils.store_utils")
            if okSU and StoreUtils and StoreUtils.CheckIsChest and StoreUtils.CheckIsChest(resId) then
                return FLS.grantFromChestMarketId(shopId, count, params)
            end
            if FLS.grantResId(resId, count) then
                return true, { FLS.buildReward(resId, count, 0) }
            end
        end
    end

    if FLS.isSupplyCrateShopId(shopId, params, true) then
        return FLS.grantFromChestMarketId(shopId, count, params)
    end
    return false, {}
end

function FLS.isMoneyError(code)
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    if not okSC or not StoreConst then return false end
    return code == StoreConst.error_code_uc_not_enough
        or code == StoreConst.error_code_uc_not_enough_new
        or code == StoreConst.error_code_gold_not_enough
        or code == StoreConst.error_code_gold_not_enough_new
        or code == StoreConst.error_code_silver_not_enough
        or code == StoreConst.error_code_silver_not_enough_new
        or code == StoreConst.error_code_bp_not_enough
        or code == StoreConst.error_code_bp_not_enough_new
        or code == StoreConst.error_code_fp_not_enough
        or code == StoreConst.error_code_fp_not_enough_new
        or code == StoreConst.error_code_coin_not_enough
        or code == StoreConst.error_code_coin_not_enough_new
end

function FLS.simulateShopBuy(shop_id, params)
    if not FLS.chargeForBuy(params) then return false end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    local granted, rewards = false, {}
    if params then
        granted, rewards = FLS.grantFromShopParams(params)
    end
    if not granted and okSC and StoreConst then
        local fallback = {
            [StoreConst.label_buy_param_id] = shop_id,
            [StoreConst.label_buy_param_count] = 1
        }
        granted, rewards = FLS.grantFromShopParams(fallback)
    end
    if not granted and FLS.isSupplyCrateShopId(shop_id, params, true) then
        local openCount = 1
        if okSC and StoreConst and params then
            openCount = params[StoreConst.label_buy_param_count] or 1
        end
        granted, rewards = FLS.grantFromChestMarketId(shop_id, openCount, params)
    end
    if granted then
        local openCount = 1
        if okSC and StoreConst and params then
            openCount = params[StoreConst.label_buy_param_count] or 1
        end
        if FLS.shouldPlayCrateAnimation(shop_id, params, rewards, openCount) then
            FLS.finishCrateOpen(shop_id, rewards, openCount)
        else
            pcall(function()
                EventSystem:postEvent(EVENTTYPE_STORE_DATA, EVENTID_SUPPLY_BUY, shop_id, {}, nil)
            end)
            FLS.showRewards(rewards)
        end
        if FLS.isSupplyCrateShopId(shop_id, params, true) then
            FLS.bumpOptionalBuyCnt(shop_id, openCount)
        end
        FLS.pendingShopBuy = nil
    end
    return granted
end

function FLS.simulateWardrobeUseItem(instID, count, params)
    count = tonumber(count) or 1
    instID = tonumber(instID)
    if not instID then return false end
    local resId = nil
    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local item = wd:GetHallDepotItemDataByInsID(instID)
        if item then resId = item.res_id or item.resID or item.item_res_id end
    end)
    if not resId then return false end
    -- Hộp nhánh XSuit (1 trong 3) — UI XSuit_Box_Select_UIBP
    if FLS.isXSuitBranchBox and FLS.isXSuitBranchBox(resId) then
        return FLS.openXSuitBranchBoxUI(resId, 1, instID)
    end
    -- Hộp chọn 1 trong N (CustomSelectChest): mở UI chọn local
    if FLS.isCustomSelectChest(resId) then
        return FLS.openCustomSelectChestUI(resId, count)
    end
    local cfg = CDataTable.GetTableData("Item", resId)
    if not cfg then return false end
    local awards = nil
    pcall(function()
        local bdt = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataDropTable)
        if bdt and bdt.GetCacheData then
            local cached = bdt:GetCacheData(resId)
            if cached then
                awards = {}
                for _, v in pairs(cached) do
                    if v and v.DropItemID then
                        table.insert(awards, {
                            DropItemID = v.DropItemID,
                            DropItemNum = v.DropItemNum or 1,
                            is_owned = false
                        })
                    end
                end
            end
        end
    end)
    if (not awards or #awards == 0) and cfg.ItemType == 15 then
        local grantedChest, chestRewards = FLS.grantFromChestMarketId(resId, count, nil)
        if grantedChest then
            FLS.finishCrateOpen(resId, chestRewards, count)
        end
        return grantedChest
    end
    if not awards or #awards == 0 then return false end
    local rewards = {}
    local granted = false
    for _ = 1, count do
        local pick = FLS.pickChestAwardRandom(awards)
        if pick and pick.DropItemID and FLS.grantResId(pick.DropItemID, pick.DropItemNum or 1) then
            granted = true
            table.insert(rewards, FLS.buildReward(pick.DropItemID, pick.DropItemNum or 1, 0))
        end
    end
    if granted then FLS.showRewards(rewards) end
    return granted
end

function FLS.trySimulateCrateFromParams(params, shopId)
    if FLS.isClassicCrateParams(params) then
        return FLS.simulateClassicCrateOpen(params)
    end
    shopId = shopId or (params and params[1])
    if shopId and FLS.findStoreItemByMarketId(shopId) then return false end
    if not FLS.isSupplyCrateShopId(shopId, params, true) then return false end
    return FLS.simulateShopBuy(shopId, params)
end

function FLS.grantFromNtfList(item_list)
    if type(item_list) ~= "table" then return false end
    local rewards = {}
    local granted = false
    for _, v in pairs(item_list) do
        local resId = v.resid or v.res_id or v.item_id or v.id
        local cnt = v.count or v.num or 1
        if resId and FLS.grantResId(resId, cnt) then
            granted = true
            table.insert(rewards, FLS.buildReward(resId, cnt, v.valid_hours or 0))
        end
    end
    if granted then FLS.showRewards(rewards) end
    return granted
end

function FLS.scheduleCrateFallback(shop_id, params, delaySec)
    delaySec = delaySec or 2.0
    pcall(function()
        local ticker = require("common.time_ticker")
        if not ticker or not ticker.AddTimerOnce then return end
        ticker.AddTimerOnce(delaySec, function()
            if not FLS.IsEnabled() then return end
            if FLS._lastCrateSimulated == shop_id then return end
            if FLS.isClassicCrateParams(params) then
                FLS.simulateClassicCrateOpen(params)
            else
                FLS.simulateShopBuy(shop_id, params)
            end
        end)
    end)
end

function FLS.simulateMarketBuy(market_id, params)
    if not FLS.chargeForBuy(params) then return false end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    local reqParams = params
    if (not reqParams or not reqParams[1]) and okSC and StoreConst then
        reqParams = {
            [StoreConst.label_buy_param_id] = market_id,
            [StoreConst.label_buy_param_count] = 1
        }
    end
    local granted, rewards = FLS.grantFromShopParams(reqParams)
    if granted then
        local openCount = 1
        if okSC and StoreConst and params then
            openCount = params[StoreConst.label_buy_param_count] or 1
        end
        if FLS.shouldPlayCrateAnimation(market_id, reqParams, rewards, openCount) then
            FLS.finishCrateOpen(market_id, rewards, openCount)
        else
            pcall(function()
                EventSystem:postEvent(EVENTTYPE_STORE_DATA, EVENTID_STORE_BUY, { market_id = market_id, info = {} })
                EventSystem:postEvent(EVENTTYPE_STORE, EVENTID_STORE_SUBSCRIBE_BUY_CALLBACK)
            end)
            FLS.showRewards(rewards)
        end
        FLS.pendingMarketBuy = nil
    end
    return granted
end

FLS.PKG_DO_DRAW_ACT = 620217751
FLS.PKG_LUCKYBACK_DRAW = 1478162855
FLS.PKG_DOUBLE_DRAW = 1018293095
FLS.PKG_DOUBLE_DRAW_ON_SHOT = 1699809135
FLS._drawPoolCache = FLS._drawPoolCache or {}

function FLS.isDrawError(code)
    code = tonumber(code)
    if not code or code == 0 then return false end
    if code == 100170006 or code == 100170005 or code == 100170004 then return true end
    if code == 100900008 or code == 100900006 or code == 100900007 then return true end
    return FLS.isMoneyError(code)
end

function FLS.cacheDrawPool(activity_id, pool_info, price_info)
    activity_id = tonumber(activity_id)
    if not activity_id or type(pool_info) ~= "table" then return end
    FLS._drawPoolCache[activity_id] = pool_info
    if type(price_info) == "table" then
        FLS._drawPriceCache = FLS._drawPriceCache or {}
        FLS._drawPriceCache[activity_id] = price_info
    end
    FLS._lastDrawActivityId = activity_id
end

function FLS.ingestPoolNode(node, addEntry, depth)
    if type(node) ~= "table" or (depth or 0) > 5 then return end
    depth = depth or 0
    local id = node.item_id or node.itemid or node.resid or node.res_id or node.itemId
        or node.award_item_id or node.PropId1 or node.prop_id1 or node.DropItemID
        or node.reward_item_id or node.reward_id or node.prop_id
        or node.ItemID or node.MatID or node.item_res_id
    id = tonumber(id)
    if id and id > 0 then
        addEntry(id,
            node.item_num or node.count or node.itemCount or node.award_item_num or node.DropItemNum or 1,
            node.award_weight or node.weight or node.probability or 1,
            node.valid_hours or node.vaild_time or node.award_item_valid_time or 0,
            node.pos_id or node.posId or node.display_sort or node.pos,
            node.itemQuality or node.show_quality)
        return
    end
    for _, child in pairs(node) do
        if type(child) == "table" then FLS.ingestPoolNode(child, addEntry, depth + 1) end
    end
end

function FLS.chargeDrawCost(currency_id, amount)
    if not FLS.IsEnabled() then return true end
    currency_id = tonumber(currency_id) or 1006
    amount = tonumber(amount) or 0
    if amount <= 0 then return true end
    if UC and UC.spend then return UC.spend(currency_id, amount, true) == true end
    return FLS.checkMoney(currency_id, amount)
end

function FLS.gatherEventDrawPools(activity_id)
    activity_id = tonumber(activity_id) or FLS._lastDrawActivityId
    local pools = {}
    local function addEntry(id, count, weight, valid, pos, quality)
        id = tonumber(id)
        if id and id > 0 then
            pools[#pools + 1] = {
                id = id, count = tonumber(count) or 1,
                weight = tonumber(weight) or 1,
                valid = tonumber(valid) or 0,
                pos = tonumber(pos) or (#pools + 1),
                quality = tonumber(quality) or FLS.getItemQuality(id) or 0
            }
        end
    end
    if activity_id and FLS._drawPoolCache and FLS._drawPoolCache[activity_id] then
        FLS.ingestPoolNode(FLS._drawPoolCache[activity_id], addEntry, 0)
        if #pools > 0 then return pools end
    end
    pcall(function()
        local mix = require("client.slua.logic.lobby_activity.logic_luckmix_activity")
        if mix then
            if not activity_id or tonumber(mix.ActivityId) == activity_id or tonumber(mix.activityId) == activity_id then
                FLS.ingestPoolNode(mix.poolItemConfig or mix.pool_info or mix.tPoolInfo or mix.PoolInfo, addEntry, 0)
            end
        end
    end)
    pcall(function()
        local LD = require("client.slua.logic.lobby_activity.logic_luckydouble_activity")
        if LD then
            FLS.ingestPoolNode(LD.CurSmallAwardPoolConfig, addEntry, 0)
            FLS.ingestPoolNode(LD.CurBigAwardPoolConfig, addEntry, 0)
            local data = LD.Data and LD.ActivityId and LD.Data[LD.ActivityId]
            if data then
                FLS.ingestPoolNode(data.bigPoolInfo, addEntry, 0)
                FLS.ingestPoolNode(data.smallPoolInfo, addEntry, 0)
            end
        end
    end)
    pcall(function()
        local lb = require("client.slua.logic.lobby_activity.logic_luckyback_activity")
        if lb and lb.poolItemConfig and (not activity_id or tonumber(lb.activityId) == activity_id) then
            for _, v in ipairs(lb.poolItemConfig) do
                addEntry(v.itemId, v.itemCount, v.award_weight, v.vaild_time, v.posId, v.itemQuality)
            end
        end
    end)
    pcall(function()
        local sg = require("client.slua.logic.lobby_activity.logic_scrapgold_draw")
        if sg and (not activity_id or tonumber(sg.ActivityId) == activity_id) then
            if sg.poolItemConfig then
                for _, v in ipairs(sg.poolItemConfig) do
                    addEntry(v.itemId, v.itemCount, 1, v.vaild_time, v.posId)
                end
            elseif sg.pool_info then
                FLS.ingestPoolNode(sg.pool_info, addEntry, 0)
            end
        end
    end)
    pcall(function()
        local mod = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.Logic_LukcyOptionalTurntable)
        if mod and mod.tPoolInfo then FLS.ingestPoolNode(mod.tPoolInfo, addEntry, 0) end
    end)
    pcall(function()
        local xa = ModuleManager.GetModule(ModuleManager.JumpModuleConfig.logic_xsuit_activity)
        if xa then
            local pinfo = xa.GetDrawPoolInfo and xa:GetDrawPoolInfo()
            if pinfo then FLS.ingestPoolNode(pinfo, addEntry, 0) end
        end
        if FLS._xsuitPoolCache then FLS.ingestPoolNode(FLS._xsuitPoolCache, addEntry, 0) end
    end)
    pcall(function()
        local cfg = CDataTable.GetTable("SupplyTurntableModuleCfg")
        if cfg and activity_id and cfg[activity_id] then
            local moduleName = cfg[activity_id].ActivityModuleName
            local mod = moduleName and ModuleManager.GetModule(ModuleManager.LobbyModuleConfig[moduleName])
            if mod then
                FLS.ingestPoolNode(mod.tPoolInfo or mod.poolItemConfig or mod.pool_info, addEntry, 0)
            end
        end
    end)
    return pools
end

function FLS.pickEventDrawAward(pool)
    if not pool or #pool < 1 then return nil end
    local boost = FLS.getCrateRareBoostPct()
    local entries, total = {}, 0
    for _, e in ipairs(pool) do
        local w = e.weight or 1
        if boost > 0 and e.quality and e.quality > 0 then
            w = w * (1 + (boost / 100) * math.min(1, e.quality / 8))
        end
        if w > 0 then total = total + w; entries[#entries + 1] = { e = e, w = w } end
    end
    if total <= 0 then return pool[math.random(1, #pool)] end
    local roll, acc = math.random() * total, 0
    for _, x in ipairs(entries) do
        acc = acc + x.w
        if roll <= acc then return x.e end
    end
    return entries[#entries].e
end

function FLS.buildDrawItemList(pool, drawTimes)
    local list = {}
    for i = 1, drawTimes do
        local pick = FLS.pickEventDrawAward(pool)
        if pick then
            local idx = #list + 1
            list[idx] = {
                resid = pick.id, count = pick.count or 1,
                valid_hours = pick.valid or 0,
                display_sort = pick.pos or idx, pos_id = pick.pos or idx
            }
            FLS.grantResId(pick.id, pick.count or 1)
        end
    end
    return list
end

function FLS.resolveDrawCost(drawKind, currency_id, drawTimes, activity_id)
    currency_id = tonumber(currency_id) or 1006
    drawTimes = tonumber(drawTimes) or 1
    activity_id = tonumber(activity_id) or FLS._lastDrawActivityId
    local isTen = drawTimes >= 10 or drawKind == 10 or drawKind == 2
    local cost = 0
    pcall(function()
        local lb = require("client.slua.logic.lobby_activity.logic_luckyback_activity")
        if lb and lb.playerData then
            cost = isTen and (lb.playerData.tenDrawFinalPrice or 0) or (lb.playerData.oneDrawFinalPrice or 0)
        end
    end)
    if cost <= 0 then
        pcall(function()
            local sg = require("client.slua.logic.lobby_activity.logic_scrapgold_draw")
            if sg and sg.playerData then
                if isTen then
                    cost = sg.playerData.tenDrawFinalPrice or (sg.globalConfig and sg.globalConfig.tenDrawOriginalPrice) or 0
                else
                    cost = sg.playerData.oneDrawFinalPrice or (sg.GetOneDrawOriginalPrice and sg.GetOneDrawOriginalPrice()) or 0
                end
            end
        end)
    end
    if cost <= 0 then
        pcall(function()
            local LD = require("client.slua.logic.lobby_activity.logic_luckydouble_activity")
            if LD then
                if isTen and LD.GetRestDrawTotalCost then
                    cost = select(1, LD.GetRestDrawTotalCost()) or 0
                end
                if cost <= 0 then cost = LD.DiscountPrice or LD.CurPrice or 0 end
            end
        end)
    end
    if cost <= 0 and activity_id and FLS._drawPriceCache and FLS._drawPriceCache[activity_id] then
        pcall(function()
            local pi = FLS._drawPriceCache[activity_id]
            local row = pi[1] and (pi[1][currency_id] or pi[1][1006])
            if row then
                cost = isTen and (row.ten_cost or row.one_cost * 10) or (row.dis_one_cost or row.one_cost or 0)
            end
        end)
    end
    return currency_id, cost
end

function FLS.resolveDrawCostForActivity(activity_id, drawKind, currency_id, drawTimes)
    FLS._lastDrawActivityId = tonumber(activity_id) or FLS._lastDrawActivityId
    return FLS.resolveDrawCost(drawKind, currency_id, drawTimes, activity_id)
end

function FLS.simulateDoDrawAct(activity_id, voucher_id, currency_id, cost_times, ext_info)
    if not FLS.IsEnabled() then return false end
    activity_id = tonumber(activity_id)
    cost_times = tonumber(cost_times) or 1
    FLS._lastDrawActivityId = activity_id
    local pool = FLS.gatherEventDrawPools(activity_id)
    if #pool < 1 then return false end
    local cur, cost = FLS.resolveDrawCostForActivity(activity_id, 1, currency_id, cost_times)
    if voucher_id and tonumber(voucher_id) and tonumber(voucher_id) > 0 then cost = 0 end
    if not FLS.chargeDrawCost(cur, cost) then
        pcall(function()
            local PayBox = require("client.slua.logic.common.Payclass.logic_common_pay_box")
            if PayBox and PayBox.ShowUcRechargeMsg then PayBox.ShowUcRechargeMsg(cost) end
        end)
        return false
    end
    local item_list = FLS.buildDrawItemList(pool, cost_times)
    if not item_list or not next(item_list) then return false end
    local ext = ext_info or {}
    pcall(function()
        local SLN = require("client.slua.logic.lobby_activity.special_luck_network")
        if SLN and SLN.on_do_draw_act_rsp then
            SLN.on_do_draw_act_rsp(activity_id, item_list, {}, ext)
        end
    end)
    pcall(function() if F and F.refreshWardrobe then F.refreshWardrobe() end end)
    return true
end

function FLS.simulateLuckyDoubleDraw(pool_id, activity_id, voucher_id, cost, isOnShot)
    if not FLS.IsEnabled() then return false end
    activity_id = tonumber(activity_id)
    FLS._lastDrawActivityId = activity_id
    local pool = FLS.gatherEventDrawPools(activity_id)
    if #pool < 1 then return false end
    local cur = 1006
    local price = tonumber(cost) or 0
    if price <= 0 then
        cur, price = FLS.resolveDrawCostForActivity(activity_id, isOnShot and 10 or 1, 1006, isOnShot and 10 or 1)
    end
    if voucher_id and tonumber(voucher_id) and tonumber(voucher_id) > 0 then price = 0 end
    if not FLS.chargeDrawCost(cur, price) then
        pcall(function()
            local PayBox = require("client.slua.logic.common.Payclass.logic_common_pay_box")
            if PayBox and PayBox.ShowUcRechargeMsg then PayBox.ShowUcRechargeMsg(price) end
        end)
        return false
    end
    local LD = require("client.slua.logic.lobby_activity.logic_luckydouble_activity")
    local drawTimes = isOnShot and math.min(10, #pool) or 1
    if isOnShot then
        local main_reward_info, little_reward_info = {}, {}
        for i = 1, drawTimes do
            local pick = FLS.pickEventDrawAward(pool)
            if pick then
                little_reward_info[pick.pos or i] = {
                    item_id = pick.id, item_num = pick.count or 1, valid_hours = pick.valid or 0
                }
                FLS.grantResId(pick.id, pick.count or 1)
            end
        end
        local actInfo = LD.Data and LD.ActivityId and LD.Data[LD.ActivityId] and LD.Data[LD.ActivityId].actInfo
        pcall(function()
            if LD.on_double_draw_on_shot_rsp then
                LD.on_double_draw_on_shot_rsp(0, actInfo or {}, main_reward_info, little_reward_info, 0, {}, {}, {})
            end
        end)
    else
        local pick = FLS.pickEventDrawAward(pool)
        if not pick then return false end
        local pos = pick.pos or 1
        local reward_info = { [pos] = { item_id = pick.id, item_num = pick.count or 1, valid_hours = pick.valid or 0 } }
        FLS.grantResId(pick.id, pick.count or 1)
        local actInfo = LD.Data and LD.ActivityId and LD.Data[LD.ActivityId] and LD.Data[LD.ActivityId].actInfo
        pcall(function()
            if LD.on_do_one_lucky_double_draw_by_activity_rsp then
                LD.on_do_one_lucky_double_draw_by_activity_rsp(0, 1, actInfo or {}, reward_info, {}, {})
            end
        end)
    end
    pcall(function() if F and F.refreshWardrobe then F.refreshWardrobe() end end)
    return true
end

function FLS.simulateLuckybackDraw(act_Id, draw_type, data_info, coupon_id)
    if not FLS.IsEnabled() then return false end
    draw_type = tonumber(draw_type) or 1
    local drawTimes = (draw_type == 1) and 1 or 10
    FLS._lastDrawActivityId = tonumber(act_Id)
    local pool = FLS.gatherEventDrawPools(act_Id)
    if #pool < 1 then return false end
    local cur, cost = FLS.resolveDrawCost(draw_type, 1006, drawTimes)
    if coupon_id and tonumber(coupon_id) and tonumber(coupon_id) > 0 then cost = 0 end
    if draw_type == 1 and data_info then cost = 0 end
    if not FLS.chargeDrawCost(cur, cost) then
        pcall(function()
            local PayBox = require("client.slua.logic.common.Payclass.logic_common_pay_box")
            if PayBox and PayBox.ShowUcRechargeMsg then PayBox.ShowUcRechargeMsg(cost) end
        end)
        return false
    end
    local award_info = FLS.buildDrawItemList(pool, drawTimes)
    if not award_info or not next(award_info) then return false end
    local myData = {}
    pcall(function()
        local lb = require("client.slua.logic.lobby_activity.logic_luckyback_activity")
        local pd = lb and lb.playerData
        myData = {
            sum_draw_times = (pd and pd.totalDrawTime or 0) + drawTimes,
            one_draw_times = (pd and pd.one_draw_times or 0) + ((draw_type == 1) and 1 or 0),
            duo_draw_times = (pd and pd.duo_draw_times or 0) + ((draw_type ~= 1) and 1 or 0),
            cur_lucky_value = pd and pd.curLuckyValue or 0,
            is_uc_discount_by_day = false
        }
    end)
    pcall(function()
        local LBH = require("client.network.Protocol.LuckybackHandler")
        if LBH and LBH.on_do_one_draw_back_by_activity_rsp then
            LBH.on_do_one_draw_back_by_activity_rsp(0, myData, award_info, {}, draw_type, nil)
        end
    end)
    pcall(function() if F and F.refreshWardrobe then F.refreshWardrobe() end end)
    return true
end

-- ===== SportsCarSpin / LadderDraw (Start Accelerating → siêu xe) =====
function FLS.syncLadderActOther(activity_id, info)
    pcall(function()
        local LadderDrawSystem = require("client.slua.logic.lobby_activity.logic_ladder_draw")
        local act = LadderDrawSystem.GetActData and LadderDrawSystem.GetActData(activity_id)
        if act then
            act.other = type(act.other) == "table" and act.other or {}
            for k, v in pairs(info or {}) do
                act.other[k] = v
            end
        end
    end)
end

function FLS.resolveLadderDropItems(chestId)
    chestId = tonumber(chestId)
    local items = {}
    if not chestId or chestId <= 0 then return items end
    local function pushList(list)
        if type(list) ~= "table" then return end
        for _, v in pairs(list) do
            if type(v) == "table" then
                local id = tonumber(v.DropItemID or v.dropItemID or v.item_id or v.resid or v.res_id)
                if id and id > 0 then
                    items[#items + 1] = {
                        resid = id,
                        count = tonumber(v.DropItemNum or v.count or v.item_num) or 1,
                        valid_hours = tonumber(v.valid_hours or v.ValidHours) or 0,
                    }
                end
            end
        end
    end
    pcall(function()
        local BasicDataDropTable = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataDropTable)
        if not BasicDataDropTable then return end
        if BasicDataDropTable.GetCacheData then
            pushList(BasicDataDropTable:GetCacheData(chestId))
        end
        if #items == 0 and BasicDataDropTable.BatchGetOrReqData then
            local dataList = BasicDataDropTable:BatchGetOrReqData({ chestId })
            if type(dataList) == "table" then
                pushList(dataList[chestId] or dataList[tostring(chestId)] or dataList[1])
                if #items == 0 then
                    for _, chestList in pairs(dataList) do
                        pushList(chestList)
                        if #items > 0 then break end
                    end
                end
            end
        end
        if #items == 0 and BasicDataDropTable.GetOrReqData then
            -- sync-ish: callback may run immediately if cached
            BasicDataDropTable:GetOrReqData(chestId, function(_, itemList)
                pushList(itemList)
            end)
        end
    end)
    return items
end

function FLS.pickLadderAwardForPos(activity_id, pos)
    local pick = nil
    pcall(function()
        local LadderDrawSystem = require("client.slua.logic.lobby_activity.logic_ladder_draw")
        local poolCfg = LadderDrawSystem.GetAwardPoolAndPriceConfig(activity_id) or {}
        pos = tonumber(pos) or 0
        local cfg = poolCfg[pos] or poolCfg[tostring(pos)]
        if type(cfg) ~= "table" then return end
        local chestId = tonumber(cfg.reward_item_id or cfg.item_id or cfg.reward_id)
        local items = FLS.resolveLadderDropItems(chestId)
        if #items > 0 then
            pick = items[math.random(1, #items)]
            return
        end
        -- fallback: dùng chính chest id nếu là item
        if chestId and chestId > 0 then
            pick = { resid = chestId, count = 1, valid_hours = 0 }
        end
    end)
    return pick
end

function FLS.findLadderMaxPos(activity_id)
    local maxPos = 0
    pcall(function()
        local LadderDrawSystem = require("client.slua.logic.lobby_activity.logic_ladder_draw")
        local poolCfg = LadderDrawSystem.GetAwardPoolAndPriceConfig(activity_id) or {}
        local paidZero = nil
        for k, cfg in pairs(poolCfg) do
            local idx = tonumber(k)
            if idx and idx > maxPos then maxPos = idx end
            if idx and type(cfg) == "table" and (not cfg.paid_count or tonumber(cfg.paid_count) == 0) then
                if not paidZero or idx > paidZero then paidZero = idx end
            end
        end
        if paidZero then maxPos = paidZero end
        local ui = LadderDrawSystem.GetUIConfig and LadderDrawSystem.GetUIConfig()
        if ui and tonumber(ui.poolNum) and tonumber(ui.poolNum) > maxPos then
            maxPos = tonumber(ui.poolNum)
        end
    end)
    return maxPos
end

-- Start Accelerating / Safe Acceleration (client, FreeLobbyShop)
function FLS.simulateLadderRotate(activity_id, op_type, voucher)
    if not FLS.IsEnabled() then return false end
    activity_id = tonumber(activity_id)
    if not activity_id then return false end
    local ok = false
    pcall(function()
        local LadderDrawSystem = require("client.slua.logic.lobby_activity.logic_ladder_draw")
        if not LadderDrawSystem then return end
        local opPay = (LadderDrawSystem.CONST and LadderDrawSystem.CONST.E_DrawOperateType
            and LadderDrawSystem.CONST.E_DrawOperateType.Pay) or 2
        local opFree = (LadderDrawSystem.CONST and LadderDrawSystem.CONST.E_DrawOperateType
            and LadderDrawSystem.CONST.E_DrawOperateType.Free) or 1
        op_type = tonumber(op_type) or opPay

        local curPos = 0
        pcall(function() curPos = tonumber(LadderDrawSystem.GetLadder(activity_id)) or 0 end)
        if LadderDrawSystem.IsMaxLadder and LadderDrawSystem.IsMaxLadder(activity_id) then
            ShowNotice(508491)
            return
        end

        local poolCfg = {}
        pcall(function() poolCfg = LadderDrawSystem.GetAwardPoolAndPriceConfig(activity_id) or {} end)
        local pCfg = poolCfg[curPos] or poolCfg[tostring(curPos)] or {}
        local needUC = tonumber(pCfg.paid_count) or 0
        if op_type == opPay and not (voucher and tonumber(voucher) and tonumber(voucher) > 0) and needUC > 0 then
            pcall(FLS.chargeDrawCost, 1006, needUC)
        end

        local maxPos = FLS.findLadderMaxPos(activity_id)
        local step = 1
        local newPos = curPos + step
        if maxPos > 0 and newPos > maxPos then newPos = maxPos end
        if newPos == curPos and maxPos > curPos then newPos = curPos + 1 end
        step = newPos - curPos
        if step < 1 then step = 1; newPos = curPos + 1 end

        local prev = {}
        pcall(function()
            local d = LadderDrawSystem.GetDrawData(activity_id)
            if type(d) == "table" then
                for k, v in pairs(d) do prev[k] = v end
            end
        end)
        local lottery_times = {}
        if type(prev.lottery_times) == "table" then
            for k, v in pairs(prev.lottery_times) do lottery_times[k] = v end
        end
        if op_type == opPay then
            lottery_times[2] = (tonumber(lottery_times[2]) or 0) + 1
        else
            lottery_times[1] = (tonumber(lottery_times[1]) or 0) + 1
        end

        local info = {
            activity_id = activity_id,
            pos = newPos,
            last_opt_rest = step,
            last_opt_type = op_type,
            protect_count = tonumber(prev.protect_count) or 3,
            lottery_times = lottery_times,
        }

        -- Lucky Voucher (exchange_item_id): grant + rebate UI (trước đây simulate bỏ qua)
        pcall(function()
            local param = LadderDrawSystem.GetParamConfig and LadderDrawSystem.GetParamConfig(activity_id) or {}
            local voucherId = tonumber(param.exchange_item_id)
            if not voucherId or voucherId <= 0 then return end
            local voucherCount = 1
            if op_type == opPay then
                voucherCount = (needUC and needUC > 0) and needUC or 10
                local cfgCount = tonumber(pCfg.return_count or pCfg.lucky_count or pCfg.rebate_count
                    or param.return_count or param.lucky_ticket_count)
                if cfgCount and cfgCount > 0 then voucherCount = cfgCount end
            end
            FLS.grantResId(voucherId, voucherCount)
            info.extra_award = {
                {
                    resid = voucherId,
                    count = voucherCount,
                    valid_hours = 0,
                }
            }
            -- Một số build OnRotateRsp không gán luckyRebate từ extra_award
            LadderDrawSystem.luckyRebate = {
                resid = voucherId,
                count = voucherCount,
                valid_hours = 0,
                lastUcNum = (DataMgr and DataMgr.ticket) or 0,
            }
        end)

        -- Giống handler: chờ rsp rồi success ngay (không gửi server)
        pcall(function()
            if LadderDrawSystem.SetWaitRotateFlag then LadderDrawSystem.SetWaitRotateFlag(true) end
            LadderDrawSystem.bIsDrawRsp = false
            if LadderDrawSystem.IsForceCloseMainUI then LadderDrawSystem.IsForceCloseMainUI() end
        end)
        FLS.syncLadderActOther(activity_id, info)
        pcall(function()
            if LadderDrawSystem.SetWaitRotateFlag then LadderDrawSystem.SetWaitRotateFlag(false) end
            LadderDrawSystem.bIsDrawRsp = true
            LadderDrawSystem.OnRotateRsp(info)
            -- Re-apply luckyRebate nếu OnRotateRsp ghi đè/xóa
            if info.extra_award and info.extra_award[1] then
                local ea = info.extra_award[1]
                LadderDrawSystem.luckyRebate = LadderDrawSystem.luckyRebate or {
                    resid = ea.resid,
                    count = ea.count,
                    valid_hours = ea.valid_hours or 0,
                    lastUcNum = (DataMgr and DataMgr.ticket) or 0,
                }
            end
        end)
        -- Refresh số Lucky Voucher trên UI (TextBlock_Currency đọc depot)
        pcall(function()
            if EventSystem and EVENTTYPE_DATA_MGR and EVENTID_DATAMGR_TICKET_CHANGE then
                EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_TICKET_CHANGE, DataMgr and DataMgr.ticket)
            end
            if EventSystem and EVENTTYPE_LADDER_DRAW and EVENTID_LADDER_DRAW_UPDATE_SUBUI then
                EventSystem:postEvent(EVENTTYPE_LADDER_DRAW, EVENTID_LADDER_DRAW_UPDATE_SUBUI)
            end
        end)
        -- Prefetch random award cho level mới (UI sẽ gọi send_random_award_req)
        pcall(function()
            local pick = FLS.pickLadderAwardForPos(activity_id, newPos)
            if pick then
                LadderDrawSystem.svrRandomAwardData = LadderDrawSystem.svrRandomAwardData or {}
                LadderDrawSystem.svrRandomAwardData[activity_id] = {
                    activity_id = activity_id,
                    random_pos = newPos,
                    real_list = { pick },
                    reward_list = { { resid = pick.resid, count = pick.count, valid_hours = pick.valid_hours } },
                }
            end
        end)
        ok = true
    end)
    return ok
end

function FLS.simulateLadderRandomAward(activity_id)
    if not FLS.IsEnabled() then return false end
    activity_id = tonumber(activity_id)
    if not activity_id then return false end
    local ok = false
    pcall(function()
        local LadderDrawSystem = require("client.slua.logic.lobby_activity.logic_ladder_draw")
        local pos = 0
        pcall(function() pos = tonumber(LadderDrawSystem.GetLadder(activity_id)) or 0 end)
        if pos <= 0 then return end
        local pick = FLS.pickLadderAwardForPos(activity_id, pos)
        if not pick then return end
        local info = {
            activity_id = activity_id,
            random_pos = pos,
            real_list = { pick },
            reward_list = { { resid = pick.resid, count = pick.count, valid_hours = pick.valid_hours } },
        }
        LadderDrawSystem.OnRandomAwardRsp(info)
        ok = true
    end)
    return ok
end

function FLS.simulateLadderRecvAward(activity_id)
    if not FLS.IsEnabled() then return false end
    activity_id = tonumber(activity_id)
    if not activity_id then return false end
    local ok = false
    pcall(function()
        local LadderDrawSystem = require("client.slua.logic.lobby_activity.logic_ladder_draw")
        local awardData = LadderDrawSystem.GetRandomAwardData and LadderDrawSystem.GetRandomAwardData(activity_id)
        local real_list = awardData and awardData.real_list
        local reward_list = awardData and awardData.reward_list
        local pos = 0
        pcall(function() pos = tonumber(LadderDrawSystem.GetLadder(activity_id)) or 0 end)
        if (not real_list or not real_list[1]) and pos > 0 then
            local pick = FLS.pickLadderAwardForPos(activity_id, pos)
            if pick then
                real_list = { pick }
                reward_list = { { resid = pick.resid, count = pick.count, valid_hours = pick.valid_hours } }
            end
        end
        if not real_list or not real_list[1] then return end
        for _, item in ipairs(real_list) do
            if item and item.resid then
                FLS.grantResId(item.resid, item.count or 1)
            end
        end
        local info = {
            activity_id = activity_id,
            real_list = real_list,
            reward_list = reward_list or real_list,
            decompose_list = {},
        }
        LadderDrawSystem.OnRecvAwardRsp(info)
        -- Reset ladder về 0 để tiếp tục quay (client)
        pcall(function()
            local reset = {
                activity_id = activity_id,
                pos = 0,
                last_opt_rest = 0,
                last_opt_type = 0,
                protect_count = 3,
                lottery_times = { [1] = 0, [2] = 0 },
            }
            FLS.syncLadderActOther(activity_id, reset)
        end)
        pcall(function() if F and F.refreshWardrobe then F.refreshWardrobe() end end)
        ok = true
    end)
    return ok
end

function FLS.cacheXSuitDrawInfo(draw_info)
    if type(draw_info) ~= "table" then return end
    FLS._xsuitDrawInfo = draw_info
    if draw_info.activity_id then FLS._lastDrawActivityId = tonumber(draw_info.activity_id) end
    if draw_info.pool_info then FLS._xsuitPoolCache = draw_info.pool_info end
    if draw_info.draw_currency and draw_info.activity_id then
        FLS._drawPriceCache = FLS._drawPriceCache or {}
        FLS._drawPriceCache[tonumber(draw_info.activity_id)] = { draw_info.draw_currency }
    end
end

function FLS.gatherXSuitDrawPool(pool_id)
    pool_id = tonumber(pool_id)
    local pools = {}
    local function addEntry(id, count, weight, valid, pos, quality)
        id = tonumber(id)
        if id and id > 0 then
            weight = tonumber(weight) or 1
            if weight > 0 and weight < 1 then weight = weight * 10000 end
            pools[#pools + 1] = {
                id = id, count = tonumber(count) or 1,
                weight = weight,
                valid = tonumber(valid) or 0,
                pos = tonumber(pos) or (#pools + 1),
                quality = tonumber(quality) or FLS.getItemQuality(id) or 0
            }
        end
    end
    local src = FLS._xsuitPoolCache
    if not src then
        pcall(function()
            local xa = ModuleManager.GetModule(ModuleManager.JumpModuleConfig.logic_xsuit_activity)
            if xa and xa.GetDrawPoolInfo then src = xa:GetDrawPoolInfo() end
        end)
    end
    if src and pool_id and src[pool_id] then
        for _, v in pairs(src[pool_id]) do
            if type(v) == "table" then
                addEntry(v.itemid or v.item_id, v.count or v.item_num or 1,
                    v.probability or v.weight or 1, v.valid_hours or 0,
                    v.pos or v.pos_id, v.show_quality or v.itemQuality)
            end
        end
    end
    if #pools < 1 and src then
        for _, list in pairs(src) do
            if type(list) == "table" then
                for _, v in pairs(list) do
                    if type(v) == "table" then
                        addEntry(v.itemid or v.item_id, v.count or 1, v.probability or 1, v.valid_hours or 0)
                    end
                end
            end
        end
    end
    return pools
end

function FLS.resolveXSuitDrawCost(cost_times, currency_id, voucher_id)
    cost_times = tonumber(cost_times) or 1
    currency_id = tonumber(currency_id) or 1006
    local cost = 0
    pcall(function()
        local xa = ModuleManager.GetModule(ModuleManager.JumpModuleConfig.logic_xsuit_activity)
        if xa then
            local info = xa.GetDrawActivityInfo and xa:GetDrawActivityInfo() or xa.DrawActivityInfo
            if info and info.draw_currency then
                local row = info.draw_currency[currency_id]
                if row then
                    if cost_times >= 10 then
                        cost = row.ten_cost or (row.one_cost or 0) * 10
                    elseif info.is_first_dis and info.discount_uc_cost and info.discount_uc_cost > 0 then
                        cost = info.discount_uc_cost
                    else
                        cost = row.dis_one_cost or row.one_cost or 0
                    end
                end
            end
        end
    end)
    if voucher_id and tonumber(voucher_id) and tonumber(voucher_id) > 0 then cost = 0 end
    return currency_id, cost
end

function FLS.buildXSuitDrawItemList(pool, drawTimes)
    local list = {}
    for i = 1, drawTimes do
        local pick = FLS.pickEventDrawAward(pool)
        if pick then
            list[#list + 1] = {
                itemid = pick.id,
                count = pick.count or 1,
                valid_hours = pick.valid or 0
            }
            FLS.grantResId(pick.id, pick.count or 1)
            if FLS.unlockXSuitWorkshopForItem then
                pcall(FLS.unlockXSuitWorkshopForItem, pick.id)
            end
        end
    end
    return list
end

function FLS.simulateXSuitDraw(cost_times, currency_id, voucher_id, pool_id)
    if not FLS.IsEnabled() then return false end
    cost_times = tonumber(cost_times) or 1
    pool_id = tonumber(pool_id)
    local pool = FLS.gatherXSuitDrawPool(pool_id)
    if #pool < 1 then return false end
    local cur, cost = FLS.resolveXSuitDrawCost(cost_times, currency_id, voucher_id)
    if not FLS.chargeDrawCost(cur, cost) then
        pcall(function()
            local PayBox = require("client.slua.logic.common.Payclass.logic_common_pay_box")
            if PayBox and PayBox.ShowUcRechargeMsg then PayBox.ShowUcRechargeMsg(cost) end
        end)
        return false
    end
    local item_list = FLS.buildXSuitDrawItemList(pool, cost_times)
    if not item_list or #item_list < 1 then return false end
    local decompose_list = {}
    local pool_accumulate_info, pool_draw_times, is_can_first, accumulate_coin_count = {}, {}, false, nil
    pcall(function()
        local xa = ModuleManager.GetModule(ModuleManager.JumpModuleConfig.logic_xsuit_activity)
        if xa then
            if xa.GetAccumulateAwardInfo then pool_accumulate_info = xa:GetAccumulateAwardInfo() or {} end
            if xa.GetAccumulateDrawTime then pool_draw_times = xa:GetAccumulateDrawTime() or {} end
            local info = xa.GetDrawActivityInfo and xa:GetDrawActivityInfo()
            if info then
                is_can_first = info.is_first_dis
                accumulate_coin_count = info.accumulate_coin_count
            end
        end
    end)
    pcall(function()
        local XH = require("client.network.Protocol.XSuitHandler")
        if XH and XH.on_draw_gold_dress_rsp then
            if FLS._origDrawGoldDressRsp then
                FLS._origDrawGoldDressRsp(0, item_list, decompose_list, pool_accumulate_info, pool_draw_times, is_can_first, accumulate_coin_count)
            else
                XH.on_draw_gold_dress_rsp(0, item_list, decompose_list, pool_accumulate_info, pool_draw_times, is_can_first, accumulate_coin_count)
            end
        end
    end)
    pcall(function() if F and F.refreshWardrobe then F.refreshWardrobe() end end)
    return true
end

-- Hộp chọn nhánh XSuit (1 trong 3) — protocol riêng open_gold_dress_branch_box (decompiled_new)
function FLS.isXSuitBranchBox(resId)
    resId = tonumber(resId)
    if not resId then return false end
    local ok = false
    pcall(function()
        local boxCfg = CDataTable.GetTableData("XSuitBranchChest", resId)
        ok = boxCfg ~= nil
    end)
    if ok then return true end
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if LogicXSuit and LogicXSuit.IsSpecialBranchBox then
            ok = LogicXSuit.IsSpecialBranchBox(resId) and true or false
        end
    end)
    return ok == true
end

function FLS.openXSuitBranchBoxUI(resId, source, instid)
    if not FLS.IsEnabled() then return false end
    resId = tonumber(resId)
    if not resId or not FLS.isXSuitBranchBox(resId) then return false end
    source = tonumber(source) or 1
    instid = tonumber(instid)
    local opened = false
    pcall(function()
        local cfg = UIManager.UI_Config and (UIManager.UI_Config.XSuit_Box_Select_UIBP or UIManager.UI_Config.XSuit_Box_Select_UIBP_Special)
        if not cfg then return end
        -- Tham số 3 = instid hộp (wardrobe/mail/gift); nil khiến consume/grant lệch
        UIManager.ShowUI(cfg, resId, instid, source)
        opened = true
    end)
    return opened
end

-- Gộp list wardrobe: mỗi (period, branch) chỉ giữ 1 XSuit level cao nhất / đang mặc
function FLS.collapseXSuitItemList(itemList)
    if type(itemList) ~= "table" then return itemList end
    local out, best = {}, {}
    local LogicXSuit = nil
    pcall(function() LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit") end)
    if not LogicXSuit or not LogicXSuit.IsXSuit then return itemList end
    for _, v in pairs(itemList) do
        local rid = v and tonumber(v.res_id or v.resID or v.item_id)
        if rid and LogicXSuit.IsXSuit(rid) then
            local period = LogicXSuit.GetPeriodByItemId and LogicXSuit.GetPeriodByItemId(rid)
            local branchId = (LogicXSuit.GetBranchByItemId and LogicXSuit.GetBranchByItemId(rid)) or 0
            local level = (LogicXSuit.GetLevelByItemId and LogicXSuit.GetLevelByItemId(rid)) or 1
            period, branchId, level = tonumber(period), tonumber(branchId) or 0, tonumber(level) or 1
            if period then
                local key = tostring(period) .. ":" .. tostring(branchId)
                local prev = best[key]
                local prefer = false
                if not prev then
                    prefer = true
                elseif v.isUsing and not (prev.item and prev.item.isUsing) then
                    prefer = true
                elseif (not (prev.item and prev.item.isUsing) or v.isUsing) and level > (prev.level or 0) then
                    prefer = true
                end
                if prefer then best[key] = { item = v, level = level } end
            else
                out[#out + 1] = v
            end
        else
            out[#out + 1] = v
        end
    end
    for _, b in pairs(best) do
        if b and b.item then out[#out + 1] = b.item end
    end
    return out
end

-- Wardrobe lọc XSuit theo XSuitWardrobeBranchData[period].branch_id
-- FreeLobbyShop: hiện mọi nhánh đã sở hữu, nhưng mỗi nhánh chỉ 1 level (cao nhất).
function FLS.hookXSuitWardrobeBranchFilter()
    local function patchFilter(mod, fnName)
        if type(mod) ~= "table" or type(mod[fnName]) ~= "function" then return false end
        local flag = "__Kutta_" .. fnName
        local orig = mod[flag] or mod[fnName]
        mod[flag] = orig
        mod[fnName] = function(self, itemList, ...)
            if FLS.IsEnabled() then
                return FLS.collapseXSuitItemList(itemList)
            end
            return orig(self, itemList, ...)
        end
        return true
    end
    -- Luôn re-patch FilterAvatarMultiItem (fix collapse level không bị kẹt hook cũ)
    pcall(function()
        local tools = require("client.slua.logic.lobby.Left.SocialLobby.Logic_AvatarWardrobeDataTools")
        if type(tools) ~= "table" or type(tools.FilterAvatarMultiItem) ~= "function" then return end
        local orig = tools.__Kutta_FilterAvatarMultiItem or tools.FilterAvatarMultiItem
        tools.__Kutta_FilterAvatarMultiItem = orig
        tools.FilterAvatarMultiItem = function(tAvatarAllItem, tAllMultiLevelItemId)
                if not FLS.IsEnabled() then
                    return orig(tAvatarAllItem, tAllMultiLevelItemId)
                end
                -- Giữ multi-level/fusion; XSuit: 1 skin / (period, branch) = level cao nhất đang có
                local tFilterResult = {}
                local tMultiLevelResult = {}
                local tXSuitBest = {}
                local LogicMultiItemModule = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicMultiItemModule)
                local LogicFusionModule = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicFusionModule)
                local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                local WardrobeLogicManager = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                for _, v in pairs(tAvatarAllItem or {}) do
                    if LogicXSuit.IsXSuit and LogicXSuit.IsXSuit(v.res_id) then
                        local period = LogicXSuit.GetPeriodByItemId and LogicXSuit.GetPeriodByItemId(v.res_id)
                        local branchId = (LogicXSuit.GetBranchByItemId and LogicXSuit.GetBranchByItemId(v.res_id)) or 0
                        local level = (LogicXSuit.GetLevelByItemId and LogicXSuit.GetLevelByItemId(v.res_id)) or 1
                        period, branchId, level = tonumber(period), tonumber(branchId) or 0, tonumber(level) or 1
                        if period then
                            local key = tostring(period) .. ":" .. tostring(branchId)
                            local prev = tXSuitBest[key]
                            local prefer = false
                            if not prev then
                                prefer = true
                            elseif v.isUsing and not prev.item.isUsing then
                                prefer = true
                            elseif (not prev.item.isUsing or v.isUsing) and level > (prev.level or 0) then
                                prefer = true
                            end
                            if prefer then
                                tXSuitBest[key] = { item = v, level = level }
                            end
                        else
                            table.insert(tFilterResult, v)
                        end
                    elseif LogicMultiItemModule:IsWardRobeMultiLevelItem(v.res_id) then
                        local nGroupID = LogicMultiItemModule:GetMultiItemGroup(v.res_id)
                        if not LogicMultiItemModule:CheckLowLevelHasOwn(v.res_id, EWardrobeDataSource.Wardrobe) then
                        elseif v.isUsing then
                            tMultiLevelResult[nGroupID] = v
                        elseif tAllMultiLevelItemId and tAllMultiLevelItemId[v.res_id] then
                            tMultiLevelResult[nGroupID] = v
                        elseif LogicMultiItemModule:IsLastSelectMultiLevel(v.res_id) then
                            tMultiLevelResult[nGroupID] = v
                        elseif not tMultiLevelResult[nGroupID] then
                            tMultiLevelResult[nGroupID] = v
                        end
                    elseif LogicFusionModule:IsFusionItem(v.res_id) then
                        local config = LogicFusionModule:GetFusionConfig(v.res_id)
                        local period = config.period
                        local targetItem = config.targetItem
                        local fusionRecord = LogicFusionModule:GetFusionRecord(period)
                        if fusionRecord and fusionRecord.current_item_id == targetItem then
                            if v.res_id == targetItem then
                                for _, originItem in pairs(config.originItems) do
                                    local fusionItemData = DeepCopy(v)
                                    fusionItemData.originItem = originItem
                                    local displayItem = LogicFusionModule:GetDisplayItem(originItem)
                                    if displayItem then
                                        WardrobeLogicManager:SetDisplayItemId(fusionItemData, displayItem)
                                    end
                                    table.insert(tFilterResult, fusionItemData)
                                end
                            end
                        elseif v.res_id ~= targetItem then
                            table.insert(tFilterResult, v)
                        end
                    else
                        local tCartoonStyleCfg = LogicMultiItemModule:GetCartoonStyleCfg(v.res_id)
                        if tCartoonStyleCfg then
                            if v.isUsing then
                                tMultiLevelResult[tCartoonStyleCfg.BaseID] = v
                            elseif tAllMultiLevelItemId and tAllMultiLevelItemId[v.res_id] then
                                tMultiLevelResult[tCartoonStyleCfg.BaseID] = v
                            elseif not tMultiLevelResult[tCartoonStyleCfg.BaseID] and v.res_id == tCartoonStyleCfg.BaseID then
                                tMultiLevelResult[tCartoonStyleCfg.BaseID] = v
                            end
                        else
                            table.insert(tFilterResult, v)
                        end
                    end
                end
                for _, v in pairs(tMultiLevelResult) do
                    table.insert(tFilterResult, v)
                end
                for _, best in pairs(tXSuitBest) do
                    if best and best.item then table.insert(tFilterResult, best.item) end
                end
                return tFilterResult
            end
    end)
    if FLS._hookedXSuitWardrobeBranchFilter then return true end
    pcall(function()
        local avatar = require("client.slua.umg.Wardrobe.subtab_avatar")
        patchFilter(avatar, "FilterBranchXSuit")
        if avatar and avatar.__inner_impl then patchFilter(avatar.__inner_impl, "FilterBranchXSuit") end
    end)
    pcall(function()
        local suit = require("client.slua.umg.Wardrobe.subtab_suit")
        patchFilter(suit, "FilterBranchXSuitMatchList")
        if suit and suit.__inner_impl then patchFilter(suit.__inner_impl, "FilterBranchXSuitMatchList") end
    end)
    FLS._hookedXSuitWardrobeBranchFilter = true
    return true
end

-- opts.skipEvent: chỉ ghi data, không bắn UPDATE_DRESS_BRANCH (tránh đè UI trước khi putOn)
function FLS.setXSuitWardrobeBranch(meta, opts)
    if not meta or not meta.period then return false end
    opts = type(opts) == "table" and opts or {}
    local ok = false
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return end
        local branchId = tonumber(meta.branchId) or 0
        local data = {
            branch_id = branchId,
            resid = meta.itemId,
            item_id = meta.itemId,
        }
        LogicXSuit.XSuitWardrobeBranchData = LogicXSuit.XSuitWardrobeBranchData or {}
        if LogicXSuit.SetWardrobeBranchByPeriod then
            LogicXSuit.SetWardrobeBranchByPeriod(meta.period, data)
        else
            LogicXSuit.XSuitWardrobeBranchData[meta.period] = data
        end
        if LogicXSuit.SetActiveBranchInfo then
            LogicXSuit.SetActiveBranchInfo(meta.period, meta.itemId, branchId)
        end
        LogicXSuit.activeBranchInfo = LogicXSuit.activeBranchInfo or {}
        LogicXSuit.activeBranchInfo[meta.period] = { resid = meta.itemId, branch_id = branchId }
        -- Khi đang nâng level / skipEvent: không bắn (wardrobe rebuild đè UI)
        if not opts.skipEvent and not FLS._risingStar and not FLS._switchingBranch
            and EventSystem and EVENTTYPE_GOLDEN_SUIT and EVENTID_GOLDEN_SUIT_UPDATE_DRESS_BRANCH then
            EventSystem:postEvent(EVENTTYPE_GOLDEN_SUIT, EVENTID_GOLDEN_SUIT_UPDATE_DRESS_BRANCH, meta.period, branchId, meta.itemId)
        end
        ok = true
    end)
    return ok
end

-- Cập nhật list: nhánh đang mặc → đúng level + dấu tích; nhánh khác giữ item, bỏ tích
function FLS.refreshXSuitWardrobeWearFlags(period, wearResId, wearInsId, suitSelf)
    period = tonumber(period)
    wearResId = tonumber(wearResId)
    wearInsId = tonumber(wearInsId)
    if not period then return end
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return end
        local suitUI = suitSelf or FLS._wardrobeSuitSelf
        local wearBranch = nil
        if wearResId and LogicXSuit.GetBranchByItemId then
            wearBranch = tonumber(LogicXSuit.GetBranchByItemId(wearResId))
        end
        local wearItemInfo = nil
        if wearResId then
            pcall(function()
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local WardrobeLogicManager = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                local depotData = wd and wd.GetHallDepotItemDataByResID and wd:GetHallDepotItemDataByResID(wearResId)
                if depotData and WardrobeLogicManager and WardrobeLogicManager.ArrayHallDepotToCommonItem then
                    wearItemInfo = WardrobeLogicManager:ArrayHallDepotToCommonItem(depotData, nil, true, true, false, false)
                    wearItemInfo.isUsing = true
                    wearItemInfo.isSelected = true
                    wearItemInfo.isRolewear = false
                    if not wearInsId then
                        wearInsId = tonumber(depotData.insID or depotData.ins_id or depotData.instid)
                    end
                end
            end)
        end
        local function refreshGrid(grid)
            if not grid or not grid.GetItemCount then return end
            local n = grid:GetItemCount() or 0
            for i = 1, n do
                local data = grid:GetItemData(i)
                if data and data.res_id and LogicXSuit.GetPeriodByItemId
                    and LogicXSuit.GetPeriodByItemId(data.res_id) == period then
                    local itemBranch = tonumber(LogicXSuit.GetBranchByItemId and LogicXSuit.GetBranchByItemId(data.res_id)) or 0
                    if wearBranch ~= nil and itemBranch == wearBranch and wearItemInfo then
                        if grid.RefreshItem then grid:RefreshItem(i, wearItemInfo) end
                    else
                        data.isUsing = false
                        data.isSelected = false
                        if grid.RefreshItem then grid:RefreshItem(i, data) end
                    end
                end
            end
        end
        if suitUI then
            FLS._wardrobeSuitSelf = suitUI
            refreshGrid(suitUI.LoopScrollGrid_Normal)
            if suitUI.OnRefreshButtonByBranch and wearResId then
                pcall(suitUI.OnRefreshButtonByBranch, suitUI, period, wearBranch or 0, wearResId)
            end
        end
    end)
end

-- Hook: không thay item trong list bằng 1 skin (làm mất nhánh / mất dấu tích)
function FLS.hookXSuitBranchChangeUI()
    if FLS._hookedXSuitBranchChangeUI then return true end
    local function patch(mod)
        if type(mod) ~= "table" then return end
        if type(mod.UpdateXSuitItemByBranch) == "function" and not mod.__Kutta_UpdateXSuitItemByBranch then
            local orig = mod.UpdateXSuitItemByBranch
            mod.__Kutta_UpdateXSuitItemByBranch = orig
            mod.UpdateXSuitItemByBranch = function(self, period, branchId)
                if self then FLS._wardrobeSuitSelf = self end
                if FLS.IsEnabled() then
                    local wearRes, wearIns = nil, nil
                    pcall(function()
                        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                        -- Ưu tiên item đang mặc thật, không lấy L1 của nhánh
                        if F.findWornInsBySubType then
                            wearIns, wearRes = F.findWornInsBySubType(OUTFIT_SUB, function(r)
                                return LogicXSuit.IsXSuit and LogicXSuit.IsXSuit(r)
                            end)
                        end
                        if not wearRes then
                            wearRes = LogicXSuit.GetItemIDByPeriod and LogicXSuit.GetItemIDByPeriod(period, nil, branchId)
                            if wearRes then
                                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                                local d = wd and wd.GetHallDepotItemDataByResID and wd:GetHallDepotItemDataByResID(wearRes)
                                if d then wearIns = tonumber(d.insID or d.ins_id or d.instid) end
                            end
                        end
                    end)
                    FLS.refreshXSuitWardrobeWearFlags(period, wearRes, wearIns, self)
                    if self and self.OnRefreshButtonByBranch then
                        pcall(self.OnRefreshButtonByBranch, self, period, branchId, wearRes)
                    end
                    return
                end
                return orig(self, period, branchId)
            end
        end
        if type(mod.OnXSuitBranchChange) == "function" and not mod.__Kutta_OnXSuitBranchChange then
            local origC = mod.OnXSuitBranchChange
            mod.__Kutta_OnXSuitBranchChange = origC
            mod.OnXSuitBranchChange = function(self, ...)
                if self then FLS._wardrobeSuitSelf = self end
                return origC(self, ...)
            end
        end
    end
    pcall(function()
        local suit = require("client.slua.umg.Wardrobe.subtab_suit")
        patch(suit)
        if suit and suit.__inner_impl then patch(suit.__inner_impl) end
    end)
    FLS._hookedXSuitBranchChangeUI = true
    return true
end

function FLS.ensureXSuitInDepot(itemId)
    itemId = tonumber(itemId)
    if not itemId or itemId <= 0 then return false end
    local function have()
        local n = 0
        pcall(function()
            if F.getEntityDepotCount then n = tonumber(F.getEntityDepotCount(itemId)) or 0 end
        end)
        if n > 0 then return true end
        pcall(function()
            if F.getDepotCount then n = tonumber(F.getDepotCount(itemId)) or 0 end
        end)
        if n > 0 then return true end
        local found = false
        pcall(function()
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            if wd and wd.GetHallDepotItemDataByResID then
                found = wd:GetHallDepotItemDataByResID(itemId) ~= nil
            end
            if not found and wd and wd.GetHallDepotItemCountByResID then
                found = (tonumber(wd:GetHallDepotItemCountByResID(itemId)) or 0) > 0
            end
        end)
        return found
    end
    if have() then
        pcall(function() if F.registerDumpExtraSkin then F.registerDumpExtraSkin(itemId) end end)
        return true
    end
    pcall(function()
        if F.grantDepotItem then F.grantDepotItem(itemId, 1, { markNew = true }) end
    end)
    if not have() then
        pcall(function()
            if F.injectDumpItem then F.injectDumpItem(itemId, { markNew = true, count = 1 }) end
        end)
    end
    if not have() then
        pcall(function()
            local entity = F.getEntity and F.getEntity()
            if not entity or not entity.bInit then return end
            local ins = (R and R.resToIns and R.resToIns[itemId]) or (F.dumpInsForRes and F.dumpInsForRes(itemId))
            if ins and F.injectOne then F.injectOne(entity, itemId, ins, 1) end
        end)
    end
    if have() then
        pcall(function() if F.registerDumpExtraSkin then F.registerDumpExtraSkin(itemId) end end)
        pcall(function() if F.forceWardrobeDepotRefresh then F.forceWardrobeDepotRefresh() end end)
        return true
    end
    return false
end

-- Workshop X-Suit: unlock_flag/current nằm ở LogicXSuit.shareTimeList (server rise_star)
FLS._xsuitWorkshopUnlocks = FLS._xsuitWorkshopUnlocks or {}

function FLS.resolveXSuitMeta(itemId)
    itemId = tonumber(itemId)
    if not itemId then return nil end
    local period, branchId, level = nil, 0, 1
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return end
        if LogicXSuit.InitXSuitItemList then pcall(LogicXSuit.InitXSuitItemList, itemId) end
        period = LogicXSuit.GetPeriodByItemId and LogicXSuit.GetPeriodByItemId(itemId)
        branchId = (LogicXSuit.GetBranchByItemId and LogicXSuit.GetBranchByItemId(itemId)) or 0
        level = (LogicXSuit.GetLevelByItemId and LogicXSuit.GetLevelByItemId(itemId)) or 1
    end)
    if not period then return nil end
    return {
        itemId = itemId,
        period = tonumber(period),
        branchId = tonumber(branchId) or 0,
        level = tonumber(level) or 1
    }
end

function FLS.rememberXSuitWorkshopUnlock(meta)
    if not meta or not meta.period then return end
    FLS._xsuitWorkshopUnlocks = FLS._xsuitWorkshopUnlocks or {}
    local key = tostring(meta.period) .. ":" .. tostring(meta.branchId or 0)
    local prev = FLS._xsuitWorkshopUnlocks[key]
    local lv = tonumber(meta.level) or 1
    if prev and tonumber(prev.current or 0) > lv then lv = tonumber(prev.current) end
    FLS._xsuitWorkshopUnlocks[key] = {
        period = meta.period,
        branchId = meta.branchId or 0,
        current = lv,
        itemId = meta.itemId,
        unlock_flag = true
    }
end

function FLS.applyXSuitWorkshopUnlocks()
    local unlocks = FLS._xsuitWorkshopUnlocks or {}
    local applied = false
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return end
        LogicXSuit.shareTimeList = LogicXSuit.shareTimeList or {}
        local now = 1
        pcall(function()
            local TimeUtil = require("client.common.time_util")
            if TimeUtil and TimeUtil.GetServerTimeInSec then
                now = TimeUtil.GetServerTimeInSec() or 1
            else
                now = os.time()
            end
        end)
        for _, u in pairs(unlocks) do
            local period = tonumber(u.period)
            local branchId = tonumber(u.branchId) or 0
            local current = tonumber(u.current) or 1
            if period then
                LogicXSuit.shareTimeList[period] = LogicXSuit.shareTimeList[period] or {}
                -- Format mới: shareTimeList[period][branchId]
                local branchInfo = LogicXSuit.shareTimeList[period][branchId]
                if type(branchInfo) ~= "table" then
                    branchInfo = {}
                    LogicXSuit.shareTimeList[period][branchId] = branchInfo
                end
                branchInfo.unlock_flag = true
                branchInfo.current = math.max(tonumber(branchInfo.current) or 0, current)
                branchInfo.init_show_time = tonumber(branchInfo.init_show_time) or 0
                if branchInfo.init_show_time > now then branchInfo.init_show_time = 0 end
                branchInfo.level_time = branchInfo.level_time or {}
                for lv = 1, branchInfo.current do
                    branchInfo.level_time[lv] = branchInfo.level_time[lv] or now
                end
                -- Format cũ (không branch): một số field nằm thẳng trên period
                if LogicXSuit.shareTimeList[period].current ~= nil or LogicXSuit.shareTimeList[period].unlock_flag ~= nil then
                    LogicXSuit.shareTimeList[period].unlock_flag = true
                    LogicXSuit.shareTimeList[period].current = math.max(
                        tonumber(LogicXSuit.shareTimeList[period].current) or 0, current)
                end
                if LogicXSuit.SetActiveBranchInfo then
                    pcall(LogicXSuit.SetActiveBranchInfo, period, u.itemId, branchId)
                end
                LogicXSuit.activeBranchInfo = LogicXSuit.activeBranchInfo or {}
                LogicXSuit.activeBranchInfo[period] = LogicXSuit.activeBranchInfo[period]
                    or { resid = u.itemId, branch_id = branchId }
                applied = true
            end
        end
        -- Áp lại nhánh tủ đồ đã chọn (không loop mọi branch — tránh đè nhầm)
        for period, meta in pairs(FLS._xsuitWardrobeBranchPrefer or {}) do
            if FLS.setXSuitWardrobeBranch then FLS.setXSuitWardrobeBranch(meta) end
        end
        if applied and EventSystem and EVENTTYPE_SHARECOMPONENT and EVENTID_SHARECOMPONENT_UPDATE_SHARE_TIME then
            EventSystem:postEvent(EVENTTYPE_SHARECOMPONENT, EVENTID_SHARECOMPONENT_UPDATE_SHARE_TIME)
        end
        if applied and EventSystem and EVENTTYPE_XSUIT then
            pcall(function()
                if EVENTID_XSUIT_ACTIVE_BRANCH_UPDATE then
                    EventSystem:postEvent(EVENTTYPE_XSUIT, EVENTID_XSUIT_ACTIVE_BRANCH_UPDATE)
                end
            end)
        end
    end)
    return applied
end

-- ID skin level 7 (Grand Descent cần GoldClothBattleEffect.CallStatue của L7)
function FLS.resolveXSuitLevel7Id(itemId)
    itemId = tonumber(itemId)
    if not itemId then return nil end
    local id7 = nil
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return end
        local period = LogicXSuit.GetPeriodByItemId and LogicXSuit.GetPeriodByItemId(itemId)
        local branchId = (LogicXSuit.GetBranchByItemId and LogicXSuit.GetBranchByItemId(itemId)) or 0
        if not period then return end
        if LogicXSuit.InitXSuitBaseInfo then pcall(LogicXSuit.InitXSuitBaseInfo, period) end
        if LogicXSuit.GetItemIDByLevel then
            id7 = LogicXSuit.GetItemIDByLevel(period, 7, branchId)
        end
        if not id7 and LogicXSuit.upgradeInfo and LogicXSuit.upgradeInfo[period]
            and LogicXSuit.upgradeInfo[period][branchId]
            and LogicXSuit.upgradeInfo[period][branchId][7] then
            id7 = LogicXSuit.upgradeInfo[period][branchId][7].item_id
        end
    end)
    return tonumber(id7)
end

-- Max workshop + skin L7 + switchLevel=7 (Grand Descent / form Common)
-- Chỉ cập nhật switchLevel local — KHÔNG gọi OnSetGoldDressNewLevelRsp
-- (rsp gốc: UpdateLobbyAvatar + GetOrReqData force → treo/crash khi equip)
function FLS.applySwitchLevelQuiet(period, switchLevel, branchId)
    period = tonumber(period)
    switchLevel = tonumber(switchLevel)
    branchId = tonumber(branchId) or 0
    if not period or not switchLevel then return false end
    local ok = false
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return end
        LogicXSuit.switchLevel = LogicXSuit.switchLevel or {}
        LogicXSuit.switchLevel[period] = LogicXSuit.switchLevel[period] or {}
        LogicXSuit.switchLevel[period][branchId] = switchLevel
        if EventSystem and EVENTTYPE_GOLDEN_SUIT and EVENTID_GOLDEN_SUIT_UPDATE_DRESS_LEVEL then
            EventSystem:postEvent(EVENTTYPE_GOLDEN_SUIT, EVENTID_GOLDEN_SUIT_UPDATE_DRESS_LEVEL, branchId)
        end
        ok = true
    end)
    return ok
end

-- opts.quiet = true: không putOn / không OnSetGoldDressNewLevelRsp / không refresh nặng
function FLS.maxXSuitToLevel7(period, branchId, opts)
    period = tonumber(period)
    branchId = tonumber(branchId) or 0
    opts = type(opts) == "table" and opts or {}
    local quiet = opts.quiet == true
    if not period then return false end
    FLS._xsuitMaxed = FLS._xsuitMaxed or {}
    local cacheKey = tostring(period) .. ":" .. tostring(branchId)
    if quiet and FLS._xsuitMaxed[cacheKey] then
        -- Đã max rồi: chỉ sync switchLevel nhẹ
        FLS.applySwitchLevelQuiet(period, 7, branchId)
        return true
    end
    local ok = false
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return end
        if LogicXSuit.InitXSuitBaseInfo then pcall(LogicXSuit.InitXSuitBaseInfo, period) end
        local levels = LogicXSuit.upgradeInfo and LogicXSuit.upgradeInfo[period]
            and LogicXSuit.upgradeInfo[period][branchId]
        local id7, maxLv = nil, 0
        if type(levels) == "table" then
            for lv, info in pairs(levels) do
                local n = tonumber(lv) or 0
                if n > maxLv then maxLv = n end
                if n == 7 and info then id7 = info.item_id end
            end
        end
        if not id7 and LogicXSuit.GetItemIDByLevel then
            id7 = LogicXSuit.GetItemIDByLevel(period, 7, branchId)
        end
        id7 = tonumber(id7)
        -- Chỉ inject L7, gỡ L1..L6 — tránh kho đồ hiện 2 skin
        if id7 then
            FLS.grantXSuitLevelSkinQuiet(id7)
            FLS.purgeXSuitOtherLevelSkins(period, branchId, id7)
        end
        local meta = {
            itemId = id7 or (levels and levels[maxLv] and levels[maxLv].item_id),
            period = period,
            branchId = branchId,
            level = 7,
        }
        FLS.rememberXSuitWorkshopUnlock(meta)
        FLS._xsuitWardrobeBranchPrefer = FLS._xsuitWardrobeBranchPrefer or {}
        FLS._xsuitWardrobeBranchPrefer[period] = meta
        LogicXSuit.shareTimeList = LogicXSuit.shareTimeList or {}
        LogicXSuit.shareTimeList[period] = LogicXSuit.shareTimeList[period] or {}
        local b = LogicXSuit.shareTimeList[period][branchId]
        if type(b) ~= "table" then
            b = {}
            LogicXSuit.shareTimeList[period][branchId] = b
        end
        b.unlock_flag = true
        b.current = 7
        b.init_show_time = tonumber(b.init_show_time) or 0
        b.level_time = b.level_time or {}
        local now = os.time()
        for lv = 1, 7 do b.level_time[lv] = b.level_time[lv] or now end
        FLS.applySwitchLevelQuiet(period, 7, branchId)
        -- Không gọi OnSetGoldDressNewLevelRsp / putOnOutfit / forceWardrobe — treo khi equip
        if not quiet then
            pcall(function() FLS.applyXSuitWorkshopUnlocks() end)
            pcall(function() FLS.setXSuitWardrobeBranch(meta) end)
        else
            -- Prefer branch data nhẹ, không bắn event wardrobe rebuild
            pcall(function()
                LogicXSuit.XSuitWardrobeBranchData = LogicXSuit.XSuitWardrobeBranchData or {}
                LogicXSuit.XSuitWardrobeBranchData[period] = {
                    branch_id = branchId,
                    resid = meta.itemId,
                    item_id = meta.itemId,
                }
            end)
        end
        FLS._xsuitMaxed[cacheKey] = true
        ok = true
    end)
    return ok
end

function FLS.unlockXSuitWorkshopForItem(itemId)
    itemId = tonumber(itemId)
    if not itemId then return false end
    local meta = FLS.resolveXSuitMeta(itemId)
    if not meta then return false end
    FLS.rememberXSuitWorkshopUnlock(meta)
    FLS._xsuitWardrobeBranchPrefer = FLS._xsuitWardrobeBranchPrefer or {}
    FLS._xsuitWardrobeBranchPrefer[meta.period] = meta
    FLS.applyXSuitWorkshopUnlocks()
    FLS.setXSuitWardrobeBranch(meta)
    -- Không auto L7 — người chơi tự nâng trong workshop
    FLS.grantXSuitUpgradeMaterials(meta.period, meta.branchId or 0)
    -- Một lần re-apply sau sync server (tránh 3 timer chồng khi equip)
    pcall(function()
        local ticker = require("common.time_ticker")
        if ticker and ticker.AddTimerOnce then
            ticker.AddTimerOnce(1.0, function()
                FLS.applyXSuitWorkshopUnlocks()
                FLS.setXSuitWardrobeBranch(meta)
            end)
        end
    end)
    return true
end

-- Sau load JSON / inject: unlock mọi nhánh XSuit đang có (nút đổi dạng cần ≥2 unlock_flag)
function FLS.scanDepotAndUnlockXSuits()
    local ok = false
    pcall(function()
        if not (_G.KuttaVaiConfig and (_G.KuttaVaiConfig.ModSkin == true or _G.KuttaVaiConfig.FreeLobbyShop == true)) then
            return
        end
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit or not LogicXSuit.IsXSuit then return end

        local seen = {}
        local function consider(res)
            res = tonumber(res)
            if not res or res <= 0 or seen[res] then return end
            if not LogicXSuit.IsXSuit(res) then return end
            seen[res] = true
            local meta = FLS.resolveXSuitMeta(res)
            if not meta then return end
            pcall(function() FLS.grantXSuitLevelSkinQuiet(res) end)
            pcall(function() FLS.ensureXSuitInDepot(res) end)
            pcall(function() if F.registerDumpExtraSkin then F.registerDumpExtraSkin(res) end end)
            FLS.rememberXSuitWorkshopUnlock(meta)
            pcall(function() FLS.grantXSuitUpgradeMaterials(meta.period, meta.branchId or 0) end)
        end

        -- 1) Unlock đã lưu JSON
        for _, u in pairs(FLS._xsuitWorkshopUnlocks or {}) do
            if u and u.itemId then consider(u.itemId) end
        end
        -- 2) Depot entity
        local entity = F.getEntity and F.getEntity()
        if entity and entity._data then
            for i = 1, (entity._DataCount or #entity._data) do
                local d = entity._data[i]
                if d and (tonumber(d.count) or 0) > 0 then
                    consider(d.resID or d.res_id)
                end
            end
        end
        -- 3) Dump / persist
        for res, on in pairs(_G.KuttaCheatTG_DumpExtraSkins or {}) do
            if on then consider(res) end
        end
        if type(PERSIST) == "table" and type(PERSIST.configDepotItems) == "table" then
            for res, on in pairs(PERSIST.configDepotItems) do
                if on then consider(res) end
            end
        end
        -- 4) Slot trang phục đã lưu
        if type(PERSIST) == "table" and type(PERSIST.configSlots) == "table" then
            for _, res in pairs(PERSIST.configSlots) do
                consider(res)
            end
        end

        if not next(FLS._xsuitWorkshopUnlocks or {}) then return end

        FLS.applyXSuitWorkshopUnlocks()

        -- Nhánh tủ đồ: ưu tiên đang mặc / prefer
        local preferMeta = nil
        pcall(function()
            if F.findWornInsBySubType then
                local _, wornRes = F.findWornInsBySubType(OUTFIT_SUB, function(r)
                    return LogicXSuit.IsXSuit(r)
                end)
                if wornRes then preferMeta = FLS.resolveXSuitMeta(wornRes) end
            end
        end)
        if not preferMeta then
            for _, meta in pairs(FLS._xsuitWardrobeBranchPrefer or {}) do
                preferMeta = meta
                break
            end
        end
        if not preferMeta then
            for _, u in pairs(FLS._xsuitWorkshopUnlocks or {}) do
                if u and u.itemId then
                    preferMeta = {
                        itemId = u.itemId,
                        period = u.period,
                        branchId = u.branchId or 0,
                        level = u.current or 1,
                    }
                    break
                end
            end
        end
        if preferMeta then
            FLS._xsuitWardrobeBranchPrefer = FLS._xsuitWardrobeBranchPrefer or {}
            FLS._xsuitWardrobeBranchPrefer[preferMeta.period] = preferMeta
            FLS.setXSuitWardrobeBranch(preferMeta, { skipEvent = true })
        end
        -- Mỗi nhánh chỉ giữ 1 level cao nhất (tránh tủ đồ hiện cả 7)
        pcall(function() if FLS.collapseOwnedXSuitLevelsInDepot then FLS.collapseOwnedXSuitLevelsInDepot() end end)
        ok = true
    end)
    return ok
end

-- Nguyên liệu XSuit ảo kiểu UnlimitedCash: chỉ tăng count khi query, KHÔNG inject depot
FLS.XSUIT_MAT_VALUE = 999999999
FLS._xsuitMatVirtual = FLS._xsuitMatVirtual or {}

function FLS.isXSuitVirtualMat(resId)
    resId = tonumber(resId)
    return resId ~= nil and FLS._xsuitMatVirtual[resId] ~= nil
end

function FLS.getXSuitVirtualMatCount(resId)
    resId = tonumber(resId)
    if not resId then return 0 end
    local v = FLS._xsuitMatVirtual[resId]
    if v == nil then return 0 end
    return tonumber(v) or FLS.XSUIT_MAT_VALUE
end

function FLS.spendXSuitVirtualMat(resId, amount)
    resId = tonumber(resId)
    amount = tonumber(amount) or 0
    if not resId or amount < 1 then return true end
    if not FLS.isXSuitVirtualMat(resId) then return false end
    -- Giống UC: trừ ảo nhưng luôn giữ mức cao (không bao giờ hết)
    local cur = FLS.getXSuitVirtualMatCount(resId)
    local nextv = cur - amount
    if nextv < FLS.XSUIT_MAT_VALUE / 2 then nextv = FLS.XSUIT_MAT_VALUE end
    FLS._xsuitMatVirtual[resId] = nextv
    return true
end

function FLS.registerXSuitVirtualMat(resId, amount)
    resId = tonumber(resId)
    if not resId or resId <= 0 then return false end
    amount = tonumber(amount) or FLS.XSUIT_MAT_VALUE
    FLS._xsuitMatVirtual = FLS._xsuitMatVirtual or {}
    local cur = tonumber(FLS._xsuitMatVirtual[resId]) or 0
    if cur < amount then FLS._xsuitMatVirtual[resId] = amount end
    return true
end

-- Đăng ký nguyên liệu ảo cho period/branch (không đụng entity/depot → tránh treo)
function FLS.grantXSuitUpgradeMaterials(period, branchId, minAmount)
    period = tonumber(period)
    branchId = tonumber(branchId) or 0
    minAmount = tonumber(minAmount) or FLS.XSUIT_MAT_VALUE
    if not period then return false end
    local ok = false
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return end
        if LogicXSuit.InitXSuitBaseInfo then pcall(LogicXSuit.InitXSuitBaseInfo, period) end
        local levels = LogicXSuit.upgradeInfo and LogicXSuit.upgradeInfo[period]
            and LogicXSuit.upgradeInfo[period][branchId]
        local function addMat(id)
            if FLS.registerXSuitVirtualMat(id, minAmount) then ok = true end
        end
        if type(levels) == "table" then
            for _, info in pairs(levels) do
                local cfg = info and (info.cfg or info)
                if type(cfg) == "table" then
                    for i = 1, 2 do
                        addMat(cfg["MatID" .. i])
                        addMat(cfg["LimitMatID" .. i])
                        addMat(cfg["ActiveID" .. i])
                        addMat(cfg["BackID" .. i])
                        addMat(cfg["SecondMatID" .. i])
                    end
                    addMat(cfg.SecondMatID)
                    addMat(cfg.MatID1)
                    addMat(cfg.MatID2)
                    addMat(cfg.LimitMatID1)
                    addMat(cfg.LimitMatID2)
                    addMat(cfg.ActiveID1)
                    addMat(cfg.ActiveID2)
                    addMat(cfg.BackID1)
                    addMat(cfg.BackID2)
                end
            end
        end
        -- Coin draw XSuit (makeup) — không duyệt cả materialItemIDMap (nặng)
        pcall(function()
            local act = ModuleManager.GetModule(ModuleManager.JumpModuleConfig.logic_xsuit_activity)
            local cid = act and act.GetDrawCurrencyID and act:GetDrawCurrencyID()
            addMat(cid)
        end)
    end)
    return ok
end

function FLS.ensureXSuitMaterialsForItem(itemId)
    itemId = tonumber(itemId)
    if not itemId then return false end
    local meta = FLS.resolveXSuitMeta(itemId)
    if not meta then return false end
    return FLS.grantXSuitUpgradeMaterials(meta.period, meta.branchId or 0)
end

-- Inject skin level mới nhẹ: không refreshWardrobe / reinject (tránh treo khi nâng)
function FLS.grantXSuitLevelSkinQuiet(resId)
    resId = tonumber(resId)
    if not resId or resId <= 0 then return false end
    local ok = false
    pcall(function()
        local entity = F.getEntity and F.getEntity()
        if not entity or not entity.bInit then return end
        if F.firstInsForRes and F.firstInsForRes(entity, resId) then
            ok = true
            return
        end
        local ins = (R and R.resToIns and R.resToIns[resId]) or (F.dumpInsForRes and F.dumpInsForRes(resId))
        if not ins or not F.injectOne then return end
        if F.injectOne(entity, resId, ins, 1) then
            if R then
                R.resToIns[resId] = ins
                R.insToRes[ins] = resId
            end
            if F.registerDumpExtraSkin then F.registerDumpExtraSkin(resId) end
            ok = true
        end
    end)
    return ok
end

-- Chỉ giữ 1 skin level hiện tại trong depot (tránh tủ đồ hiện L1..L7)
function FLS.purgeXSuitOtherLevelSkins(period, branchId, keepItemId)
    period = tonumber(period)
    keepItemId = tonumber(keepItemId)
    branchId = tonumber(branchId) or 0
    if not period or not keepItemId then return end
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return end
        if LogicXSuit.InitXSuitBaseInfo then pcall(LogicXSuit.InitXSuitBaseInfo, period) end
        local levels = LogicXSuit.upgradeInfo and LogicXSuit.upgradeInfo[period]
            and LogicXSuit.upgradeInfo[period][branchId]
        if type(levels) ~= "table" then return end
        local entity = F.getEntity and F.getEntity()
        for _, info in pairs(levels) do
            local rid = info and tonumber(info.item_id)
            if rid and rid > 0 and rid ~= keepItemId then
                local ins = nil
                if entity and F.firstInsForRes then ins = F.firstInsForRes(entity, rid) end
                if not ins and R and R.resToIns then ins = R.resToIns[rid] end
                if entity and ins and F.purgeEntityDepotItem then
                    F.purgeEntityDepotItem(entity, rid, ins)
                elseif F.consumeDepotItem then
                    pcall(function()
                        local n = 1
                        if F.getDepotCount then n = math.max(1, tonumber(F.getDepotCount(rid)) or 1) end
                        F.consumeDepotItem(rid, n)
                    end)
                end
                if R then
                    if R.resToIns then R.resToIns[rid] = nil end
                    if ins and R.insToRes then R.insToRes[ins] = nil end
                end
                -- Xóa khỏi persist/dump để không bị reinject lại L1..L6
                pcall(function()
                    if F.persistForgetDepotItem then F.persistForgetDepotItem(rid) end
                end)
            end
        end
        pcall(function()
            if F.registerDumpExtraSkin then F.registerDumpExtraSkin(keepItemId) end
            PERSIST.configDepotItems = PERSIST.configDepotItems or {}
            if F.shouldPersistDepotGrant and F.shouldPersistDepotGrant(keepItemId) then
                PERSIST.configDepotItems[keepItemId] = true
            end
        end)
    end)
end

-- Sau scan/upgrade: mỗi (period, branch) chỉ giữ skin level cao nhất trong depot
function FLS.collapseOwnedXSuitLevelsInDepot()
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit or not LogicXSuit.IsXSuit then return end
        local best = {}
        local function consider(res)
            res = tonumber(res)
            if not res or res <= 0 or not LogicXSuit.IsXSuit(res) then return end
            local meta = FLS.resolveXSuitMeta(res)
            if not meta or not meta.period then return end
            local key = tostring(meta.period) .. ":" .. tostring(meta.branchId or 0)
            local prev = best[key]
            if not prev or (tonumber(meta.level) or 1) > (tonumber(prev.level) or 1) then
                best[key] = meta
            end
        end
        for res, on in pairs(PERSIST.configDepotItems or {}) do
            if on then consider(res) end
        end
        for res, on in pairs(_G.KuttaCheatTG_DumpExtraSkins or {}) do
            if on then consider(res) end
        end
        local entity = F.getEntity and F.getEntity()
        if entity and entity._data then
            for i = 1, (entity._DataCount or #entity._data) do
                local d = entity._data[i]
                local res = d and tonumber(d.resID or d.res_id)
                if res and (tonumber(d.count) or 0) > 0 then consider(res) end
            end
        end
        for _, meta in pairs(FLS._xsuitWorkshopUnlocks or {}) do
            if meta and meta.itemId then consider(meta.itemId) end
        end
        for _, meta in pairs(best) do
            FLS.purgeXSuitOtherLevelSkins(meta.period, meta.branchId or 0, meta.itemId)
        end
    end)
end

-- Grand Descent: class() chặn __newindex trên class table → phải patch __inner_impl
-- Instance cache method (EnableLuaClassIndexCache) → phải rawset lên actor đang sống
function FLS.hookXSuitPlatform()
    local path = "GameLua.Activity.Commercialize.Actor.InteractActor.XSuitPlatform"
    local path2 = "GameLua.Activity.Commercialize.Actor.InteractActor.XSuitPlatform"

    local function xsuitBattleOn()
        if FLS.IsEnabled and FLS.IsEnabled() then return true end
        if _G.KuttaVaiConfig and (_G.KuttaVaiConfig.FreeLobbyShop == true or _G.KuttaVaiConfig.ModSkin == true) then return true end
        if FLS._xsuitWorkshopUnlocks and next(FLS._xsuitWorkshopUnlocks) then return true end
        if FLS._xsuitWardrobeBranchPrefer and next(FLS._xsuitWardrobeBranchPrefer) then return true end
        return false
    end

    local function resolveL7ForChar(self, Character, impl)
        local id7 = nil
        pcall(function()
            local real = 0
            local getter = (impl and impl.__Kutta_origGetWear) or (self and self.GetWearingXSuitID)
            if type(getter) == "function" then
                real = getter(self, Character)
            end
            real = tonumber(real) or 0
            if real > 0 then id7 = FLS.resolveXSuitLevel7Id(real) or real end
        end)
        if not id7 or id7 <= 0 then
            for _, meta in pairs(FLS._xsuitWardrobeBranchPrefer or {}) do
                if meta and meta.itemId then
                    id7 = FLS.resolveXSuitLevel7Id(meta.itemId) or tonumber(meta.itemId)
                    if id7 and id7 > 0 then break end
                end
            end
        end
        if not id7 or id7 <= 0 then
            for _, u in pairs(FLS._xsuitWorkshopUnlocks or {}) do
                if u and u.itemId then
                    id7 = FLS.resolveXSuitLevel7Id(u.itemId) or tonumber(u.itemId)
                    if id7 and id7 > 0 then break end
                end
            end
        end
        return tonumber(id7)
    end

    local function playLocalGrandDescent(self, Character, impl)
        local id7 = resolveL7ForChar(self, Character, impl)
        if not id7 or id7 <= 0 then return false end
        local name = ""
        pcall(function()
            if Character and Character.GetPlayerNameSafety then
                name = Character:GetPlayerNameSafety() or ""
            end
        end)
        self.CallerInfoTable = { PlayerName = name, ItemID = id7, Nation = "None" }
        self.CurItemID = id7
        self.NeedShowStatue = true
        -- Gọi impl gốc CallStatue (tránh instance cache cũ)
        local callFn = (impl and impl.CallStatue) or self.CallStatue
        pcall(function() if type(callFn) == "function" then callFn(self) end end)
        pcall(function()
            local tipFn = (impl and impl.MulticastRPC_ShowCallTips) or self.MulticastRPC_ShowCallTips
            if type(tipFn) == "function" then tipFn(self, id7, name) end
        end)
        return true
    end

    local function patchImpl(impl)
        if type(impl) ~= "table" then return false end
        if type(impl.Wearing7StarXSuit) ~= "function" and type(impl.OnClientClickInteractiveButton) ~= "function" then
            return false
        end
        if impl.__Kutta_xsuit_platform then return true end
        impl.__Kutta_xsuit_platform = true

        if type(impl.Wearing7StarXSuit) == "function" and not impl.__Kutta_origWear7 then
            impl.__Kutta_origWear7 = impl.Wearing7StarXSuit
            impl.Wearing7StarXSuit = function(self, Character)
                if xsuitBattleOn() then return true end
                return impl.__Kutta_origWear7(self, Character)
            end
        end

        if type(impl.GetWearingXSuitID) == "function" and not impl.__Kutta_origGetWear then
            impl.__Kutta_origGetWear = impl.GetWearingXSuitID
            impl.GetWearingXSuitID = function(self, Character)
                local real = impl.__Kutta_origGetWear(self, Character)
                if xsuitBattleOn() then
                    real = tonumber(real) or 0
                    if real > 0 then
                        local id7 = FLS.resolveXSuitLevel7Id(real)
                        if id7 then return id7 end
                    end
                    local id7 = resolveL7ForChar(self, Character, impl)
                    if id7 and id7 > 0 then return id7 end
                end
                return real
            end
        end

        if type(impl.OnClientClickInteractiveButton) == "function" and not impl.__Kutta_origClientClick then
            impl.__Kutta_origClientClick = impl.OnClientClickInteractiveButton
            impl.OnClientClickInteractiveButton = function(self, Character, Component)
                if xsuitBattleOn() then
                    playLocalGrandDescent(self, Character, impl)
                    -- false = không gửi server (tránh tip 49553 từ DS)
                    return false
                end
                return impl.__Kutta_origClientClick(self, Character, Component)
            end
        end

        if type(impl.MustCheckResultAfterServerClick) == "function" and not impl.__Kutta_origMustCheck then
            impl.__Kutta_origMustCheck = impl.MustCheckResultAfterServerClick
            impl.MustCheckResultAfterServerClick = function(self, Character, Ret, Component, Flag, Reason)
                if xsuitBattleOn() then
                    playLocalGrandDescent(self, Character, impl)
                    return
                end
                return impl.__Kutta_origMustCheck(self, Character, Ret, Component, Flag, Reason)
            end
        end
        return true
    end

    local function apply(mod)
        if type(mod) ~= "table" then return end
        -- class() forbid __newindex trên class → chỉ patch __inner_impl
        if type(mod.__inner_impl) == "table" then
            patchImpl(mod.__inner_impl)
        end
        -- Một số bản method nằm thẳng trên table
        pcall(function() patchImpl(mod) end)
    end

    local function patchLiveActors()
        -- Không GetAllActorsOfClass(Actor) — rất nặng, gây treo sảnh/equip.
        -- Chỉ đảm bảo __inner_impl đã patch; instance lấy method qua class_index.
        pcall(function()
            local mod = package.loaded[path] or package.loaded[path2]
            if type(mod) == "table" then apply(mod) end
            for name, m in pairs(package.loaded) do
                if type(name) == "string" and string.find(name, "XSuitPlatform", 1, true) and type(m) == "table" then
                    apply(m)
                end
            end
        end)
    end

    -- Chặn tip 49553 (client + UIShowTips từ server)
    pcall(function()
        if FLS._xsuitTip49553Hooked then return end
        FLS._xsuitTip49553Hooked = true
        local tipsPath = "GameLua.Mod.BaseMod.Common.UI.InGameTipsTools"
        local function wrapTips(mod)
            if type(mod) ~= "table" or mod.__Kutta_tip49553 then return end
            mod.__Kutta_tip49553 = true
            if type(mod.BattleNormalTipsByTextID) == "function" then
                local o = mod.BattleNormalTipsByTextID
                mod.BattleNormalTipsByTextID = function(textId, ...)
                    if tonumber(textId) == 49553 and xsuitBattleOn() then return end
                    return o(textId, ...)
                end
            end
            if type(mod.BattleGeneralTip) == "function" then
                local o = mod.BattleGeneralTip
                mod.BattleGeneralTip = function(tipId, ...)
                    if tonumber(tipId) == 49553 and xsuitBattleOn() then return end
                    return o(tipId, ...)
                end
            end
        end
        if package.loaded[tipsPath] then wrapTips(package.loaded[tipsPath]) end
        pcall(function() wrapTips(require(tipsPath)) end)
        if type(Game) == "table" and type(Game.UIShowTips) == "function" and not Game.__Kutta_tip49553 then
            Game.__Kutta_tip49553 = true
            local o = Game.UIShowTips
            Game.UIShowTips = function(playerKey, tipId, ...)
                if tonumber(tipId) == 49553 and xsuitBattleOn() then
                    -- Thay vì tip: thử play Grand Descent trên actor gần nhất
                    pcall(FLS.tryPlayGrandDescentNearPlayer)
                    return
                end
                return o(playerKey, tipId, ...)
            end
        end
    end)

    -- Scan mọi module đã load có Wearing7StarXSuit
    pcall(function()
        for name, mod in pairs(package.loaded) do
            if type(name) == "string" and type(mod) == "table" then
                if string.find(name, "XSuitPlatform", 1, true) then
                    apply(mod)
                else
                    local impl = mod.__inner_impl
                    if type(impl) == "table" and type(impl.Wearing7StarXSuit) == "function" then
                        apply(mod)
                    end
                end
            end
        end
    end)

    pcall(function()
        if package.loaded[path] then apply(package.loaded[path]) end
    end)

    -- Hook require để bắt module khi vào trận
    if not FLS._xsuitRequireHooked then
        FLS._xsuitRequireHooked = true
        local origRequire = _G.require
        _G.require = function(modname, ...)
            local m = origRequire(modname, ...)
            if type(modname) == "string" and string.find(modname, "XSuitPlatform", 1, true) then
                pcall(apply, m)
                pcall(patchLiveActors)
            end
            return m
        end
    end

    pcall(patchLiveActors)

    pcall(function()
        local ticker = require("common.time_ticker")
        if ticker and ticker.AddTimerOnce then
            for _, d in ipairs({ 1, 2, 4, 8, 15 }) do
                ticker.AddTimerOnce(d, function()
                    pcall(function()
                        for name, mod in pairs(package.loaded) do
                            if type(name) == "string" and string.find(name, "XSuitPlatform", 1, true) then
                                apply(mod)
                            end
                        end
                        patchLiveActors()
                    end)
                end)
            end
        end
    end)
end

function FLS.tryPlayGrandDescentNearPlayer()
    if not (FLS.IsEnabled and FLS.IsEnabled()) and not (_G.KuttaVaiConfig and _G.KuttaVaiConfig.ModSkin) then
        if not (FLS._xsuitWardrobeBranchPrefer and next(FLS._xsuitWardrobeBranchPrefer)) then return end
    end
    pcall(function()
        local GameplayData = require("GameLua.GameCore.Data.GameplayData")
        local Character = GameplayData.GetPlayerCharacter and GameplayData.GetPlayerCharacter()
        local GameplayStatics = import("GameplayStatics")
        local ActorClass = import("/Script/Engine.Actor")
        local world = slua_GameFrontendHUD and slua_GameFrontendHUD.GetWorld and slua_GameFrontendHUD:GetWorld()
        if not world or not slua.isValid(Character) then return end
        local arr = GameplayStatics.GetAllActorsOfClass(world, ActorClass, slua.Array(UEnums.EPropertyClass.Object, ActorClass))
        if not arr then return end
        local n = arr.Num and arr:Num() or 0
        for i = 0, n - 1 do
            local a = arr:Get(i)
            if slua.isValid(a) and type(a.CallStatue) == "function" and type(a.Wearing7StarXSuit) == "function" then
                local impl = a.__class and a.__class.__inner_impl
                local id7 = nil
                pcall(function()
                    id7 = FLS.resolveXSuitLevel7Id(a:GetWearingXSuitID(Character))
                end)
                if not id7 then
                    for _, meta in pairs(FLS._xsuitWardrobeBranchPrefer or {}) do
                        id7 = FLS.resolveXSuitLevel7Id(meta.itemId) or meta.itemId
                        break
                    end
                end
                if id7 then
                    local name = Character:GetPlayerNameSafety() or ""
                    a.CallerInfoTable = { PlayerName = name, ItemID = id7, Nation = "None" }
                    a.CurItemID = id7
                    a.NeedShowStatue = true
                    a:CallStatue()
                    return
                end
            end
        end
    end)
end

function FLS.simulateXSuitRiseStar(period, item_id, branch_id)
    if not FLS.IsEnabled() then return false end
    if FLS._risingStar then return false end
    FLS._risingStar = true
    local success = false
    pcall(function()
        period = tonumber(period)
        item_id = tonumber(item_id)
        branch_id = tonumber(branch_id)
        local meta = item_id and FLS.resolveXSuitMeta(item_id) or nil
        if meta then
            period = period or meta.period
            branch_id = branch_id or meta.branchId
        end
        if not period then return end
        branch_id = branch_id or 0

        local curLevel, nextItemId, nextLevel = 0, nil, nil
        local LogicXSuit = nil
        pcall(function()
            LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
            if not LogicXSuit then return end
            curLevel = (LogicXSuit.GetLevelByPeriodSelf and LogicXSuit.GetLevelByPeriodSelf(period, branch_id)) or 0
            if curLevel <= 0 and meta then curLevel = meta.level or 1 end
            if curLevel <= 0 then curLevel = 1 end
            nextLevel = curLevel + 1
            if LogicXSuit.GetItemIDByLevel then
                nextItemId = LogicXSuit.GetItemIDByLevel(period, nextLevel, branch_id)
            end
            if not nextItemId and LogicXSuit.upgradeInfo
                and LogicXSuit.upgradeInfo[period]
                and LogicXSuit.upgradeInfo[period][branch_id]
                and LogicXSuit.upgradeInfo[period][branch_id][nextLevel] then
                nextItemId = LogicXSuit.upgradeInfo[period][branch_id][nextLevel].item_id
            end
        end)
        if not nextItemId or not nextLevel then return end

        -- 1) Skin mới (quiet) + 2) gỡ skin level cũ + 3) unlock local
        -- KHÔNG gọi _origRiseStarRsp (orig gửi get_rise_star_info_req → crash)
        FLS.grantXSuitLevelSkinQuiet(nextItemId)
        FLS.purgeXSuitOtherLevelSkins(period, branch_id, nextItemId)
        pcall(function() if FLS.collapseOwnedXSuitLevelsInDepot then FLS.collapseOwnedXSuitLevelsInDepot() end end)
        local newMeta = {
            itemId = nextItemId,
            period = period,
            branchId = branch_id,
            level = nextLevel,
        }
        FLS.rememberXSuitWorkshopUnlock(newMeta)
        FLS._xsuitWardrobeBranchPrefer = FLS._xsuitWardrobeBranchPrefer or {}
        FLS._xsuitWardrobeBranchPrefer[period] = newMeta
        FLS.applyXSuitWorkshopUnlocks()
        FLS.setXSuitWardrobeBranch(newMeta)

        -- Chặn sync rise_star từ server trong lúc hiện UI thành công
        FLS._blockRiseStarInfoReq = true

        pcall(function()
            if EventSystem and EVENTTYPE_GOLDEN_SUIT and EVENTID_GOLDEN_SUIT_UPGRADE_SUCCESS then
                EventSystem:postEvent(EVENTTYPE_GOLDEN_SUIT, EVENTID_GOLDEN_SUIT_UPGRADE_SUCCESS, nextLevel, period, branch_id)
            end
        end)
        pcall(function()
            if LogicXSuit and LogicXSuit.ShowUpgradeSuccessUI then
                LogicXSuit.ShowUpgradeSuccessUI(nextLevel, period, branch_id)
            end
        end)

        -- Refresh nhẹ sau UI; mở lại sync và merge unlock client
        pcall(function()
            local ticker = require("common.time_ticker")
            if not ticker or not ticker.AddTimerOnce then
                FLS._blockRiseStarInfoReq = false
                return
            end
            ticker.AddTimerOnce(0.35, function()
                pcall(function() if F and F.refreshWardrobe then F.refreshWardrobe() end end)
                pcall(FLS.applyXSuitWorkshopUnlocks)
            end)
            ticker.AddTimerOnce(1.2, function()
                FLS._blockRiseStarInfoReq = false
                pcall(FLS.applyXSuitWorkshopUnlocks)
            end)
        end)
        success = true
    end)
    FLS._risingStar = false
    return success
end

function FLS.xsuitClientOn()
    if FLS.IsEnabled and FLS.IsEnabled() then return true end
    if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModSkin == true then return true end
    return false
end

-- Đổi nhánh (nút đổi dạng): UI gửi resid = L1 nhánh mới → map sang đúng level đang có
function FLS.simulateXSuitBranchSwitch(resid)
    if not FLS.IsEnabled() then return false end
    if FLS._switchingBranch then return true end
    resid = tonumber(resid)
    if not resid or resid <= 0 then return false end
    local meta = FLS.resolveXSuitMeta(resid)
    if not meta then return false end
    FLS._switchingBranch = true
    local ok = false
    pcall(function()
        local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
        if not LogicXSuit then return end
        local period = meta.period
        local nextBranch = meta.branchId or 0

        -- Level nguồn: nhánh đang chọn / đang mặc (không luôn L1)
        local fromBranch = 0
        pcall(function()
            fromBranch = (LogicXSuit.GetWardrobeBranchByPeriod and LogicXSuit.GetWardrobeBranchByPeriod(period)) or 0
        end)
        local fromLevel = 0
        pcall(function()
            fromLevel = tonumber(LogicXSuit.GetLevelByPeriodSelf and LogicXSuit.GetLevelByPeriodSelf(period, fromBranch)) or 0
        end)
        local fromSwitch = nil
        pcall(function()
            fromSwitch = LogicXSuit.GetSwitchLevelByPeriod and LogicXSuit.GetSwitchLevelByPeriod(period, fromBranch)
        end)
        pcall(function()
            if F.findWornInsBySubType then
                local _, wornRes = F.findWornInsBySubType(OUTFIT_SUB, function(r)
                    return LogicXSuit.IsXSuit and LogicXSuit.IsXSuit(r)
                end)
                wornRes = tonumber(wornRes)
                if wornRes and LogicXSuit.GetPeriodByItemId and LogicXSuit.GetPeriodByItemId(wornRes) == period then
                    local wl = tonumber(LogicXSuit.GetLevelByItemId and LogicXSuit.GetLevelByItemId(wornRes)) or 0
                    if wl > fromLevel then fromLevel = wl end
                    local wb = tonumber(LogicXSuit.GetBranchByItemId and LogicXSuit.GetBranchByItemId(wornRes)) or fromBranch
                    local bl = tonumber(LogicXSuit.GetLevelByPeriodSelf and LogicXSuit.GetLevelByPeriodSelf(period, wb)) or 0
                    if bl > fromLevel then fromLevel = bl end
                    if not fromSwitch and LogicXSuit.GetSwitchLevelByPeriod then
                        fromSwitch = LogicXSuit.GetSwitchLevelByPeriod(period, wb)
                    end
                end
            end
        end)
        -- Max level đã unlock trong period (các nhánh đã mở hộp)
        pcall(function()
            for _, u in pairs(FLS._xsuitWorkshopUnlocks or {}) do
                if tonumber(u.period) == period then
                    local lv = tonumber(u.current) or 0
                    if lv > fromLevel then fromLevel = lv end
                end
            end
        end)
        local existLevel = tonumber(LogicXSuit.GetLevelByPeriodSelf and LogicXSuit.GetLevelByPeriodSelf(period, nextBranch)) or 0
        local toLevel = math.max(fromLevel, existLevel, 1)

        local targetItemId = resid
        pcall(function()
            if LogicXSuit.GetItemIDByLevel then
                targetItemId = LogicXSuit.GetItemIDByLevel(period, toLevel, nextBranch) or resid
            end
        end)
        targetItemId = tonumber(targetItemId) or resid

        -- Inject đúng level + gỡ L1 cũ của nhánh mới (tránh kho hiện 2 skin)
        pcall(function() FLS.grantXSuitLevelSkinQuiet(targetItemId) end)
        pcall(function() FLS.purgeXSuitOtherLevelSkins(period, nextBranch, targetItemId) end)
        pcall(function() FLS.ensureXSuitInDepot(targetItemId) end)
        local newMeta = {
            itemId = targetItemId,
            period = period,
            branchId = nextBranch,
            level = toLevel,
        }
        FLS.rememberXSuitWorkshopUnlock(newMeta)
        FLS._xsuitWardrobeBranchPrefer = FLS._xsuitWardrobeBranchPrefer or {}
        FLS._xsuitWardrobeBranchPrefer[period] = newMeta
        FLS.applyXSuitWorkshopUnlocks()

        -- Giữ form Common (1/3/6/7) đang dùng
        if fromSwitch and tonumber(fromSwitch) and tonumber(fromSwitch) > 0 then
            FLS.applySwitchLevelQuiet(period, tonumber(fromSwitch), nextBranch)
        elseif LogicXSuit.GetDefaultSwitchLevelByItemID then
            local sl = LogicXSuit.GetDefaultSwitchLevelByItemID(targetItemId)
            if sl and tonumber(sl) and tonumber(sl) > 0 then
                FLS.applySwitchLevelQuiet(period, tonumber(sl), nextBranch)
            end
        end

        -- Ghi nhánh trước (không event) → putOn → event/UI
        FLS.setXSuitWardrobeBranch(newMeta, { skipEvent = true })

        local ins = nil
        pcall(function()
            local entity = F.getEntity and F.getEntity()
            if entity and F.firstInsForRes then ins = F.firstInsForRes(entity, targetItemId) end
            if not ins and R and R.resToIns then ins = R.resToIns[targetItemId] end
            if not ins then
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local d = wd and wd.GetHallDepotItemDataByResID and wd:GetHallDepotItemDataByResID(targetItemId)
                if d then ins = tonumber(d.insID or d.ins_id or d.instid) end
            end
        end)
        if ins and F.putOnOutfit then
            F.putOnOutfit(ins)
        end

        if EventSystem and EVENTTYPE_GOLDEN_SUIT and EVENTID_GOLDEN_SUIT_UPDATE_DRESS_BRANCH then
            EventSystem:postEvent(EVENTTYPE_GOLDEN_SUIT, EVENTID_GOLDEN_SUIT_UPDATE_DRESS_BRANCH,
                period, nextBranch, targetItemId)
        end
        FLS.refreshXSuitWardrobeWearFlags(period, targetItemId, ins)

        -- Refresh nhẹ dấu tích sau 1 frame (tránh race OnUpdatePutOnData)
        pcall(function()
            local ticker = require("common.time_ticker")
            if ticker and ticker.AddTimerOnce then
                ticker.AddTimerOnce(0.05, function()
                    FLS.refreshXSuitWardrobeWearFlags(period, targetItemId, ins)
                end)
            end
        end)
        ok = true
    end)
    FLS._switchingBranch = false
    return ok
end

function FLS.simulateXSuitBranchBoxOpen(instid, target_item_id, source)
    if not FLS.IsEnabled() then return false end
    instid = tonumber(instid)
    target_item_id = tonumber(target_item_id)
    source = tonumber(source) or 0
    if not target_item_id or target_item_id <= 0 then return false end
    if FLS._openingBranchBox then return true end
    FLS._openingBranchBox = true

    local ok = false
    pcall(function()
        local boxResId = nil
        pcall(function()
            if instid and instid > 0 then
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local item = wd and wd.GetHallDepotItemDataByInsID and wd:GetHallDepotItemDataByInsID(instid)
                if item then boxResId = tonumber(item.res_id or item.resID) end
            end
        end)
        if not boxResId and instid and F.getEntity then
            pcall(function()
                local entity = F.getEntity()
                local d = entity and entity.GetDataByInsID and entity:GetDataByInsID(instid)
                if d then boxResId = tonumber(d.resID or d.res_id) end
            end)
        end

        -- Inject skin (quiet) — không phụ thuộc ensure trả false → tránh gửi server lỗi
        pcall(function() FLS.grantXSuitLevelSkinQuiet(target_item_id) end)
        pcall(function() FLS.grantResId(target_item_id, 1) end)
        pcall(function() FLS.ensureXSuitInDepot(target_item_id) end)
        pcall(function() if F.registerDumpExtraSkin then F.registerDumpExtraSkin(target_item_id) end end)

        if boxResId and boxResId ~= target_item_id and F.consumeDepotItem then
            pcall(function() F.consumeDepotItem(boxResId, 1) end)
        end

        -- Unlock + nhánh tủ đồ (quiet, không forceWardrobeDepotRefresh)
        local meta = FLS.resolveXSuitMeta(target_item_id)
        pcall(function()
            if meta then
                FLS.rememberXSuitWorkshopUnlock(meta)
                FLS._xsuitWardrobeBranchPrefer = FLS._xsuitWardrobeBranchPrefer or {}
                FLS._xsuitWardrobeBranchPrefer[meta.period] = meta
                FLS.applyXSuitWorkshopUnlocks()
                FLS.setXSuitWardrobeBranch(meta)
                -- Giữ level hộp (thường L1); tự nâng trong workshop
                FLS.grantXSuitUpgradeMaterials(meta.period, meta.branchId or 0)
            else
                FLS.unlockXSuitWorkshopForItem(target_item_id)
            end
        end)

        -- Chặn sync server trong lúc mở hộp (orig rsp hay gọi get_rise_star / branch_switch)
        FLS._blockRiseStarInfoReq = true
        FLS._blockBranchSwitchInfoReq = true

        local result_info = {
            resid = target_item_id,
            itemid = target_item_id,
            item_id = target_item_id,
            count = 1,
            source = source,
            instid = instid or 0,
            item_list = {
                { resid = target_item_id, itemid = target_item_id, count = 1, valid_hours = 0 }
            }
        }

        -- Không gọi full orig rsp (kéo 2 req server → lỗi/ghi đè). Chỉ event + UI nhận.
        pcall(function()
            if EventSystem and EVENTTYPE_XSUIT and EVENTID_XSUIT_BRANCH_BOX_OPEN then
                EventSystem:postEvent(EVENTTYPE_XSUIT, EVENTID_XSUIT_BRANCH_BOX_OPEN, result_info)
            end
        end)
        pcall(function()
            local Logic_CommonItemGet = require("client.slua.logic.common.CommonItemGet.Logic_CommonItemGet")
            if Logic_CommonItemGet and Logic_CommonItemGet.ShowPanel_DefaultStyle then
                Logic_CommonItemGet.ShowPanel_DefaultStyle({
                    { res_id = target_item_id, count = 1, valid_hours = 0 }
                })
            end
        end)

        -- Refresh nhẹ 1 lần, rồi mở lại sync + giữ unlock client
        pcall(function()
            local ticker = require("common.time_ticker")
            local function finish()
                pcall(function() FLS.ensureXSuitInDepot(target_item_id) end)
                pcall(function() FLS.applyXSuitWorkshopUnlocks() end)
                if meta then pcall(function() FLS.setXSuitWardrobeBranch(meta) end) end
                pcall(function() if F and F.refreshWardrobe then F.refreshWardrobe() end end)
            end
            if ticker and ticker.AddTimerOnce then
                ticker.AddTimerOnce(0.25, finish)
                ticker.AddTimerOnce(1.0, function()
                    FLS._blockRiseStarInfoReq = false
                    FLS._blockBranchSwitchInfoReq = false
                    finish()
                end)
            else
                finish()
                FLS._blockRiseStarInfoReq = false
                FLS._blockBranchSwitchInfoReq = false
            end
        end)
        ok = true
    end)

    FLS._openingBranchBox = false
    return ok
end

function FLS.findExchangeOffer(exchangeActId, itemId, req_params)
    exchangeActId = tonumber(exchangeActId)
    itemId = tonumber(itemId)
    if not exchangeActId or not itemId then return nil end
    local posId = req_params and (req_params.pos_id or req_params.pos)
    local found = nil
    local function matchList(list)
        if type(list) ~= "table" then return end
        for _, v in pairs(list) do
            if type(v) == "table" and tonumber(v.itemId) == itemId then
                if not posId or tonumber(v.pos) == tonumber(posId) then
                    found = v
                    return
                end
                if not found then found = v end
            end
        end
    end
    pcall(function()
        local lex = require("client.slua.logic.lobby_activity.lucky_exchange.logic_lucky_exchange")
        matchList(lex and (lex.GetExchangeDataList and lex.GetExchangeDataList(exchangeActId) or lex.ExchangeItemList[exchangeActId]))
    end)
    if found then return found end
    pcall(function()
        local lb = require("client.slua.logic.lobby_activity.logic_luckyback_activity")
        if not lb then return end
        matchList(lb.exchangeInfo and lb.exchangeInfo[exchangeActId])
        if not found then matchList(lb.exchangeItemList) end
    end)
    return found
end

function FLS.simulateActivityExchange(exchangeActId, itemId, times, req_params)
    if not FLS.IsEnabled() then return false end
    if type(F) ~= "table" or not F.consumeDepotItem or not F.getDepotCount then return false end
    exchangeActId = tonumber(exchangeActId)
    itemId = tonumber(itemId)
    times = tonumber(times) or 1
    if not exchangeActId or not itemId or times < 1 then return false end
    local offer = FLS.findExchangeOffer(exchangeActId, itemId, req_params)
    if not offer then return false end
    local needId = tonumber(offer.needItemId)
    local unitCost = tonumber(offer.finalPrice) or tonumber(offer.needItemNum) or 0
    local needNum = unitCost * times
    if not needId or needNum < 1 then return false end
    if F.getDepotCount(needId) < needNum then return false end
    if not F.consumeDepotItem(needId, needNum) then return false end
    local awardNum = (tonumber(offer.itemNum) or 1) * times
    local validHours = tonumber(offer.validTime) or 0
    if not FLS.grantResId(itemId, awardNum) then
        -- rollback consume best-effort
        pcall(function() F.grantDepotItem(needId, needNum, { markNew = false, count = needNum }) end)
        return false
    end
    local key = string.format("%s_%s_%s", tostring(itemId), tostring(offer.itemNum or 1), tostring(validHours))
    local prev = tonumber(offer.hasExchangeCount) or 0
    local myData = { new_limit_exchange_info = { [key] = prev + times } }
    local award_info = {
        [1] = {
            resid = itemId,
            count = awardNum,
            valid_hours = validHours,
            expire_ts = 0,
        }
    }
    pcall(function()
        local LBH = require("client.network.Protocol.LuckybackHandler")
        if LBH and LBH.on_do_exchange_by_activity_id_rsp then
            LBH.on_do_exchange_by_activity_id_rsp(0, myData, award_info, exchangeActId)
        end
    end)
    pcall(function() if F.refreshWardrobe then F.refreshWardrobe() end end)
    return true
end

function FLS.simulateCharacterExchange(itemId)
    if not FLS.IsEnabled() then return false end
    if type(F) ~= "table" or not F.consumeDepotItem or not F.getDepotCount then return false end
    itemId = tonumber(itemId)
    if not itemId then return false end
    local consume = nil
    pcall(function()
        local sod = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.supply_optional_data)
        local data = sod and sod.rawExchangeData and sod.rawExchangeData[itemId]
        if data and type(data.consume_items) == "table" then consume = data.consume_items end
    end)
    if not consume then return false end
    local needList = {}
    for cid, need in pairs(consume) do
        cid = tonumber(cid)
        need = tonumber(need) or 0
        if cid and need > 0 then
            if F.getDepotCount(cid) < need then return false end
            needList[#needList + 1] = { cid, need }
        end
    end
    if #needList < 1 then return false end
    for _, row in ipairs(needList) do
        if not F.consumeDepotItem(row[1], row[2]) then return false end
    end
    if not FLS.grantResId(itemId, 1) then
        for _, row in ipairs(needList) do
            pcall(function() F.grantDepotItem(row[1], row[2], { markNew = false, count = row[2] }) end)
        end
        return false
    end
    pcall(function()
        local net = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.NewCharacterNetSystem)
        if net and net.on_character_exchange_rsp then
            net:on_character_exchange_rsp(itemId)
            return
        end
        local Logic_CommonItemGet = require("client.slua.logic.common.CommonItemGet.Logic_CommonItemGet")
        Logic_CommonItemGet.ShowPanel_DefaultStyle({ { res_id = itemId, count = 1 } })
        if EventSystem and EVENTTYPE_CHARACTER and EVENTID_CHARACTER_EXCHANGE_SUC then
            EventSystem:postEvent(EVENTTYPE_CHARACTER, EVENTID_CHARACTER_EXCHANGE_SUC, itemId)
        end
    end)
    pcall(function() if F.refreshWardrobe then F.refreshWardrobe() end end)
    return true
end

FLS._optionalChestSessions = FLS._optionalChestSessions or {}

function FLS.indexOptionalDropId(byDropId, did, item)
    if type(byDropId) ~= "table" or type(item) ~= "table" then return end
    if did == nil then
        did = item.drop_image_id or item.DropImageId or item.pos_id or item.resid or item.res_id
    end
    if did == nil then return end
    byDropId[did] = item
    local n = tonumber(did)
    if n then byDropId[n] = item end
    byDropId[tostring(did)] = item
end

function FLS.normalizeOptionalAddList(addlist)
    if type(addlist) ~= "table" then return nil end
    local out = {}
    for _, item in pairs(addlist) do
        if type(item) == "table" then
            local resid = tonumber(item.resid or item.res_id or item.DropItemID or item.item_id)
            if resid and resid > 0 then
                local dropId = item.drop_image_id or item.DropImageId or item.pos_id or resid
                out[#out + 1] = {
                    resid = resid,
                    count = tonumber(item.count or item.DropItemNum) or 1,
                    valid_hours = tonumber(item.valid_hours or item.DropItemTime) or 0,
                    drop_image_id = dropId,
                    display_sort = tonumber(item.display_sort or item.DropItemSort) or 0
                }
            end
        end
    end
    return #out > 0 and out or nil
end

function FLS.cacheOptionalChestSession(params, addlist)
    if type(params) ~= "table" then return end
    addlist = FLS.normalizeOptionalAddList(addlist)
    if not addlist then return end
    FLS._optionalChestSessions = FLS._optionalChestSessions or {}
    local shopId = tonumber(params.shop_id) or tonumber(params.chest_id) or 0
    local byDropId = {}
    for _, item in ipairs(addlist) do
        FLS.indexOptionalDropId(byDropId, nil, item)
        FLS.indexOptionalDropId(byDropId, item.resid, item)
    end
    local session = { params = params, addlist = addlist, byDropId = byDropId }
    FLS._optionalChestSessions[tostring(shopId)] = session
    local chestId = tonumber(params.chest_id)
    if chestId and chestId > 0 then
        FLS._optionalChestSessions[tostring(chestId)] = session
    end
    if tonumber(params.shop_id) and tonumber(params.shop_id) > 0 then
        FLS._optionalChestSessions[tostring(params.shop_id)] = session
    end
end

function FLS.getOptionalChestSession(params)
    if type(params) ~= "table" then return nil end
    local sessions = FLS._optionalChestSessions or {}
    local shopId = tonumber(params.shop_id)
    local chestId = tonumber(params.chest_id)
    return (shopId and sessions[tostring(shopId)])
        or (chestId and sessions[tostring(chestId)])
        or sessions[tostring(params.shop_id or "")]
        or sessions[tostring(params.chest_id or "")]
end

function FLS.buildCustomSelectChestAddList(chestId)
    chestId = tonumber(chestId)
    if not chestId then return nil end
    local addlist = nil
    pcall(function()
        local bdt = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataChestTable)
        local datas = bdt and bdt.GetCacheData and bdt:GetCacheData(chestId)
        if type(datas) == "table" and next(datas) then
            addlist = FLS.normalizeOptionalAddList(datas)
            if not addlist then
                local tmp = {}
                for _, v in pairs(datas) do
                    if type(v) == "table" then
                        local resid = tonumber(v.DropItemID or v.resid)
                        if resid and resid > 0 then
                            tmp[#tmp + 1] = {
                                drop_image_id = v.DropImageId or v.drop_image_id or resid,
                                resid = resid,
                                valid_hours = tonumber(v.DropItemTime) or 0,
                                count = tonumber(v.DropItemNum) or 1,
                                display_sort = tonumber(v.DropItemSort) or 0
                            }
                        end
                    end
                end
                addlist = #tmp > 0 and tmp or nil
            end
        end
    end)
    if addlist and #addlist > 0 then return addlist end
    pcall(function()
        local mod = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.store_detail_data_select_chest)
        if mod and mod.GetProductItemData and mod.GetSelectBoxItemId
            and tonumber(mod:GetSelectBoxItemId()) == chestId then
            local product = mod:GetProductItemData()
            if type(product) == "table" and next(product) then
                local tmp = {}
                for _, v in pairs(product) do
                    if type(v) == "table" and tonumber(v.DropItemID) then
                        local resid = tonumber(v.DropItemID)
                        tmp[#tmp + 1] = {
                            drop_image_id = v.DropImageId or v.drop_image_id or resid,
                            resid = resid,
                            valid_hours = 0,
                            count = tonumber(v.DropItemNum) or 1,
                            display_sort = tonumber(v.DropItemSort) or 0
                        }
                    end
                end
                addlist = #tmp > 0 and tmp or nil
            end
        end
    end)
    return (addlist and #addlist > 0) and addlist or nil
end

function FLS.isCustomSelectChest(resId)
    resId = tonumber(resId)
    if not resId then return false end
    local ok = false
    pcall(function()
        local Logic_DetailUtils = require("client.slua.logic.common.Logic_DetailUtils")
        if Logic_DetailUtils and Logic_DetailUtils.CheckIfCustomSelectChest then
            ok = Logic_DetailUtils.CheckIfCustomSelectChest(resId) == true
        end
    end)
    if ok then return true end
    pcall(function()
        local cfg = CDataTable.GetTableData("Item", resId)
        -- Starter_Pack + CustomSelectChest (thường ItemType=36 / ItemSubType tương ứng)
        -- ENUM_ITEM_TYPE.Starter_Pack(15) + ENUM_ITEM_SUBTYPE.CustomSelectChest(1506)
        if cfg and tonumber(cfg.ItemType) == 15 and tonumber(cfg.ItemSubType) == 1506 then
            ok = true
        end
    end)
    return ok
end

function FLS.openCustomSelectChestUI(chestId, cnt)
    if not FLS.IsEnabled() then return false end
    chestId = tonumber(chestId)
    cnt = tonumber(cnt) or 1
    if not chestId or cnt < 1 then return false end
    local opened = false
    local function show(chestID, datas)
        local list = FLS.normalizeOptionalAddList(datas) or FLS.buildCustomSelectChestAddList(chestID)
        if not list or #list < 1 then return end
        local params = { chest_id = chestID, cnt = cnt }
        FLS.cacheOptionalChestSession(params, list)
        pcall(function()
            UIManager.ShowUI(UIManager.UI_Config.select_optional_chest, {
                addlist = list,
                openNum = cnt,
                chest_id = chestID
            })
            opened = true
        end)
    end
    pcall(function()
        local bdt = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataChestTable)
        if not bdt then return end
        local cached = bdt.GetCacheData and bdt:GetCacheData(chestId)
        if type(cached) == "table" and next(cached) then
            show(chestId, cached)
            return
        end
        if bdt.GetOrReqData then
            opened = true
            bdt:GetOrReqData(chestId, function(id, datas)
                show(id or chestId, datas)
            end)
        end
    end)
    return opened
end

function FLS.resolveOptionalPick(byDropId, addlist, dropId)
    if type(byDropId) ~= "table" then return nil end
    local src = byDropId[dropId] or byDropId[tonumber(dropId)] or byDropId[tostring(dropId)]
    if src then return src end
    local n = tonumber(dropId)
    if n and type(addlist) == "table" then
        for _, item in ipairs(addlist) do
            if type(item) == "table" then
                local resid = tonumber(item.resid or item.res_id)
                local did = item.drop_image_id or item.DropImageId
                if resid == n or tonumber(did) == n then return item end
            end
        end
    end
    return nil
end

function FLS.buildOptionalChestAddList(shopId)
    shopId = tonumber(shopId)
    if not shopId then return nil end
    local dropList = FLS.getSupplyDropList(shopId, nil)
    if type(dropList) ~= "table" or not next(dropList) then return nil end
    local okSC, StoreConst = pcall(require, "client.logic.store.store_const")
    local addlist, seen = {}, {}
    local function pushEntry(v, allowAll)
        if type(v) ~= "table" then return end
        local resid = tonumber(v.DropItemID)
            or (StoreConst and tonumber(v[StoreConst.label_drop_index_item_id]))
            or tonumber(v.resid) or tonumber(v.item_id)
        if not resid or resid <= 0 or seen[resid] then return end
        local isOpt = v.is_optional
        if StoreConst then isOpt = isOpt or v[StoreConst.label_drop_index_is_optional] end
        local dropType = tonumber(v.DropType)
        if not allowAll and isOpt ~= 1 and dropType ~= 9 then return end
        seen[resid] = true
        local dropId = (StoreConst and v[StoreConst.label_drop_index_drop_image_id])
            or v.drop_image_id or v.DropImageId or resid
        addlist[#addlist + 1] = {
            resid = resid,
            count = tonumber(v.DropItemNum)
                or (StoreConst and tonumber(v[StoreConst.label_drop_index_item_num]))
                or 1,
            valid_hours = tonumber(v.item_time_limit)
                or (StoreConst and tonumber(v[StoreConst.label_drop_index_item_time]))
                or 0,
            drop_image_id = dropId,
            display_sort = tonumber(v.DropItemSort)
                or (StoreConst and tonumber(v[StoreConst.label_drop_index_item_sort]))
                or 0
        }
    end
    for _, v in pairs(dropList) do pushEntry(v, false) end
    if #addlist < 1 then
        for _, v in pairs(dropList) do pushEntry(v, true) end
    end
    return #addlist > 0 and addlist or nil
end

function FLS.adjustOptionalBuyCnt(shopId, openCnt)
    shopId = tonumber(shopId)
    openCnt = tonumber(openCnt) or 1
    if not shopId or openCnt < 1 then return end
    pcall(function()
        local StoreConst = require("client.logic.store.store_const")
        local tab = StoreConst.supply_data and StoreConst.supply_data[shopId]
        if not tab then return end
        local optCnt = tonumber(tab[StoreConst.label_shop_index_optional_cnt_type]) or 0
        if optCnt <= 0 then return end
        local buyCnt = tonumber(tab[StoreConst.label_shop_index_buy_cnt_type]) or 0
        local newCnt = math.max(0, buyCnt - optCnt * openCnt)
        tab[StoreConst.label_shop_index_buy_cnt_type] = newCnt
        local OCH = require("client.network.Protocol.OptionalChestHandler")
        if OCH and OCH.on_optional_chest_sync_buy_cnt then
            OCH.on_optional_chest_sync_buy_cnt(shopId, newCnt)
        end
    end)
end

function FLS.bumpOptionalBuyCnt(shopId, openCnt)
    shopId = tonumber(shopId)
    openCnt = tonumber(openCnt) or 1
    if not shopId or openCnt < 1 then return end
    pcall(function()
        local StoreConst = require("client.logic.store.store_const")
        local tab = StoreConst.supply_data and StoreConst.supply_data[shopId]
        if not tab then return end
        local optCnt = tonumber(tab[StoreConst.label_shop_index_optional_cnt_type]) or 0
        if optCnt <= 0 then return end
        local buyCnt = tonumber(tab[StoreConst.label_shop_index_buy_cnt_type]) or 0
        local newCnt = buyCnt + openCnt
        tab[StoreConst.label_shop_index_buy_cnt_type] = newCnt
        local OCH = require("client.network.Protocol.OptionalChestHandler")
        if OCH and OCH.on_optional_chest_sync_buy_cnt then
            OCH.on_optional_chest_sync_buy_cnt(shopId, newCnt)
        end
    end)
end

function FLS.simulateOpenOptionalChest(shop_id, cnt)
    if not FLS.IsEnabled() then return false end
    shop_id = tonumber(shop_id)
    cnt = tonumber(cnt) or 1
    if not shop_id or cnt < 1 then return false end
    local addlist = FLS.buildOptionalChestAddList(shop_id)
    if not addlist or #addlist < 1 then return false end
    local chest_id = shop_id
    pcall(function()
        local tab = FLS.findSupplyTabEntry(shop_id, nil, true)
        local StoreConst = require("client.logic.store.store_const")
        if tab then
            chest_id = tab[StoreConst.label_shop_index_item_id_box]
                or tab[StoreConst.label_shop_index_id_box]
                or shop_id
        end
    end)
    local params = { shop_id = shop_id, chest_id = chest_id, cnt = cnt }
    FLS.cacheOptionalChestSession(params, addlist)
    FLS.adjustOptionalBuyCnt(shop_id, cnt)
    pcall(function()
        local OCH = require("client.network.Protocol.OptionalChestHandler")
        if OCH and OCH.on_optional_chest_show_panel then
            OCH.on_optional_chest_show_panel(params, addlist)
        end
    end)
    return true
end

function FLS.simulateOptionalChestSelect(params)
    if not FLS.IsEnabled() or type(params) ~= "table" then return false end
    if type(params.selected) ~= "table" or not next(params.selected) then return false end
    local session = FLS.getOptionalChestSession(params)
    local byDropId = session and session.byDropId or {}
    local sessionAddlist = session and session.addlist
    if not next(byDropId) then
        local shopId = tonumber(params.shop_id)
        local chestId = tonumber(params.chest_id)
        local addlist = (chestId and FLS.buildCustomSelectChestAddList(chestId))
            or (shopId and FLS.buildOptionalChestAddList(shopId))
            or (chestId and FLS.buildOptionalChestAddList(chestId))
        if addlist and #addlist > 0 then
            FLS.cacheOptionalChestSession(params, addlist)
            session = FLS.getOptionalChestSession(params)
            byDropId = session and session.byDropId or {}
            sessionAddlist = session and session.addlist
        end
    end
    local addlist, decompose_list = {}, {}
    for dropId, pickCount in pairs(params.selected) do
        pickCount = tonumber(pickCount) or 0
        if pickCount > 0 then
            local src = FLS.resolveOptionalPick(byDropId, sessionAddlist, dropId)
            local resid = src and tonumber(src.resid or src.res_id) or tonumber(dropId)
            if (not resid or resid <= 0) and type(sessionAddlist) == "table" then
                for _, it in pairs(sessionAddlist) do
                    if type(it) == "table" and tonumber(it.resid or it.res_id) then
                        resid = tonumber(it.resid or it.res_id)
                        src = it
                        break
                    end
                end
            end
            if resid and resid > 0 then
                local perCnt = tonumber(src and src.count) or 1
                local totalCnt = perCnt * pickCount
                local hadBefore = FLS.hadPermanentItemBefore(resid)
                local granted = FLS.grantResId(resid, totalCnt)
                if not granted and hadBefore then granted = true end
                if granted then
                    if hadBefore then
                        decompose_list[#decompose_list + 1] = { resid = resid, count = totalCnt }
                    end
                    addlist[#addlist + 1] = {
                        resid = resid,
                        count = totalCnt,
                        valid_hours = tonumber(src and src.valid_hours) or 0
                    }
                end
            end
        end
    end
    if #addlist < 1 then return false end
    local chestId = tonumber(params.chest_id)
    local shopId = tonumber(params.shop_id)
    local openCnt = tonumber(params.cnt) or 1
    if chestId and (not shopId or shopId <= 0) and F.consumeDepotItem then
        if F.getDepotCount and F.getDepotCount(chestId) >= openCnt then
            F.consumeDepotItem(chestId, openCnt)
        end
    elseif shopId and shopId > 0 then
        FLS.adjustOptionalBuyCnt(shopId, openCnt)
    end
    pcall(function()
        if FLS._origOptChestSelectRsp then
            FLS._origOptChestSelectRsp(0, params, addlist, decompose_list)
        else
            local OCH = require("client.network.Protocol.OptionalChestHandler")
            if OCH and OCH.on_optional_chest_select_rsp then
                OCH.on_optional_chest_select_rsp(0, params, addlist, decompose_list)
            end
        end
    end)
    pcall(function() if F.refreshWardrobe then F.refreshWardrobe() end end)
    return true
end

function FLS.simulateMallBatch(list)
    if type(list) ~= "table" then return false end
    local rewards = {}
    local granted = false
    for _, v in ipairs(list) do
        local resId = v.id or v.item_id or v.itemId
        local cnt = v.count or v.num or 1
        if resId and FLS.grantResId(resId, cnt) then
            granted = true
            table.insert(rewards, FLS.buildReward(resId, cnt, v.time_limit or 0))
        end
    end
    if granted then
        FLS.showRewards(rewards)
        pcall(function()
            EventSystem:postEvent(EVENTTYPE_MALL, EVENTID_MALL_BUY_RESULT, { true, list })
        end)
        FLS.pendingMallBatch = nil
    end
    return granted
end

function FLS.EnsureHooks()
    local hooked = false
    local okSU, StoreUtils = pcall(require, "client.slua.logic.store.utils.store_utils")
    local okMall, MallSystem = pcall(require, "client.logic.mall.logic_mall")
    local okPay, CommonPayBoxMgr = pcall(require, "client.slua.logic.common.Payclass.logic_common_pay_box")
    local okMgr, store_supply_manager = pcall(function()
        return ModuleManager.GetModule(ModuleManager.CommonModuleConfig.store_supply_manager)
    end)

    if okSU and StoreUtils then
        if StoreUtils.CheckMoney and not FLS._origCheckMoney then
            FLS._origCheckMoney = StoreUtils.CheckMoney
            StoreUtils.CheckMoney = function(callback, priceList, couponDiscount)
                if FLS.IsEnabled() then
                    if type(callback) == "function" then callback() end
                    return true
                end
                return FLS._origCheckMoney(callback, priceList, couponDiscount)
            end
        end

        if StoreUtils.CheckMoneyIsEnough and not FLS._origCheckMoneyIsEnough then
            FLS._origCheckMoneyIsEnough = StoreUtils.CheckMoneyIsEnough
            StoreUtils.CheckMoneyIsEnough = function(money_type, money_price, callback)
                if FLS.IsEnabled() then
                    local enough = FLS.checkMoney(money_type, money_price)
                    if type(callback) == "function" then callback(enough) end
                    return
                end
                return FLS._origCheckMoneyIsEnough(money_type, money_price, callback)
            end
        end

        if StoreUtils.NoEnoughUCAndGoCharge and not FLS._origNoEnoughUC then
            FLS._origNoEnoughUC = StoreUtils.NoEnoughUCAndGoCharge
            StoreUtils.NoEnoughUCAndGoCharge = function()
                if FLS.IsEnabled() then return end
                return FLS._origNoEnoughUC()
            end
        end
        hooked = true
    end

    if okMall and MallSystem then
        if MallSystem.IsMoneyEnough and not FLS._origMallIsEnough then
            FLS._origMallIsEnough = MallSystem.IsMoneyEnough
            MallSystem.IsMoneyEnough = function(money_type, money_price)
                if FLS.IsEnabled() then return FLS.checkMoney(money_type, money_price) end
                return FLS._origMallIsEnough(money_type, money_price)
            end
        end
        if MallSystem.CheckMoneyIsEnough and not FLS._origMallCheck then
            FLS._origMallCheck = MallSystem.CheckMoneyIsEnough
            MallSystem.CheckMoneyIsEnough = function(money_type, money_price, callback)
                if FLS.IsEnabled() then
                    local enough = FLS.checkMoney(money_type, money_price)
                    if type(callback) == "function" then callback(enough) end
                    return
                end
                return FLS._origMallCheck(money_type, money_price, callback)
            end
        end
        if MallSystem.BatchBuyReq and not FLS._origMallBatchReq then
            FLS._origMallBatchReq = MallSystem.BatchBuyReq
            MallSystem.BatchBuyReq = function(list, curVersion, voucher)
                if FLS.IsEnabled() then FLS.pendingMallBatch = list end
                return FLS._origMallBatchReq(list, curVersion, voucher)
            end
        end
        if MallSystem.BatchBuyRsp and not FLS._origMallBatchRsp then
            FLS._origMallBatchRsp = MallSystem.BatchBuyRsp
            MallSystem.BatchBuyRsp = function(res, itemList)
                if FLS.IsEnabled() and res ~= NetErrorCode_NONE then
                    if res == 9910225 or FLS.isMoneyError(res) then
                        if FLS.simulateMallBatch(FLS.pendingMallBatch or itemList) then return end
                    end
                end
                return FLS._origMallBatchRsp(res, itemList)
            end
        end
        hooked = true
    end

    if okPay and CommonPayBoxMgr and CommonPayBoxMgr.ShowUcRechargeMsg and not FLS._origShowUc then
        FLS._origShowUc = CommonPayBoxMgr.ShowUcRechargeMsg
        CommonPayBoxMgr.ShowUcRechargeMsg = function(...)
            if FLS.IsEnabled() then return end
            return FLS._origShowUc(...)
        end
        hooked = true
    end

    pcall(function()
        if DataMgr and DataMgr.IsMoneyEnough and not FLS._origDmMoney then
            FLS._origDmMoney = DataMgr.IsMoneyEnough
            DataMgr.IsMoneyEnough = function(money_type, money_price)
                if FLS.IsEnabled() then return FLS.checkMoney(money_type, money_price) end
                return FLS._origDmMoney(money_type, money_price)
            end
            hooked = true
        end
    end)

    pcall(function()
        local okNM, NetManager = pcall(require, "client.network.comm.NetManager")
        if okNM and NetManager and NetManager.SendPkg and not FLS._origSendPkg then
            FLS._origSendPkg = NetManager.SendPkg
            NetManager.SendPkg = function(hash, ...)
                if hash == 2136611687 and type((...)) == "table" then
                    FLS.pendingShopBuy = ...
                end
                if FLS.UnlimitedCashOn() and hash == 2136611687 then
                    if _G.UnlimitedCash and _G.UnlimitedCash.ApplyNow then
                        _G.UnlimitedCash.ApplyNow(true)
