                end
            end
            -- Chặn get_rise_star_info ngay sau nâng / mở hộp client
            if XSuitHandler.send_get_rise_star_info_req and not FLS._origSendGetRiseStarInfo then
                FLS._origSendGetRiseStarInfo = XSuitHandler.send_get_rise_star_info_req
