                    end
                    local ret = FLS._origBranchSwitchRsp(err_code, resid, ext_info)
                    if FLS.IsEnabled() then pcall(FLS.applyXSuitWorkshopUnlocks) end
                    return ret
                end
            end
            -- UI nguyên liệu: đăng ký count ảo (không inject) + ép bUpgrade
            pcall(function()
                local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                if LogicXSuit and LogicXSuit.BuildMaterialInfo and not FLS._origBuildMaterialInfo then
                    FLS._origBuildMaterialInfo = LogicXSuit.BuildMaterialInfo
                    LogicXSuit.BuildMaterialInfo = function(period, branchId, nextLevel, featureIndex, state, bGlide)
                        if FLS.IsEnabled() then
                            pcall(FLS.grantXSuitUpgradeMaterials, period, branchId)
                        end
                        local info = FLS._origBuildMaterialInfo(period, branchId, nextLevel, featureIndex, state, bGlide)
                        if FLS.IsEnabled() and type(info) == "table" then
                            info.bUpgrade = true
                            info.bCanMakeUp = true
                            info.bNeedMakeUp = false
                            info.needCurrency = 0
                            if type(info.materialList) == "table" then
                                for _, m in pairs(info.materialList) do
                                    if type(m) == "table" then
                                        local need = tonumber(m.needCount) or 1
                                        m.count = math.max(tonumber(m.count) or 0, need, FLS.XSUIT_MAT_VALUE or 999999999)
                                    end
                                end
                            end
                        end
                        return info
                    end
                end
                -- GetDrawCurrencyCount ảo
                local actOk, act = pcall(function()
                    return ModuleManager.GetModule(ModuleManager.JumpModuleConfig.logic_xsuit_activity)
                end)
                if actOk and act and act.GetDrawCurrencyCount and not act.__Kutta_xsuit_draw_count then
                    act.__Kutta_xsuit_draw_count = act.GetDrawCurrencyCount
                    act.GetDrawCurrencyCount = function(self, ...)
                        if FLS.IsEnabled() then
                            local cid = self.GetDrawCurrencyID and self:GetDrawCurrencyID()
                            if cid then FLS.registerXSuitVirtualMat(cid) end
                            return FLS.XSUIT_MAT_VALUE or 999999999
                        end
                        return act.__Kutta_xsuit_draw_count(self, ...)
