                end
            end)
            -- Nâng level XSuit workshop (rise_star) — chỉ simulate client, không gửi server
            if XSuitHandler.send_rise_star_req and not FLS._origSendRiseStar then
                FLS._origSendRiseStar = XSuitHandler.send_rise_star_req
                XSuitHandler.send_rise_star_req = function(id, item_id, branch_id)
                    FLS._pendingXSuitRiseStar = { id, item_id, branch_id }
