            if XSuitHandler.on_rise_star_rsp and not FLS._origRiseStarRsp then
                FLS._origRiseStarRsp = XSuitHandler.on_rise_star_rsp
                XSuitHandler.on_rise_star_rsp = function(err_code, cur_level, period, branch_id)
                    -- Đang simulate local → bỏ rsp server (tránh double UI / get_rise_star)
                    if FLS.IsEnabled() and (FLS._risingStar or FLS._blockRiseStarInfoReq) then
                        return
                    end
                    -- Rsp lỗi: fallback simulate local, không chạy orig (ShowErrCode + sync)
                    if FLS.IsEnabled() and err_code and tonumber(err_code) ~= 0 then
                        local p = FLS._pendingXSuitRiseStar
                        FLS._pendingXSuitRiseStar = nil
                        if p and FLS.simulateXSuitRiseStar(p[1], p[2], p[3]) then
