                end
            end
            -- Switch form Common (1/3/6/7) — chỉ ghi switchLevel, KHÔNG OnSetGoldDressNewLevelRsp
            pcall(function()
                local LogicXSuit = require("client.slua.logic.XSuit.logic_xsuit")
                if LogicXSuit and LogicXSuit.SetSwitchLevelByPeriod and not FLS._origSetSwitchLevel then
                    FLS._origSetSwitchLevel = LogicXSuit.SetSwitchLevelByPeriod
                    LogicXSuit.SetSwitchLevelByPeriod = function(period, switchLevel, branch_id)
                        if FLS.IsEnabled() then
                            period = tonumber(period)
                            switchLevel = tonumber(switchLevel)
                            branch_id = tonumber(branch_id) or 0
                            if period and switchLevel and switchLevel > 0 then
                                if switchLevel >= 7 then
                                    pcall(FLS.maxXSuitToLevel7, period, branch_id, { quiet = true })
                                end
                                FLS.applySwitchLevelQuiet(period, switchLevel, branch_id)
                                return
                            end
                        end
                        return FLS._origSetSwitchLevel(period, switchLevel, branch_id)
                    end
                end
            end)
            if XSuitHandler.send_set_gold_dress_new_level_req and not FLS._origSendSetGoldDressLevel then
                FLS._origSendSetGoldDressLevel = XSuitHandler.send_set_gold_dress_new_level_req
                XSuitHandler.send_set_gold_dress_new_level_req = function(periodic_id, level_id, branch_id)
                    if FLS.IsEnabled() then
                        -- Equip/switch form: chỉ quiet local — tránh UpdateLobbyAvatar treo
                        pcall(FLS.applySwitchLevelQuiet, periodic_id, level_id, branch_id)
                        return
                    end
                    return FLS._origSendSetGoldDressLevel(periodic_id, level_id, branch_id)
                end
            end
            -- Grand Descent (đảo chờ XSuitPlatform)
            pcall(FLS.hookXSuitPlatform)
            -- Hiện cả 3 nhánh XSuit trong kho (bỏ FilterBranchXSuit)
            pcall(FLS.hookXSuitWardrobeBranchFilter)
            -- Đổi nhánh: không thay item list (giữ dấu tích / cả 3 nhánh)
            pcall(FLS.hookXSuitBranchChangeUI)
        end
    end)

    hooked = true
    end

    FLS.__hooked = hooked
    return hooked
end

