function F.inferSubTypeFromItemId(resID)
    resID = tonumber(resID) or 0
    if resID >= 401000 and resID < 402000 then return 401 end
    if resID >= 402000 and resID < 403000 then return 402 end
    if resID >= 403000 and resID < 404000 then return 403 end
    if resID >= 404000 and resID < 405000 then return 404 end
    if resID >= 405000 and resID < 406000 then return 405 end
    if resID >= 452000 and resID < 453000 then return 452 end
    if resID >= 501001 and resID <= 501199 then return 501 end
    if resID >= 502001 and resID <= 502199 then return 502 end
    if resID >= 1401000 and resID < 1402000 then return 701 end
    return 0
end

function F.classifyDumpSkinCategory(resID)
    resID = tonumber(resID) or 0
    local st = F.subType(F.cfg(resID)) or F.inferSubTypeFromItemId(resID) or 0
    local isBag = (st == 501 or st == 504)
        or (resID >= 1501000000 and resID < 1502000000)
        or (resID >= 501001 and resID <= 501199)
    local isHat = (st == 401) or (resID >= 401000 and resID < 402000)
    local isHelmet = (st == 502 or st == 505)
        or (resID >= 1502000000 and resID < 1503000000)
        or (resID >= 502001 and resID <= 502199)
    if isHat or isHelmet then return 1 end
    if isBag then return 2 end
    if GUN_SUB[st] or st == MELEE_ID or GRENADE_SUB[st] then return 4 end
    if resID >= 1101000000 and resID < 1200000000 then return 4 end
    if resID >= 612000000 and resID < 616000000 then return 4 end
    if resID >= 612000 and resID < 617000 then return 4 end
    if st == 701 or (resID >= 1401000 and resID < 1402000) then return 0 end
    if st == 402 or st == 407 then return 0 end
    if st == 404 or st == 405 or st == 452 then return 3 end
    if resID >= 404000 and resID < 406000 then return 3 end
    if resID >= 452000 and resID < 453000 then return 3 end
    if st == 403 or (resID >= 403000 and resID < 404000) then return 3 end
    if resID >= 1400000 and resID < 1500000 then return 3 end
    if resID >= 140000 and resID < 1401000 then return 3 end
    return 0
end

function F.shouldClearDumpSkin(resID, category)
    resID = tonumber(resID)
    category = tonumber(category) or 0
    if not resID or resID <= 0 then return false end
    F.loadDumpExtraSkins()
    local inDepot = F.isInjectedRes(resID)
    local inDump = _G.KuttaCheatTG_DumpExtraSkins and _G.KuttaCheatTG_DumpExtraSkins[resID] == true
    if not inDepot and not inDump then return false end
    if category == 0 then return true end
    return F.classifyDumpSkinCategory(resID) == category
end

function F.isInjectedDepotAlive(resID, insID)
    resID, insID = tonumber(resID), tonumber(insID)
    if not insID or insID <= 0 then
        if resID and resID > 0 then insID = tonumber(R.resToIns[resID]) end
    end
    if not insID or insID <= 0 then return false end
    if not R.insToRes[insID] then return false end
    local entity = F.getEntity()
    if not entity or not entity.GetDataByInsID then return false end
    local d = entity:GetDataByInsID(insID)
    return d ~= nil and (tonumber(d.count) or 0) > 0
end

function F.unequipInjectedIns(insID, resID)
    insID = tonumber(insID)
    if not insID or insID <= 0 then return end
    pcall(function()
        local AvatarData = require("client.logic.data.AvatarData")
        AvatarData.RemoveRoleWearDataByValue(insID)
    end)
    pcall(function()
        local cch = F.cache()
        local function clearSlot(resKey, insKey)
            if tonumber(cch[insKey]) == insID then
                cch[resKey], cch[insKey] = nil, nil
            end
        end
        clearSlot("outfitRes", "outfitIns")
        clearSlot("hatRes", "hatIns")
        clearSlot("maskRes", "maskIns")
        clearSlot("glassRes", "glassIns")
        clearSlot("tshirtRes", "tshirtIns")
        clearSlot("pantsRes", "pantsIns")
        clearSlot("shoesRes", "shoesIns")
        clearSlot("bagRes", "bagIns")
        clearSlot("helmetRes", "helmetIns")
        clearSlot("parachuteRes", "parachuteIns")
        clearSlot("gliderRes", "gliderIns")
        clearSlot("glovesRes", "glovesIns")
        for wid, w in pairs(cch.weapons or {}) do
            if w and tonumber(w.insID) == insID then cch.weapons[wid] = nil end
        end
    end)
    if resID and tonumber(resID) == tonumber(_G.BackpackSkin) then _G.BackpackSkin = nil end
    if resID and tonumber(resID) == tonumber(_G.HelmetSkin) then _G.HelmetSkin = nil end
end

function F.purgeEntityDepotItem(entity, resID, insID)
    entity = entity or F.getEntity()
    resID, insID = tonumber(resID), tonumber(insID)
    if not entity or not insID or insID <= 0 then return false end

    local removed = false
    local function zeroData(d)
        if not d then return end
        d.count = 0
        d.insID = 0
        d.instid = 0
        d.ins_id = 0
        d.resID = 0
        d.res_id = 0
        removed = true
    end

    pcall(function()
        for _, fn in ipairs({"DeleteData", "RemoveData", "DelDataByInsID", "DeleteDataByInsID", "RemoveDataByInsID"}) do
            if entity[fn] then
                entity[fn](entity, insID)
                removed = true
            end
        end
    end)

    pcall(function()
        if entity._data then
            for i = 1, (entity._DataCount or #entity._data) do
                local d = entity._data[i]
                if d then
                    local ins = tonumber(d.insID or d.instid or d.ins_id)
                    local res = tonumber(d.resID or d.res_id)
                    if ins == insID or (resID and res == resID and ins == insID) then
                        zeroData(d)
                    end
                end
            end
        end
    end)

    pcall(function()
        if entity.GetDataByInsID then zeroData(entity:GetDataByInsID(insID)) end
    end)

    pcall(function()
        if resID and entity.ResIDToIndexArrayMap then
            entity.ResIDToIndexArrayMap[resID] = nil
        end
        for _, mapName in ipairs({"InsIDToIndexArrayMap", "InsIdToIndexArrayMap", "InstIDToIndexArrayMap", "InsIDToIndexMap"}) do
            local m = entity[mapName]
            if m then m[insID] = nil end
        end
        for _, fn in ipairs({"RebuildIndexMap", "BuildIndexMap", "InitIndexMap", "UpdateIndexMap"}) do
            if entity[fn] then entity[fn](entity) end
        end
    end)

    return removed
end

function F.forceWardrobeDepotRefresh()
    LOBBY.wardrobeRefreshed = false
    F.invalidateSocialWearCache()
    F.refreshWardrobe()
    pcall(function()
        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
        local tryFns = {
            "RefreshCurrentPageItemList", "UpdateItemList", "RefreshItemList",
            "OnUpdateItemList", "InitItemList", "UpdateWardrobeItemList",
            "RefreshWardrobeItemList", "ReloadCurrentPage",
        }
        for _, fn in ipairs(tryFns) do
            if wl[fn] then pcall(wl[fn], wl) end
        end
        if wl.GetInstance then
            local inst = wl:GetInstance()
            if inst then
                for _, fn in ipairs({"RefreshItemList", "UpdateItemList", "OnShow", "Refresh", "ReloadData"}) do
                    if inst[fn] then pcall(inst[fn], inst) end
                end
            end
        end
    end)
    pcall(function()
        local subs = {
            "client.slua.umg.Wardrobe.subtab_avatar",
            "client.slua.umg.Wardrobe.subtab_suit",
            "client.slua.umg.Wardrobe.subtab_bag",
            "client.slua.umg.Wardrobe.subtab_gun",
        }
        for _, path in ipairs(subs) do
            local ok, cls = pcall(require, path)
            if ok and cls then
                for _, fn in ipairs({"RefreshItemList", "UpdateItemList", "OnShow", "Refresh", "ReloadData"}) do
                    if cls[fn] then pcall(cls[fn], cls) end
                    if cls.__inner_impl and cls.__inner_impl[fn] then
                        pcall(cls.__inner_impl[fn], cls.__inner_impl)
                    end
                end
            end
        end
    end)
    F.scheduleInjectRefresh()
end

function F.removeInjectedFromDepot(entity, resID, insID)
    resID, insID = tonumber(resID), tonumber(insID)
    if not resID or not insID then return false end

    F.unequipInjectedIns(insID, resID)
    F.purgeEntityDepotItem(entity, resID, insID)

    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        if wd and wd.GetHallDepotItemDataByInsID then
            local hd = wd:GetHallDepotItemDataByInsID(insID)
            if hd then
                hd.count = 0
                hd.insID = 0
                hd.instid = 0
                hd.ins_id = 0
                hd.resID = 0
                hd.res_id = 0
            end
        end
    end)

    if F.isWeaponSkinRes(resID) then
        pcall(function()
            local wid = F.weaponIdFromSkin(resID)
            local Arm = require("client.logic.armory.logic_armory")
            if Arm.rsp_list and Arm.rsp_list.skin_list and wid and Arm.rsp_list.skin_list[wid] then
                Arm.rsp_list.skin_list[wid][resID] = nil
            end
            if Arm.WardrobeInsList then Arm.WardrobeInsList[resID] = nil end
            if wid and Arm.rsp_list and Arm.rsp_list.install_list then
                local entry = Arm.rsp_list.install_list[wid]
                if entry and tonumber(entry.skin_id) == insID then
                    Arm.rsp_list.install_list[wid] = nil
                end
            end
            if wid and R.byWeapon[wid] then R.byWeapon[wid][resID] = nil end
            F.clearWeaponEquippedMark(wid)
        end)
    end

    R.resToIns[resID] = nil
    R.insToRes[insID] = nil
    F.loadDumpExtraSkins()
    if _G.KuttaCheatTG_DumpExtraSkins then _G.KuttaCheatTG_DumpExtraSkins[resID] = nil end
    if PERSIST.configDepotItems then PERSIST.configDepotItems[resID] = nil end
    F.persistMarkDirty()
    return true
end

function F.clearDumpSkinsByCategory(category)
    category = tonumber(category) or 0
    F.loadDumpExtraSkins()
    local entity = F.getEntity()
    local removed, todo = 0, {}
    local seen = {}
    for resID, insID in pairs(R.resToIns) do
        resID, insID = tonumber(resID), tonumber(insID)
        if resID and insID and F.shouldClearDumpSkin(resID, category) and not seen[resID] then
            seen[resID] = true
            todo[#todo + 1] = { resID, insID }
        end
    end
    for resID, on in pairs(_G.KuttaCheatTG_DumpExtraSkins or {}) do
        resID = tonumber(resID)
        if on and resID and not seen[resID] and F.shouldClearDumpSkin(resID, category) then
            seen[resID] = true
            todo[#todo + 1] = { resID, R.resToIns[resID] or F.dumpInsForRes(resID) }
        end
    end
    for i = 1, #todo do
        local pair = todo[i]
        if F.removeInjectedFromDepot(entity, pair[1], pair[2]) then
            removed = removed + 1
        end
    end
    if _G.KuttaCheatTG_DumpExtraSkins then
        for resID, on in pairs(_G.KuttaCheatTG_DumpExtraSkins) do
            resID = tonumber(resID)
            if on and resID and (category == 0 or F.classifyDumpSkinCategory(resID) == category) then
                _G.KuttaCheatTG_DumpExtraSkins[resID] = nil
                if PERSIST.configDepotItems then PERSIST.configDepotItems[resID] = nil end
            end
        end
    end
    F.persistMarkDirty()
    pcall(F.perfInvalidateLobby)
    F.forceWardrobeDepotRefresh()
    F.later(0.15, function() F.forceWardrobeDepotRefresh() end)
    return removed
end

_G.KuttaCheatTG_ClearDumpSkinsByCategory = function(category)
    return F.clearDumpSkinsByCategory(category) or 0
end

function F.injectAll(entity)
    if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModSkin == false then return false end -- Bỏ qua nếu tắt Mod Skin
    entity = entity or F.getEntity()
    if not entity or not entity.bInit then return false end
    -- P23-FIX Task1: DYNAMIC ITEMS (old/6.lua logic) - manual ID dalne ki zarurat nahi.
    -- Item table se auto-collect (WardrobeMainTab/BPID wale), sirf max-level rakhte hain.
    -- Purana hardcoded ITEMS fallback ki tarah rehta hai, naya patch auto-include.
    pcall(function()
        if not _G._p23_dynItemsDone then
            local seenDyn = {}
            for _, v in ipairs(ITEMS) do seenDyn[v] = true end
            local nonMax = {}
            pcall(function()
                local upTbl = _ENV.CDataTable and _ENV.CDataTable.GetTable and _ENV.CDataTable.GetTable("ItemUpgradeConfig")
                if upTbl then
                    local maxLvl, maxItem, members = {}, {}, {}
                    for _, cfg in pairs(upTbl) do
                        local gid = tonumber(cfg.GroupID); local lvl = tonumber(cfg.Level); local itm = tonumber(cfg.ItemID)
                        if gid and lvl and itm then
                            members[gid] = members[gid] or {}; members[gid][#members[gid]+1] = itm
                            if not maxLvl[gid] or lvl > maxLvl[gid] then maxLvl[gid] = lvl; maxItem[gid] = itm end
                        end
                    end
                    for gid, ms in pairs(members) do for _, itm in ipairs(ms) do if itm ~= maxItem[gid] then nonMax[itm] = true end end end
                end
            end)
            for _, tn in ipairs({"GoldenSuitUpgradeCfg","GoldenSuitUpgradeCfgKJ","GoldenSuitUpgradeCfgIN"}) do
                pcall(function()
                    local tbl = _ENV.CDataTable.GetTable(tn)
                    if tbl then
                        local maxS, maxI, mem = {}, {}, {}
                        for _, d in pairs(tbl) do
                            local p = tonumber(d.Period or d.period); local s = tonumber(d.Star or d.star or d.Level or d.level); local itm = tonumber(d.ItemID or d.itemID or d.ItemId)
                            if p and s and itm then
                                mem[p] = mem[p] or {}; mem[p][#mem[p]+1] = itm
                                if not maxS[p] or s > maxS[p] then maxS[p] = s; maxI[p] = itm end
                            end
                        end
                        for p, ms in pairs(mem) do for _, itm in ipairs(ms) do if itm ~= maxI[p] then nonMax[itm] = true end end end
                    end
                end)
            end
            pcall(function()
                local bpMap = _ENV.CDataTable.GetTable("BackpackMapping")
                if bpMap then for _, m in pairs(bpMap) do
                    local lv3 = tonumber(m.SkinItemIDLv3 or 0) or 0; local lv1 = tonumber(m.SkinItemIDLv1 or 0) or 0; local lv2 = tonumber(m.SkinItemIDLv2 or 0) or 0
                    if lv1 > 0 and lv1 ~= lv3 then nonMax[lv1] = true end
                    if lv2 > 0 and lv2 ~= lv3 then nonMax[lv2] = true end
                end end
            end)
            pcall(function()
                local ItemTable = _ENV.CDataTable.GetTable("Item")
                if ItemTable then
                    local added = 0
                    for id, v in pairs(ItemTable) do
                        local rid = tonumber(v.ID or v.Id or id)
                        if rid and rid > 0 and not seenDyn[rid] and not nonMax[rid] then
                            local bpId = tonumber(v.BPID or v.bpID or v.BpId or 0) or 0
                            local mainTab = tonumber(v.WardrobeMainTab or v.wardrobeMainTab or 0) or 0
                            if bpId ~= 0 or mainTab ~= 0 then
                                ITEMS[#ITEMS+1] = rid; seenDyn[rid] = true; added = added + 1
                            end
                        end
                    end
                    table.sort(ITEMS)
                    F.log("P23 dynamic ITEMS added:", added, "total:", #ITEMS)
                end
            end)
            _G._p23_dynItemsDone = true
        end
    end)
    -- P23-FIX lobby trail/hall/emote: auto Item scan me na ho to explicit inject (expired/blank fix, NO hardcoded gun IDs)
    pcall(function()
        if not _G._p23_specialInjectDone then
            _G._p23_specialInjectDone = true
            -- trail IDs lobby equip ke liye (CheckItemValid already true)
            for _, tid in ipairs({4531001, 4531002, 4541001}) do
                if F.cfg and F.cfg(tid) then
                    -- ITEMS me add taaki injectOne chale (duplicate nahi hoga, seen check neeche hota hai)
                    local found = false
                    for _, v in ipairs(ITEMS) do if v == tid then found = true break end end
                    if not found then ITEMS[#ITEMS+1] = tid end
                end
            end
            -- hall theme IDs (HallThemeItem table wale, Item scan me miss ho sakte hain)
            pcall(function()
                local htTbl = _ENV.CDataTable and _ENV.CDataTable.GetTable and _ENV.CDataTable.GetTable("HallThemeItem")
                if htTbl then
                    for k, row in pairs(htTbl) do
                        local rid = tonumber(row.ItemID or row.itemID or k)
                        if rid and rid > 0 then
                            local found = false
                            for _, v in ipairs(ITEMS) do if v == rid then found = true break end end
                            if not found then ITEMS[#ITEMS+1] = rid end
                        end
                    end
                end
            end)
        end
    end)
    F.loadDumpExtraSkins()
    local n, nNew = 0, 0
    -- Skin có sẵn trong script (ITEMS): tắt bằng KuttaVaiConfig.UseScriptSkins = false
    local useScript = true
    if _G.KuttaVaiConfig and _G.KuttaVaiConfig.UseScriptSkins == false then useScript = false end
    if useScript then
        for i, resID in ipairs(ITEMS) do
            local insID = INS_BASE + i
            local had = R.resToIns[resID] ~= nil
            if F.injectOne(entity, resID, insID) then
                n = n + 1
                if not had then nNew = nNew + 1 end
                local c = F.cfg(resID)
                if GUN_SUB[F.subType(c)] or F.subType(c) == MELEE_ID then
                    F.injectArmory(resID, insID)
                end
            end
        end
    end
    for resID, on in pairs(_G.KuttaCheatTG_DumpExtraSkins or {}) do
        if on then
            resID = tonumber(resID)
            if resID and not F.isInjectedDepotAlive(resID) and F.shouldInjectDepotRes(resID) then
                local insID = R.resToIns[resID] or F.dumpInsForRes(resID)
                if F.injectOne(entity, resID, insID) then
                    n = n + 1
                    nNew = nNew + 1
                    insID = R.resToIns[resID] or insID
                    local c = F.cfg(resID)
                    if GUN_SUB[F.subType(c)] or F.subType(c) == MELEE_ID then
                        F.injectArmory(resID, insID)
                    end
                end
            end
        end
    end
    if not _G.AddOutfitUnexpireDone then
        _G.AddOutfitUnexpireDone = true
        pcall(F.reviveExpiredOwned, entity)
    end
    F.mergeRevivedIntoMaps()
    F.sanitizeAllInjectedExpire()
    F.ensureInjectedResources()
    pcall(F.fixInjectedVehicleDepotTabs, entity)
    pcall(F.fixInjectedEmoteDepotTabs, entity)
    pcall(F.fixInjectedParachuteDepotTabs, entity)
    -- Workshop XSuit + nút đổi nhánh sau inject/load JSON
    pcall(function()
        local fls = _G.KuttaCheatTG_FreeLobbyShop
        if type(fls) ~= "table" or not fls.scanDepotAndUnlockXSuits then return end
        fls.scanDepotAndUnlockXSuits()
        local ticker = require("common.time_ticker")
        if ticker and ticker.AddTimerOnce then
            ticker.AddTimerOnce(1.0, function() pcall(fls.scanDepotAndUnlockXSuits) end)
            ticker.AddTimerOnce(3.0, function() pcall(fls.scanDepotAndUnlockXSuits) end)
        end
    end)
    return n > 0
end

function F.refreshWardrobe()
    pcall(function()
        if EventSystem and EVENTTYPE_WARDROBE then
            if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
            end
            if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
            end
            if EVENTID_WARDROBE_UPDATE_GUN_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_GUN_LIST, -1)
            end
        end
    end)
end

function F.refreshWardrobeOnce()
    if LOBBY.wardrobeRefreshed then return end
    LOBBY.wardrobeRefreshed = true
    F.refreshWardrobe()
end

function F.scheduleInjectRefresh()
    LOBBY.injectRefreshGen = (LOBBY.injectRefreshGen or 0) + 1
    local gen = LOBBY.injectRefreshGen
    F.later(0.5, function()
        if gen ~= LOBBY.injectRefreshGen then return end
        F.refreshWardrobe()
    end)
end

function F.scheduleDepotReinject()
    if LOBBY.depotReinjectScheduled then return end
    LOBBY.depotReinjectScheduled = true
    F.later(2.0, function()
        LOBBY.depotReinjectScheduled = false
        local n = 0
        pcall(function() n = F.reinjectMissingDumpExtras() or 0 end)
        pcall(function()
            local fls = _G.KuttaCheatTG_FreeLobbyShop
            if type(fls) == "table" and fls.scanDepotAndUnlockXSuits then
                fls.scanDepotAndUnlockXSuits()
            end
        end)
        if n > 0 then F.refreshWardrobe() end
    end)
end

function F.putOnOutfit(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d0 = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
        resID = d0 and tonumber(d0.resID or d0.res_id)
    end
    if not resID or resID <= 0 then return end
    if not R.insToRes[insID] then R.insToRes[insID] = resID; R.resToIns[resID] = insID end
    F.ensureDepotItemValid(insID, resID)
    if not F.isResourcesReady(resID) then
        F.requestResourceDownload(resID)
        return
    end
    if not F.isSuitRes(resID) then
        if F.isTshirtRes(resID) then return F.putOnRoleWear(insID) end
        return
    end
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local d = wd:GetHallDepotItemDataByInsID(insID)
    if not d then return end

    local suitFilter = function(r) return F.isSuitRes(r) end
    local oldIns, oldRes = F.findWornInsBySubType(OUTFIT_SUB, suitFilter)
    F.removeRoleWearBySubType(OUTFIT_SUB, suitFilter)
    F.saveEquip(resID, insID)

    local slot = PKG_SLOT
    pcall(function()
        local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
        local idx = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(OUTFIT_SUB)
        if idx then slot = idx end
    end)

    local olditem
    if oldIns and oldIns ~= insID then
        olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
    end

    local WRH = require("client.network.Protocol.WardRobeHandler")
    local item = { res_id = resID, count = 1, instid = insID }
    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

    pcall(function()
        local av = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
        av:AddToWearInfo(OUTFIT_SUB, insID, resID, 0, 0)
        F.syncFashionBagRolewear()
    end)
    F.rememberLobbyOutfitRes(resID)
    pcall(function() F.patchSelfWearCache(true) end)
    pcall(function() F.requestSocialAvatarRefresh() end)
end

function F.putOnHat(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d0 = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
        resID = d0 and tonumber(d0.resID or d0.res_id)
    end
    if not resID or resID <= 0 then return end
    if not R.insToRes[insID] then R.insToRes[insID] = resID; R.resToIns[resID] = insID end
    F.ensureDepotItemValid(insID, resID)
    if not F.isResourcesReady(resID) then
        F.requestResourceDownload(resID)
        return
    end
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local d = wd:GetHallDepotItemDataByInsID(insID)
    if not d then return end
    local st = F.subType(F.cfg(resID)) or HAT_SUB

    local oldIns, oldRes = F.findWornInsBySubType(st)
    if not oldIns and st ~= HAT_SUB then
        oldIns, oldRes = F.findWornInsBySubType(HAT_SUB)
    end
    F.removeRoleWearBySubType(st)
    if st ~= HAT_SUB then F.removeRoleWearBySubType(HAT_SUB) end
    F.saveEquip(resID, insID)

    local slot = 1
    pcall(function()
        local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
        local idx = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(st)
        if idx then slot = idx end
    end)

    local olditem
    if oldIns and oldIns ~= insID then
        olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
    end

    local WRH = require("client.network.Protocol.WardRobeHandler")
    local item = { res_id = resID, count = 1, instid = insID, color = d.color, pattern = d.pattern }
    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

    pcall(function()
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        fbd:SetHeadShow(insID)
        F.syncFashionBagRolewear()
    end)
    F.invalidateSocialWearCache()
end

function F.putOnFaceAccessory(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d0 = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
        resID = d0 and tonumber(d0.resID or d0.res_id)
    end
    if not resID or resID <= 0 then return end
    if not R.insToRes[insID] then R.insToRes[insID] = resID; R.resToIns[resID] = insID end
    F.ensureDepotItemValid(insID, resID)
    if not F.isResourcesReady(resID) then
        F.requestResourceDownload(resID)
        return
    end
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local d = wd:GetHallDepotItemDataByInsID(insID)
    if not d then return end
    local st = F.subType(F.cfg(resID)) or tonumber(d.itemSubType)
    if not FACE_SUBS[st] then return end

    local oldIns, oldRes = F.findWornInsBySubType(st)
    F.removeRoleWearBySubType(st)
    F.saveEquip(resID, insID)

    local slot = (st == MASK_SUB) and 2 or 6
    pcall(function()
        local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
        local idx = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(st)
        if idx then slot = idx end
    end)

    local olditem
    if oldIns and oldIns ~= insID then
        olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
    end

    local WRH = require("client.network.Protocol.WardRobeHandler")
    local item = { res_id = resID, count = 1, instid = insID, color = d.color, pattern = d.pattern }
    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

    pcall(function() F.syncFashionBagRolewear() end)
    F.invalidateSocialWearCache()
end

function F.canRoleWear(resID, st)
    st = st or F.subType(F.cfg(resID))
    if FACE_SUBS[st] or BODY_SUBS[st] then return true end
    if st == GLOVES_SUB then return true end
    if st == OUTFIT_SUB and F.wardrobeTab(resID) == TAB_CLOTHES then return true end
    return false
end

F.putOnRoleWear = function(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d0 = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
        resID = d0 and tonumber(d0.resID or d0.res_id)
    end
    if not resID or resID <= 0 then return end
    if not R.insToRes[insID] then R.insToRes[insID] = resID; R.resToIns[resID] = insID end
    F.ensureDepotItemValid(insID, resID)
    if not F.isResourcesReady(resID) then
        F.requestResourceDownload(resID)
        return
    end
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local d = wd:GetHallDepotItemDataByInsID(insID)
    if not d then return end
    local st = F.subType(F.cfg(resID)) or tonumber(d.itemSubType)
    if not F.canRoleWear(resID, st) then return end

    -- Nón/balo: dùng mapping key sảnh (*000xxx) để Lv1/2/3 hiện đúng
    if BAG_SUBS[st] or HELMET_SUBS[st] then
        local norm = F.equipToLobbyMappingID(resID)
        if norm and norm > 0 and norm ~= resID then
            resID = norm
            R.insToRes[insID] = resID
            R.resToIns[resID] = insID
            pcall(function()
                if d.resID ~= nil then d.resID = resID end
                if d.res_id ~= nil then d.res_id = resID end
            end)
        end
    end

    local filterFn
    if st == OUTFIT_SUB then
        filterFn = function(r) return F.wardrobeTab(r) == TAB_CLOTHES end
    end
    local oldIns, oldRes = F.findWornInsBySubType(st, filterFn)
    F.removeRoleWearBySubType(st, filterFn)
    F.saveEquip(resID, insID)

    local slot = PKG_SLOT
    pcall(function()
        local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
        local idx = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(st)
        if idx then slot = idx end
    end)

    local olditem
    if oldIns and oldIns ~= insID then
        olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
    end

    local WRH = require("client.network.Protocol.WardRobeHandler")
    local item = { res_id = resID, count = 1, instid = insID, color = d.color, pattern = d.pattern }
    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

    if BAG_SUBS[st] or HELMET_SUBS[st] then
        pcall(function()
            DataMgr.equipmentSkinInsIDTable = DataMgr.equipmentSkinInsIDTable or {}
            DataMgr.equipmentSkinInsIDTable[st] = insID
            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
            if bag then
                if st == 504 or st == 501 then
                    DataMgr.equipmentSkinInsIDTable[504] = insID
                    bag.bag_skin = insID
                elseif st == 505 or st == 502 then
                    DataMgr.equipmentSkinInsIDTable[505] = insID
                    bag.helmet_skin = insID
                end
            end
        end)
        -- Ép avatar sảnh hiện đúng SkinItemIDLv theo level preview
        pcall(function()
            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            local level = 3
            if HELMET_SUBS[st] then
                level = tonumber(fbd:GetHelmetLevel()) or 3
            else
                level = tonumber(fbd:GetBagLevel()) or 3
            end
            local displayID = 0
            if DataMgr and DataMgr.GetEquipmentItemIDByResID then
                displayID = tonumber(DataMgr.GetEquipmentItemIDByResID(level, resID)) or 0
            end
            if displayID <= 0 then displayID = resID end
            F.ensureSkinDownload(displayID)
            local av = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
            local skinSub = HELMET_SUBS[st] and 505 or 504
            if av.AddToWearInfo then
                av:AddToWearInfo(skinSub, insID, resID, d.color or 0, d.pattern or 0)
            end
            if av.AvatarChange then
                av:AvatarChange(displayID, true, d.color or 0, d.pattern or 0)
            end
        end)
    end

    pcall(function() F.syncFashionBagRolewear() end)
    F.invalidateSocialWearCache()
end

function F.putOnGloves(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d0 = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
        resID = d0 and tonumber(d0.resID or d0.res_id)
    end
    if not resID or resID <= 0 then return end
    if not R.insToRes[insID] then R.insToRes[insID] = resID; R.resToIns[resID] = insID end
    F.ensureDepotItemValid(insID, resID)
    if not F.isResourcesReady(resID) then
        F.requestResourceDownload(resID)
        return
    end
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local d = wd:GetHallDepotItemDataByInsID(insID)
    if not d then return end

    local oldIns, oldRes = F.findWornInsBySubType(GLOVES_SUB)
    F.removeRoleWearBySubType(GLOVES_SUB)
    F.saveEquip(resID, insID)

    local slot = 8
    pcall(function()
        local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
        local idx = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(GLOVES_SUB)
        if idx then slot = idx end
    end)

    local olditem
    if oldIns and oldIns ~= insID then
        olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
    end

    local WRH = require("client.network.Protocol.WardRobeHandler")
    local item = { res_id = resID, count = 1, instid = insID, color = d.color, pattern = d.pattern, expire_ts = 0 }
    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)

    pcall(function()
        local logic_wardrobe_avatar = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
        logic_wardrobe_avatar:AddToWearInfo(GLOVES_SUB, insID, resID, d.color or 0, d.pattern or 0)
        DataMgr.UpdateRoleWearData(insID, oldIns or 0)
        logic_wardrobe_avatar:AvatarChange(resID, true, d.color, d.pattern)
    end)
    pcall(function()
        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
        if wl.SetClickItemInsId then wl:SetClickItemInsId(insID) end
    end)
    pcall(function()
        if EventSystem and EVENTTYPE_WARDROBE then
            if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
            end
            if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
                EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
            end
        end
    end)
    F.invalidateSocialWearCache()
end

function F.ensureDepotItemValid(insID, resID)
    insID = tonumber(insID)
    if not insID then return end
    pcall(function()
        local entity = F.getEntity()
        if entity and entity.GetDataByInsID then
            local d = entity:GetDataByInsID(insID)
            if d then
                d.expire_ts = 0
                if d.expireTS ~= nil then d.expireTS = 0 end
                if d.valid_hours ~= nil then d.valid_hours = 0 end
            end
        end
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local hd = wd:GetHallDepotItemDataByInsID(insID)
        if hd then
            hd.expire_ts = 0
            if hd.expireTS ~= nil then hd.expireTS = 0 end
            if hd.valid_hours ~= nil then hd.valid_hours = 0 end
        end
    end)
end

function F.clearItemExpire(itemData, insID, resID)
    F.ensureDepotItemValid(insID, resID)
    if type(itemData) == "table" then
        itemData.expireTS = 0
        itemData.expire_ts = 0
        itemData.expireTs = 0
    end
end

function F.onGlideClick(self, itemData)
    if not itemData then return end
    local insID = tonumber(itemData.ins_id)
    local resID = tonumber(itemData.res_id)
    F.clearItemExpire(itemData, insID, resID)
    local isGlide = resID and F.isGlideRes(resID)
    if not isGlide and itemData.itemSubType then
        isGlide = GLIDER_SUBS[tonumber(itemData.itemSubType)] == true
    end
    if insID and resID and isGlide then
        F.saveEquip(resID, insID)
        if F.putOnGlider(insID) then
            pcall(function()
                if self.ShowGlide then self:ShowGlide(resID) end
                if self.ChangeItemStatus then self:ChangeItemStatus(insID, true) end
            end)
            return
        end
    end
    if _G.AddOutfitGlideClickOrig then
        F.clearItemExpire(itemData, insID, resID)
        return _G.AddOutfitGlideClickOrig(self, itemData)
    end
end

function F.onParachuteClick(self, itemData)
    if not itemData then return end
    local insID = tonumber(itemData.ins_id)
    local resID = tonumber(itemData.res_id)
    F.clearItemExpire(itemData, insID, resID)
    if insID and resID and F.isParachuteRes(resID) then
        F.saveEquip(resID, insID)
        if F.putOnParachute(insID) then
            pcall(function()
                if self.ChangeItemStatus then self:ChangeItemStatus(insID, true) end
            end)
            return
        end
    end
    if _G.AddOutfitParaClickOrig then
        return _G.AddOutfitParaClickOrig(self, itemData)
    end
end

function F.onThrowObjectClick(self, widget, index)
    local itemData = nil
    pcall(function()
        if self.LoopScrollGrid_Normal and self.LoopScrollGrid_Normal.GetItemData then
            itemData = self.LoopScrollGrid_Normal:GetItemData(index)
        end
    end)
    if itemData then
        local insID = tonumber(itemData.ins_id or itemData.insID)
        local resID = tonumber(itemData.res_id or itemData.resID)
        F.clearItemExpire(itemData, insID, resID)
        local st = tonumber(itemData.itemSubType) or (resID and F.subType(F.cfg(resID)))
        if insID and resID and GRENADE_SUB[st] then
            if (F.isInjectedIns(insID) or F.isInjectedRes(resID)) and F.putOnGrenade(insID) then
                pcall(function()
                    if self.ChangeItemStatusByInsID then
                        self:ChangeItemStatusByInsID(insID, true)
                    elseif self.ChangeItemStatus then
                        self:ChangeItemStatus(insID, true)
                    end
                end)
                return
            end
        end
    end
    if _G.AddOutfitThrowClickOrig then
        return _G.AddOutfitThrowClickOrig(self, widget, index)
    end
end

function F.hookAirborneClick()
    pcall(function()
        local WG = require("client.slua.umg.Wardrobe.subtab_gliding")
        if WG then
            if not WG._AddOutfitGlideWrapped then
                WG._AddOutfitGlideWrapped = true
                _G.AddOutfitGlideClickOrig = WG.ClickItem
            end
            WG.ClickItem = function(self, itemData)
                return F.onGlideClick(self, itemData)
            end
        end
        local WP = require("client.slua.umg.Wardrobe.subtab_parachute")
        if WP then
            if not WP._AddOutfitParaWrapped then
                WP._AddOutfitParaWrapped = true
                _G.AddOutfitParaClickOrig = WP.ClickItem
            end
            WP.ClickItem = function(self, itemData)
                return F.onParachuteClick(self, itemData)
            end
        end
        -- Skin lựu: tab throw_object — click giống dù
        local WT = require("client.slua.umg.Wardrobe.subtab_throw_object")
        if WT then
            if not WT._AddOutfitThrowWrapped then
                WT._AddOutfitThrowWrapped = true
                _G.AddOutfitThrowClickOrig = WT.OnClickItem
            end
            WT.OnClickItem = function(self, widget, index)
                return F.onThrowObjectClick(self, widget, index)
            end
        end
    end)
    pcall(function()
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        if fbd and not fbd._AddOutfitAirborneFBHooked then
            fbd._AddOutfitAirborneFBHooked = true
            local oG = fbd.UpdateAircraftOrGliding
            fbd.UpdateAircraftOrGliding = function(self, putOnID, bAircraft)
                local r = oG(self, putOnID, bAircraft)
                local ins = tonumber(putOnID)
                if ins and ins > 0 then
                    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                    local d = wd:GetValidHallDepotItemDataByInsID(ins) or wd:GetHallDepotItemDataByInsID(ins)
                    local res = d and tonumber(d.resID)
                    if res and F.isGlideRes(res) then F.saveEquip(res, ins) end
                end
                return r
            end
            local oP = fbd.UpdateParachute
            if oP then
                fbd.UpdateParachute = function(self, insID)
                    local r = oP(self, insID)
                    local ins = tonumber(insID)
                    if ins and ins > 0 then
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetValidHallDepotItemDataByInsID(ins) or wd:GetHallDepotItemDataByInsID(ins)
                        local res = d and tonumber(d.resID)
                        if res and F.isParachuteRes(res) then F.saveEquip(res, ins) end
                    end
                    return r
                end
            end
            local oT = fbd.PutOnThrowObjectSkin
            if oT then
                fbd.PutOnThrowObjectSkin = function(self, putOnId, index)
                    local r = oT(self, putOnId, index)
                    local ins = tonumber(putOnId)
                    if ins and ins > 0 then
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        local d = wd:GetValidHallDepotItemDataByInsID(ins) or wd:GetHallDepotItemDataByInsID(ins)
                        local res = d and tonumber(d.resID)
                        local base = res and F.grenadeBaseFromSkin(res)
                        if base then F.saveGrenadeToCache(base, res, ins) end
                    end
                    return r
                end
            end
        end
    end)
    pcall(function()
        if not ModuleManager or not ModuleManager.GetModule then return end
        local FB = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.FashionBagEditUtils)
        if FB and not FB._AddOutfitFBBagHooked then
            FB._AddOutfitFBBagHooked = true
            local o = FB.PutOnFashionBagItem
            FB.PutOnFashionBagItem = function(self, itemData)
                if itemData then
                    F.clearItemExpire(itemData, itemData.ins_id, itemData.res_id)
                end
                local r = o(self, itemData)
                if itemData then
                    local res = tonumber(itemData.res_id)
                    local ins = tonumber(itemData.ins_id)
                    if res and ins and (F.isGlideRes(res) or F.isParachuteRes(res)) then
                        F.saveEquip(res, ins)
                    elseif res and ins and F.isGrenadeSkinRes(res) then
                        local base = F.grenadeBaseFromSkin(res)
                        if base then F.saveGrenadeToCache(base, res, ins) end
                    end
                end
                return r
            end
        end
    end)
end

function F.putOnParachute(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
        resID = d and tonumber(d.resID)
    end
    if not resID or not F.isParachuteRes(resID) then return false end
    if not R.insToRes[insID] then R.insToRes[insID] = resID end
    F.ensureDepotItemValid(insID, resID)
    F.saveEquip(resID, insID)
    F.ensureInjectedItemAlive(nil, resID, insID)
    local ready = F.isResourcesReady(resID)
    if not ready then F.requestResourceDownload(resID) end
    pcall(function()
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        if fbd.SetParachute then fbd:SetParachute(insID) end
        if fbd.UpdateParachute then fbd:UpdateParachute(insID) end
    end)
    if ready then
        local item = {
            res_id = resID, resID = resID,
            instid = insID, ins_id = insID, insID = insID,
            expire_ts = 0, expireTS = 0, count = 1,
        }
        local WRH = require("client.network.Protocol.WardRobeHandler")
        WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
    end
    return true
end

function F.putOnGlider(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
        resID = d and tonumber(d.resID)
    end
    if not resID or resID <= 0 then return false end
    local st = F.depotSubType(insID, resID)
    if not F.isGlideRes(resID) and not GLIDER_SUBS[st] then return false end
    if not R.insToRes[insID] then R.insToRes[insID] = resID end
    F.ensureDepotItemValid(insID, resID)
    F.saveEquip(resID, insID)
    F.ensureInjectedItemAlive(nil, resID, insID)
    local ready = F.isResourcesReady(resID)
    if not ready then F.requestResourceDownload(resID) end
    local bAircraft = false
    pcall(function()
        local ModelDisplayTypeHelper = require("client.logic.avatar.ModelDisplayTypeHelper")
        local st = F.subType(F.cfg(resID))
        bAircraft = ModelDisplayTypeHelper.IsGlideSmoke(st)
    end)
    pcall(function()
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        if fbd.UpdateAircraftOrGliding then
            fbd:UpdateAircraftOrGliding(insID, bAircraft)
        elseif fbd.SetGliding then
            fbd:SetGliding(insID)
            if DataMgr.UpdateEffect then DataMgr.UpdateEffect(insID) end
        end
    end)
    if ready then
        local item = {
            res_id = resID, resID = resID,
            instid = insID, ins_id = insID, insID = insID,
            expire_ts = 0, expireTS = 0, count = 1,
        }
        local WRH = require("client.network.Protocol.WardRobeHandler")
        WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
    end
    return true
end

function F.syncAirborneToDataMgr()
    F.applyPersistSlotsToCache()
    local cch = F.cache()
    local paraRes = F.getDesiredParachuteRes()
    local gliderRes = F.getDesiredGliderRes()
    if paraRes and paraRes > 0 and not cch.parachuteIns then
        cch.parachuteIns = F.resolveInsForRes(paraRes)
        cch.parachuteRes = paraRes
    end
    if gliderRes and gliderRes > 0 and not cch.gliderIns then
        cch.gliderIns = F.resolveInsForRes(gliderRes)
        cch.gliderRes = gliderRes
    end
    pcall(function()
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        if cch.parachuteIns and tonumber(cch.parachuteIns) > 0 then
            if fbd.SetParachute then fbd:SetParachute(cch.parachuteIns) end
            if DataMgr.roleData then DataMgr.roleData.parachute = tostring(cch.parachuteIns) end
        end
        if cch.gliderIns and tonumber(cch.gliderIns) > 0 then
            local bAircraft = false
            if cch.gliderRes then
                pcall(function()
                    local MDH = require("client.logic.avatar.ModelDisplayTypeHelper")
                    bAircraft = not MDH.IsGlideSmoke(F.subType(F.cfg(cch.gliderRes)))
                end)
            end
            if fbd.UpdateAircraftOrGliding then
                fbd:UpdateAircraftOrGliding(cch.gliderIns, bAircraft)
            elseif fbd.SetGliding then
                fbd:SetGliding(cch.gliderIns)
                if DataMgr.UpdateEffect then DataMgr.UpdateEffect(cch.gliderIns) end
            end
            if DataMgr.roleData then
                if bAircraft then
                    DataMgr.roleData.aircraft_put_id = tostring(cch.gliderIns)
                    DataMgr.gliding = cch.gliderIns
                else
                    DataMgr.roleData.gliding = tostring(cch.gliderIns)
                end
            end
        end
    end)
end

function F.putOnGenericInjected(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then return end
    if not F.isResourcesReady(resID) then
        F.requestResourceDownload(resID)
        return
    end
    F.saveEquip(resID, insID)
    local WRH = require("client.network.Protocol.WardRobeHandler")
    WRH.on_depot_put_on_rsp(NET_OK, { res_id = resID, count = 1, instid = insID }, nil, 1, insID, 0)
end

function F.clearEquipCache(resID)
    local st = F.subType(F.cfg(resID))
    local cch = F.cache()
    if st == OUTFIT_SUB then
        if F.wardrobeTab(resID) == TAB_CLOTHES then
            cch.tshirtRes, cch.tshirtIns = nil, nil
            _G.AddOutfitLastLobbyTshirtRes = nil
            F.persistForgetSlot("tshirt")
        else
            cch.outfitRes, cch.outfitIns = nil, nil
            _G.AddOutfitLastLobbyOutfitRes = nil
            F.persistForgetSlot("outfit")
        end
    elseif st == HAT_SUB or HEAD_SUBS[st] then
        cch.hatRes, cch.hatIns = nil, nil
        _G.AddOutfitLastLobbyHatRes = nil
        F.persistForgetSlot("hat")
    elseif st == MASK_SUB then
        cch.maskRes, cch.maskIns = nil, nil
        _G.AddOutfitLastLobbyMaskRes = nil
        F.persistForgetSlot("mask")
    elseif st == GLASS_SUB then
        cch.glassRes, cch.glassIns = nil, nil
        _G.AddOutfitLastLobbyGlassRes = nil
        F.persistForgetSlot("glass")
    elseif st == PANTS_SUB then
        cch.pantsRes, cch.pantsIns = nil, nil
        _G.AddOutfitLastLobbyPantsRes = nil
        F.persistForgetSlot("pants")
    elseif st == SHOES_SUB then
        cch.shoesRes, cch.shoesIns = nil, nil
        _G.AddOutfitLastLobbyShoesRes = nil
        F.persistForgetSlot("shoes")
    elseif BAG_SUBS[st] then
        cch.bagRes, cch.bagIns = nil, nil
        _G.AddOutfitLastLobbyBagRes = nil
        F.persistForgetSlot("bag")
    elseif HELMET_SUBS[st] then
        cch.helmetRes, cch.helmetIns = nil, nil
        _G.AddOutfitLastLobbyHelmetRes = nil
        F.persistForgetSlot("helmet")
    elseif st == PARACHUTE_SUB then
        cch.parachuteRes, cch.parachuteIns = nil, nil
        _G.AddOutfitLastLobbyParachuteRes = nil
        F.persistForgetSlot("parachute")
    elseif F.isGlideRes(resID) then
        cch.gliderRes, cch.gliderIns = nil, nil
        _G.AddOutfitLastLobbyGliderRes = nil
        F.persistForgetSlot("glider")
    elseif st == GLOVES_SUB then
        cch.glovesRes, cch.glovesIns = nil, nil
        _G.AddOutfitLastLobbyGlovesRes = nil
        F.persistForgetSlot("gloves")
    end
    _matchApplied = false
    F.invalidateSocialWearCache()
    F.perfInvalidateLobby()
    F.persistMarkDirty()
end

function F.takeOffInjected(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then return end
    local st = F.subType(F.cfg(resID))

    pcall(function()
        local WRH = require("client.network.Protocol.WardRobeHandler")
        WRH.on_depot_put_down_rsp(NET_OK, { res_id = resID, count = 1 }, insID)
    end)

    pcall(function()
        local AvatarData = require("client.logic.data.AvatarData")
        AvatarData.RemoveRoleWearDataByValue(insID)
    end)
    if st == HAT_SUB or HEAD_SUBS[st] then
        pcall(function()
            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
            if bag and tonumber(bag.head_show) == insID then fbd:SetHeadShow(0) end
        end)
    end
    if BAG_SUBS[st] or HELMET_SUBS[st] then
        pcall(function()
            local t = DataMgr.equipmentSkinInsIDTable
            if t then
                for _, k in ipairs({ st, 504, 505 }) do
                    if tonumber(t[k]) == insID then t[k] = 0 end
                end
            end
            local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
            local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
            if bag then
                if tonumber(bag.bag_skin) == insID then bag.bag_skin = 0 end
                if tonumber(bag.helmet_skin) == insID then bag.helmet_skin = 0 end
            end
        end)
    end

    F.clearEquipCache(resID)
    pcall(function() F.syncFashionBagRolewear() end)
end

function F.syncWeaponArmorySilent(weaponID, insID)
    weaponID, insID = tonumber(weaponID), tonumber(insID)
    if not weaponID or not insID or not F.isInjectedIns(insID) then return end
    local resID = R.insToRes[insID]
    if not resID then return end
    local Arm = require("client.logic.armory.logic_armory")
    Arm.rsp_list = Arm.rsp_list or { skin_list = {}, install_list = {} }
    Arm.rsp_list.install_list = Arm.rsp_list.install_list or {}
    F.injectArmory(resID, insID)
    Arm.rsp_list.install_list[weaponID] = { skin_id = insID }
    pcall(function()
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        if fbd.UpdateCurrentFashionBagWeaponSkin then
            fbd:UpdateCurrentFashionBagWeaponSkin(weaponID, insID)
        end
    end)
end

function F.equipWeaponSkin(weaponID, insID, forceVisual)
    weaponID, insID = tonumber(weaponID), tonumber(insID)
    if not weaponID or not insID or not F.isInjectedIns(insID) then return false end
    local resID = R.insToRes[insID]
    if not resID then return false end

    local meleeSkin = F.subType(F.cfg(resID)) == MELEE_ID
    local mappedWid = tonumber(F.weaponIdFromSkin(resID))
    -- Each melee type uses its own WeaponID (108001 dao, 108004 chảo, …)
    local displayWid = weaponID
    if meleeSkin then
        if mappedWid and mappedWid > 0 then
            displayWid = mappedWid
        elseif weaponID >= 108000 and weaponID < 109000 then
            displayWid = weaponID
        end
    end

    _G.AddOutfitWeaponEquipped = _G.AddOutfitWeaponEquipped or {}
    if not forceVisual and F.isWeaponVisuallyEquipped(displayWid, insID) then
        F.syncWeaponArmorySilent(displayWid, insID)
        return false
    end
    F.saveEquip(resID, insID)

    local Arm = require("client.logic.armory.logic_armory")
    local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
    local HT = require("client.logic.lobby.hall_theme_utils")
    local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")

    F.injectArmory(resID, insID)
    Arm.rsp_list.install_list[displayWid] = { skin_id = insID }
    if fbd.UpdateCurrentFashionBagWeaponSkin then
        fbd:UpdateCurrentFashionBagWeaponSkin(displayWid, insID)
    end

    local bagIdx = fbd:GetFashionBagUseIndex()
    HT.proc_skin_list_chg("weapon_skin", displayWid, insID, bagIdx, {})

    wgl:SetGunID(displayWid)
    wgl:UpdateCurrentGunAvatar(displayWid, insID)

    if EventSystem and EVENTTYPE_ARMORY and EVENTID_ARMORY_EQUIP_STAT_CHANGE then
        EventSystem:postEvent(EVENTTYPE_ARMORY, EVENTID_ARMORY_EQUIP_STAT_CHANGE, resID)
    end
    if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
        EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN, resID)
    end
    _G.AddOutfitWeaponEquipped[displayWid] = insID
    return true
end

local SOCIAL = _G.AddOutfitSocialState or {}
_G.AddOutfitSocialState = SOCIAL
SOCIAL.debGen = SOCIAL.debGen or 0
SOCIAL.wearPatchKey = SOCIAL.wearPatchKey or nil
SOCIAL.snapshotKey = SOCIAL.snapshotKey or nil
SOCIAL.fullSnapshot = SOCIAL.fullSnapshot or nil

function F.socialDebounce(sec, fn)
    SOCIAL.debGen = (SOCIAL.debGen or 0) + 1
    local gen = SOCIAL.debGen
    F.later(sec, function()
        if gen ~= SOCIAL.debGen then return end
        pcall(fn)
    end)
end

function F.getLobbyCurPage()
    local p = nil
    pcall(function()
        local LMC = require("client.slua.logic.lobby.Main.Lobby_Main_Control")
        if LMC.GetCurPage then p = LMC.GetCurPage() end
    end)
    return p
end

function F.isLobbyLeftPage()
    return ENUM_LobbyPageType and F.getLobbyCurPage() == ENUM_LobbyPageType.Left
end

function F.isSelfRoleInfoOpen()
    local ok = false
    pcall(function()
        if UIManager and UIManager.UI_Config then
            local cfgs = {
                UIManager.UI_Config.roleinfo_main,
                UIManager.UI_Config.Personalization_UIBP,
                UIManager.UI_Config.Lobby_RoleInfo_Segment180_UIBP,
                UIManager.UI_Config.Lobby_RoleInfo_Combat180_UIBP,
            }
            for _, cfg in ipairs(cfgs) do
                if cfg and UIManager.IsUIShow and UIManager.IsUIShow(cfg) then
                    ok = true
                    break
                end
            end
        end
    end)
    return ok
end

function F.isSelfUid(uid)
    if uid == nil then return false end
    local myUid
    pcall(function() myUid = DataMgr.roleData.uid end)
    return myUid and tostring(uid) == tostring(myUid)
end

function F.isBattleResultOrMvpOpen()
    local ok = false
    pcall(function()
        if not UIManager or not UIManager.UI_Config_InGame then return end
        local cfgs = {
            UIManager.UI_Config_InGame.BattleResultRanking_UIBP,
            UIManager.UI_Config_InGame.BattleResultShowMvp_UIBP,
            UIManager.UI_Config_InGame.BattleResultChickenUI,
            UIManager.UI_Config_InGame.BattleResultMedalDisplayUI,
            UIManager.UI_Config_InGame.Mvp_Sequence_Mask,
        }
        for _, cfg in ipairs(cfgs) do
            if cfg and UIManager.IsUIShow and UIManager.IsUIShow(cfg) then
                ok = true
                break
            end
        end
    end)
    return ok
end

function F.prepareBattleResultWearPatch()
    LOBBY.outfitResolved = false
    LOBBY.skinResolved = false
    F.syncWeaponCacheFromLobby(true)
    F.applyPersistSlotsToCache()
end

function F.setBattleResultWearExtSlot(wear_ext, slot, res)
    if not wear_ext or not slot or not res or res <= 0 then return end
    wear_ext[slot] = wear_ext[slot] or { 0, 0, 0 }
    wear_ext[slot][1] = res
end

function F.patchSelfBattleResultWearExt(wear_ext)
    if not wear_ext or not ENUM_AVATAR_SHOW_TYPE then return end
    F.prepareBattleResultWearPatch()
    local outfitRes = F.resolveLobbyOutfitRes()
    if outfitRes and outfitRes > 0 then
        F.setBattleResultWearExtSlot(wear_ext, ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH, outfitRes)
    end
    local skinRes = F.resolveLobbyWeaponSkinRes()
    if skinRes and skinRes > 0 then
        F.setBattleResultWearExtSlot(wear_ext, ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON, 0)
        F.setBattleResultWearExtSlot(wear_ext, ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN, skinRes)
    end
    local cch = F.cache()
    if cch.hatRes and cch.hatRes > 0 then
        F.setBattleResultWearExtSlot(wear_ext, ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HEADWEAR, cch.hatRes)
    end
    if cch.helmetRes and cch.helmetRes > 0 then
        F.setBattleResultWearExtSlot(wear_ext, ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HELMET, cch.helmetRes)
    end
    if cch.bagRes and cch.bagRes > 0 then
        F.setBattleResultWearExtSlot(wear_ext, ENUM_AVATAR_SHOW_TYPE.SHOW_POS_BAG, cch.bagRes)
    end
end

function F.patchSelfInTeammateList(list)
    if not list then return end
    for _, v in pairs(list) do
        if v and F.isSelfUid(v.UID or v.uid) then
            v.wear_ext = v.wear_ext or {}
            F.patchSelfBattleResultWearExt(v.wear_ext)
        end
    end
end

function F.shouldApplySelfOutfitPatch()
    if F.isLobbyLeftPage() or F.isSelfRoleInfoOpen() then return true end
    if F.isBattleResultOrMvpOpen() then return true end
    local ok = false
    pcall(function()
        if GameStatus and GameStatus.IsInLobbyOrMainCity and GameStatus.IsInLobbyOrMainCity() then
            ok = true
        end
    end)
    return ok
end

function F.getWeaponSkinResFast()
    local cch = F.cache()
    local wid = tonumber(DataMgr.Weapon_ID) or 0
    local w = wid > 0 and cch.weapons[wid] or nil
    if w and w.resID and w.resID > 0 then return w.resID end
    for _, ww in pairs(cch.weapons) do
        if ww.resID and ww.resID > 0 then return ww.resID end
    end
    return nil
end

function F.resolveLobbyWeaponSkinRes()
    if LOBBY.skinResolved then return LOBBY.cachedSkin end
    local wid = tonumber(DataMgr.Weapon_ID) or 0
    local skin = F.getWeaponSkinResFast()
    if skin and skin > 0 then return skin end

    if wid > 0 then
        local fromMatch = F.getMatchWeaponSkin(wid)
        if fromMatch and fromMatch > 0 then return fromMatch end
    end
    if MATCH_CONFIG.weaponSkins then
        for _, s in pairs(MATCH_CONFIG.weaponSkins) do
            s = tonumber(s)
            if s and s > 0 then return s end
        end
    end

    pcall(function()
        local Arm = require("client.logic.armory.logic_armory")
        local entry = Arm.rsp_list and Arm.rsp_list.install_list
            and Arm.rsp_list.install_list[wid > 0 and wid or 101004]
        local insID = tonumber(entry and entry.skin_id) or 0
        if insID > 0 and F.isInjectedIns(insID) then
            skin = tonumber(R.insToRes[insID])
        elseif insID > 0 then
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d = wd:GetHallDepotItemDataByInsID(insID)
            if d and d.resID then skin = tonumber(d.resID) end
        end
    end)
    if skin and skin > 0 then return skin end

    pcall(function()
        local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
        if wgl.GetSkinIdByWeaponID and wid > 0 then
            local insID = tonumber(wgl:GetSkinIdByWeaponID(wid)) or 0
            if insID > 0 and F.isInjectedIns(insID) then
                skin = tonumber(R.insToRes[insID])
            end
        end
    end)
    LOBBY.skinResolved = true
    LOBBY.cachedSkin = (skin and skin > 0) and skin or nil
    return LOBBY.cachedSkin
end

function F.resolveLobbyOutfitRes()
    if LOBBY.outfitResolved and LOBBY.cachedOutfit then return LOBBY.cachedOutfit end
    LOBBY.outfitResolved = false
    LOBBY.cachedOutfit = nil
    local cch = F.cache()
    local outfitRes = tonumber(cch.outfitRes) or 0
    if outfitRes > 0 then
        LOBBY.outfitResolved = true
        LOBBY.cachedOutfit = outfitRes
        return outfitRes
    end
    outfitRes = tonumber(_G.AddOutfitLastLobbyOutfitRes) or 0
    if outfitRes > 0 then
        LOBBY.outfitResolved = true
        LOBBY.cachedOutfit = outfitRes
        return outfitRes
    end
    if MATCH_CONFIG.outfitRes and tonumber(MATCH_CONFIG.outfitRes) > 0 then
        LOBBY.outfitResolved = true
        LOBBY.cachedOutfit = tonumber(MATCH_CONFIG.outfitRes)
        return LOBBY.cachedOutfit
    end

    local injectedRes, anyRes
    pcall(function()
        local AvatarData = require("client.logic.data.AvatarData")
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local function resFromIns(ins)
            ins = tonumber(ins)
            if not ins or ins <= 0 then return nil end
            if F.isInjectedIns(ins) then return tonumber(R.insToRes[ins]) end
            local d = wd:GetHallDepotItemDataByInsID(ins)
            return d and tonumber(d.resID) or nil
        end
        for _, ins in pairs(AvatarData.GetRoleWear()) do
            local res = resFromIns(ins)
            if res and F.isSuitRes(res) then
                if F.isInjectedRes(res) then injectedRes = res end
                anyRes = anyRes or res
            end
        end
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
        if bag and bag.rolewear_list then
            for _, ins in pairs(bag.rolewear_list) do
                local res = resFromIns(ins)
                if res and F.isSuitRes(res) then
                    if F.isInjectedRes(res) then injectedRes = res end
                    anyRes = anyRes or res
                end
            end
        end
    end)
    if injectedRes and injectedRes > 0 then
        LOBBY.outfitResolved = true
        LOBBY.cachedOutfit = injectedRes
        return injectedRes
    end
    if anyRes and anyRes > 0 then
        LOBBY.outfitResolved = true
        LOBBY.cachedOutfit = anyRes
        return anyRes
    end
    LOBBY.outfitResolved = true
    LOBBY.cachedOutfit = nil
    return nil
end

function F.rememberLobbyOutfitRes(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 or not F.isSuitRes(resID) then return end
    _G.AddOutfitLastLobbyOutfitRes = resID
    F.invalidateLobbyResolved()
    local cch = F.cache()
    if not cch.outfitRes or cch.outfitRes <= 0 then
        cch.outfitRes = resID
        if F.isInjectedRes(resID) then cch.outfitIns = R.resToIns[resID] end
    end
end

function F.wearPatchKey()
    local outfit = F.resolveLobbyOutfitRes() or 0
    local skin = F.resolveLobbyWeaponSkinRes() or 0
    local openGun = 1
    pcall(function()
        local lds = require("client.slua.logic.wardrobe.logic_display_setting")
        if lds.data and lds.data.OpenGun ~= nil then openGun = lds.data.OpenGun and 1 or 0 end
    end)
    return outfit .. "_" .. skin .. "_" .. openGun
end

function F.syncDepotShowWeaponFlags(depot)
    depot = depot or {}
    pcall(function()
        local lds = require("client.slua.logic.wardrobe.logic_display_setting")
        if lds.data then
            if lds.data.OpenGun ~= nil then depot.weapon = lds.data.OpenGun end
            if lds.data.OpenSocialWeapon ~= nil then depot.social_weapon = lds.data.OpenSocialWeapon end
        end
    end)
    return depot
end

function F.applyInjectedPspace(roleData)
    if not roleData then return end
    roleData.bshow = true
    roleData.pspace_wear_ext = roleData.pspace_wear_ext or {}
    local outfitRes = F.resolveLobbyOutfitRes()
    if outfitRes and outfitRes > 0 then
        roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH] = { outfitRes, 0, 0 }
    end
    local skinRes = F.resolveLobbyWeaponSkinRes()
    if skinRes and skinRes > 0 then
        roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON] = { 0, 0, 0 }
        roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN] = { skinRes, 0, 0 }
        roleData.depot_show_info = roleData.depot_show_info or {}
        if roleData.depot_show_info.weapon == nil then
            roleData.depot_show_info.weapon = true
        end
    end
    roleData.depot_show_info = F.syncDepotShowWeaponFlags(roleData.depot_show_info)
end

function F.patchSelfWearCache(force)
    local key = F.wearPatchKey()
    if not force and SOCIAL.wearPatchKey == key then return false end
    SOCIAL.wearPatchKey = key
    SOCIAL.snapshotKey = nil
    SOCIAL.fullSnapshot = nil

    local myUid = tonumber(DataMgr.roleData.uid)
    if not myUid then return false end

    local changed = false
    pcall(function()
        local BD = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo)
        local d = BD:GetCacheData(myUid)
        if not d then
            BD:OnHandleMsgDataAndCallback(myUid, F.buildLocalRoleDataForCoupleAvatar())
            return true
        end
        local oldCloth = d.pspace_wear_ext and d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH]
        local oldSkin = d.pspace_wear_ext and d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN]
        F.applyInjectedPspace(d)
        local nc = d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH]
        local ns = d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN]
        if oldCloth ~= nc or oldSkin ~= ns or not d.bshow then changed = true end
    end)
    return force or changed
end

function F.requestSocialAvatarRefresh()
    pcall(function()
        if EventSystem and EVENTTYPE_LOBBY_SOCIAL and EVENTID_SOCIAL_LOBBY_REFRESH_AVATAR then
            EventSystem:postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_SOCIAL_LOBBY_REFRESH_AVATAR)
        end
    end)
end

function F.onSocialWearDirty(forceRefresh)
    SOCIAL.lastHandSkin = nil
    if F.patchSelfWearCache(forceRefresh) then
        F.requestSocialAvatarRefresh()
    end
end

function F.buildLocalRoleDataForCoupleAvatar()
    local key = F.wearPatchKey()
    if SOCIAL.fullSnapshot and SOCIAL.snapshotKey == key then
        return SOCIAL.fullSnapshot
    end
    F.syncWeaponCacheFromLobby()
    local cch = F.cache()
    local ad = DataMgr.avatarData or {}
    local gender = tonumber(ad.gamegender) or 2
    if gender < 1 then gender = 2 end

    local data = {
        uid = DataMgr.roleData.uid,
        gender = gender,
        bshow = true,
        pspace_wear_ext = {
            [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HEAD] = { tonumber(ad.headid) or 401993, 0, 0 },
            [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HAIR] = { tonumber(ad.hairid) or 40601001, 0, 0 },
            [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON] = { 0, 0, 0 },
            [ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN] = { 0, 0, 0 },
        },
        depot_show_info = {
            weapon = true, social_weapon = true, idle = true,
            helmet = true, bag = true, vehicle = true, hand = true,
        },
    }

    local outfitRes = F.resolveLobbyOutfitRes()
    if outfitRes and outfitRes > 0 then
        data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH] = { outfitRes, 0, 0 }
    end

    local skinRes = F.resolveLobbyWeaponSkinRes()
    if skinRes and skinRes > 0 then
        data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON][1] = 0
        data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN][1] = skinRes
    end
    data.depot_show_info = F.syncDepotShowWeaponFlags(data.depot_show_info)
    SOCIAL.fullSnapshot = data
    SOCIAL.snapshotKey = F.wearPatchKey()
    return data
end

local _myUidCached
function F.isMyWearData(wearData)
    if not wearData then return false end
    if not _myUidCached then
        pcall(function() _myUidCached = tonumber(DataMgr.roleData.uid) end)
    end
    return _myUidCached and tonumber(wearData.uid) == _myUidCached
end

function F.mergeInjectedWeaponIntoWearData(wearData)
    if not F.isMyWearData(wearData) then return end
    local skinRes = F.resolveLobbyWeaponSkinRes()
    wearData.depot_show_info = F.syncDepotShowWeaponFlags(wearData.depot_show_info)
    if not skinRes or skinRes <= 0 then return end
    wearData.mainWeaponInfo = wearData.mainWeaponInfo or {
        weaponResId = 0, weaponSkinId = 0,
        diyInfo = { diyWeaponId = 0, diyDefaultScheme = false, diyScheme = nil },
    }
    if wearData.mainWeaponInfo.weaponSkinId == skinRes
        and (tonumber(wearData.mainWeaponInfo.weaponResId) or 0) == 0 then
        return
    end
    wearData.mainWeaponInfo.weaponSkinId = skinRes
    wearData.mainWeaponInfo.weaponResId = 0
end

function F.equipSocialHandWeapon(avatar, skinRes)
    if not avatar or not skinRes or skinRes <= 0 then return end
    if SOCIAL.lastHandSkin == skinRes then return end
    SOCIAL.lastHandSkin = skinRes
    pcall(function()
        avatar:PutonEquipment(skinRes, nil, { bIsUse = true })
    end)
end

function F.shouldShowHandWeapon()
    local show = true
    pcall(function()
        local lds = require("client.slua.logic.wardrobe.logic_display_setting")
        if lds.data and lds.data.OpenGun ~= nil then
            show = lds.data.OpenGun ~= false
        end
    end)
    return show
end

function F.mergeInjectedOutfitIntoWearData(wearData)
    if not F.isMyWearData(wearData) then return end
    local outfitRes = F.resolveLobbyOutfitRes()
    if not outfitRes or outfitRes <= 0 then return end
    F.rememberLobbyOutfitRes(outfitRes)
    local AvatarData = require("client.logic.data.AvatarData")
    local converted = AvatarData.ConvertToAvatarCustom({ outfitRes, 0, 0 })
    if not converted then return end
    wearData.WearInfoList = wearData.WearInfoList or {}
    local replaced = false
    for i, e in ipairs(wearData.WearInfoList) do
        if e and e.ItemID and F.isSuitRes(e.ItemID) then
            wearData.WearInfoList[i] = converted
            replaced = true
            break
        end
    end
    if not replaced then
        table.insert(wearData.WearInfoList, converted)
    end
end

function F.mergeInjectedIntoWearData(wearData)
    if not wearData then return end
    F.mergeInjectedWeaponIntoWearData(wearData)
    F.mergeInjectedOutfitIntoWearData(wearData)
end

function F.reapplyLobbyEquipped()
    if not GameStatus or not GameStatus.IsInLobbyOrMainCity or not GameStatus.IsInLobbyOrMainCity() then
        return
    end
    F.syncWeaponCacheFromLobby()
    F.applyPersistSlotsToCache()
    local curPage = F.getLobbyCurPage()

    if ENUM_LobbyPageType and curPage == ENUM_LobbyPageType.Left then
        F.onSocialWearDirty(true)
        return
    end

    local cch = F.cache()
    if cch.outfitIns and F.isInjectedIns(cch.outfitIns) then
        F.putOnOutfit(cch.outfitIns)
    end
    if cch.hatIns and F.isInjectedIns(cch.hatIns) then
        F.putOnHat(cch.hatIns)
    end
    if cch.maskIns and F.isInjectedIns(cch.maskIns) then
        F.putOnRoleWear(cch.maskIns)
    end
    if cch.glassIns and F.isInjectedIns(cch.glassIns) then
        F.putOnRoleWear(cch.glassIns)
    end
    if cch.tshirtIns and F.isInjectedIns(cch.tshirtIns) then
        F.putOnRoleWear(cch.tshirtIns)
    end
    if cch.pantsIns and F.isInjectedIns(cch.pantsIns) then
        F.putOnRoleWear(cch.pantsIns)
    end
    if cch.shoesIns and F.isInjectedIns(cch.shoesIns) then
        F.putOnRoleWear(cch.shoesIns)
    end
    if cch.bagIns and F.isInjectedIns(cch.bagIns) then
        F.putOnRoleWear(cch.bagIns)
    end
    if cch.helmetIns and F.isInjectedIns(cch.helmetIns) then
        F.putOnRoleWear(cch.helmetIns)
    end
    if cch.parachuteIns then
        F.putOnParachute(cch.parachuteIns)
    end
    if cch.gliderIns then
        F.putOnGlider(cch.gliderIns)
    end
    if cch.glovesIns and F.isInjectedIns(cch.glovesIns) then
        F.putOnGloves(cch.glovesIns)
    end

    F.reapplyLobbyCurrentWeapon()
    F.reapplyVehicleSlotsFromConfig(true)
    F.reapplyHallThemeFromConfig(true)
    F.reapplyWeaponsFromConfig()
    pcall(F.applyVehicleSkinsToPC)
    if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModPet then
        pcall(F.injectAllPets)
        pcall(F.applyPersistedPet)
    end
end

-- Lightweight: only restore mod skin for the gun currently shown in lobby
function F.reapplyLobbyCurrentWeapon()
    if not GameStatus or not GameStatus.IsInLobbyOrMainCity or not GameStatus.IsInLobbyOrMainCity() then
        return
    end
    F.syncWeaponCacheFromLobby()
    local cch = F.cache()
    local displayWid = tonumber(DataMgr.Weapon_ID) or 0
    if displayWid <= 0 then return end
    local w = cch.weapons[displayWid]
    -- Legacy: Weapon_ID=108 → resolve via mapped skin if present
    if (not w or not w.resID) and displayWid == MELEE_ID then
        for wid, ww in pairs(cch.weapons or {}) do
            wid = tonumber(wid)
            if wid and wid >= 108000 and wid < 109000 and ww and ww.resID then
                w = ww
                displayWid = wid
                break
            end
        end
    end
    if not w or not w.resID or w.resID <= 0 then return end
    if w.insID and F.isInjectedIns(w.insID) then
        local prev = _G.AddOutfitSkipGunReapply
        _G.AddOutfitSkipGunReapply = true
        pcall(function() F.equipWeaponSkin(displayWid, w.insID) end)
        _G.AddOutfitSkipGunReapply = prev
        pcall(function()
            local uid = tostring(DataMgr.roleData.uid)
            local LAM = require("client.logic.avatar.LobbyAvatarManager")
            local TAM = require("client.logic.avatar.logic_team_avatar_manager")
            if TAM.GetAvatarByUid(uid) then
                LAM.EquipWeapon(uid, { weaponId = displayWid, skinId = w.resID }, nil, true)
            end
        end)
    else
        pcall(function() DataMgr.InitWeaponData(displayWid, w.resID, w.insID or 0) end)
    end
end

F.scheduleLobbyReapplyOnce = function()
    if LOBBY.reapplyDone or LOBBY.reapplyScheduled then return end
    LOBBY.reapplyScheduled = true
    F.later(2.0, function()
        LOBBY.reapplyScheduled = false
        if LOBBY.reapplyDone then return end
        LOBBY.reapplyDone = true
        F.reapplyLobbyEquipped()
    end)
end

function F.hookBattleResultSkins()
    if _G.AddOutfitBattleResultHooked then return end
    _G.AddOutfitBattleResultHooked = true

    pcall(function()
        local M = require("GameLua.Mod.BaseMod.Client.BattleResult.BattleResultData.BattleResultDataLogic")
        local impl = M and (M.__inner_impl or M)
        if not impl or not impl.OnBattleResult or impl._AddOutfitBRDataHooked then return end
        impl._AddOutfitBRDataHooked = true
        local o = impl.OnBattleResult
        impl.OnBattleResult = function(self, result)
            if result and result.TeammateList then
                F.patchSelfInTeammateList(result.TeammateList)
            end
            return o(self, result)
        end
    end)

    pcall(function()
        local M = require("GameLua.Mod.Library.Client.BattleResultLib.SpecialShow.Logic.BattleResultSpecialShowBaseLogic")
        local impl = M and (M.__inner_impl or M)
        if not impl or not impl.PutOnAvatar or impl._AddOutfitBRPutOnHooked then return end
        impl._AddOutfitBRPutOnHooked = true
        local o = impl.PutOnAvatar
        impl.PutOnAvatar = function(self, InPawn, InData)
            if InData and InData.wear_ext and F.isSelfUid(InData.UID) then
                F.patchSelfBattleResultWearExt(InData.wear_ext)
            end
            return o(self, InPawn, InData)
        end
    end)

    pcall(function()
        local M = require("GameLua.Mod.BaseMod.Client.BattleResult.ShowAvatar.BattleResultShowAvatarLogic")
        local impl = M and (M.__inner_impl or M)
        if not impl or not impl.InitRoleInfoList or impl._AddOutfitBRAvatarHooked then return end
        impl._AddOutfitBRAvatarHooked = true
        local oInit = impl.InitRoleInfoList
        impl.InitRoleInfoList = function(self, result)
            if result and result.TeammateList then
                F.patchSelfInTeammateList(result.TeammateList)
            end
            return oInit(self, result)
        end
        if impl.OnResultProcessStart then
            local oStart = impl.OnResultProcessStart
            impl.OnResultProcessStart = function(self, ...)
                F.prepareBattleResultWearPatch()
                F.patchSelfWearCache(true)
                return oStart(self, ...)
            end
        end
    end)

    pcall(function()
        local M = require("GameLua.Mod.BaseMod.Client.BattleResult.ShowMvp.BattleResultShowMvpLogic")
        local impl = M and (M.__inner_impl or M)
        if not impl or impl._AddOutfitBRMvpHooked then return end
        impl._AddOutfitBRMvpHooked = true
        if impl.InitBRModeMvpInfo then
            local o = impl.InitBRModeMvpInfo
            impl.InitBRModeMvpInfo = function(self, result)
                if result and result.TeammateList then
                    F.patchSelfInTeammateList(result.TeammateList)
                end
                return o(self, result)
            end
        end
        if impl._InitTDMModeMvpInfo then
            local o = impl._InitTDMModeMvpInfo
            impl._InitTDMModeMvpInfo = function(self, list)
                F.patchSelfInTeammateList(list)
                return o(self, list)
            end
        end
        if impl.OnResultProcessStart then
            local oStart = impl.OnResultProcessStart
            impl.OnResultProcessStart = function(self, ...)
                F.prepareBattleResultWearPatch()
                F.patchSelfWearCache(true)
                return oStart(self, ...)
            end
        end
    end)
end

function F.hookLobbySwipePersistence()
    if _G.AddOutfitLobbySwipeHooked then return end
    _G.AddOutfitLobbySwipeHooked = true
    pcall(function()
        local BD = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo)
        local oRsp = BD.on_get_avatar_show_rsp
        BD.on_get_avatar_show_rsp = function(self, res, target_uid, data)
            if tonumber(target_uid) == tonumber(DataMgr.roleData.uid) and data then
                F.applyInjectedPspace(data)
            end
            oRsp(self, res, target_uid, data)
                if tonumber(target_uid) == tonumber(DataMgr.roleData.uid) then
                F.patchSelfWearCache(true)
                SOCIAL.forceAvatarRedraw = true
                SOCIAL.lastHandSkin = nil
                if ENUM_LobbyPageType and F.getLobbyCurPage() == ENUM_LobbyPageType.Left then
                    F.requestSocialAvatarRefresh()
                end
            end
        end
    end)

    pcall(function()
        local AC = require("client.slua.logic.avatar.avatar_common")
        local oGetWear = AC.GetWearDataFromRoleData
        AC.GetWearDataFromRoleData = function(roleData)
            local wearData = oGetWear(roleData)
            if wearData and roleData and tonumber(roleData.uid) == tonumber(DataMgr.roleData.uid)
                and F.shouldApplySelfOutfitPatch() then
                F.mergeInjectedIntoWearData(wearData)
            end
            return wearData
        end
        local oUp = AC.UpdateAvatar
        AC.UpdateAvatar = function(avatar, wearData, isShowWeapon, isShowHelmet, isShowBag)
            if F.isMyWearData(wearData) and F.shouldApplySelfOutfitPatch() then
                F.mergeInjectedIntoWearData(wearData)
            end
            local showGun = isShowWeapon and F.shouldShowHandWeapon()
            if wearData and wearData.depot_show_info then
                showGun = showGun and wearData.depot_show_info.weapon ~= false
            end
            if F.isMyWearData(wearData) and F.shouldApplySelfOutfitPatch() then
                for _, e in ipairs(wearData.WearInfoList or {}) do
                    if e and e.ItemID and F.isSuitRes(e.ItemID) then
                        F.rememberLobbyOutfitRes(e.ItemID)
                        break
                    end
                end
            end
            local ret = oUp(avatar, wearData, showGun, isShowHelmet, isShowBag)
            if showGun and F.isMyWearData(wearData) and avatar and F.shouldApplySelfOutfitPatch() then
                local skin = tonumber(wearData.mainWeaponInfo and wearData.mainWeaponInfo.weaponSkinId) or 0
                if skin <= 0 then skin = F.resolveLobbyWeaponSkinRes() or 0 end
                if skin > 0 then F.equipSocialHandWeapon(avatar, skin) end
            end
            return ret
        end
    end)

    pcall(function()
        local CA = require("client.logic.avatar.CoupleAvatar")
        local Cfg = require("client.slua.logic.lobby.Left.CoupleAvatarConfig")
        local oMulti = CA._UpdateMultiAvatar
        if oMulti then
            CA._UpdateMultiAvatar = function(self, avatar, avatarType)
                local isSelf = avatarType == Cfg.AvatarType.Self
                    and self.SelfUID and tostring(self.SelfUID) == tostring(DataMgr.roleData.uid)
                if isSelf and F.shouldApplySelfOutfitPatch() then
                    pcall(function()
                        local BD = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo)
                        local d = BD:GetCacheData(tonumber(self.SelfUID))
                        if d then F.applyInjectedPspace(d) end
                    end)
                    if SOCIAL.forceAvatarRedraw then
                        self.CompareDataCache[avatarType] = nil
                        SOCIAL.forceAvatarRedraw = nil
                    end
                end
                oMulti(self, avatar, avatarType)
                if isSelf and F.shouldApplySelfOutfitPatch() and self.isShowWeapon ~= false and F.shouldShowHandWeapon() then
                    local skin = F.resolveLobbyWeaponSkinRes()
                    if skin and skin > 0 then F.equipSocialHandWeapon(avatar, skin) end
                end
            end
        end
        local oHideCheck = CA.CheckSelfIsHideAvatar
        CA.CheckSelfIsHideAvatar = function(self, nSelfUId, tRoleData)
            if F.shouldApplySelfOutfitPatch() and tostring(nSelfUId) == tostring(DataMgr.roleData.uid) then
                return false
            end
            return oHideCheck(self, nSelfUId, tRoleData)
        end

        local oUpdate = CA.Update
        CA.Update = function(self)
            if not F.shouldApplySelfOutfitPatch() and not F.isLobbyLeftPage() then
                return oUpdate(self)
            end
            local isSelf = self.SelfUID and tostring(self.SelfUID) == tostring(DataMgr.roleData.uid)
            local oHide = CA.HideAvatars
            if isSelf then
                CA.HideAvatars = function() end
            end
            local ok, err = pcall(oUpdate, self)
            CA.HideAvatars = oHide
        end

        local oRecv = CA.OnReceiveData
        CA.OnReceiveData = function(self, uid, data)
            if tostring(uid) == tostring(DataMgr.roleData.uid) and F.shouldApplySelfOutfitPatch() then
                if data then
                    F.applyInjectedPspace(data)
                else
                    data = F.buildLocalRoleDataForCoupleAvatar()
                end
            end
            return oRecv(self, uid, data)
        end
    end)

    pcall(function()
        if not EventSystem or not EventSystem.registEvent then return end
        if EVENTTYPE_LOBBY and EVENTID_SWITCHTO_PAGE_START then
            EventSystem:registEvent(EVENTTYPE_LOBBY, EVENTID_SWITCHTO_PAGE_START, function(_, _, toPage)
                if ENUM_LobbyPageType and toPage == ENUM_LobbyPageType.Left then
                    F.syncWeaponCacheFromLobby()
                    SOCIAL.lastHandSkin = nil
                    local o = F.resolveLobbyOutfitRes()
                    if o then F.rememberLobbyOutfitRes(o) end
                    F.patchSelfWearCache(true)
                    SOCIAL.forceAvatarRedraw = true
                end
            end)
        end
        if EVENTTYPE_LOBBY and EVENTID_SWITCHTO_PAGE_END then
            EventSystem:registEvent(EVENTTYPE_LOBBY, EVENTID_SWITCHTO_PAGE_END, function(_, _, _, toPage)
                if ENUM_LobbyPageType and toPage == ENUM_LobbyPageType.Left then
                    F.syncWeaponCacheFromLobby()
                    SOCIAL.lastHandSkin = nil
                    F.socialDebounce(0.45, function()
                        F.onSocialWearDirty(true)
                    end)
                elseif ENUM_LobbyPageType and toPage == ENUM_LobbyPageType.Mid then
                    SOCIAL.wearPatchKey = nil
                    F.invalidateLobbyResolved()
                    if not LOBBY.reapplyDone then
                        F.socialDebounce(0.5, F.scheduleLobbyReapplyOnce)
                    end
                end
            end)
        end
        if EVENTTYPE_LOBBY_SOCIAL and EVENTID_GOT_SOCIAL_LOBBY_SHOW_DATA then
            EventSystem:registEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_GOT_SOCIAL_LOBBY_SHOW_DATA, function(_, _, nUId)
                if tonumber(nUId) == tonumber(DataMgr.roleData.uid) then
                    F.socialDebounce(0.2, function() F.patchSelfWearCache(false) end)
                end
            end)
        end
        if EVENTTYPE_ROLEINFO and EVENTID_ROLEINFO_UPDATE_ROLEINFO then
            EventSystem:registEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_ROLEINFO, function()
                F.invalidateLobbyResolved()
                F.patchSelfWearCache(true)
                F.requestSocialAvatarRefresh()
            end)
        end
        if EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
            EventSystem:registEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN, function()
                if _G.AddOutfitSkipGunReapply then return end
                SOCIAL.wearPatchKey = nil
                SOCIAL.snapshotKey = nil
                F.syncWeaponCacheFromLobby()
                
                local curPage = ENUM_LobbyPageType and F.getLobbyCurPage()
                if curPage == ENUM_LobbyPageType.Left then
                    F.socialDebounce(0.25, function() F.onSocialWearDirty(true) end)
                end
                
                -- Only re-apply current gun skin (full lobby reapply caused lag on every switch)
                F.socialDebounce(0.3, function()
                    if F.reapplyLobbyCurrentWeapon then F.reapplyLobbyCurrentWeapon() end
                end)
            end)
        end
    end)

    pcall(function()
        local lds = require("client.slua.logic.wardrobe.logic_display_setting")
        local oSwitch = lds.SwitchGun
        lds.SwitchGun = function(...)
            local r = oSwitch(...)
            if _G.AddOutfitSkipGunReapply then return r end
            SOCIAL.wearPatchKey = nil
            
            local curPage = ENUM_LobbyPageType and F.getLobbyCurPage()
            if curPage == ENUM_LobbyPageType.Left then
                F.socialDebounce(0.2, function() F.onSocialWearDirty(true) end)
            end
            
            F.socialDebounce(0.3, function()
                if F.reapplyLobbyCurrentWeapon then F.reapplyLobbyCurrentWeapon() end
            end)
            
            return r
        end
    end)
end

function F.hookDepotInit()
    pcall(function()
        local WDE = require("client.slua.logic.wardrobe.WardrobeDataEntity")
        if WDE._AddOutfitInitHooked then return end
        WDE._AddOutfitInitHooked = true
        local orig = WDE.InitData
        WDE.InitData = function(self, pkg)
            orig(self, pkg)
            _G.AddOutfitUnexpireDone = false
            pcall(function()
                if F.injectAll(self) then
                    F.scheduleInjectRefresh()
                    LOBBY.reapplyDone = false
                    LOBBY.reapplyScheduled = false
                    F.scheduleLobbyReapplyOnce()
                end
            end)
        end
    end)
end

function F.hookWardrobeData()
    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        if wd._AddOutfitDataHooked then return end
        wd._AddOutfitDataHooked = true
        local function wrapGet(name)
            local o = wd[name]
            if not o then return end
            wd[name] = function(self, insID, ...)
                insID = tonumber(insID)
                local r
                if F.isInjectedIns(insID) then
                    local e = F.getEntity()
                    if e then r = e:GetDataByInsID(insID) end
                else
                    r = o(self, insID, ...)
                end
                if r and (tonumber(r.count) or 0) <= 0 then return nil end
                if r and (F.isInjectedIns(insID) or F.isInjectedRes(r.resID or r.res_id)) then
                    r.expire_ts = 0
                    r.expireTS = 0
                    r.valid_hours = 0
                end
                return r
            end
        end
        wrapGet("GetHallDepotItemDataByInsID")
        wrapGet("GetValidHallDepotItemDataByInsID")
        local oCountByRes = wd.GetHallDepotItemCountByResID
        if oCountByRes then
            F._wardrobeOrigCountByRes = oCountByRes
            wd.GetHallDepotItemCountByResID = function(self, resID, ...)
                resID = tonumber(resID)
                -- XSuit mat ảo (UnlimitedCash-style) — ưu tiên trước count thật
                if resID and type(FLS) == "table" and FLS.IsEnabled and FLS.IsEnabled()
                    and FLS.getXSuitVirtualMatCount then
                    local vn = tonumber(FLS.getXSuitVirtualMatCount(resID)) or 0
                    if vn > 0 then return vn end
                end
                local n = tonumber(oCountByRes(self, resID, ...)) or 0
                if n <= 0 and resID then
                    local c = F.getEntityDepotCount and F.getEntityDepotCount(resID) or 0
                    if c > 0 then return c end
                end
                return n
            end
        end
        local oCountValid = wd.GetHallDepotItemCountByResIDAndValidInfo
        if oCountValid then
            wd.GetHallDepotItemCountByResIDAndValidInfo = function(self, resID, isValidTime, ...)
                resID = tonumber(resID)
                if resID and type(FLS) == "table" and FLS.IsEnabled and FLS.IsEnabled()
                    and FLS.getXSuitVirtualMatCount then
                    local vn = tonumber(FLS.getXSuitVirtualMatCount(resID)) or 0
                    if vn > 0 then return vn end
                end
                local n = tonumber(oCountValid(self, resID, isValidTime, ...)) or 0
                if n <= 0 and resID then
                    local c = F.getEntityDepotCount and F.getEntityDepotCount(resID) or 0
                    if c > 0 then return c end
                end
                return n
            end
        end
        local oDataValidExpire = wd.GetHallDepotItemDataByResIDAndValidExpireTime
        if oDataValidExpire then
            wd.GetHallDepotItemDataByResIDAndValidExpireTime = function(self, resID, ...)
                local r = oDataValidExpire(self, resID, ...)
                if r and (tonumber(r.count) or 0) > 0 then return r end
                resID = tonumber(resID)
                if resID and (F.isInjectedRes(resID) or (F.getEntityDepotCount and F.getEntityDepotCount(resID) > 0)) then
                    local e = F.getEntity()
                    local ins = R.resToIns[resID] or (e and F.firstInsForRes and F.firstInsForRes(e, resID))
                    local d = e and ins and e.GetDataByInsID and e:GetDataByInsID(ins)
                    if d and (tonumber(d.count) or 0) > 0 then return d end
                end
                return r
            end
        end
        local oListByRes = wd.GetHallDepotItemListByResID
        if oListByRes then
            wd.GetHallDepotItemListByResID = function(self, resID, ...)
                resID = tonumber(resID)
                if resID and F.isInjectedRes(resID) and F.isInjectedDepotAlive(resID) then
                    local e = F.getEntity()
                    local ins = R.resToIns[resID]
                    local d = e and ins and e.GetDataByInsID and e:GetDataByInsID(ins)
                    if d and (tonumber(d.count) or 0) > 0 then return { d } end
                    return {}
                end
                return oListByRes(self, resID, ...)
            end
        end
        local function wrapBool(name)
            local o = wd[name]
            if not o then return end
            wd[name] = function(self, id, ...)
                id = tonumber(id)
                if id and (F.isInjectedRes(id) or F.isInjectedIns(id)) then
                    if F.isInjectedIns(id) then
                        return F.isInjectedDepotAlive(nil, id)
                    end
                    return F.isInjectedDepotAlive(id, nil)
                end
                return o(self, id, ...)
            end
        end
        wrapBool("HasItem")
        wrapBool("HasValidItem")
        wrapBool("CheckHasPermanentItem")
    end)
end

function F.hookPageFilter()
    pcall(function()
        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
        if wl._AddOutfitPageFilterHooked then return end
        wl._AddOutfitPageFilterHooked = true
        local o1 = wl.IsValidCurrentPageItem
        wl.IsValidCurrentPageItem = function(self, mainTab, subTab, v, t)
            if v then
                local cnt = tonumber(v.count)
                if cnt ~= nil and cnt <= 0 then
                    return o1(self, mainTab, subTab, v, t)
                end
            end
            local resID = v and tonumber(v.resID or v.res_id)
            if v and resID and F.isInjectedRes(resID) then
                if not F.isInjectedDepotAlive(resID) then
                    return o1(self, mainTab, subTab, v, t)
                end
                -- Emote/Hành động: trang Parachute (5) + subTab MVP_MOTION (21)
                if F.isEmoteRes(resID) then
                    local c = F.cfg(resID)
                    local main = tonumber(c and c.WardrobeMainTab) or PAGE_PARACHUTE
                    local itemTab = (c and c.WardrobeTab) or v.subTabType or F.wardrobeTab(resID) or 21
                    if itemTab == 0 or itemTab == "" then itemTab = 21 end
                    v.mainTabType = main
                    v.subTabType = itemTab
                    if v.resID == nil then v.resID = resID end
                    v.expire_ts = 0
                    v.expireTS = 0
                    return F.tabsEqual(mainTab, main) and F.tabsEqual(itemTab, subTab)
                end
                -- Strict vehicle tab: never treat missing/0 as "show on all vehicle types"
                if mainTab == PAGE_VEHICLE and F.isVehicleRes(resID) then
                    local itemTab = v.subTabType
                    if itemTab == nil or itemTab == 0 or itemTab == "" then
                        itemTab = F.vehicleWardrobeTab(resID)
                        if itemTab ~= nil and itemTab ~= 0 and itemTab ~= "" then
                            v.subTabType = itemTab
                            v.mainTabType = PAGE_VEHICLE
                        end
                    end
                    return F.tabsEqual(itemTab, subTab)
                end
                local itemTab = v.subTabType
                if itemTab == nil or itemTab == 0 or itemTab == "" then
                    itemTab = F.wardrobeTab(resID)
                end
                if itemTab and F.tabsEqual(itemTab, subTab) then
                    if mainTab == PAGE_AVATAR then
                        if F.isVehicleRes(resID) or F.isWeaponSkinRes(resID) then
                            return o1(self, mainTab, subTab, v, t)
                        end
                        return true
                    end
                    -- Parachute page: dù / glider / plane / theme / MVP… (không chỉ hall theme)
                    if mainTab == PAGE_PARACHUTE then
                        if F.isWeaponSkinRes(resID) then
                            return o1(self, mainTab, subTab, v, t)
                        end
                        -- Xe combat (Coupe/Moto…) không hiện ở trang dù; plane/wingman giữ nếu đúng WardrobeTab
                        local mainCfg = tonumber((F.cfg(resID) or {}).WardrobeMainTab)
                        if F.isVehicleRes(resID) and mainCfg == PAGE_VEHICLE then
                            return o1(self, mainTab, subTab, v, t)
                        end
                        return true
                    end
                end
            end
            return o1(self, mainTab, subTab, v, t)
        end
        local o2 = wl.IsCanUse
        wl.IsCanUse = function(self, resId)
            if F.isInjectedRes(resId) then return F.isInjectedDepotAlive(resId) end
            return o2(self, resId)
        end
        local o3 = wl.IsCharacterUse
        wl.IsCharacterUse = function(self, resId)
            if F.isInjectedRes(resId) then return F.isInjectedDepotAlive(resId) end
            return o3(self, resId)
        end
        local o4 = wl.GetWardrobeInsIdByResId
        wl.GetWardrobeInsIdByResId = function(self, resid)
            resid = tonumber(resid)
            if F.isInjectedRes(resid) then
                if not F.isInjectedDepotAlive(resid) then return nil end
                return R.resToIns[resid]
            end
            return o4(self, resid)
        end
    end)
end

function F.hookArmory()
    pcall(function()
        local Arm = require("client.logic.armory.logic_armory")
        if Arm._AddOutfitArmoryHooked then return end
        Arm._AddOutfitArmoryHooked = true
        local oa = Arm.get_weapon_skin_list_rsp
        Arm.get_weapon_skin_list_rsp = function(a, b, c, d)
            oa(a, b, c, d)
            F.mergeInjectedArmorySkins()
        end
        local oi = Arm.install_weapon_skin
        Arm.install_weapon_skin = function(cd, wid, ins)
            ins = tonumber(ins)
            if F.isWeaponSkinIns(ins) then
                wid = tonumber(F.weaponIdFromSkin(R.insToRes[ins]) or wid)
                F.equipWeaponSkin(wid, ins)
                return
            end
            return oi(cd, wid, ins)
        end
    end)
    pcall(function()
        local AH = require("client.network.Protocol.ArmoryHandler")
        if AH._AddOutfitArmorySendHooked then return end
        AH._AddOutfitArmorySendHooked = true
        local o = AH.send_install_weapon_skin
        AH.send_install_weapon_skin = function(cd, wid, ins)
            ins = tonumber(ins)
            if F.isWeaponSkinIns(ins) then
                wid = tonumber(F.weaponIdFromSkin(R.insToRes[ins]) or wid)
                F.equipWeaponSkin(wid, ins)
                return
            end
            return o(cd, wid, ins)
        end
    end)
end

function F.hookGunSkinId()
    pcall(function()
        local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
        if wgl._AddOutfitGunSkinHooked then return end
        wgl._AddOutfitGunSkinHooked = true
        local o = wgl.GetSkinIdByWeaponID
        wgl.GetSkinIdByWeaponID = function(self, wid)
            local c = F.cache()
            local w = c.weapons[wid]
            if w and F.isWeaponSkinIns(w.insID) then return w.insID end
            local Arm = require("client.logic.armory.logic_armory")
            if Arm.rsp_list and Arm.rsp_list.install_list and Arm.rsp_list.install_list[wid] then
                local sid = Arm.rsp_list.install_list[wid].skin_id
                if sid and F.isWeaponSkinIns(sid) then return sid end
            end
            return o(self, wid)
        end
    end)
end

function F.hookPutOn()
    pcall(function()
        local WRH = require("client.network.Protocol.WardRobeHandler")
        if WRH._AddOutfitPutOnHooked then return end
        WRH._AddOutfitPutOnHooked = true
        local o = WRH.send_depot_put_on_req
        WRH.send_depot_put_on_req = function(insID, extra)
            insID = tonumber(insID)
            if F.tryLocalWearByIns(insID) then return end
            return o(insID, extra)
        end
    end)
end

function F.hookPutDown()
    pcall(function()
        local WRH = require("client.network.Protocol.WardRobeHandler")
        if WRH._AddOutfitPutDownHooked then return end
        WRH._AddOutfitPutDownHooked = true
        local o = WRH.send_depot_put_down_req
        WRH.send_depot_put_down_req = function(insID)
            if F.isInjectedIns(tonumber(insID)) then
                F.takeOffInjected(insID)
                return
            end
            return o(insID)
        end
        local ob = WRH.send_depot_batch_put_down_req
        WRH.send_depot_batch_put_down_req = function(instid_list)
            local rest = {}
            for _, id in ipairs(instid_list or {}) do
                if F.isInjectedIns(tonumber(id)) then
                    F.takeOffInjected(id)
                else
                    rest[#rest + 1] = id
                end
            end
            if #rest > 0 then return ob(rest) end
        end
    end)
end

function F.isEmoteRes(resID)
    resID = tonumber(resID)
    if not resID then return false end
    if resID >= 12200000 and resID < 12300000 then return true end
    local c = F.cfg(resID)
    local t = tonumber(c and (c.ItemType or c.itemType))
    local st = tonumber(c and (c.ItemSubType or c.itemSubType))
    return t == 22 and (st == 2201 or st == 2206)
end

function F.ensureMotionSlotCapacity(slot)
    slot = tonumber(slot) or 0
    if slot <= 0 then return end
    local max = tonumber(DataMgr.MotionSlotMax) or 0
    if max < slot then DataMgr.MotionSlotMax = slot end
    while #DataMgr.MotionSlotList < slot do
        table.insert(DataMgr.MotionSlotList, 0)
    end
end

function F.buildMotionItem(insID)
    insID = tonumber(insID)
    if not insID or insID <= 0 then return nil end
    local resID = R.insToRes[insID]
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local d = wd:GetHallDepotItemDataByInsID(insID)
    if d then resID = resID or tonumber(d.resID or d.res_id) end
    if not resID then return nil end
    return {
        instid = insID, insID = insID, ins_id = insID,
        res_id = resID, resID = resID, count = 1,
    }
end

function F.postMotionSlotUpdate()
    F.invalidateInGameEmoteCache()
    pcall(function()
        if EventSystem and EVENTTYPE_MOTION and EVENTID_MOTION_UPDATE_SLOT_LIST then
            EventSystem:postEvent(EVENTTYPE_MOTION, EVENTID_MOTION_UPDATE_SLOT_LIST)
        end
    end)
end

function F.invalidateInGameEmoteCache()
    _G.__EMOTE_INGAME_CACHE_DIRTY = true
end

function F.rememberLocalMotionSlot(slot, insID)
    _G.AddOutfitLocalMotionSlots = _G.AddOutfitLocalMotionSlots or {}
    slot = tonumber(slot)
    insID = tonumber(insID) or 0
    if not slot or slot <= 0 then return end
    if insID > 0 then
        _G.AddOutfitLocalMotionSlots[slot] = insID
        local resID = R.insToRes[insID]
        if not resID then
            pcall(function()
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local d = wd:GetHallDepotItemDataByInsID(insID)
                if d then resID = tonumber(d.resID or d.res_id) end
            end)
        end
        if resID and resID > 0 then
            F.persistRememberMotionSlot(slot, resID)
        end
    else
        _G.AddOutfitLocalMotionSlots[slot] = nil
        F.persistRememberMotionSlot(slot, nil)
    end
    F.invalidateInGameEmoteCache()
end

function F.applyLocalMotionSlots()
    F.applyPersistedMotionSlots()
    local slots = _G.AddOutfitLocalMotionSlots
    if not slots then return end
    for slot, ins in pairs(slots) do
        slot = tonumber(slot)
        ins = tonumber(ins) or 0
        if slot and slot > 0 then
            F.ensureMotionSlotCapacity(slot)
            DataMgr.MotionSlotList[slot] = ins
        end
    end
end

function F.buildInGameEmoteListFromMotionSlots()
    F.applyLocalMotionSlots()
    local list = {}
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    for _, ins in ipairs(DataMgr.MotionSlotList or {}) do
        ins = tonumber(ins)
        if ins and ins > 0 then
            local resID = tonumber(R.insToRes[ins])
            local d = nil
            pcall(function() d = wd:GetHallDepotItemDataByInsID(ins) end)
            if d then resID = resID or tonumber(d.resID or d.res_id) end
            -- P23-FIX old: ItemType 22 sab emotes (F.isEmoteRes sirf 2201/2206 dekhta tha, kuch miss hote the)
            local isE = false
            pcall(function() isE = F.isEmoteRes(resID) end)
            if not isE and resID and resID > 0 then
                pcall(function()
                    local c = F.cfg and F.cfg(resID)
                    if c and tonumber(c.ItemType or c.itemType) == 22 then isE = true end
                end)
                -- injected motion slot me hai to emote maano (old getInjectedEmotes)
                if not isE and F.isInjectedIns and F.isInjectedIns(ins) then
                    if resID >= 12200000 and resID < 12300000 then isE = true end
                end
            end
            if resID and resID > 0 and isE then
                local name = tostring(resID)
                pcall(function()
                    local c = F.cfg(resID)
                    if c and c.ItemName then name = c.ItemName end
                end)
                list[#list + 1] = {
                    DefineID = { Type = 22, TypeSpecificID = resID },
                    Name = name,
                }
            end
        end
    end
    return list
end

function F.mergeMotionListWithSpecials(baseList, motionList)
    local merged = {}
    if baseList then
        for _, data in ipairs(baseList) do
            if data and data.bWeaponShow then
                merged[#merged + 1] = data
                break
            end
        end
    end
    for _, data in ipairs(motionList or {}) do
        merged[#merged + 1] = data
    end
    if baseList then
        for _, data in ipairs(baseList) do
            if data and data.bClothEmote then
                merged[#merged + 1] = data
                break
            end
        end
    end
    return merged
end

function F.hookMotionSync()
    pcall(function()
        if _G.AddOutfitMotionSyncHooked then return end
        _G.AddOutfitMotionSyncHooked = true
        local orig = DataMgr.InitMotionInfo
        if not orig then return end
        DataMgr.InitMotionInfo = function(motion_info, limit)
            orig(motion_info, limit)
            F.applyLocalMotionSlots()
            F.invalidateInGameEmoteCache()
        end
    end)
end

function F.localEquipMotion(instid, dst_slot)
    instid = tonumber(instid)
    dst_slot = tonumber(dst_slot)
    if not instid or not dst_slot or dst_slot <= 0 then return false end
    if not F.isInjectedIns(instid) then return false end
    F.ensureDepotItemValid(instid)
    local item = F.buildMotionItem(instid)
    if not item or not F.isEmoteRes(item.resID) then return false end
    F.ensureMotionSlotCapacity(dst_slot)
    local oldIns = tonumber(DataMgr.MotionSlotList[dst_slot]) or 0
    for i = 1, #DataMgr.MotionSlotList do
        if tonumber(DataMgr.MotionSlotList[i]) == instid then
            DataMgr.MotionSlotList[i] = 0
        end
    end
    DataMgr.MotionSlotList[dst_slot] = instid
    F.rememberLocalMotionSlot(dst_slot, instid)
    local old_item = (oldIns > 0 and oldIns ~= instid) and F.buildMotionItem(oldIns) or nil
    local WRH = require("client.network.Protocol.WardRobeHandler")
    WRH.on_equip_motion_rsp(NET_OK, dst_slot, item, old_item)
    F.postMotionSlotUpdate()
    return true
end

function F.localExchangeMotion(src_slot, dst_slot)
    src_slot = tonumber(src_slot)
    dst_slot = tonumber(dst_slot)
    if not src_slot or not dst_slot or src_slot <= 0 or dst_slot <= 0 then return false end
    F.ensureMotionSlotCapacity(math.max(src_slot, dst_slot))
    local srcIns = tonumber(DataMgr.MotionSlotList[src_slot]) or 0
    local dstIns = tonumber(DataMgr.MotionSlotList[dst_slot]) or 0
    DataMgr.MotionSlotList[src_slot] = dstIns
    DataMgr.MotionSlotList[dst_slot] = srcIns
    F.rememberLocalMotionSlot(src_slot, dstIns)
    F.rememberLocalMotionSlot(dst_slot, srcIns)
    local WRH = require("client.network.Protocol.WardRobeHandler")
    WRH.on_exchange_motion_rsp(NET_OK, F.buildMotionItem(srcIns), F.buildMotionItem(dstIns))
    F.postMotionSlotUpdate()
    return true
end

function F.localUnequipMotion(instid, slot)
    instid = tonumber(instid)
    slot = tonumber(slot)
    if not instid or not slot or slot <= 0 then return false end
    if not F.isInjectedIns(instid) then return false end
    F.ensureMotionSlotCapacity(slot)
    if (tonumber(DataMgr.MotionSlotList[slot]) or 0) ~= instid then return false end
    DataMgr.MotionSlotList[slot] = 0
    F.rememberLocalMotionSlot(slot, 0)
    local WRH = require("client.network.Protocol.WardRobeHandler")
    WRH.on_unequip_motion_rsp(NET_OK, slot, F.buildMotionItem(instid))
    F.postMotionSlotUpdate()
    return true
end

-- ================= PET (thú cưng) =================
-- Không dùng "local" ở chunk (Lua ≤200 locals) — gắn vào F
-- Pet sở hữu ở logic_pet.MyPetInfo.pets (ID 50001–50039)
F.PET_IDS = {
    50001, 50002, 50003, 50004, 50005, 50006, 50007, 50008, 50009, 50010,
    50011, 50012, 50013, 50014, 50015, 50016, 50017, 50018, 50019, 50020,
    50021, 50022, 50023, 50024, 50025, 50026, 50027, 50028, 50029, 50030,
    50031, 50032, 50033, 50034, 50035, 50036, 50037, 50038, 50039,
}

function F.isPetRes(resID)
    resID = tonumber(resID)
    if not resID then return false end
    if resID == 50000 then return false end -- MiniTV blocked
    return resID >= 50001 and resID < 50100
end

function F.getLogicPet()
    local lp
    pcall(function()
        local MM = require("client.module_framework.ModuleManager")
        lp = MM.GetModule(MM.CommonModuleConfig.logic_pet)
    end)
    return lp
end

function F.injectPet(petId)
    petId = tonumber(petId)
    if not F.isPetRes(petId) then return false end
    local logic_pet = F.getLogicPet()
    if not logic_pet then return false end
    logic_pet.MyPetInfo = logic_pet.MyPetInfo or {}
    logic_pet.MyPetInfo.pets = logic_pet.MyPetInfo.pets or {}
    logic_pet.MyPetInfo.dresses = logic_pet.MyPetInfo.dresses or {}
    if logic_pet.MyPetInfo.pets[petId] then
        local p = logic_pet.MyPetInfo.pets[petId]
        p.id = petId
        p.ins_id = petId
        p.expire_time = nil
        p.locked = false
        if not p.exp or p.exp < 1 then p.exp = 999999 end
        p.dress = p.dress or {}
    else
        logic_pet.MyPetInfo.pets[petId] = {
            id = petId,
            ins_id = petId,
            exp = 999999,
            dress = {},
            locked = false,
        }
    end
    local cnt = 0
    for _ in pairs(logic_pet.MyPetInfo.pets) do cnt = cnt + 1 end
    logic_pet.MyPetInfo.pet_cnt = cnt
    _G.AddOutfitInjectedPets = _G.AddOutfitInjectedPets or {}
    _G.AddOutfitInjectedPets[petId] = true
    pcall(function()
        if F.requestResourceDownload then F.requestResourceDownload(petId) end
    end)
    return true
end

function F.injectAllPets()
    if not _G.KuttaVaiConfig or _G.KuttaVaiConfig.ModPet ~= true then return 0 end
    local n = 0
    for _, id in ipairs(F.PET_IDS) do
        if F.injectPet(id) then n = n + 1 end
    end
    pcall(function()
        if EventSystem and EVENTTYPE_PET and EVENTID_PET_CHANGE then
            EventSystem:postEvent(EVENTTYPE_PET, EVENTID_PET_CHANGE)
        end
    end)
    return n
end

function F.persistRememberPet(petId)
    petId = tonumber(petId)
    if petId and F.isPetRes(petId) then
        PERSIST.configPetResID = petId
        _G.AddOutfitLastPetRes = petId
        _G.OutfitMap = _G.OutfitMap or {}
        _G.OutfitMap.Pet = petId
    else
        PERSIST.configPetResID = nil
        _G.AddOutfitLastPetRes = nil
        if _G.OutfitMap then _G.OutfitMap.Pet = 0 end
    end
    F.persistMarkDirty()
end

function F.localEquipPet(petId)
    petId = tonumber(petId)
    if not F.isPetRes(petId) then return false end
    F.injectPet(petId)
    local logic_pet = F.getLogicPet()
    if not logic_pet or not logic_pet.MyPetInfo then return false end
    local ok = false
    pcall(function()
        if logic_pet.equip_pet_rsp then
            logic_pet:equip_pet_rsp(0, petId)
            ok = true
        else
            logic_pet.MyPetInfo.equip_pet_ins_id = petId
            local ServerInfo = logic_pet:GetPetDataByInsID(petId)
            local PetData = logic_pet:FormatPetDataByServerInfo(DataMgr.roleData.uid, ServerInfo)
            if EventSystem and EVENTTYPE_PET then
                if EVENTID_PET_EQUIP_PET_SUCCESS then
                    EventSystem:postEvent(EVENTTYPE_PET, EVENTID_PET_EQUIP_PET_SUCCESS, petId)
                end
                if EVENTID_PET_EQUIP_PET_CHANGE then
                    EventSystem:postEvent(EVENTTYPE_PET, EVENTID_PET_EQUIP_PET_CHANGE, PetData)
                end
            end
            ok = true
        end
    end)
    if ok then
        F.persistRememberPet(petId)
        _G.LastAppliedPet = petId
    end
    return ok
end

function F.applyPersistedPet()
    local petId = tonumber(PERSIST.configPetResID) or tonumber(_G.AddOutfitLastPetRes)
    if not petId or not F.isPetRes(petId) then return false end
    return F.localEquipPet(petId)
end

function F.hookPetEquip()
    pcall(function()
        local logic_pet = F.getLogicPet()
        if not logic_pet or logic_pet._AddOutfitPetHooked then return end
        logic_pet._AddOutfitPetHooked = true
        local oEquip = logic_pet.equip_pet_req
        if oEquip then
            logic_pet.equip_pet_req = function(self, PetInsID)
                PetInsID = tonumber(PetInsID)
                if PetInsID and F.isPetRes(PetInsID)
                    and (_G.KuttaVaiConfig.ModPet == true or (_G.AddOutfitInjectedPets and _G.AddOutfitInjectedPets[PetInsID])) then
                    if F.localEquipPet(PetInsID) then return end
                end
                return oEquip(self, PetInsID)
            end
        end
        local oUnequip = logic_pet.unequip_pet_req
        if oUnequip then
            logic_pet.unequip_pet_req = function(self)
                local eq = tonumber(self.MyPetInfo and self.MyPetInfo.equip_pet_ins_id) or 0
                if eq > 0 and _G.AddOutfitInjectedPets and _G.AddOutfitInjectedPets[eq] then
                    pcall(function()
                        if self.unequip_pet_rsp then
                            self:unequip_pet_rsp(0)
                        else
                            self.MyPetInfo.equip_pet_ins_id = 0
                        end
                    end)
                    F.persistRememberPet(nil)
                    _G.LastAppliedPet = nil
                    return
                end
                return oUnequip(self)
            end
        end
        local function wrapHas(name)
            local o = logic_pet[name]
            if not o then return end
            logic_pet[name] = function(self, petId, ...)
                petId = tonumber(petId)
                if petId and F.isPetRes(petId) and _G.KuttaVaiConfig.ModPet == true then
                    F.injectPet(petId)
                    return true
                end
                if petId and _G.AddOutfitInjectedPets and _G.AddOutfitInjectedPets[petId] then
                    return true
                end
                return o(self, petId, ...)
            end
        end
        wrapHas("HasPet")
        wrapHas("HasPetPermanently")
        wrapHas("HasPetIncludeInherit")
    end)
end

_G.HandlePetLogic = function()
    pcall(function()
        if not _G.KuttaVaiConfig or not _G.KuttaVaiConfig.ModSkin then return end
        if _G.KuttaVaiConfig.ModPet == true and not _G.AddOutfitPetsInjected then
            F.injectAllPets()
            _G.AddOutfitPetsInjected = true
        elseif _G.KuttaVaiConfig.ModPet ~= true then
            _G.AddOutfitPetsInjected = false
        end
        local petSkin = tonumber(_G.OutfitMap and _G.OutfitMap.Pet)
            or tonumber(PERSIST.configPetResID)
            or tonumber(_G.AddOutfitLastPetRes)
        if not petSkin or petSkin == 0 or petSkin == 50000 then return end
        if not F.isPetRes(petSkin) then return end
        if petSkin == _G.LastAppliedPet then return end
        if F.localEquipPet(petSkin) then
            _G.LastAppliedPet = petSkin
        end
    end)
end

function F.hookMotionEquip()
    pcall(function()
        local WRH = require("client.network.Protocol.WardRobeHandler")
        if WRH._AddOutfitMotionHooked then return end
        WRH._AddOutfitMotionHooked = true
        local oEquip = WRH.send_equip_motion_req
        WRH.send_equip_motion_req = function(instid, dst_slot)
            instid = tonumber(instid)
            dst_slot = tonumber(dst_slot)
            if instid and dst_slot and F.localEquipMotion(instid, dst_slot) then return end
            return oEquip(instid, dst_slot)
        end
        local oExchange = WRH.send_exchange_motion_req
        WRH.send_exchange_motion_req = function(src_slot, dst_slot)
            src_slot = tonumber(src_slot)
            dst_slot = tonumber(dst_slot)
            if not src_slot or not dst_slot then return oExchange(src_slot, dst_slot) end
            local srcIns = tonumber(DataMgr.MotionSlotList[src_slot]) or 0
            local dstIns = tonumber(DataMgr.MotionSlotList[dst_slot]) or 0
            if F.isInjectedIns(srcIns) or F.isInjectedIns(dstIns) then
                if F.localExchangeMotion(src_slot, dst_slot) then return end
            end
            return oExchange(src_slot, dst_slot)
        end
        local oUnequip = WRH.send_unequip_motion_req
        WRH.send_unequip_motion_req = function(instid, slot)
            instid = tonumber(instid)
            slot = tonumber(slot)
            if instid and slot and F.localUnequipMotion(instid, slot) then return end
            return oUnequip(instid, slot)
        end
    end)
end

function F.hookVehicleSwitchEffect()
    if _G.AddOutfitVehSwitchHooked then return end
    pcall(function()
        local VAC = require("GameLua.GameCore.Module.Vehicle.Component.VehicleAvatarComponent")
        local impl = VAC and VAC.__inner_impl
        if not impl or impl._AddOutfitVehSwitchHooked then return end
        impl._AddOutfitVehSwitchHooked = true

        if not _G.AddOutfitVehOrigCanSwitch then
            _G.AddOutfitVehOrigCanSwitch = impl.CheckCanPlaySkinSwitchEffect
        end
        impl.CheckCanPlaySkinSwitchEffect = function(self, curVehicleId, lastVehicleId)
            if self.IsLobbyActor and self:IsLobbyActor() then return false end
            if not F.isInRealMatch() then return false end
            return true
        end

        if not _G.AddOutfitVehOrigShowSwitch then
            _G.AddOutfitVehOrigShowSwitch = impl.ShowVehicleSwitchEffect
        end
        impl.ShowVehicleSwitchEffect = function(self)
            if self.IsLobbyActor and self:IsLobbyActor() then return false end
            if not F.isInRealMatch() then return false end
            if not self.curSwitchEffectId or self.curSwitchEffectId <= 0 then
                self.curSwitchEffectId = VEH_SWITCH_EFFECT_ID
            end
            local vehicleActor = self:GetOwner()
            if not slua.isValid(vehicleActor) then return false end
            if self.uSwitchEffectActor then
                self:StopSkinSwitchEffect()
                pcall(function() self.uSwitchEffectActor:K2_DestroyActor() end)
                self.uSwitchEffectActor = nil
            end
            if not self.lastEquipedAvatarId or self.lastEquipedAvatarId <= 0 then
                local defId = 0
                pcall(function() defId = self:GetDefaultAvatarID() or 0 end)
                self.lastEquipedAvatarId = vehicleActor.ClientUsedAvatarID or defId or 0
            end
            local currentAvatarID = vehicleActor.ClientUsedAvatarID or self.lastEquipedAvatarId or 0
            local bIsLobbyActor = self:IsLobbyActor()
            local world = slua_GameFrontendHUD:GetWorld()
            local VehiclePlateLicenseUtil = require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
            local SkinSwitchEffectActorPath = VehiclePlateLicenseUtil.GetSwitchEffectActorPath()
            local BP_DissolveVehicleClass = import(SkinSwitchEffectActorPath)
            self.uSwitchEffectActor = world:SpawnActor(BP_DissolveVehicleClass, nil, nil, nil)
            if not slua.isValid(self.uSwitchEffectActor) then
                self.uSwitchEffectActor = nil
                return false
            end
            self.uSwitchEffectActor:K2_AttachToActor(vehicleActor, "None", 1, 1, 1, false)
            self.uSwitchEffectActor:K2_SetActorRelativeLocation(FVector(0, 0, 0), false, nil, false)
            self.uSwitchEffectActor:K2_SetActorRelativeRotation(FRotator(0, 0, 0), false, nil, false)
            pcall(function() self:HideParticles() end)
            self:ChangeFakeSwitchVehicleAvatar(self.uSwitchEffectActor.Mesh, self.lastEquipedAvatarId)
            self.uSwitchEffectActor:SetAnimInsAndAnimState(self.uOldVehicleMeshAnimClass, vehicleActor)
            self.uSwitchEffectActor:StartVehicleSwitchEffect(
                vehicleActor, self.curSwitchEffectId, self.lastEquipedAvatarId, currentAvatarID, bIsLobbyActor)
            self.uOldVehicleMeshAnimClass = nil
            return true
        end

        if not _G.AddOutfitVehOrigBeginPlay then
            _G.AddOutfitVehOrigBeginPlay = impl.ReceiveBeginPlay
        end
        local oBegin = _G.AddOutfitVehOrigBeginPlay
        impl.ReceiveBeginPlay = function(self)
            oBegin(self)
            pcall(function()
                if self.uSwitchEffectActor then
                    self:StopSkinSwitchEffect()
                    pcall(function() self.uSwitchEffectActor:K2_DestroyActor() end)
                    self.uSwitchEffectActor = nil
                end
                self.lastEquipedAvatarId = 0
                if self.IsLobbyActor and self:IsLobbyActor() then
                    self.curSwitchEffectId = 0
                elseif F.isInRealMatch() then
                    self.curSwitchEffectId = VEH_SWITCH_EFFECT_ID
                else
                    self.curSwitchEffectId = 0
                end
            end)
        end

        if impl.LuaIsAssetsAlreadyAvailable and not _G.AddOutfitVehOrigAssets then
            _G.AddOutfitVehOrigAssets = impl.LuaIsAssetsAlreadyAvailable
            impl.LuaIsAssetsAlreadyAvailable = function(self, avatarId)
                if F.isVehicleSkinAllowed(tonumber(avatarId)) then return true end
                return _G.AddOutfitVehOrigAssets(self, avatarId)
            end
        end

        -- Match: inject brake/canopy (không vành) từ persist
        if impl.SyncMultiSlotDataOnAvatarChange and not impl._Kutta_SyncMultiSlotHooked then
            impl._Kutta_SyncMultiSlotHooked = true
            local oSync = impl.SyncMultiSlotDataOnAvatarChange
            impl.SyncMultiSlotDataOnAvatarChange = function(self, playerUID, vehicleItemId)
                local useLocal = false
                pcall(function()
                    if not (F.vehicleModUnlockOn and F.vehicleModUnlockOn()) then return end
                    local localUid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
                    if playerUID == nil or playerUID == "" or tostring(playerUID) == tostring(localUid) then
                        useLocal = true
                    end
                end)
                if useLocal and F.getDesiredMultiSlotPartsForSkin then
                    local parts = F.getDesiredMultiSlotPartsForSkin(vehicleItemId)
                    if type(parts) == "table" and next(parts) then
                        pcall(function() self.bEnableMultiSlot = true end)
                        self:SetNetMultiSlotData(parts)
                        return
                    end
                end
                return oSync(self, playerUID, vehicleItemId)
            end
        end
        if impl.BP_PostChangeItemAvatar and not impl._Kutta_PostChangeMultiSlotHooked then
            impl._Kutta_PostChangeMultiSlotHooked = true
            local oPost = impl.BP_PostChangeItemAvatar
            impl.BP_PostChangeItemAvatar = function(self)
                oPost(self)
                pcall(function()
                    if not (F.vehicleModUnlockOn and F.vehicleModUnlockOn()) then return end
                    local owner = self.GetOwner and self:GetOwner()
                    if slua.isValid(owner) then
                        F.applyVehicleModPartsToVehicle(owner, owner.ClientUsedAvatarID)
                    end
                end)
            end
        end

        _G.AddOutfitVehSwitchHooked = true
    end)
end

function F.vehicleModUnlockOn()
    if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModSkin == true then return true end
    if _G.KuttaVaiConfig and _G.KuttaVaiConfig.FreeLobbyShop == true then return true end
    return false
end

function F.seedAllVehicleRefitOwnership()
    pcall(function()
        local VRH = require("client.network.Protocol.VehicleRefitHandler")
        if not VRH then return end
        VRH.OwnCarInfoMap = VRH.OwnCarInfoMap or {}
        VRH.resCarInfoList = VRH.resCarInfoList or {}
        VRH.resCarInfoList.car_list = VRH.resCarInfoList.car_list or {}
        VRH.resCarInfoList.unlocked_car_list = VRH.resCarInfoList.unlocked_car_list or {}
        local tb = CDataTable and CDataTable.GetTable and CDataTable.GetTable("VehicleRefitStyle")
        if type(tb) ~= "table" then return end
        for k, cfg in pairs(tb) do
            local styleId = tonumber(k)
            if not styleId and type(cfg) == "table" then
                styleId = tonumber(cfg.style_id or cfg.StyleID or cfg.ID)
            end
            if styleId and styleId > 0 then
                VRH.OwnCarInfoMap[styleId] = 1
            end
        end
    end)
end

-- Equip cần itemData trong depot — inject mọi xe Workshop (ưu tiên max level)
function F.ensureWorkshopVehiclesInDepot()
    if not F.vehicleModUnlockOn() then return false end
    local granted = 0
    pcall(function()
        local VRH = require("client.network.Protocol.VehicleRefitHandler")
        if VRH and VRH.CreateUnlockCarCfgTable and (not VRH.unlock_car_cfgtb or not next(VRH.unlock_car_cfgtb)) then
            pcall(VRH.CreateUnlockCarCfgTable)
        end
        local seen = {}
        local function grant(vid)
            vid = tonumber(vid)
            if not vid or vid <= 0 or seen[vid] then return end
            seen[vid] = true
            local has = false
            pcall(function()
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                if wd and wd.GetHallDepotItemDataByResID then
                    has = wd:GetHallDepotItemDataByResID(vid) ~= nil
                end
            end)
            if has then return end
            if F.getEntityDepotCount and F.getEntityDepotCount(vid) > 0 then return end
            if F.grantDepotItem and F.grantDepotItem(vid, 1, { markNew = false }) then
                granted = granted + 1
            elseif F.injectDumpItem and F.injectDumpItem(vid, { markNew = false }) then
                granted = granted + 1
            end
        end
        local sources = {}
        pcall(function()
            if VRH and VRH.GetUnlockCarCfgTable then
                sources[#sources + 1] = VRH.GetUnlockCarCfgTable()
            end
        end)
        pcall(function()
            if VRH and VRH.ShowAbleCars then
                sources[#sources + 1] = VRH.ShowAbleCars()
            end
        end)
        pcall(function()
            sources[#sources + 1] = CDataTable.GetTable("VehicleRefitInfo")
        end)
        -- Max level mỗi group trước
        local byGroup = {}
        for _, src in ipairs(sources) do
            if type(src) == "table" then
                for _, v in pairs(src) do
                    if type(v) == "table" and tonumber(v.vehicle_id) then
                        local g = tonumber(v.vehicle_group_id) or 0
                        local lv = tonumber(v.level) or 1
                        local prev = byGroup[g]
                        if not prev or lv > (tonumber(prev.level) or 0) then
                            byGroup[g] = v
                        end
                    end
                end
            end
        end
        for _, v in pairs(byGroup) do grant(v.vehicle_id) end
        for _, src in ipairs(sources) do
            if type(src) == "table" then
                for _, v in pairs(src) do
                    if type(v) == "table" then grant(v.vehicle_id) end
                end
            end
        end
    end)
    return granted > 0
end

function F.resolveVehicleIdFromInst(car_instid)
    local car_id = nil
    car_instid = tonumber(car_instid)
    if not car_instid then return nil end
    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        if wd and wd.GetHallDepotItemDataByInsID then
            local d = wd:GetHallDepotItemDataByInsID(car_instid)
            car_id = d and tonumber(d.res_id or d.resID or d.item_id)
        end
    end)
    if not car_id then
        pcall(function()
            if R and R.insToRes then car_id = tonumber(R.insToRes[car_instid]) end
        end)
    end
    if not car_id then
        pcall(function()
            local entity = F.getEntity and F.getEntity()
            if entity and entity.GetDataByInsID then
                local d = entity:GetDataByInsID(car_instid)
                car_id = d and tonumber(d.res_id or d.resID)
            end
        end)
    end
    return car_id
end

-- Equip Refit/Main cần itemData.insID — lấy depot hoặc tạo synthetic từ inject map
function F.ensureVehicleItemData(vehicle_id)
    vehicle_id = tonumber(vehicle_id)
    if not vehicle_id or vehicle_id <= 0 then return nil end
    local itemData = nil
    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        if wd and wd.GetHallDepotItemDataByResID then
            itemData = wd:GetHallDepotItemDataByResID(vehicle_id)
        end
    end)
    if itemData and (itemData.insID or itemData.ins_id) then
        itemData.insID = tonumber(itemData.insID or itemData.ins_id)
        itemData.ins_id = itemData.insID
        itemData.resID = tonumber(itemData.resID or itemData.res_id or vehicle_id)
        itemData.res_id = itemData.resID
        return itemData
    end
    if F.grantDepotItem then
        pcall(F.grantDepotItem, vehicle_id, 1, { markNew = false })
    end
    pcall(function()
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        if wd and wd.GetHallDepotItemDataByResID then
            itemData = wd:GetHallDepotItemDataByResID(vehicle_id)
        end
    end)
    if itemData and (itemData.insID or itemData.ins_id) then
        itemData.insID = tonumber(itemData.insID or itemData.ins_id)
        itemData.ins_id = itemData.insID
        itemData.resID = tonumber(itemData.resID or itemData.res_id or vehicle_id)
        itemData.res_id = itemData.resID
        return itemData
    end
    local insID = nil
    if R and R.resToIns then insID = tonumber(R.resToIns[vehicle_id]) end
    if not insID and F.dumpInsForRes then
        pcall(function() insID = tonumber(F.dumpInsForRes(vehicle_id)) end)
    end
    if not insID or insID <= 0 then
        insID = 900000000 + (vehicle_id % 100000000)
    end
    if R then
        R.resToIns = R.resToIns or {}
        R.insToRes = R.insToRes or {}
        R.resToIns[vehicle_id] = insID
        R.insToRes[insID] = vehicle_id
    end
    return {
        insID = insID,
        ins_id = insID,
        resID = vehicle_id,
        res_id = vehicle_id,
        count = 1,
        expireTS = 0,
        expire_ts = 0,
    }
end

function F.patchCarInfoForEquip(info)
    if type(info) ~= "table" or type(info.cfg) ~= "table" then return info end
    local vid = tonumber(info.cfg.vehicle_id)
    if not info.itemData and vid then
        info.itemData = F.ensureVehicleItemData(vid)
    end
    -- Soften level lock in OnRefreshItem (cfg.level < unLockLevel)
    local lv = tonumber(info.cfg.level) or 1
    if lv < 99 then
        local cfg = {}
        for k, v in pairs(info.cfg) do cfg[k] = v end
        cfg.level = 99
        info.cfg = cfg
    end
    return info
end

-- Seed ownership cho Wheel Hub / Brake Caliper / Canopy (+ rail cũ)
function F.seedExtendedFeatureOwnership()
    if not F.vehicleModUnlockOn() then return end
    pcall(function()
        local LVF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
        if not LVF then return end
        if LVF.ParseSportCarSupportParts and not LVF.vehicleSupportParts then
            pcall(function() LVF:ParseSportCarSupportParts() end)
        end
        LVF.car_plate_background = LVF.car_plate_background or {}
        LVF.car_chassis_light = LVF.car_chassis_light or {}
        LVF.car_switch_effect = LVF.car_switch_effect or {}
        LVF.car_wheel_hub = LVF.car_wheel_hub or {}
        LVF.car_brake_caliper = LVF.car_brake_caliper or {}
        LVF.car_sunroof = LVF.car_sunroof or {}
        LVF.equip_plate_background = LVF.equip_plate_background or {}
        LVF.equip_chassis_light = LVF.equip_chassis_light or {}
        LVF.equip_wheel_hub = LVF.equip_wheel_hub or {}
        LVF.equip_brake_caliper = LVF.equip_brake_caliper or {}
        LVF.equip_sunroof = LVF.equip_sunroof or {}
        local function own(map, id)
            id = tonumber(id)
            if id and id > 0 and map[id] == nil then map[id] = 0 end
        end
        local EVehiclePartSlot = nil
        pcall(function() EVehiclePartSlot = import("EVehiclePartSlot") end)
        for _, slots in pairs(LVF.vehicleSupportParts or {}) do
            if type(slots) == "table" then
                for slot, parts in pairs(slots) do
                    if type(parts) == "table" then
                        local target = nil
                        if EVehiclePartSlot then
                            if slot == EVehiclePartSlot.WheelHub then target = LVF.car_wheel_hub
                            elseif slot == EVehiclePartSlot.BrakeCaliper then target = LVF.car_brake_caliper
                            elseif slot == EVehiclePartSlot.Canopy then target = LVF.car_sunroof
                            end
                        end
                        for _, pid in pairs(parts) do
                            if target then
                                own(target, pid)
                            else
                                own(LVF.car_wheel_hub, pid)
                                own(LVF.car_brake_caliper, pid)
                                own(LVF.car_sunroof, pid)
                            end
                        end
                    end
                end
            end
        end
        -- Fallback tables
        pcall(function()
            for _, cfg in pairs(CDataTable.GetTable("VehicleChassisLightCfg") or {}) do own(LVF.car_chassis_light, cfg.ItemID) end
        end)
        pcall(function()
            for _, cfg in pairs(CDataTable.GetTable("VehicleSwitchEffectCfg") or {}) do own(LVF.car_switch_effect, cfg.ItemID) end
        end)
        pcall(function()
            for _, cfg in pairs(CDataTable.GetTable("VehiclePlateBgCfg") or {}) do own(LVF.car_plate_background, cfg.ItemID) end
        end)
    end)
end

-- Phân loại feature: wheel hub / brake / canopy / chassis / plate / switch
function F.resolveExtendedFeatureKind(LVF, resid)
    resid = tonumber(resid)
    if not resid then return nil end
    local sub, itemType = nil, nil
    pcall(function()
        local cfg = CDataTable.GetTableData("Item", resid)
        if cfg then
            sub = tonumber(cfg.ItemSubType)
            itemType = tonumber(cfg.ItemType)
        end
    end)
    local ST = _G.ENUM_ITEM_SUBTYPE
    if ST and sub then
        if ST.VehicleWheelHub and sub == ST.VehicleWheelHub then return "wheel" end
        if ST.VehicleBrakeCaliper and sub == ST.VehicleBrakeCaliper then return "brake" end
        if ST.VehicleCanopy and sub == ST.VehicleCanopy then return "canopy" end
        if ST.VehicleChassisLight and sub == ST.VehicleChassisLight then return "chassis" end
        if ST.VehicleSwitchEffect and sub == ST.VehicleSwitchEffect then return "switch" end
        if ST.VehiclePlateBackground and sub == ST.VehiclePlateBackground then return "plate" end
    end
    local kind = nil
    pcall(function()
        local MD = require("client.logic.avatar.ModelDisplayTypeHelper")
        if not MD then return end
        if MD.IsVehicleWheelHub and MD.IsVehicleWheelHub(itemType, sub) then kind = "wheel"; return end
        if MD.IsVehicleBrakeCaliper and MD.IsVehicleBrakeCaliper(itemType, sub) then kind = "brake"; return end
        if MD.IsVehicleCanopy and MD.IsVehicleCanopy(itemType, sub) then kind = "canopy"; return end
    end)
    if kind then return kind end
    if F.isChassisLightId and F.isChassisLightId(resid) then return "chassis" end
    -- Slot từ SportCarSupportParts
    local found = nil
    pcall(function()
        if not LVF then return end
        if LVF.ParseSportCarSupportParts and not LVF.vehicleSupportParts then
            pcall(function() LVF:ParseSportCarSupportParts() end)
        end
        local EVehiclePartSlot = import("EVehiclePartSlot")
        for _, slots in pairs(LVF.vehicleSupportParts or {}) do
            if type(slots) == "table" then
                for slot, parts in pairs(slots) do
                    if type(parts) == "table" then
                        for _, pid in pairs(parts) do
                            if tonumber(pid) == resid then
                                if EVehiclePartSlot then
                                    if slot == EVehiclePartSlot.WheelHub then found = "wheel"
                                    elseif slot == EVehiclePartSlot.BrakeCaliper then found = "brake"
                                    elseif slot == EVehiclePartSlot.Canopy then found = "canopy"
                                    end
                                end
                                if not found then
                                    local n = tonumber(slot)
                                    if n == 2 then found = "wheel"
                                    elseif n == 1 then found = "brake"
                                    elseif n == 3 then found = "canopy"
                                    end
                                end
                                return
                            end
                        end
                    end
                end
            end
        end
    end)
    return found
end

function F.buildExtendedFeatureData(LVF)
    if not LVF then return {} end
    return {
        equip_plate_background = LVF.equip_plate_background or {},
        equip_chassis_light = LVF.equip_chassis_light or {},
        equip_switch_effect = LVF.equip_switch_effect,
        car_plate_background = LVF.car_plate_background or {},
        car_chassis_light = LVF.car_chassis_light or {},
        car_switch_effect = LVF.car_switch_effect or {},
        car_brake_caliper = LVF.car_brake_caliper or {},
        equip_brake_caliper = LVF.equip_brake_caliper or {},
        car_wheel_hub = LVF.car_wheel_hub or {},
        equip_wheel_hub = LVF.equip_wheel_hub or {},
        car_sunroof = LVF.car_sunroof or {},
        equip_sunroof = LVF.equip_sunroof or {},
    }
end

function F.vehicleModPersist()
    PERSIST.configVehicleMod = PERSIST.configVehicleMod or {
        wheelHub = {},
        brakeCaliper = {},
        canopy = {},
        chassisLight = {},
        plateBg = {},
        switchEffect = nil,
        refit = {},
        accessories = {},
    }
    local m = PERSIST.configVehicleMod
    m.wheelHub = m.wheelHub or {}
    m.brakeCaliper = m.brakeCaliper or {}
    m.canopy = m.canopy or {}
    m.chassisLight = m.chassisLight or {}
    m.plateBg = m.plateBg or {}
    m.refit = m.refit or {}
    m.accessories = m.accessories or {}
    return m
end

function F.forEachVehicleGroupIds(carId, fn)
    carId = tonumber(carId)
    if not carId or type(fn) ~= "function" then return end
    fn(carId)
    local gid = nil
    pcall(function()
        local cfg = CDataTable.GetTableData("VehicleRefitInfo", carId)
        gid = cfg and tonumber(cfg.vehicle_group_id)
    end)
    if not gid then return end
    pcall(function()
        local tb = CDataTable.GetTable("VehicleRefitInfo")
        if type(tb) ~= "table" then return end
        for k, cfg in pairs(tb) do
            local vid = tonumber(k)
            if not vid and type(cfg) == "table" then
                vid = tonumber(cfg.vehicle_id or cfg.VehicleID or cfg.ID)
            end
            local g2 = type(cfg) == "table" and tonumber(cfg.vehicle_group_id)
            if vid and g2 == gid then fn(vid) end
        end
    end)
end

function F.expandVehicleFeatureMap(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for carId, resid in pairs(src) do
        carId, resid = tonumber(carId), tonumber(resid)
        if carId and resid and resid > 0 then
            F.forEachVehicleGroupIds(carId, function(vid) out[vid] = resid end)
        end
    end
    return out
end

-- Bảng attr 66 (VehicleExtendedFeatures) dùng trong trận / license / SyncMultiSlot
function F.buildVehicleExtendedFeaturesTable(base)
    local t = {}
    if type(base) == "table" then
        for k, v in pairs(base) do t[k] = v end
    end
    local m = F.vehicleModPersist and F.vehicleModPersist() or {}
    local function mergeMap(dstKey, srcMap)
        local expanded = F.expandVehicleFeatureMap(srcMap)
        t[dstKey] = type(t[dstKey]) == "table" and t[dstKey] or {}
        for k, v in pairs(expanded) do t[dstKey][k] = v end
    end
    -- Bỏ wheel_hub_info (vành không apply trong trận)
    mergeMap("brake_caliper_info", m.brakeCaliper)
    mergeMap("sunroof_info", m.canopy)
    mergeMap("chassis_light_info", m.chassisLight)
    mergeMap("plate_background_info", m.plateBg)
    pcall(function()
        local LVF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
        if not LVF then return end
        mergeMap("brake_caliper_info", LVF.equip_brake_caliper)
        mergeMap("sunroof_info", LVF.equip_sunroof)
        mergeMap("chassis_light_info", LVF.equip_chassis_light)
        mergeMap("plate_background_info", LVF.equip_plate_background)
        if tonumber(LVF.equip_switch_effect) and tonumber(LVF.equip_switch_effect) > 0 then
            t.switch_effect_info = tonumber(LVF.equip_switch_effect)
        end
    end)
    if tonumber(m.switchEffect) and tonumber(m.switchEffect) > 0 then
        t.switch_effect_info = tonumber(m.switchEffect)
    elseif t.switch_effect_info == nil then
        t.switch_effect_info = 0
    end
    -- Wardrobe chassis map
    if type(PERSIST.configChassisLightMap) == "table" then
        t.chassis_light_info = t.chassis_light_info or {}
        for vid, lid in pairs(PERSIST.configChassisLightMap) do
            vid, lid = tonumber(vid), tonumber(lid)
            if vid and lid and lid > 0 then t.chassis_light_info[vid] = lid end
        end
    end
    return t
end

function F.applyVehiclePartDataToPC(pc, skinId)
    pc = pc or F.getPC()
    if not slua.isValid(pc) then return false end
    skinId = tonumber(skinId) or tonumber(pc.ShowVehicleSkin) or 0
    local parts = F.getDesiredMultiSlotPartsForSkin and F.getDesiredMultiSlotPartsForSkin(skinId) or {}
    local SLOT_BRAKE, SLOT_CANOPY = 1, 3
    pcall(function()
        SLOT_BRAKE, SLOT_CANOPY = F.getVehiclePartSlots()
    end)
    local partData = {
        [1] = tonumber(parts[SLOT_BRAKE]) or tonumber(parts[1]),
        [2] = nil, -- bỏ vành
        [3] = tonumber(parts[SLOT_CANOPY]) or tonumber(parts[3]),
    }
    pcall(function() pc.VehiclePartData = partData end)
    pcall(function()
        local feat = F.buildVehicleExtendedFeaturesTable()
        if feat and tonumber(feat.switch_effect_info) and tonumber(feat.switch_effect_info) > 0 then
            pc.nVehicleSwitchEffectId = tonumber(feat.switch_effect_info)
        end
    end)
    return true
end

function F.hookVehicleExtendedFeaturesServerData()
    if _G._Kutta_VehExtFeatHooked then return end
    _G._Kutta_VehExtFeatHooked = true
    pcall(function()
        local SPD = require("Server.Data.ServerPlayerDataMgr")
        local EA = require("Server.config.ExtendAttribute")
        if not SPD or not EA or not SPD.GetPlayerProgressFromServer then return end
        if not _G._Kutta_GetPlayerProgressOrig then
            _G._Kutta_GetPlayerProgressOrig = SPD.GetPlayerProgressFromServer
        end
        local o = _G._Kutta_GetPlayerProgressOrig
        SPD.GetPlayerProgressFromServer = function(nUID, nTypeID)
            local ret = o(nUID, nTypeID)
            pcall(function()
                if not (F.vehicleModUnlockOn and F.vehicleModUnlockOn()) then return end
                if nTypeID ~= EA.VehicleExtendedFeatures then return end
                local localUid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
                if nUID ~= nil and localUid ~= nil and tostring(nUID) ~= tostring(localUid) then return end
                ret = F.buildVehicleExtendedFeaturesTable(ret)
            end)
            return ret
        end
    end)
end

function F.saveVehicleFeaturePersist(kind, car_id, resid, potOn)
    local m = F.vehicleModPersist()
    car_id = tonumber(car_id)
    resid = tonumber(resid)
    if kind == "switch" then
        m.switchEffect = potOn and resid or nil
    elseif kind == "plate" then
        local vt = car_id -- caller may pass vehicleType as car_id for plate
        if vt then
            if potOn then m.plateBg[vt] = resid else m.plateBg[vt] = nil end
        end
    elseif car_id then
        local map = nil
        if kind == "wheel" then map = m.wheelHub
        elseif kind == "brake" then map = m.brakeCaliper
        elseif kind == "canopy" then map = m.canopy
        elseif kind == "chassis" then map = m.chassisLight
        end
        if map then
            -- Ghi mọi level cùng vehicle_group để match trong trận
            F.forEachVehicleGroupIds(car_id, function(vid)
                if potOn then map[vid] = resid else map[vid] = nil end
            end)
        end
    end
    F.persistMarkDirty()
end

function F.saveVehicleRefitPersist(car_id, styleMap)
    car_id = tonumber(car_id)
    if not car_id or type(styleMap) ~= "table" then return end
    local m = F.vehicleModPersist()
    m.refit[car_id] = m.refit[car_id] or {}
    for partId, styleId in pairs(styleMap) do
        partId, styleId = tonumber(partId) or partId, tonumber(styleId)
        if styleId then m.refit[car_id][partId] = styleId end
    end
    F.persistMarkDirty()
end

function F.saveVehicleAccessoryPersist(car_id, acc_id, potOn)
    car_id, acc_id = tonumber(car_id), tonumber(acc_id)
    if not car_id or not acc_id then return end
    local m = F.vehicleModPersist()
    m.accessories[car_id] = m.accessories[car_id] or {}
    if potOn then m.accessories[car_id][acc_id] = 1
    else m.accessories[car_id][acc_id] = nil end
    F.persistMarkDirty()
end

function F.applyVehicleModPersistToLVF(LVF)
    if not F.vehicleModUnlockOn() then return end
    LVF = LVF or ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
    if not LVF then return end
    F.seedExtendedFeatureOwnership()
    local m = F.vehicleModPersist()
    LVF.equip_wheel_hub = LVF.equip_wheel_hub or {}
    LVF.equip_brake_caliper = LVF.equip_brake_caliper or {}
    LVF.equip_sunroof = LVF.equip_sunroof or {}
    LVF.equip_chassis_light = LVF.equip_chassis_light or {}
    LVF.equip_plate_background = LVF.equip_plate_background or {}
    for carId, resid in pairs(m.wheelHub) do
        carId, resid = tonumber(carId), tonumber(resid)
        if carId and resid then
            LVF.equip_wheel_hub[carId] = resid
            LVF.car_wheel_hub[resid] = LVF.car_wheel_hub[resid] or 0
        end
    end
    for carId, resid in pairs(m.brakeCaliper) do
        carId, resid = tonumber(carId), tonumber(resid)
        if carId and resid then
            LVF.equip_brake_caliper[carId] = resid
            LVF.car_brake_caliper[resid] = LVF.car_brake_caliper[resid] or 0
        end
    end
    for carId, resid in pairs(m.canopy) do
        carId, resid = tonumber(carId), tonumber(resid)
        if carId and resid then
            LVF.equip_sunroof[carId] = resid
            LVF.car_sunroof[resid] = LVF.car_sunroof[resid] or 0
        end
    end
    for carId, resid in pairs(m.chassisLight) do
        carId, resid = tonumber(carId), tonumber(resid)
        if carId and resid then
            LVF.equip_chassis_light[carId] = resid
            LVF.car_chassis_light[resid] = LVF.car_chassis_light[resid] or 0
        end
    end
    for vt, resid in pairs(m.plateBg) do
        vt, resid = tonumber(vt), tonumber(resid)
        if vt and resid then
            LVF.equip_plate_background[vt] = resid
            LVF.car_plate_background[resid] = LVF.car_plate_background[resid] or 0
        end
    end
    if m.switchEffect then
        LVF.equip_switch_effect = tonumber(m.switchEffect)
        LVF.car_switch_effect[LVF.equip_switch_effect] = LVF.car_switch_effect[LVF.equip_switch_effect] or 0
    end
end

function F.applyVehicleModPersistToVRH(VRH)
    if not F.vehicleModUnlockOn() then return end
    VRH = VRH or require("client.network.Protocol.VehicleRefitHandler")
    if not VRH then return end
    local m = F.vehicleModPersist()
    VRH.resCarInfoList = VRH.resCarInfoList or {}
    VRH.resCarInfoList.car_list = VRH.resCarInfoList.car_list or {}
    VRH.OwnCarInfoMap = VRH.OwnCarInfoMap or {}
    for carId, styles in pairs(m.refit) do
        carId = tonumber(carId)
        if carId and type(styles) == "table" then
            local cur = VRH.resCarInfoList.car_list[carId]
            if type(cur) ~= "table" then
                VRH.resCarInfoList.car_list[carId] = {}
                cur = VRH.resCarInfoList.car_list[carId]
            end
            for partId, styleId in pairs(styles) do
                partId, styleId = tonumber(partId) or partId, tonumber(styleId)
                if styleId then
                    cur[partId] = styleId
                    VRH.OwnCarInfoMap[styleId] = 1
                end
            end
        end
    end
end

function F.applyVehicleModPersistToAccessory(LVA)
    if not F.vehicleModUnlockOn() then return end
    LVA = LVA or ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleAccessory)
    if not LVA then return end
    local m = F.vehicleModPersist()
    LVA.car_acc_list = LVA.car_acc_list or {}
    LVA.car_install_acc_list = LVA.car_install_acc_list or {}
    for carId, accs in pairs(m.accessories) do
        carId = tonumber(carId)
        if carId and type(accs) == "table" then
            LVA.car_install_acc_list[carId] = LVA.car_install_acc_list[carId] or {}
            for accId, on in pairs(accs) do
                accId = tonumber(accId)
                if accId and on then
                    LVA.car_acc_list[accId] = 1
                    LVA.car_install_acc_list[carId][accId] = 1
                end
            end
        end
    end
end

function F.reapplyVehicleModPersist(refreshTheme)
    if not F.vehicleModUnlockOn() then return end
    pcall(F.seedAllVehicleRefitOwnership)
    pcall(F.seedExtendedFeatureOwnership)
    pcall(F.applyVehicleModPersistToLVF)
    pcall(F.applyVehicleModPersistToVRH)
    pcall(F.applyVehicleModPersistToAccessory)
    if refreshTheme then
        pcall(function()
            local HallThemeUtils = require("client.logic.lobby.hall_theme_utils")
            if HallThemeUtils and HallThemeUtils.ShowThemeVehicle then
                HallThemeUtils.ShowThemeVehicle()
            end
        end)
    end
end

-- Apply equip/unequip local cho mọi extended feature (gồm vành + mạ phanh)
function F.applyExtendedFeatureEquipLocal(LVF, car_id, resid, op_type)
    if not LVF then return nil end
    resid = tonumber(resid)
    car_id = tonumber(car_id)
    if not resid or op_type == nil then return nil end
    F.seedExtendedFeatureOwnership()
    LVF.car_plate_background = LVF.car_plate_background or {}
    LVF.car_chassis_light = LVF.car_chassis_light or {}
    LVF.car_switch_effect = LVF.car_switch_effect or {}
    LVF.car_wheel_hub = LVF.car_wheel_hub or {}
    LVF.car_brake_caliper = LVF.car_brake_caliper or {}
    LVF.car_sunroof = LVF.car_sunroof or {}
    LVF.equip_plate_background = LVF.equip_plate_background or {}
    LVF.equip_chassis_light = LVF.equip_chassis_light or {}
    LVF.equip_wheel_hub = LVF.equip_wheel_hub or {}
    LVF.equip_brake_caliper = LVF.equip_brake_caliper or {}
    LVF.equip_sunroof = LVF.equip_sunroof or {}
    -- mark owned
    LVF.car_plate_background[resid] = LVF.car_plate_background[resid] or 0
    LVF.car_chassis_light[resid] = LVF.car_chassis_light[resid] or 0
    LVF.car_switch_effect[resid] = LVF.car_switch_effect[resid] or 0
    LVF.car_wheel_hub[resid] = LVF.car_wheel_hub[resid] or 0
    LVF.car_brake_caliper[resid] = LVF.car_brake_caliper[resid] or 0
    LVF.car_sunroof[resid] = LVF.car_sunroof[resid] or 0

    local kind = F.resolveExtendedFeatureKind(LVF, resid) or "switch"
    local potOn = (tonumber(op_type) == 0)
    local persistKey = car_id
    if potOn then
        if kind == "chassis" then
            if car_id then LVF.equip_chassis_light[car_id] = resid end
            pcall(function() if F.saveChassisLight then F.saveChassisLight(car_id, resid) end end)
        elseif kind == "plate" then
            pcall(function()
                local util = require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
                local vt = util and util.GetVehicleType and util.GetVehicleType(car_id)
                if vt then
                    LVF.equip_plate_background[vt] = resid
                    persistKey = vt
                end
            end)
        elseif kind == "wheel" then
            if car_id then LVF.equip_wheel_hub[car_id] = resid end
        elseif kind == "brake" then
            if car_id then LVF.equip_brake_caliper[car_id] = resid end
        elseif kind == "canopy" then
            if car_id then LVF.equip_sunroof[car_id] = resid end
        else
            LVF.equip_switch_effect = resid
        end
    else
        if kind == "chassis" then
            if car_id then LVF.equip_chassis_light[car_id] = nil end
        elseif kind == "plate" then
            pcall(function()
                local util = require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
                local vt = util and util.GetVehicleType and util.GetVehicleType(car_id)
                if vt then
                    LVF.equip_plate_background[vt] = nil
                    persistKey = vt
                end
            end)
        elseif kind == "wheel" then
            if car_id then LVF.equip_wheel_hub[car_id] = nil end
        elseif kind == "brake" then
            if car_id then LVF.equip_brake_caliper[car_id] = nil end
        elseif kind == "canopy" then
            if car_id then LVF.equip_sunroof[car_id] = nil end
        elseif LVF.equip_switch_effect == resid then
            LVF.equip_switch_effect = nil
        end
    end
    pcall(F.saveVehicleFeaturePersist, kind, persistKey, resid, potOn)
    -- Preview actor trong DetailShow
    pcall(function()
        local ui = UIManager and UIManager.GetUI and UIManager.GetUI(UIManager.UI_Config.Vehicle_DetailShow_UIBP)
        if not (ui and ui.curShowActor) then return end
        if kind == "wheel" and ui.curShowActor.SetVehicleWheelHub then
            ui.curShowActor:SetVehicleWheelHub(potOn and resid or nil)
        elseif kind == "brake" and ui.curShowActor.SetVehicleBrakeCaliper then
            ui.curShowActor:SetVehicleBrakeCaliper(potOn and resid or nil)
        elseif kind == "canopy" and ui.curShowActor.SetVehicleCanopy then
            ui.curShowActor:SetVehicleCanopy(potOn and resid or nil)
        elseif kind == "chassis" and ui.curShowActor.SetVehicleChassisLight then
            ui.curShowActor:SetVehicleChassisLight(potOn and resid or nil)
        end
    end)
    return F.buildExtendedFeatureData(LVF)
end

-- Unlock hết Vehicle Mod System (Workshop: Collect / Refit / Accessory / Extended)
function F.hookVehicleModSystemUnlock()
    -- Nuốt notice parameter error khi fake client
    pcall(function()
        if _G.ShowNotice and not _G._Kutta_ShowNoticeVehMod then
            _G._Kutta_ShowNoticeVehMod = _G.ShowNotice
            _G.ShowNotice = function(id, ...)
                local n = tonumber(id)
                if F.vehicleModUnlockOn() and n and (n == 9920302 or n == 8082 or n == 7034) then
                    return
                end
                return _G._Kutta_ShowNoticeVehMod(id, ...)
            end
        end
    end)
    -- Workshop entry: bỏ level / menu lock
    pcall(function()
        local UV = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.upgradeVehicle)
        if UV and UV.JumpVehicle and not UV._Kutta_JumpVehicle then
            UV._Kutta_JumpVehicle = UV.JumpVehicle
            UV.JumpVehicle = function(self, a, b, vars)
                if F.vehicleModUnlockOn() then
                    local VCS = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.VehicleCollectSystem)
                    if VCS and VCS.OpenVehicleWorkShop then
                        local tab = vars and tonumber(vars.tab)
                        local REFIT = VCS.ENUM_VEHICLE_SYSTEM and VCS.ENUM_VEHICLE_SYSTEM.REFIT or 2
                        if not tab then tab = REFIT end
                        return VCS:OpenVehicleWorkShop(tab, vars and tonumber(vars.itemId))
                    end
                end
                return UV._Kutta_JumpVehicle(self, a, b, vars)
            end
        end
    end)
    pcall(function()
        local LUM = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.level_unlock_manager)
        if LUM and LUM.IsFeatureUnlocked and not LUM._Kutta_IsFeatureUnlocked then
            LUM._Kutta_IsFeatureUnlocked = LUM.IsFeatureUnlocked
            LUM.IsFeatureUnlocked = function(self, feature)
                if F.vehicleModUnlockOn() then
                    local def = self.featureDef
                    if def and (feature == def.workshop or feature == "workshop") then
                        return true
                    end
                end
                return LUM._Kutta_IsFeatureUnlocked(self, feature)
            end
        end
    end)
    pcall(function()
        local VCS = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.VehicleCollectSystem)
        if not VCS or VCS._Kutta_WorkshopUnlock then return end
        VCS._Kutta_WorkshopUnlock = true
        if VCS.OpenVehicleWorkShop and not VCS._Kutta_OpenWorkshop then
            VCS._Kutta_OpenWorkshop = VCS.OpenVehicleWorkShop
            VCS.OpenVehicleWorkShop = function(self, SystemID, vars)
                if F.vehicleModUnlockOn() then
                    pcall(F.ensureWorkshopVehiclesInDepot)
                    pcall(F.reapplyVehicleModPersist, false)
                    return UIManager.ShowUI(UIManager.UI_Config.VehicleSystem_Main_UIBP, SystemID, vars)
                end
                return VCS._Kutta_OpenWorkshop(self, SystemID, vars)
            end
        end
        if VCS.HasUnLockFeature and not VCS._Kutta_HasUnLockFeature then
            VCS._Kutta_HasUnLockFeature = VCS.HasUnLockFeature
            VCS.HasUnLockFeature = function(self, ...)
                if F.vehicleModUnlockOn() then return true end
                return VCS._Kutta_HasUnLockFeature(self, ...)
            end
        end
        if VCS.HasUnlockFeature2 and not VCS._Kutta_HasUnlockFeature2 then
            VCS._Kutta_HasUnlockFeature2 = VCS.HasUnlockFeature2
            VCS.HasUnlockFeature2 = function(self, ...)
                if F.vehicleModUnlockOn() then return true end
                return VCS._Kutta_HasUnlockFeature2(self, ...)
            end
        end
        if VCS.IsUnlockFeatureEffect and not VCS._Kutta_IsUnlockFeatureEffect then
            VCS._Kutta_IsUnlockFeatureEffect = VCS.IsUnlockFeatureEffect
            VCS.IsUnlockFeatureEffect = function(self, ...)
                if F.vehicleModUnlockOn() then return true end
                return VCS._Kutta_IsUnlockFeatureEffect(self, ...)
            end
        end
        if VCS.NeedShowSubtabLock and not VCS._Kutta_NeedShowSubtabLock then
            VCS._Kutta_NeedShowSubtabLock = VCS.NeedShowSubtabLock
            VCS.NeedShowSubtabLock = function(self, ...)
                if F.vehicleModUnlockOn() then return false end
                return VCS._Kutta_NeedShowSubtabLock(self, ...)
            end
        end
        if VCS.IsOpenHighTire and not VCS._Kutta_IsOpenHighTire then
            VCS._Kutta_IsOpenHighTire = VCS.IsOpenHighTire
            VCS.IsOpenHighTire = function(self, VehicleID, UID, Position, Source)
                if F.vehicleModUnlockOn() then
                    local localUid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
                    if UID == nil or tonumber(UID) == 0 or tostring(UID) == tostring(localUid) then
                        return true
                    end
                end
                return VCS._Kutta_IsOpenHighTire(self, VehicleID, UID, Position, Source)
            end
        end
    end)

    -- Refit: sở hữu mọi style / bỏ khóa part & level
    pcall(function()
        local VRH = require("client.network.Protocol.VehicleRefitHandler")
        if not VRH or VRH._Kutta_RefitUnlock then return end
        VRH._Kutta_RefitUnlock = true

        if VRH.HaveStyleItem and not VRH._Kutta_HaveStyleItem then
            VRH._Kutta_HaveStyleItem = VRH.HaveStyleItem
            VRH.HaveStyleItem = function(StyleID)
                if F.vehicleModUnlockOn() then return true end
                return VRH._Kutta_HaveStyleItem(StyleID)
            end
        end
        if VRH.HasStyle and not VRH._Kutta_HasStyle then
            VRH._Kutta_HasStyle = VRH.HasStyle
            VRH.HasStyle = function(car_id, style_id, source)
                if F.vehicleModUnlockOn() then return true end
                return VRH._Kutta_HasStyle(car_id, style_id, source)
            end
        end
        -- Hiện mọi xe trong bảng refit (không chỉ carWithTime)
        if VRH.ShowAbleCars and not VRH._Kutta_ShowAbleCars then
            VRH._Kutta_ShowAbleCars = VRH.ShowAbleCars
            VRH.ShowAbleCars = function()
                if F.vehicleModUnlockOn() then
                    local tb = VRH.GetUnlockCarCfgTable and VRH.GetUnlockCarCfgTable()
                    if type(tb) == "table" and next(tb) then return tb end
                    local all = CDataTable and CDataTable.GetTable and CDataTable.GetTable("VehicleRefitInfo")
                    if type(all) == "table" and next(all) then return all end
                end
                return VRH._Kutta_ShowAbleCars()
            end
        end
        if VRH.GetCarUnlockPartList and not VRH._Kutta_GetCarUnlockPartList then
            VRH._Kutta_GetCarUnlockPartList = VRH.GetCarUnlockPartList
            VRH.GetCarUnlockPartList = function(car_id)
                if not F.vehicleModUnlockOn() then
                    return VRH._Kutta_GetCarUnlockPartList(car_id)
                end
                local parts, seen = {}, {}
                pcall(function()
                    local cfg = CDataTable.GetTableData("VehicleRefitInfo", car_id)
                    local gid = cfg and tonumber(cfg.vehicle_group_id)
                    local tb = CDataTable.GetTable("VehicleRefitStyle")
                    if not (gid and type(tb) == "table") then return end
                    for _, v in pairs(tb) do
                        if type(v) == "table" and tonumber(v.vehicle_group_id) == gid then
                            local pg = tonumber(v.part_group_id)
                            if pg and not seen[pg] then
                                seen[pg] = true
                                parts[#parts + 1] = pg
                            end
                        end
                    end
                end)
                if #parts > 0 then return parts end
                return VRH._Kutta_GetCarUnlockPartList(car_id)
            end
        end
        if VRH.GetCarPartGroupList and not VRH._Kutta_GetCarPartGroupList then
            VRH._Kutta_GetCarPartGroupList = VRH.GetCarPartGroupList
            VRH.GetCarPartGroupList = function(car_id)
                local list = VRH._Kutta_GetCarPartGroupList(car_id)
                if F.vehicleModUnlockOn() and type(list) == "table" then
                    for _, info in pairs(list) do
                        if type(info) == "table" then
                            info.bLocked = false
                        end
                    end
                end
                return list
            end
        end
        if VRH.GetLevelUpCfgList and not VRH._Kutta_GetLevelUpCfgList then
            VRH._Kutta_GetLevelUpCfgList = VRH.GetLevelUpCfgList
            VRH.GetLevelUpCfgList = function(carId)
                local list = VRH._Kutta_GetLevelUpCfgList(carId)
                if F.vehicleModUnlockOn() and type(list) == "table" then
                    for _, item in pairs(list) do
                        if type(item) == "table" then item.bLocked = false end
                    end
                end
                return list
            end
        end
        if VRH.ConvertUnLockListToMap and not VRH._Kutta_ConvertUnLockListToMap then
            VRH._Kutta_ConvertUnLockListToMap = VRH.ConvertUnLockListToMap
            VRH.ConvertUnLockListToMap = function()
                VRH._Kutta_ConvertUnLockListToMap()
                if F.vehicleModUnlockOn() then
                    F.seedAllVehicleRefitOwnership()
                    F.applyVehicleModPersistToVRH(VRH)
                    F.ensureWorkshopVehiclesInDepot()
                end
            end
        end
        if VRH.CheckLevelUpItem and not VRH._Kutta_CheckLevelUpItem then
            VRH._Kutta_CheckLevelUpItem = VRH.CheckLevelUpItem
            VRH.CheckLevelUpItem = function(car_id)
                if F.vehicleModUnlockOn() then return true end
                return VRH._Kutta_CheckLevelUpItem(car_id)
            end
        end
        if VRH.on_get_car_info_rsp and not VRH._Kutta_on_get_car_info_rsp then
            VRH._Kutta_on_get_car_info_rsp = VRH.on_get_car_info_rsp
            VRH.on_get_car_info_rsp = function(...)
                local ret = VRH._Kutta_on_get_car_info_rsp(...)
                if F.vehicleModUnlockOn() then
                    F.seedAllVehicleRefitOwnership()
                    F.ensureWorkshopVehiclesInDepot()
                    F.reapplyVehicleModPersist(true)
                end
                return ret
            end
        end
        if VRH.on_car_modification_rsp and not VRH._Kutta_on_mod_rsp then
            VRH._Kutta_on_mod_rsp = VRH.on_car_modification_rsp
            VRH.on_car_modification_rsp = function(error_code, params)
                if not F.vehicleModUnlockOn() then
                    return VRH._Kutta_on_mod_rsp(error_code, params)
                end
                if error_code ~= 0 then
                    -- Nuốt lỗi server (vd. 9920302) khi fake client
                    return
                end
                params = params or {}
                local car_id = tonumber(params.car_id)
                local car_info = params.car_info or {}
                VRH.resCarInfoList = VRH.resCarInfoList or {}
                VRH.resCarInfoList.car_list = VRH.resCarInfoList.car_list or {}
                VRH.OwnCarInfoMap = VRH.OwnCarInfoMap or {}
                if car_id then
                    local cur = VRH.resCarInfoList.car_list[car_id]
                    if type(cur) ~= "table" then
                        VRH.resCarInfoList.car_list[car_id] = car_info
                    else
                        for k, v in pairs(car_info) do cur[k] = v end
                    end
                    F.saveVehicleRefitPersist(car_id, car_info)
                end
                for _, v in pairs(car_info) do
                    local sid = tonumber(v)
                    if sid then VRH.OwnCarInfoMap[sid] = 1 end
                end
                pcall(function()
                    EventSystem:postEvent(EVENTTYPE_VEHICLE_REFIT, EVENTID_VEHICLE_REFIT_MODIFY)
                end)
                pcall(function()
                    local HallThemeUtils = require("client.logic.lobby.hall_theme_utils")
                    if HallThemeUtils and HallThemeUtils.ShowThemeVehicle then
                        HallThemeUtils.ShowThemeVehicle()
                    end
                end)
                -- Không gọi BasicDataAvatarWearInfo:GetOrReqData (server ghi đè equip)
            end
        end
        if VRH.send_car_modification_req and not VRH._Kutta_send_mod then
            VRH._Kutta_send_mod = VRH.send_car_modification_req
            VRH.send_car_modification_req = function(car_instid, car_info, cost_list)
                if not F.vehicleModUnlockOn() then
                    return VRH._Kutta_send_mod(car_instid, car_info, cost_list)
                end
                F.ensureWorkshopVehiclesInDepot()
                local car_id = F.resolveVehicleIdFromInst(car_instid)
                if (not car_id or car_id <= 0) and type(car_info) == "table" then
                    for _, styleId in pairs(car_info) do
                        pcall(function()
                            local cfg = CDataTable.GetTableData("VehicleRefitStyle", tonumber(styleId))
                            if not (cfg and cfg.vehicle_group_id) then return end
                            local best, bestLv = nil, -1
                            local tb = VRH.GetUnlockCarCfgTable and VRH.GetUnlockCarCfgTable() or {}
                            for _, v in pairs(tb) do
                                if type(v) == "table" and tonumber(v.vehicle_group_id) == tonumber(cfg.vehicle_group_id) then
                                    local lv = tonumber(v.level) or 0
                                    if lv >= bestLv then bestLv, best = lv, tonumber(v.vehicle_id) end
                                end
                            end
                            if best then car_id = best end
                        end)
                        if car_id and car_id > 0 then break end
                    end
                end
                car_id = tonumber(car_id) or 0
                if car_id > 0 then
                    pcall(function()
                        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                        if wd and not wd:GetHallDepotItemDataByResID(car_id) then
                            if F.grantDepotItem then F.grantDepotItem(car_id, 1, { markNew = false }) end
                        end
                    end)
                end
                F.seedAllVehicleRefitOwnership()
                VRH.OwnCarInfoMap = VRH.OwnCarInfoMap or {}
                VRH.resCarInfoList = VRH.resCarInfoList or {}
                VRH.resCarInfoList.car_list = VRH.resCarInfoList.car_list or {}
                local styleMap = {}
                if type(car_info) == "table" then
                    for partId, styleId in pairs(car_info) do
                        styleId = tonumber(styleId)
                        partId = tonumber(partId) or partId
                        if styleId then
                            VRH.OwnCarInfoMap[styleId] = 1
                            styleMap[partId] = styleId
                        end
                    end
                end
                if car_id > 0 then
                    local cur = VRH.resCarInfoList.car_list[car_id]
                    if type(cur) ~= "table" then
                        VRH.resCarInfoList.car_list[car_id] = styleMap
                    else
                        for k, v in pairs(styleMap) do cur[k] = v end
                    end
                    F.saveVehicleRefitPersist(car_id, styleMap)
                end
                VRH.on_car_modification_rsp(0, { car_id = car_id, car_info = styleMap })
            end
        end
        if VRH.send_car_level_up_req and not VRH._Kutta_send_lv then
            VRH._Kutta_send_lv = VRH.send_car_level_up_req
            VRH.send_car_level_up_req = function(car_instid, cost_list)
                if not F.vehicleModUnlockOn() then
                    return VRH._Kutta_send_lv(car_instid, cost_list)
                end
                local car_id = F.resolveVehicleIdFromInst(car_instid)
                local next_car_id = nil
                pcall(function()
                    if not car_id then return end
                    local cfg = CDataTable.GetTableData("VehicleRefitInfo", car_id)
                    if not cfg then return end
                    -- Grant cost materials nếu thiếu
                    pcall(function()
                        if cfg.cost_id1 and F.grantDepotItem then F.grantDepotItem(cfg.cost_id1, tonumber(cfg.cost_num1) or 1, { markNew = false }) end
                        if cfg.cost_id2 and F.grantDepotItem then F.grantDepotItem(cfg.cost_id2, tonumber(cfg.cost_num2) or 1, { markNew = false }) end
                    end)
                    local nextLv = (tonumber(cfg.level) or 1) + 1
                    local tb = VRH.GetUnlockCarCfgTable and VRH.GetUnlockCarCfgTable() or {}
                    for _, v in pairs(tb) do
                        if type(v) == "table"
                            and tonumber(v.vehicle_group_id) == tonumber(cfg.vehicle_group_id)
                            and tonumber(v.level) == nextLv then
                            next_car_id = tonumber(v.vehicle_id)
                            if F.grantDepotItem then F.grantDepotItem(next_car_id, 1, { markNew = false }) end
                            break
                        end
                    end
                    -- Giữ refit styles khi lên level
                    if next_car_id and VRH.resCarInfoList and VRH.resCarInfoList.car_list then
                        local oldStyles = VRH.resCarInfoList.car_list[car_id]
                        if type(oldStyles) == "table" then
                            VRH.resCarInfoList.car_list[next_car_id] = VRH.resCarInfoList.car_list[next_car_id] or {}
                            for k, v in pairs(oldStyles) do
                                VRH.resCarInfoList.car_list[next_car_id][k] = v
                            end
                            F.saveVehicleRefitPersist(next_car_id, VRH.resCarInfoList.car_list[next_car_id])
                        end
                    end
                end)
                VRH.bMaskPutTipsInLevelUp = true
                pcall(function()
                    VRH.on_car_level_up_rsp(0, { car_instid = car_instid, car_id = next_car_id or car_id })
                end)
                pcall(function()
                    local HallThemeUtils = require("client.logic.lobby.hall_theme_utils")
                    if HallThemeUtils and HallThemeUtils.ShowThemeVehicle then
                        HallThemeUtils.ShowThemeVehicle()
                    end
                end)
            end
        end
        if VRH.on_car_level_up_rsp and not VRH._Kutta_on_lv_rsp then
            VRH._Kutta_on_lv_rsp = VRH.on_car_level_up_rsp
            VRH.on_car_level_up_rsp = function(error_code, params)
                if F.vehicleModUnlockOn() and tonumber(error_code) and tonumber(error_code) ~= 0 then
                    return -- nuốt 9920302 / lỗi server
                end
                return VRH._Kutta_on_lv_rsp(error_code, params)
            end
        end
        if VRH.send_buy_car_modification_cost and not VRH._Kutta_send_buy then
            VRH._Kutta_send_buy = VRH.send_buy_car_modification_cost
            VRH.send_buy_car_modification_cost = function(params)
                if not F.vehicleModUnlockOn() then
                    return VRH._Kutta_send_buy(params)
                end
                VRH.on_buy_car_modification_rsp(0, params or {})
            end
        end
    end)

    -- Accessory tab
    -- NOTE: game bug — on_car_accessory_op_rsp dùng `not op_type` nên PotOn(0) bị drop
    pcall(function()
        local LVA = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleAccessory)
        if not LVA or LVA._Kutta_AccUnlock then return end
        LVA._Kutta_AccUnlock = true
        if LVA.CheckHasGetAccessoryItem and not LVA._Kutta_CheckHasGetAcc then
            LVA._Kutta_CheckHasGetAcc = LVA.CheckHasGetAccessoryItem
            LVA.CheckHasGetAccessoryItem = function(self, accItemId)
                if F.vehicleModUnlockOn() and accItemId then return true end
                return LVA._Kutta_CheckHasGetAcc(self, accItemId)
            end
        end
        if LVA.CheckHasGetVehicle and not LVA._Kutta_CheckHasGetVeh then
            LVA._Kutta_CheckHasGetVeh = LVA.CheckHasGetVehicle
            LVA.CheckHasGetVehicle = function(self, vehicleId)
                if F.vehicleModUnlockOn() and vehicleId then return true end
                return LVA._Kutta_CheckHasGetVeh(self, vehicleId)
            end
        end
        if LVA.CheckHasEnoughCost and not LVA._Kutta_CheckCost then
            LVA._Kutta_CheckCost = LVA.CheckHasEnoughCost
            LVA.CheckHasEnoughCost = function(self, costItemId, count)
                if F.vehicleModUnlockOn() then return true end
                return LVA._Kutta_CheckCost(self, costItemId, count)
            end
        end
        if LVA.on_car_accessory_op_rsp and not LVA._Kutta_acc_op_rsp then
            LVA._Kutta_acc_op_rsp = LVA.on_car_accessory_op_rsp
            LVA.on_car_accessory_op_rsp = function(self, car_id, acc_id, op_type)
                -- Fix: PotOn = 0 không được dùng `not op_type`
                if not car_id or not acc_id or op_type == nil then
                    return
                end
                self.car_install_acc_list = self.car_install_acc_list or {}
                self.car_install_acc_list[car_id] = self.car_install_acc_list[car_id] or {}
                local potOn = tonumber(op_type) == 0
                if potOn then
                    self.car_install_acc_list[car_id][acc_id] = 1
                else
                    self.car_install_acc_list[car_id][acc_id] = nil
                end
                pcall(F.saveVehicleAccessoryPersist, car_id, acc_id, potOn)
                pcall(function()
                    local HallThemeUtils = require("client.logic.lobby.hall_theme_utils")
                    if HallThemeUtils and HallThemeUtils.ShowThemeVehicle then
                        HallThemeUtils.ShowThemeVehicle()
                    end
                end)
                pcall(function()
                    EventSystem:postEvent(EVENTTYPE_VEHICLE_ACCESSORY, EVENTID_VEHICLE_ACCESSORY_EQUIP_UPDATE, car_id, acc_id, op_type)
                end)
            end
        end
        if LVA.send_car_unlock_accessory_req and not LVA._Kutta_send_unlock_acc then
            LVA._Kutta_send_unlock_acc = LVA.send_car_unlock_accessory_req
            LVA.send_car_unlock_accessory_req = function(self, car_id, acc_id)
                if F.vehicleModUnlockOn() then
                    if car_id and F.grantDepotItem then
                        pcall(F.grantDepotItem, car_id, 1, { markNew = false })
                    end
                    self.car_acc_list = self.car_acc_list or {}
                    if acc_id then self.car_acc_list[acc_id] = 1 end
                    return self:on_car_unlock_accessory_rsp(car_id, acc_id)
                end
                return LVA._Kutta_send_unlock_acc(self, car_id, acc_id)
            end
        end
        if LVA.send_car_accessory_op_req and not LVA._Kutta_send_acc_op then
            LVA._Kutta_send_acc_op = LVA.send_car_accessory_op_req
            LVA.send_car_accessory_op_req = function(self, car_id, acc_id, op_type)
                if not F.vehicleModUnlockOn() then
                    return LVA._Kutta_send_acc_op(self, car_id, acc_id, op_type)
                end
                if car_id and F.grantDepotItem then
                    pcall(F.grantDepotItem, car_id, 1, { markNew = false })
                end
                self.car_acc_list = self.car_acc_list or {}
                if acc_id then self.car_acc_list[acc_id] = 1 end
                self.car_install_acc_list = self.car_install_acc_list or {}
                return self:on_car_accessory_op_rsp(car_id, acc_id, op_type)
            end
        end
    end)

    -- Protocol layer: chắc chắn không gửi server (kể cả nếu logic gọi thẳng Handler)
    pcall(function()
        local VAH = require("client.network.Protocol.VehicleAccessoryHandler")
        if not VAH or VAH._Kutta_ProtoUnlock then return end
        VAH._Kutta_ProtoUnlock = true
        if VAH.send_get_car_feature_data_req and not VAH._Kutta_send_get_feature then
            VAH._Kutta_send_get_feature = VAH.send_get_car_feature_data_req
            VAH.send_get_car_feature_data_req = function()
                if F.vehicleModUnlockOn() then
                    F.seedExtendedFeatureOwnership()
                    F.applyVehicleModPersistToLVF()
                    local LVF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
                    local feature_data = F.buildExtendedFeatureData(LVF)
                    return VAH.on_get_car_feature_data_rsp(0, feature_data, nil)
                end
                return VAH._Kutta_send_get_feature()
            end
        end
        if VAH.on_get_car_feature_data_rsp and not VAH._Kutta_on_get_feature then
            VAH._Kutta_on_get_feature = VAH.on_get_car_feature_data_rsp
            VAH.on_get_car_feature_data_rsp = function(err, feature_data, inherit_feature_data)
                if F.vehicleModUnlockOn() then
                    if tonumber(err) and tonumber(err) ~= 0 then
                        -- Server parameter error (9920302...) — dùng local persist
                        F.seedExtendedFeatureOwnership()
                        F.applyVehicleModPersistToLVF()
                        local LVF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
                        feature_data = F.buildExtendedFeatureData(LVF)
                        err = 0
                    end
                    local ret = VAH._Kutta_on_get_feature(err, feature_data, inherit_feature_data)
                    F.reapplyVehicleModPersist(true)
                    return ret
                end
                return VAH._Kutta_on_get_feature(err, feature_data, inherit_feature_data)
            end
        end
        if VAH.send_car_unlock_accessory_req and not VAH._Kutta_send_unlock then
            VAH._Kutta_send_unlock = VAH.send_car_unlock_accessory_req
            VAH.send_car_unlock_accessory_req = function(car_id, acc_id)
                if F.vehicleModUnlockOn() then
                    return VAH.on_car_unlock_accessory_rsp(0, car_id, acc_id)
                end
                return VAH._Kutta_send_unlock(car_id, acc_id)
            end
        end
        if VAH.send_car_accessory_op_req and not VAH._Kutta_send_op then
            VAH._Kutta_send_op = VAH.send_car_accessory_op_req
            VAH.send_car_accessory_op_req = function(car_id, acc_id, op_type)
                if F.vehicleModUnlockOn() then
                    local LVA = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleAccessory)
                    if LVA then
                        LVA.car_acc_list = LVA.car_acc_list or {}
                        if acc_id then LVA.car_acc_list[acc_id] = 1 end
                        LVA.car_install_acc_list = LVA.car_install_acc_list or {}
                    end
                    return VAH.on_car_accessory_op_rsp(0, car_id, acc_id, op_type)
                end
                return VAH._Kutta_send_op(car_id, acc_id, op_type)
            end
        end
        if VAH.send_equip_car_feature_req and not VAH._Kutta_send_feature then
            VAH._Kutta_send_feature = VAH.send_equip_car_feature_req
            VAH.send_equip_car_feature_req = function(car_id, resid, op_type)
                if not F.vehicleModUnlockOn() then
                    return VAH._Kutta_send_feature(car_id, resid, op_type)
                end
                local LVF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
                if not LVF then
                    return VAH._Kutta_send_feature(car_id, resid, op_type)
                end
                local feature_data = F.applyExtendedFeatureEquipLocal(LVF, car_id, resid, op_type)
                if not feature_data then return end
                return VAH.on_equip_car_feature_rsp(0, car_id, resid, op_type, feature_data)
            end
        end
        if VAH.send_car_feature_op_req and not VAH._Kutta_send_feat_op then
            VAH._Kutta_send_feat_op = VAH.send_car_feature_op_req
            VAH.send_car_feature_op_req = function(feature_id, op_type)
                if F.vehicleModUnlockOn() then
                    return VAH.on_car_feature_op_rsp(0, feature_id, op_type)
                end
                return VAH._Kutta_send_feat_op(feature_id, op_type)
            end
        end
    end)

    -- Extended feature equip (plate / chassis / switch) — client apply
    -- NOTE: game bug — on_equip_car_feature_rsp dùng `resid and op_type` nên PotOn(0) bị drop
    pcall(function()
        local LVF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
        if not LVF or LVF._Kutta_FeatureEquipUnlock then return end
        LVF._Kutta_FeatureEquipUnlock = true
        if LVF.GetFeatureItemStateFlag and not LVF._Kutta_GetFeatureFlag then
            LVF._Kutta_GetFeatureFlag = LVF.GetFeatureItemStateFlag
            LVF.GetFeatureItemStateFlag = function(self, featureId)
                if F.vehicleModUnlockOn() and featureId then
                    F.seedExtendedFeatureOwnership()
                    return 0
                end
                return LVF._Kutta_GetFeatureFlag(self, featureId)
            end
        end
        if LVF.on_equip_car_feature_rsp and not LVF._Kutta_feature_rsp then
            LVF._Kutta_feature_rsp = LVF.on_equip_car_feature_rsp
            LVF.on_equip_car_feature_rsp = function(self, car_id, resid, op_type, feature_data)
                -- Fix game bug: PotOn=0 bị `not op_type` nuốt mất
                if not resid or op_type == nil or not feature_data then return end
                if self.InitServerData then self:InitServerData(feature_data) end
                if car_id then
                    pcall(function()
                        local HallThemeUtils = require("client.logic.lobby.hall_theme_utils")
                        if HallThemeUtils and HallThemeUtils.ShowThemeVehicle then
                            HallThemeUtils.ShowThemeVehicle()
                        end
                    end)
                end
                pcall(function()
                    EventSystem:postEvent(EVENTTYPE_VEHICLE_ACCESSORY, EVENTID_VEHICLE_EXTENDED_FEATURE_EQUIP_UPDATE, resid, op_type, car_id)
                end)
            end
        end
        if LVF.send_equip_car_feature_req and not LVF._Kutta_send_feature then
            LVF._Kutta_send_feature = LVF.send_equip_car_feature_req
            LVF.send_equip_car_feature_req = function(self, car_id, resid, op_type)
                if not F.vehicleModUnlockOn() then
                    return LVF._Kutta_send_feature(self, car_id, resid, op_type)
                end
                local VAH = require("client.network.Protocol.VehicleAccessoryHandler")
                if VAH and VAH.send_equip_car_feature_req then
                    return VAH.send_equip_car_feature_req(car_id, resid, op_type)
                end
                local feature_data = F.applyExtendedFeatureEquipLocal(self, car_id, resid, op_type)
                if feature_data and self.on_equip_car_feature_rsp then
                    return self:on_equip_car_feature_rsp(car_id, resid, op_type, feature_data)
                end
                return LVF._Kutta_send_feature(self, car_id, resid, op_type)
            end
        end
        pcall(F.seedExtendedFeatureOwnership)
    end)

    -- vehicle_main: đảm bảo itemData + level max để Equip/Save không ShowNotice(8087)
    pcall(function()
        local VM = require("client.slua.umg.vehicle.vehicle_main")
        if not VM or VM._Kutta_EquipPatch then return end
        VM._Kutta_EquipPatch = true
        if VM.GetRefitCarList and not VM._Kutta_GetRefitCarList then
            VM._Kutta_GetRefitCarList = VM.GetRefitCarList
            VM.GetRefitCarList = function(self)
                if F.vehicleModUnlockOn() then
                    pcall(F.ensureWorkshopVehiclesInDepot)
                    pcall(F.seedAllVehicleRefitOwnership)
                end
                local list = VM._Kutta_GetRefitCarList(self)
                if F.vehicleModUnlockOn() and type(list) == "table" then
                    for _, group in pairs(list) do
                        if type(group) == "table" then
                            for _, info in pairs(group) do
                                F.patchCarInfoForEquip(info)
                            end
                        end
                    end
                end
                return list
            end
        end
        if VM.GetCarInfoByIndex and not VM._Kutta_GetCarInfoByIndex then
            VM._Kutta_GetCarInfoByIndex = VM.GetCarInfoByIndex
            VM.GetCarInfoByIndex = function(self, index)
                local info = VM._Kutta_GetCarInfoByIndex(self, index)
                if F.vehicleModUnlockOn() then F.patchCarInfoForEquip(info) end
                return info
            end
        end
        if VM.OnBtnEquipClick and not VM._Kutta_OnBtnEquipClick then
            VM._Kutta_OnBtnEquipClick = VM.OnBtnEquipClick
            VM.OnBtnEquipClick = function(self)
                if F.vehicleModUnlockOn() then
                    local carInfo = self:GetCarInfoByIndex(self.curSelectCarIndex)
                    F.patchCarInfoForEquip(carInfo)
                    if carInfo and carInfo.itemData and carInfo.itemData.insID then
                        local WardrobeLogicManager = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                        if F.tryLocalWearByIns and F.tryLocalWearByIns(carInfo.itemData.insID) then
                            pcall(function() self:UpdateJumpStoreBtn() end)
                            return
                        end
                        return WardrobeLogicManager:wardrobe_puton_req(carInfo.itemData.insID)
                    end
                end
                return VM._Kutta_OnBtnEquipClick(self)
            end
        end
    end)

    pcall(function()
        local VRM = require("client.slua.umg.vehicle.vehicle_refit_main")
        if not VRM or VRM._Kutta_EquipPatch then return end
        VRM._Kutta_EquipPatch = true
        if VRM.InitData and not VRM._Kutta_InitData then
            VRM._Kutta_InitData = VRM.InitData
            VRM.InitData = function(self)
                if F.vehicleModUnlockOn() and self.carInfo then
                    F.patchCarInfoForEquip(self.carInfo)
                end
                local ret = VRM._Kutta_InitData(self)
                if F.vehicleModUnlockOn() and type(self.tabDataList) == "table" then
                    for _, tab in pairs(self.tabDataList) do
                        if type(tab) == "table" then tab.bLocked = false end
                    end
                end
                return ret
            end
        end
        if VRM.OnBtnEquipClick and not VRM._Kutta_OnBtnEquipClick then
            VRM._Kutta_OnBtnEquipClick = VRM.OnBtnEquipClick
            VRM.OnBtnEquipClick = function(self)
                if F.vehicleModUnlockOn() then
                    F.patchCarInfoForEquip(self.carInfo)
                    if not (self.carInfo and self.carInfo.itemData and self.carInfo.itemData.insID) then
                        ShowNotice(8087)
                        return
                    end
                end
                return VRM._Kutta_OnBtnEquipClick(self)
            end
        end
        if VRM.OnBtnSaveClick and not VRM._Kutta_OnBtnSaveClick then
            VRM._Kutta_OnBtnSaveClick = VRM.OnBtnSaveClick
            VRM.OnBtnSaveClick = function(self)
                if F.vehicleModUnlockOn() then F.patchCarInfoForEquip(self.carInfo) end
                return VRM._Kutta_OnBtnSaveClick(self)
            end
        end
    end)

    pcall(function()
        local VRS = require("client.slua.umg.vehicle.vehicle_refit_save")
        if not VRS or VRS._Kutta_EquipPatch then return end
        VRS._Kutta_EquipPatch = true
        if VRS.OnBtnEquipClick and not VRS._Kutta_OnBtnEquipClick then
            VRS._Kutta_OnBtnEquipClick = VRS.OnBtnEquipClick
            VRS.OnBtnEquipClick = function(self)
                if F.vehicleModUnlockOn() then
                    F.patchCarInfoForEquip(self.carInfo)
                    if self.carInfo and self.carInfo.itemData and self.carInfo.itemData.insID then
                        local ins = self.carInfo.itemData.insID
                        if F.tryLocalWearByIns and F.tryLocalWearByIns(ins) then
                            pcall(function() self:UpdateJumpStoreBtn() end)
                            return
                        end
                    end
                end
                return VRS._Kutta_OnBtnEquipClick(self)
            end
        end
    end)

    -- Special effect list
    pcall(function()
        local VF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.VehicleFeature)
        if VF and VF.IsUnlockFeature and not VF._Kutta_IsUnlockFeature then
            VF._Kutta_IsUnlockFeature = VF.IsUnlockFeature
            VF.IsUnlockFeature = function(self, itemID)
                if F.vehicleModUnlockOn() then return true end
                return VF._Kutta_IsUnlockFeature(self, itemID)
            end
        end
    end)

    -- Plate unlock util
    pcall(function()
        local utilMod = require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
        if utilMod and utilMod.CheckHasUnLockFeature and not utilMod._Kutta_UnlockAllFeature then
            utilMod._Kutta_UnlockAllFeature = true
            local orig = utilMod.CheckHasUnLockFeature
            utilMod.CheckHasUnLockFeature = function(ft, uid, itemId)
                if F.vehicleModUnlockOn() then return true end
                return orig(ft, uid, itemId)
            end
        end
    end)

    pcall(F.seedAllVehicleRefitOwnership)
    _G.AddOutfitVehModUnlockHooked = true
end

function F.hookVehicleChassisLight()
    if _G.AddOutfitVehChassisHooked then return end
    pcall(function()
        local LIC = require("GameLua.Activity.Commercialize.Actor.ActorComponent.BP_VehicleLicenseComponentBase")
        if LIC and LIC.CheckHasVehicleDownloaded and not _G.AddOutfitVehOrigLicDownload then
            _G.AddOutfitVehOrigLicDownload = LIC.CheckHasVehicleDownloaded
            LIC.CheckHasVehicleDownloaded = function(self, itemID)
                local id = tonumber(itemID)
                if F.vehicleModUnlockOn() then return true end
                if F.isVehicleSkinAllowed(id) or F.isChassisLightId(id) then return true end
                return _G.AddOutfitVehOrigLicDownload(self, itemID)
            end
        end
    end)
    pcall(function()
        local LVF = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.LogicVehicleExtendedFeature)
        if not LVF or LVF._AddOutfitChassisHooked then return end
        LVF._AddOutfitChassisHooked = true

        if not _G.AddOutfitVehOrigGetFeature then
            _G.AddOutfitVehOrigGetFeature = LVF.CheckHasGetFeatureItem
        end
        LVF.CheckHasGetFeatureItem = function(self, featureId)
            if F.vehicleModUnlockOn() then return true end
            if F.isChassisLightId(featureId) then return true end
            return _G.AddOutfitVehOrigGetFeature(self, featureId)
        end

        if not _G.AddOutfitVehOrigEquippedFeature then
            _G.AddOutfitVehOrigEquippedFeature = LVF.CheckHasEquippedItem
        end
        LVF.CheckHasEquippedItem = function(self, featureId, vehicleId)
            -- [FIX VIP] Bổ sung check điều kiện ModSkin
            if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModSkin ~= false then
                if F.isChassisLightId(featureId) then
                    return F.getDesiredChassisLight(vehicleId) == tonumber(featureId)
                end
            end
            return _G.AddOutfitVehOrigEquippedFeature(self, featureId, vehicleId)
        end

        if not _G.AddOutfitVehOrigEquipChassisData then
            _G.AddOutfitVehOrigEquipChassisData = LVF.GetEquipedChassisLightData
        end
        LVF.GetEquipedChassisLightData = function(self, vehicleId, source)
            -- [FIX VIP] Bổ sung check điều kiện ModSkin
            if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModSkin ~= false then
                local our = F.getDesiredChassisLight(vehicleId)
                if our then return our end
            end
            return _G.AddOutfitVehOrigEquipChassisData(self, vehicleId, source)
        end

        if not _G.AddOutfitVehOrigChassisLightData then
            _G.AddOutfitVehOrigChassisLightData = LVF.GetVehicleChassisLightData
        end
        LVF.GetVehicleChassisLightData = function(self, uid, vehicleId, position, source)
            -- [FIX VIP] Bổ sung check điều kiện ModSkin
            if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModSkin ~= false then
                if uid and DataMgr and DataMgr.roleData and tonumber(uid) == tonumber(DataMgr.roleData.uid) then
                    local our = F.getDesiredChassisLight(vehicleId)
                    if our then return our end
                end
            end
            return _G.AddOutfitVehOrigChassisLightData(self, uid, vehicleId, position, source)
        end

        if not _G.AddOutfitVehOrigPutOnFeature then
            _G.AddOutfitVehOrigPutOnFeature = LVF.PutOnVehicleFeature
        end
        LVF.PutOnVehicleFeature = function(self, featureId, vehicleId)
            featureId = tonumber(featureId)
            vehicleId = tonumber(vehicleId)
            if F.isChassisLightId(featureId) then
                F.saveChassisLight(vehicleId, featureId)
                self.equip_chassis_light = self.equip_chassis_light or {}
                if vehicleId and vehicleId > 0 then
                    self.equip_chassis_light[vehicleId] = featureId
                end
                return
            end
            return _G.AddOutfitVehOrigPutOnFeature(self, featureId, vehicleId)
        end

        if not _G.AddOutfitVehOrigPutOffFeature then
            _G.AddOutfitVehOrigPutOffFeature = LVF.PutOffVehicleFeature
        end
        LVF.PutOffVehicleFeature = function(self, featureId, vehicleId)
            featureId = tonumber(featureId)
            vehicleId = tonumber(vehicleId)
            if F.isChassisLightId(featureId) then
                PERSIST.configChassisLightMap = PERSIST.configChassisLightMap or {}
                if vehicleId and vehicleId > 0 then
                    PERSIST.configChassisLightMap[vehicleId] = nil
                end
                if self.equip_chassis_light and vehicleId then
                    self.equip_chassis_light[vehicleId] = nil
                end
                F.persistMarkDirty()
                return
            end
            return _G.AddOutfitVehOrigPutOffFeature(self, featureId, vehicleId)
        end
    end)
    _G.AddOutfitVehChassisHooked = true
end

function F.hookVehicles()
    F.hookVehicleSwitchEffect()
    F.hookVehicleChassisLight()
    pcall(F.hookVehicleExtendedFeaturesServerData)
    F.hookVehicleModSystemUnlock()
    pcall(function()
        local WV = require("client.slua.umg.Wardrobe.subtab_vehicles")
        if not WV or WV._AddOutfitVehClickHooked then return end
        WV._AddOutfitVehClickHooked = true
        local oClick = WV.ClickItem
        WV.ClickItem = function(self, vehicleSkin, bForceUsing)
            if vehicleSkin and F.isInjectedRes(vehicleSkin.res_id) then
                vehicleSkin.expireTS = 0
                vehicleSkin.expire_ts = 0
            end
            return oClick(self, vehicleSkin, bForceUsing)
        end
        local oDrop = WV.OnVehicleSlotDrop
        if oDrop then
            WV.OnVehicleSlotDrop = function(self, DragWidget, Index, DragDropData)
                pcall(function()
                    local ins = DragDropData and DragDropData.ins_id
                    if F.isInjectedIns(tonumber(ins)) then
                        F.ensureInjectedItemAlive(nil, nil, ins)
                    end
                end)
                return oDrop(self, DragWidget, Index, DragDropData)
            end
        end
    end)
    pcall(function()
        local WNH = require("client.network.Protocol.WardrobeNewHandler")
        if WNH._AddOutfitVehicleHooked then return end
        WNH._AddOutfitVehicleHooked = true
        local oMod = WNH.send_depot_modify_combat_vehicle_req
        WNH.send_depot_modify_combat_vehicle_req = function(instid, slot_index, ope_type)
            if F.modifyInjectedVehicleSlot(instid, slot_index, ope_type == true) then return end
            return oMod(instid, slot_index, ope_type)
        end
        local oRsp = WNH.on_depot_modify_combat_vehicle_rsp
        WNH.on_depot_modify_combat_vehicle_rsp = function(err_code, knapsack_vst)
            if err_code == 0 or err_code == NET_OK then
                knapsack_vst = F.mergeInjectedIntoVehicleSlotList(knapsack_vst)
            end
            oRsp(err_code, knapsack_vst)
            if err_code == 0 or err_code == NET_OK then
                F.syncVehicleSlotsToDataMgr()
                F.equipVehicleTypesFromConfig(PERSIST.configVehicleSlots)
                if not (_G.AddOutfitLobbyVeh and _G.AddOutfitLobbyVeh.manual) then
                    pcall(F.applyVehicleSkinsToPC)
                end
                F.persistMarkDirty()
            end
        end
    end)
    pcall(function()
        local gsm = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.golden_suit_module)
        if gsm and gsm.VehicleNeedClothes and not gsm._AddOutfitVehClothesHooked then
            gsm._AddOutfitVehClothesHooked = true
            local o = gsm.VehicleNeedClothes
            gsm.VehicleNeedClothes = function(self, vehicleId)
                vehicleId = tonumber(vehicleId)
                if vehicleId and F.isInjectedRes(vehicleId) then return 0 end
                return o(self, vehicleId)
            end
        end
    end)
    pcall(function()
        local mod = require("GameLua.Activity.Commercialize.GamePlay.CommerAvatarDataUtil")
        if mod._FillVehicleSkinList then
            if not _G.AddOutfitVehFillOrig then
                _G.AddOutfitVehFillOrig = mod._FillVehicleSkinList
            end
            local o = _G.AddOutfitVehFillOrig
            mod._FillVehicleSkinList = function(self, playerInfo, uPlayerController)
                F.mergeVstIntoPlayerInfo(playerInfo)
                -- Inject VehicleExtendedFeatures (attr 66) trước khi Fill đọc ServerPlayerDataMgr
                pcall(function()
                    if not (F.vehicleModUnlockOn and F.vehicleModUnlockOn()) then return end
                    local EA = require("Server.config.ExtendAttribute")
                    if not playerInfo or not EA then return end
                    playerInfo.ext_attr = playerInfo.ext_attr or {}
                    local key = EA.VehicleExtendedFeatures
                    playerInfo.ext_attr[key] = F.buildVehicleExtendedFeaturesTable(playerInfo.ext_attr[key])
                end)
                local ret = o(self, playerInfo, uPlayerController)
                pcall(function()
                    if slua.isValid(uPlayerController) then
                        F.applyVehiclePartDataToPC(uPlayerController, uPlayerController.ShowVehicleSkin)
                    end
                end)
                return ret
            end
            mod._AddOutfitFillVehHooked = true
        end
    end)
    pcall(function()
        local classMod = require("GameLua.Mod.BaseMod.Client.InGameUI.VehicleControl.VehicleSkinItem")
        if not classMod or not classMod.__inner_impl then return end
        local impl = classMod.__inner_impl
        if not _G.AddOutfitVehOrigClick then
            _G.AddOutfitVehOrigClick = impl.OnClickSkinButton
        end
        local oClick = _G.AddOutfitVehOrigClick
        impl.OnClickSkinButton = function(self)
            local resID = tonumber(self.resID)
            if resID and resID > 0 then
                if F.matchApplyVehicleSkin(resID) then
                    pcall(function()
                        if EVENTYPE_INGAME_VEHICLE_CONTROL_PANEL and EVENTID_CHANGE_VEHICLESKIN_BUTTON_CLICK then
                            EventSystem:postEvent(EVENTYPE_INGAME_VEHICLE_CONTROL_PANEL, EVENTID_CHANGE_VEHICLESKIN_BUTTON_CLICK)
                        end
                    end)
                end
                return
            end
            return oClick(self)
        end
        if not _G.AddOutfitVehOrigRefresh then
            _G.AddOutfitVehOrigRefresh = impl.OnRefresh
        end
        local oRefresh = _G.AddOutfitVehOrigRefresh
        impl.OnRefresh = function(self, resID, selectIndex)
            oRefresh(self, resID, selectIndex)
            if self.resID and tonumber(self.resID) and tonumber(self.resID) > 0 then
                if F.isResourcesReady(self.resID) then
                    pcall(function()
                        local PufferConst = require("client.slua.logic.download.puffer_const")
                        self.dowloadState = PufferConst.ENUM_DownloadState.Done
                        self.UIRoot.Image_Download:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                        self:SetWidgetVisible(self.UIRoot.Image_Mask, false)
                    end)
                else
                    F.requestResourceDownload(self.resID)
                end
            end
        end
        classMod._AddOutfitSkinClickHooked = true
    end)
    pcall(function()
        local utilMod = require("GameLua.Activity.Commercialize.GamePlay.Vehicle.VehiclePlateLicenseUtil")
        if utilMod.CheckHasUnLockFeature and not utilMod._AddOutfitVehPlateHooked then
            utilMod._AddOutfitVehPlateHooked = true
            local orig = utilMod.CheckHasUnLockFeature
            utilMod.CheckHasUnLockFeature = function(ft, uid, itemId)
                local id = tonumber(itemId)
                if F.isVehicleSkinAllowed(id) or F.isChassisLightId(id) then return true end
                return orig(ft, uid, itemId)
            end
        end
    end)
    pcall(function()
        local panelMod = require("GameLua.Mod.BaseMod.Client.InGameUI.VehicleControl.VehicleSkinAndMusicPanel")
        if panelMod and panelMod.__inner_impl and not panelMod._AddOutfitInitSkinHooked then
            panelMod._AddOutfitInitSkinHooked = true
            local o = panelMod.__inner_impl.InitSkinList
            panelMod.__inner_impl.InitSkinList = function(self)
                F.applyVehicleSkinsToPC(F.getPC())
                return o(self)
            end
        end
    end)
    pcall(function()
        local VUC = require("GameLua.GameCore.Module.Vehicle.Component.VehicleUserComponent")
        if not VUC then return end
        if not _G.AddOutfitVehOrigEnter then
            _G.AddOutfitVehOrigEnter = VUC.SendUIMsgWhenEnterVehicleCompleted
        end
        local oEnter = _G.AddOutfitVehOrigEnter
        VUC.SendUIMsgWhenEnterVehicleCompleted = function(self)
            oEnter(self)
            pcall(function()
                if slua.isValid(self.Vehicle) then
                    F.autoApplyVehicleSkinOnEnter(self.Vehicle)
                end
            end)
        end
        VUC._AddOutfitEnterVehHooked = true
    end)
end

function F.hookWeaponWear()
    pcall(function()
        local HT = require("client.logic.lobby.hall_theme_utils")
        local o = HT.IsWeaponWear
        HT.IsWeaponWear = function(insId)
            insId = tonumber(insId)
            if F.isInjectedIns(insId) then
                local c = F.cache()
                local Arm = require("client.logic.armory.logic_armory")
                for wid, w in pairs(c.weapons) do
                    if tonumber(w.insID) == insId then
                        if Arm.rsp_list and Arm.rsp_list.install_list and Arm.rsp_list.install_list[wid] then
                            return tonumber(Arm.rsp_list.install_list[wid].skin_id) == insId
                        end
                        return true
                    end
                end
            end
            return o(insId)
        end
    end)
end

function F.hookNotice()
    pcall(function()
        if DataMgr and not DataMgr._AddOutfitExpireHooked then
            DataMgr._AddOutfitExpireHooked = true
            local oValid = DataMgr.IsValidTime
            DataMgr.IsValidTime = function(expireTS)
                if expireTS == nil or tonumber(expireTS) == 0 then return true end
                if oValid and oValid(expireTS) then return true end
                local inMatch = false
                pcall(function()
                    inMatch = GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus()
                end)
                if not inMatch then return true end
                return false
            end
        end
    end)
end

function F.wrapWardrobeClick(classMod, key)
    if not classMod or not classMod[key] or classMod["_AddOutfitWrap_" .. key] then return end
    classMod["_AddOutfitWrap_" .. key] = true
    local orig = classMod[key]
    classMod[key] = function(self, widget, index)
        local itemData = self.LoopScrollGrid_Normal and self.LoopScrollGrid_Normal:GetItemData(index)
        if itemData then
            F.clearItemExpire(itemData, itemData.ins_id, itemData.res_id)
            F.ensureDepotItemValid(itemData.ins_id, itemData.res_id)
        end
        return orig(self, widget, index)
    end
end

