function F.matchApplyFaceWear(char)
    if not F.skinFeat("SkinMatchFace") then return true end
    local maskRes = F.getDesiredMask()
    local glassRes = F.getDesiredGlass()
    if (not maskRes or maskRes <= 0) and (not glassRes or glassRes <= 0) then
        return true
    end
    char = char or F.getLocalChar()
    if not char then return false end
    local comp = F.getAvatarComp2(char)
    if not comp then return false end

    local ok = false
    pcall(function()
        local EAvatarSlotType = import("EAvatarSlotType")
        local ESyncOperation = import("ESyncOperation")
        local net = comp.NetAvatarData
        local applyData = net and net.SlotSyncData

        local function forceApplySlot(resID, slotID, slotNameStr)
            if not resID or resID <= 0 then return end
            
            local slotEnum = EAvatarSlotType and EAvatarSlotType[slotNameStr]
            local needRep = false
            
            -- 1. GHI ĐÈ DATA MẠNG (Chống lỗi không đồng bộ)
            if applyData and slua.isValid(applyData) then
                local found = false
                for i = 0, applyData:Num() - 1 do
                    local equipment = applyData:Get(i)
                    if equipment and equipment.SlotID == slotID then
                        found = true
                        local cur = tonumber(equipment.ItemId) or tonumber(equipment.ItemID) or 0
                        if cur ~= resID then
                            F.ensureSkinDownload(resID)
                            equipment.ItemId = resID
                            if equipment.ItemID ~= nil then equipment.ItemID = resID end
                            if equipment.FakeItemID ~= nil then equipment.FakeItemID = resID end
                            applyData:Set(i, equipment)
                            needRep = true
                        end
                        break
                    end
                end
                
                if not found then
                    F.ensureSkinDownload(resID)
                    local entry = import("AvatarSyncData")()
                    entry.SlotID = slotID
                    entry.ItemId = resID
                    entry.ItemID = resID
                    entry.FakeItemID = resID
                    entry.OperationType = ESyncOperation.PutOn
                    applyData:Add(entry)
                    needRep = true
                end
            end

            -- [LOGIC NGỦ ĐÔNG] - TỐI ƯU FPS TUYỆT ĐỐI
            _G.FaceWearStateCache = _G.FaceWearStateCache or {}
            -- Tạo ID định danh riêng biệt cho nhân vật hiện tại tránh trùng lặp
            local cacheKey = tostring(comp) .. "_" .. tostring(slotID)

            if needRep or _G.FaceWearStateCache[cacheKey] ~= resID then
                -- Lần đầu tiên ép hiển thị / Hoặc ID Skin bị thay đổi -> Chạy Full C++
                if slotEnum then
                    if comp.CancelHideAvatarBySlot then comp:CancelHideAvatarBySlot(slotEnum) end
                    if comp.SetAvatarVisibility then comp:SetAvatarVisibility(slotEnum, true, true) end
                end
                if comp.PutOnCustomEquipmentByID then
                    comp:PutOnCustomEquipmentByID(resID)
                end
                
                -- Cập nhật Cache để vòng lặp sau đi vào Ngủ Đông
                _G.FaceWearStateCache[cacheKey] = resID
                ok = true -- Bật cờ để gọi OnRep_BodySlotStateChanged (vẽ lại Mesh)
            else
                -- TRẠNG THÁI NGỦ ĐÔNG: Data đã đúng, Mesh 3D đã được render.
                -- Chỉ chạy hàm cực nhẹ CancelHide để chống Game tự ẩn khi nhặt Mũ bảo hiểm (1,2,3).
                -- BỎ QUA việc Render lại Mesh để tránh Drop FPS.
                if slotEnum and comp.CancelHideAvatarBySlot then 
                    comp:CancelHideAvatarBySlot(slotEnum) 
                end
            end
        end

        -- Gọi lệnh ép cho Mặt nạ (Mask)
        forceApplySlot(maskRes, F.CUST_SLOT.FaceEquipemtSlot, "EAvatarSlotType_FaceEquipemtSlot")
        -- Gọi lệnh ép cho Mắt kính (Glass)
        forceApplySlot(glassRes, F.CUST_SLOT.GlassEquipemtSlot, "EAvatarSlotType_GlassEquipemtSlot")
        
        -- Cập nhật hình ảnh 3D CHỈ KHI THOÁT KHỎI NGỦ ĐÔNG (Khi cần thiết)
        if ok and comp.OnRep_BodySlotStateChanged then
            comp:OnRep_BodySlotStateChanged()
        end
    end)
    return ok
end

function F.matchApplyGloves(char)
    local glovesRes = tonumber(F.getDesiredWear("glovesRes", "glovesRes", "AddOutfitLastLobbyGlovesRes", F.syncBodyCacheFromLobby)) or 0
    if glovesRes <= 0 then
        glovesRes = tonumber(_G.GlovesSkin) or 0
    end
    if glovesRes <= 0 then return true end
    _G.GlovesSkin = glovesRes
    char = char or F.getLocalChar()
    if not char then return false end
    local comp = F.getAvatarComp2(char)
    if not comp then return false end

    local ok = false
    pcall(function()
        local EAvatarSlotType = import("EAvatarSlotType")
        local ESyncOperation = import("ESyncOperation")
        local slotID = F.CUST_SLOT.HandEffectEquipemtSlot
        local slotNameStr = "EAvatarSlotType_HandEffectEquipemtSlot"
        local slotEnum = EAvatarSlotType and EAvatarSlotType[slotNameStr]
        local net = comp.NetAvatarData
        local applyData = net and net.SlotSyncData
        local needRep = false

        if applyData and slua.isValid(applyData) then
            local found = false
            for i = 0, applyData:Num() - 1 do
                local equipment = applyData:Get(i)
                if equipment and equipment.SlotID == slotID then
                    found = true
                    local cur = tonumber(equipment.ItemID) or tonumber(equipment.ItemId) or 0
                    local add = tonumber(equipment.AdditionalItemID) or 0
                    if cur ~= glovesRes or (equipment.AdditionalItemID ~= nil and add ~= glovesRes) then
                        F.ensureSkinDownload(glovesRes)
                        equipment.ItemId = glovesRes
                        if equipment.ItemID ~= nil then equipment.ItemID = glovesRes end
                        if equipment.FakeItemID ~= nil then equipment.FakeItemID = glovesRes end
                        if equipment.AdditionalItemID ~= nil then equipment.AdditionalItemID = glovesRes end
                        applyData:Set(i, equipment)
                        needRep = true
                    end
                    break
                end
            end
            if not found then
                F.ensureSkinDownload(glovesRes)
                local entry = import("AvatarSyncData")()
                entry.SlotID = slotID
                entry.ItemId = glovesRes
                entry.ItemID = glovesRes
                if entry.FakeItemID ~= nil then entry.FakeItemID = glovesRes end
                if entry.AdditionalItemID ~= nil then entry.AdditionalItemID = glovesRes end
                entry.OperationType = ESyncOperation.PutOn
                applyData:Add(entry)
                needRep = true
            end
        end

        _G.GlovesWearStateCache = _G.GlovesWearStateCache or {}
        local cacheKey = tostring(comp)
        if needRep or _G.GlovesWearStateCache[cacheKey] ~= glovesRes then
            if slotEnum then
                if comp.CancelHideAvatarBySlot then comp:CancelHideAvatarBySlot(slotEnum) end
                if comp.SetAvatarVisibility then comp:SetAvatarVisibility(slotEnum, true, true) end
            end
            if comp.PutOnCustomEquipmentByID then
                comp:PutOnCustomEquipmentByID(glovesRes)
            end
            if needRep then
                pcall(function()
                    if comp.OnRep_BodySlotStateChangedInternal then
                        comp:OnRep_BodySlotStateChangedInternal()
                    elseif comp.OnRep_BodySlotStateChanged then
                        comp:OnRep_BodySlotStateChanged()
                    end
                    if comp.ProcessAvatarRectify then comp:ProcessAvatarRectify() end
                end)
            end
            _G.GlovesWearStateCache[cacheKey] = glovesRes
            ok = true
        else
            ok = true
        end
    end)
    return ok
end

function F.getDesiredWear(configKey, cacheResKey, globalKey, syncFn)
    local fixed = MATCH_CONFIG[configKey] and tonumber(MATCH_CONFIG[configKey])
    if fixed and fixed > 0 then return fixed end
    local persistKey = cacheResKey and cacheResKey:gsub("Res$", "")
    if persistKey and PERSIST.configSlots then
        local pr = tonumber(PERSIST.configSlots[persistKey])
        if pr and pr > 0 then return pr end
    end
    if syncFn then syncFn() end
    local v = F.cache()[cacheResKey]
    if v and tonumber(v) > 0 then return tonumber(v) end
    return tonumber(_G[globalKey]) or nil
end

local EQUIP_APPLY = { lastBagWrite = 0, lastHelmetWrite = 0 }
-- SlotID giống luafix2.cpp (chỉ balo / nón)
local EQUIP_SLOT_BAG = 8
local EQUIP_SLOT_HELMET = 9

-- BackpackMapping key sảnh: balo 1501000xxx / nón 1502000xxx (không phải *001xxx Lv1 skin)
function F.resolveBackpackMappingBase(skinID)
    skinID = tonumber(skinID) or 0
    if skinID <= 0 then return 0 end
    local found = 0
    pcall(function()
        local function mappingOk(id)
            local t = CDataTable.GetTableData("BackpackMapping", id)
            if not t then return false end
            return (tonumber(t.SkinItemIDLv1) or tonumber(t.LobbyShowItemID) or 0) > 0
        end
        if mappingOk(skinID) then
            found = skinID
            return
        end
        -- Balo: 1501001xxx → 1501000xxx ; Nón: 1502001xxx → 1502000xxx
        if (skinID >= 1501001000 and skinID < 1501002000)
            or (skinID >= 1502001000 and skinID < 1502002000) then
            local lobbyKey = skinID - 1000
            if mappingOk(lobbyKey) then
                found = lobbyKey
                return
            end
            found = lobbyKey
            return
        end
        for _, d in ipairs({1000, 2000}) do
            local try = skinID - d
            if try > 0 and mappingOk(try) then
                local t2 = CDataTable.GetTableData("BackpackMapping", try)
                local l1 = tonumber(t2.SkinItemIDLv1) or 0
                local l2 = tonumber(t2.SkinItemIDLv2) or 0
                local l3 = tonumber(t2.SkinItemIDLv3) or 0
                if skinID == l1 or skinID == l2 or skinID == l3 or skinID == try then
                    found = try
                    return
                end
            end
        end
    end)
    return found > 0 and found or skinID
end

-- Chuẩn hóa ID nón/balo để sảnh + trận dùng cùng mapping key
function F.normalizeLobbyEquipSkinID(resID)
    return F.equipToLobbyMappingID(resID)
end

-- Level thật từ inventory (501/502), không lấy từ skin AdditionalItemID
function F.getEquippedArmorLevelBySubType(subType)
    local lvl, equipID = 0, 0
    pcall(function()
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if not pc or not slua.isValid(pc) then return end
        local bp = pc.GetBackpackComponent and pc:GetBackpackComponent()
        if not bp or not slua.isValid(bp) then return end
        local BackpackUtils = import("BackpackUtils")
        local arr = BackpackUtils.GetEuqippedArmorInBackpack(bp)
        if not arr then return end
        for _, BattleItemData in pairs(arr) do
            local DefineID = BattleItemData and (slua.IndexReference(BattleItemData, "DefineID") or BattleItemData.DefineID)
            local tid = DefineID and tonumber(DefineID.TypeSpecificID) or 0
            if tid > 0 then
                local ItemCfg = CDataTable.GetTableData("Item", tid)
                local ist = ItemCfg and tonumber(ItemCfg.ItemSubType) or 0
                if ist == subType
                    or (subType == 501 and tid >= 501001 and tid <= 501099)
                    or (subType == 502 and tid >= 502001 and tid <= 502099) then
                    equipID = tid
                    if BackpackUtils.GetEquipmentLevel then
                        local itemID = tonumber(ItemCfg and ItemCfg.ItemID) or tid
                        pcall(function() lvl = tonumber(BackpackUtils.GetEquipmentLevel(itemID)) or 0 end)
                    end
                    if lvl < 1 and subType == 501 and BackpackUtils.GetEquipmentBagLevel then
                        pcall(function() lvl = tonumber(BackpackUtils.GetEquipmentBagLevel(tid)) or 0 end)
                    end
                    if lvl < 1 and subType == 502 and BackpackUtils.GetEquipmentHelmetLevel then
                        pcall(function() lvl = tonumber(BackpackUtils.GetEquipmentHelmetLevel(tid)) or 0 end)
                    end
                    if lvl < 1 then
                        local rem = tid % 10
                        if rem >= 1 and rem <= 6 then lvl = rem end
                    end
                    break
                end
            end
        end
    end)
    return lvl, equipID
end

-- Giống sảnh: DataMgr.GetEquipmentItemIDByResID(level, base) / SkinItemIDLv*
function F.levelSkinID(baseSkin, level)
    level = tonumber(level) or 1
    if level < 1 then level = 1 end
    if level > 3 then level = 3 end
    baseSkin = F.resolveBackpackMappingBase(baseSkin)
    local mapped = 0
    pcall(function()
        if DataMgr and DataMgr.GetEquipmentItemIDByResID then
            mapped = tonumber(DataMgr.GetEquipmentItemIDByResID(level, baseSkin)) or 0
        end
    end)
    if mapped <= 0 then
        pcall(function()
            local t = CDataTable.GetTableData("BackpackMapping", baseSkin)
            if t then
                if level <= 1 then mapped = tonumber(t.SkinItemIDLv1) or 0
                elseif level == 2 then mapped = tonumber(t.SkinItemIDLv2) or 0
                else mapped = tonumber(t.SkinItemIDLv3) or 0 end
            end
        end)
    end
    if mapped > 0 then return mapped end
    return baseSkin + (level - 1) * 1000
end

-- Áp skin balo/nón: map cấp như sảnh + ghi SlotSyncData như luafix2
function F.applyEquipSkinToComp(comp, bagRes, helmetRes)
    bagRes = tonumber(bagRes) or 0
    helmetRes = tonumber(helmetRes) or 0
    if bagRes <= 0 and helmetRes <= 0 then return false, false end
    if not comp or not slua.isValid(comp) then return false, false end

    if bagRes > 0 then _G.BackpackSkin = bagRes end
    if helmetRes > 0 then _G.HelmetSkin = helmetRes end

    local applied, found = false, false
    pcall(function()
        if not comp.NetAvatarData or not comp.NetAvatarData.SlotSyncData then return end
        local TempSlotSyncData = slua.IndexReference(comp.NetAvatarData, "SlotSyncData")
        if not TempSlotSyncData then return end

        local function skinForSlot(slotID, curItemID, addItemID)
            -- P23-FIX backpack Lv3-always + flicker: real level AdditionalItemID se (Extra file method), skinned ItemID se nahi
            local function realLevel(slotID2, cur2, add2)
                local lvl = 0
                -- 1) AdditionalItemID (base armor 50100x/50200x) se level - sabse sahi
                pcall(function()
                    local BU = import("BackpackUtils")
                    add2 = tonumber(add2) or 0
                    if add2 and add2 > 0 then
                        if slotID2 == EQUIP_SLOT_BAG and BU.GetEquipmentBagLevel then
                            lvl = tonumber(BU.GetEquipmentBagLevel(add2)) or 0
                        elseif slotID2 == EQUIP_SLOT_HELMET and BU.GetEquipmentHelmetLevel then
                            lvl = tonumber(BU.GetEquipmentHelmetLevel(add2)) or 0
                        end
                        if lvl < 1 and BU.GetEquipmentLevel then
                            lvl = tonumber(BU.GetEquipmentLevel(add2)) or 0
                        end
                    end
                end)
                -- 2) fallback: inventory se (base, skinned nahi)
                if (not lvl or lvl < 1) and F.getEquippedArmorLevelBySubType then
                    local st = (slotID2 == EQUIP_SLOT_BAG) and 501 or 502
                    lvl = tonumber(F.getEquippedArmorLevelBySubType(st)) or 0
                end
                -- 3) last fallback: base id se (skinned id se kabhi nahi, warna Lv3 loop)
                if not lvl or lvl < 1 then
                    local base = tonumber(add2) or 0
                    if base >= 501001 and base <= 501099 then lvl = (base % 10) if lvl < 1 or lvl > 3 then lvl = 1 end
                    elseif base >= 502001 and base <= 502099 then lvl = (base % 10) if lvl < 1 or lvl > 3 then lvl = 1 end
                    else lvl = tonumber(F.levelFromEquipArmorID(cur2)) or 1 end
                end
                if lvl < 1 then lvl = 1 end if lvl > 3 then lvl = 3 end
                return lvl
            end
            if slotID == EQUIP_SLOT_BAG and bagRes > 0 then
                local lvl = realLevel(slotID, curItemID, addItemID)
                return tonumber(F.levelSkinID(F.resolveBackpackMappingBase(bagRes), lvl)) or 0
            elseif slotID == EQUIP_SLOT_HELMET and helmetRes > 0 then
                local lvl = realLevel(slotID, curItemID, addItemID)
                return tonumber(F.levelSkinID(F.resolveBackpackMappingBase(helmetRes), lvl)) or 0
            end
            return nil
        end

        for Index, AvatarSyncData in pairs(TempSlotSyncData) do
            if AvatarSyncData and AvatarSyncData.ItemID and AvatarSyncData.ItemID > 0 then
                local slotID = AvatarSyncData.SlotID
                if slotID == EQUIP_SLOT_BAG or slotID == EQUIP_SLOT_HELMET then
                    found = true
                    local cur = tonumber(AvatarSyncData.ItemID) or 0
                    local add = tonumber(AvatarSyncData.AdditionalItemID) or cur
                    local targetSkin = skinForSlot(slotID, cur, add)
                    if targetSkin and targetSkin > 0
                        and (targetSkin ~= cur or tonumber(AvatarSyncData.AdditionalItemID) ~= targetSkin) then
                        pcall(function() if F.ensureSkinDownload then F.ensureSkinDownload(targetSkin) end end)
                        AvatarSyncData.ItemID = targetSkin
                        AvatarSyncData.AdditionalItemID = targetSkin
                        slua.IndexReference(comp.NetAvatarData, "SlotSyncData"):Set(Index, AvatarSyncData)
                        applied = true
                        if slotID == EQUIP_SLOT_BAG then
                            EQUIP_APPLY.lastBagWrite = targetSkin
                        else
                            EQUIP_APPLY.lastHelmetWrite = targetSkin
                        end
                    end
                end
            end
        end
    end)
    return applied, found
end

function F.matchApplyEquipmentSkin(char, bagRes, helmetRes)
    -- P23-FIX backpack/helmet late: turant download + immediate + 0.5/1.5s re-apply (pickup ke baad late nahi)
    pcall(function()
        if bagRes and tonumber(bagRes) and tonumber(bagRes) > 0 and F.ensureSkinDownload then F.ensureSkinDownload(tonumber(bagRes)) end
        if helmetRes and tonumber(helmetRes) and tonumber(helmetRes) > 0 and F.ensureSkinDownload then F.ensureSkinDownload(tonumber(helmetRes)) end
    end)
    bagRes = tonumber(bagRes) or 0
    helmetRes = tonumber(helmetRes) or 0
    if bagRes <= 0 and helmetRes <= 0 then return true end
    if bagRes > 0 then _G.BackpackSkin = bagRes end
    if helmetRes > 0 then _G.HelmetSkin = helmetRes end
    pcall(F.hookArmorInventoryAvatar)
    pcall(F.applyInitialEquipmentAvatar)
    local comp = char and (char.CharacterAvatarComp2_BP or F.getAvatarComp2(char))
    if not slua.isValid(comp) then
        pcall(function()
            if char.getAvatarComponent2 then comp = char:getAvatarComponent2() end
        end)
    end
    if not slua.isValid(comp) then return false end

    local applied, found = F.applyEquipSkinToComp(comp, bagRes, helmetRes)

    if applied then
        pcall(function()
            -- P23-FIX flicker: sirf OnRep, ProcessAvatarRectify mat chalao (rectify ticker se fight karke blink hota tha)
            local ok1 = pcall(function()
                if comp.OnRep_BodySlotStateChangedInternal then
                    comp:OnRep_BodySlotStateChangedInternal()
                end
            end)
            if not ok1 and comp.OnRep_BodySlotStateChanged then
                comp:OnRep_BodySlotStateChanged()
            end
        end)
        return true
    end
    return found
end

function F.hookEquipmentRectify()
    _G.AddOutfitEquipRectifyFn = function(self)
        pcall(function()
            if self.IsLobbyActor and self:IsLobbyActor() then return end
            if not (self.IsSelf and self:IsSelf()) then return end
            local bagRes = F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes", F.syncBodyCacheFromLobby)
            local helmetRes = F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes", F.syncBodyCacheFromLobby)
            if (tonumber(bagRes) or 0) <= 0 and (tonumber(helmetRes) or 0) <= 0 then return end
            local applied = F.applyEquipSkinToComp(self, bagRes, helmetRes)
            if applied then
                pcall(function()
                    local ok1 = pcall(function()
                        if self.OnRep_BodySlotStateChangedInternal then
                            self:OnRep_BodySlotStateChangedInternal()
                        end
                    end)
                    if not ok1 and self.OnRep_BodySlotStateChanged then
                        self:OnRep_BodySlotStateChanged()
                    end
                    if self.ProcessAvatarRectify then self:ProcessAvatarRectify() end
                end)
            end
        end)
    end
    -- P23-FIX backpack/helmet late: pickup/rectify par turant re-apply + 0.5s delayed (watcher 3s ka wait nahi)
    pcall(function()
        if not _G._p23_equipPickupHooked then
            _G._p23_equipPickupHooked = true
            local okT, ticker = pcall(require, "common.time_ticker")
            if okT and ticker and ticker.AddTimerLoop then
                -- equip changed flag par turant apply (0.5s loop, sirf bag/helmet, halka)
                -- P23-FIX lag: backpack 0.5s fight -> 1.5s, flicker bhi kam
                ticker.AddTimerLoop(1.5, function()
                    pcall(function()
                        if not (F.isInRealMatch and F.isInRealMatch()) then return end
                        local char = F.getLocalChar and F.getLocalChar() or nil
                        if not char or not slua.isValid(char) then return end
                        local bagRes = F.getDesiredWear and F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes", F.syncBodyCacheFromLobby) or 0
                        local helmetRes = F.getDesiredWear and F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes", F.syncBodyCacheFromLobby) or 0
                        bagRes = tonumber(bagRes) or 0 helmetRes = tonumber(helmetRes) or 0
                        if bagRes <= 0 and helmetRes <= 0 then return end
                        -- sirf tab apply jab visual mismatch ho (spam nahi, Extra/equip_character_avatar jaisa)
                        local comp = char.CharacterAvatarComp2_BP or (F.getAvatarComp2 and F.getAvatarComp2(char))
                        if comp and slua.isValid(comp) then
                            F.matchApplyEquipmentSkin(char, bagRes, helmetRes)
                        end
                    end)
                end, -1, 0.5)
            end
        end
    end)
    pcall(function()
        local MCAC = require("GameLua.Mod.TPlan.Component.MetroCharacterAvatarComponent")
        if MCAC._AddOutfitRectifyHooked then return end
        MCAC._AddOutfitRectifyHooked = true
        local o = MCAC.ProcessClientAvatarRectify
        MCAC.ProcessClientAvatarRectify = function(self)
            o(self)
            if _G.AddOutfitEquipRectifyFn then _G.AddOutfitEquipRectifyFn(self) end
        end
    end)
end

-- Dù/cánh: chỉ apply khi ID hoặc trạng thái inAir đổi — không setMakeSkin lặp (gây giật)
function F.applyAirborneSlots(char, forceInAir)
    if not F.skinFeat("SkinMatchAirborne") then return false end
    local comp = F.getAvatarComp2(char)
    if not comp or not slua.isValid(comp) then return false end
    local inAir = forceInAir == true or F.isCharacterAirborne(char)
    local paraRes = tonumber(F.getDesiredParachuteRes()) or 0
    local gliderRes = tonumber(F.getDesiredGliderRes()) or 0
    if paraRes <= 0 and gliderRes <= 0 then return false end

    F._airApplied = F._airApplied or { para = 0, glider = 0, inAir = nil }
    local prev = F._airApplied
    if prev.para == paraRes and prev.glider == gliderRes and prev.inAir == inAir then
        return true
    end

    -- DataMgr chỉ sync khi đổi ID (không mỗi lần inAir)
    if prev.para ~= paraRes or prev.glider ~= gliderRes then
        pcall(function() F.syncAirborneToDataMgr() end)
    end

    local any = false
    if paraRes > 0 then
        any = true
        if not F.isResourcesReady(paraRes) then F.requestResourceDownload(paraRes) end
        F.setMakeSkin(comp, paraRes, F.CUST_SLOT.ParachuteEquipemtSlot, { inAir = inAir })
    end
    if gliderRes > 0 then
        any = true
        if not F.isResourcesReady(gliderRes) then F.requestResourceDownload(gliderRes) end
        F.setMakeSkin(comp, gliderRes, F.CUST_SLOT.GlideEquipemtSlot, { inAir = inAir })
    end
    F._airApplied = { para = paraRes, glider = gliderRes, inAir = inAir }
    return any
end

-- Chỉ apply khi vừa vào trạng thái dù (ground→air), không spam lúc đang bay
function F.tryApplyAirborneOnEnter(char)
    if not F.skinFeat("SkinMatchAirborne") then return false end
    char = char or F.getLocalChar()
    if not char then return false end
    local air = F.isCharacterAirborne(char)
    local was = PERF._wasAirborne == true
    PERF._wasAirborne = air
    if air and not was then
        return F.applyAirborneSlots(char, true)
    end
    return false
end

function F.matchApplyBodyWear(char)
    local pieces = {}
    if not F.getDesiredOutfit() then
        pieces[#pieces + 1] = {
            F.getDesiredWear("tshirtRes", "tshirtRes", "AddOutfitLastLobbyTshirtRes", F.syncBodyCacheFromLobby),
            F.CUST_SLOT.ClothesEquipemtSlot, "تيشرت",
        }
    end
    pieces[#pieces + 1] = { F.getDesiredWear("pantsRes", "pantsRes", "AddOutfitLastLobbyPantsRes", F.syncBodyCacheFromLobby), F.CUST_SLOT.PantsEquipemtSlot, "سروال" }
    pieces[#pieces + 1] = { F.getDesiredWear("shoesRes", "shoesRes", "AddOutfitLastLobbyShoesRes", F.syncBodyCacheFromLobby), F.CUST_SLOT.ShoesEquipemtSlot, "حذاء" }
    pieces[#pieces + 1] = { F.getDesiredWear("glovesRes", "glovesRes", "AddOutfitLastLobbyGlovesRes", F.syncBodyCacheFromLobby), F.CUST_SLOT.HandEffectEquipemtSlot, "قفازات" }
    local any, okAll = false, true
    for _, p in ipairs(pieces) do
        local res, slot, label = p[1], p[2], p[3]
        if res and res > 0 then
            any = true
            okAll = F.matchApplyWearItem(char, res, slot, label) and okAll
        end
    end
    -- Dù/cánh: không apply trong body-wear loop (chỉ edge khi nhảy)
    local bagRes = F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes", F.syncBodyCacheFromLobby)
    local helmetRes = F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes", F.syncBodyCacheFromLobby)
    if (tonumber(bagRes) or 0) > 0 or (tonumber(helmetRes) or 0) > 0 then
        any = true
        okAll = F.matchApplyEquipmentSkin(char, bagRes, helmetRes) and okAll
    end
    return not any or okAll
end

function F.matchApplyAllSlots(char)
    if not char then return false end
    if not F.skinFeat("SkinMatchOutfit") then return true end
    F.syncGlobalWearSkins()
    local comp = F.getAvatarComp2(char)
    if not comp then return false end

    local entries = {}
    local function add(skin, slot)
        skin = tonumber(skin)
        if skin and skin > 0 and slot then entries[#entries + 1] = { skin, slot } end
    end
    add(_G.HatSkin, F.CUST_SLOT.HatEquipemtSlot)
    add(_G.SuitSkin, F.CUST_SLOT.ClothesEquipemtSlot)
    add(_G.PantsSkin, F.CUST_SLOT.PantsEquipemtSlot)
    add(_G.ShoesSkin, F.CUST_SLOT.ShoesEquipemtSlot)
    add(_G.GlovesSkin, F.CUST_SLOT.HandEffectEquipemtSlot)
    add(_G.MaskSkin, F.CUST_SLOT.FaceEquipemtSlot)
    add(_G.GlassSkin, F.CUST_SLOT.GlassEquipemtSlot)

    local ok = false
    if #entries > 0 then
        ok = F.applySlotSkinBatch(comp, entries, { forceRep = true })
        if not ok then
            for _, e in ipairs(entries) do
                if F.setMakeSkin(comp, e[1], e[2], { allowPutOn = true }) then ok = true end
            end
        end
    end

    -- Dù/cánh: chỉ ghi DataMgr 1 lần (không setMakeSkin lặp trong outfit loop)
    if F.skinFeat("SkinMatchAirborne") and not PERF._airDataSynced then
        pcall(function() F.syncAirborneToDataMgr() end)
        PERF._airDataSynced = true
    end

    local bagRes = F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes", F.syncBodyCacheFromLobby)
    local helmetRes = F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes", F.syncBodyCacheFromLobby)
    if (tonumber(bagRes) or 0) > 0 or (tonumber(helmetRes) or 0) > 0 then
        ok = F.matchApplyEquipmentSkin(char, bagRes, helmetRes) or ok
    end

    return ok or #entries == 0
end

function F.matchApplyHat(char)
    local hatRes = tonumber(F.getDesiredHat())
    if not hatRes or hatRes <= 0 then return true end
    char = char or F.getLocalChar()
    if not char then return false end
    local comp = F.getAvatarComp2(char)
    if not comp then return false end
    local slotID = F.CUST_SLOT.HatEquipemtSlot
    local ok = false
    pcall(function()
        local net = comp.NetAvatarData
        if not net then return end
        local applyData = net.SlotSyncData
        if not applyData or not slua.isValid(applyData) then return end
        local found = false
        for i = 0, applyData:Num() - 1 do
            local equipment = applyData:Get(i)
            if equipment and equipment.SlotID == slotID then
                found = true
                local cur = tonumber(equipment.ItemId) or tonumber(equipment.ItemID) or 0
                if cur ~= hatRes then
                    F.ensureSkinDownload(hatRes)
                    equipment.ItemId = hatRes
                    if equipment.ItemID ~= nil then equipment.ItemID = hatRes end
                    if equipment.FakeItemID ~= nil then equipment.FakeItemID = hatRes end
                    applyData:Set(i, equipment)
                end
                ok = true
                break
            end
        end
        if not found then
            F.ensureSkinDownload(hatRes)
            local ESyncOperation = import("ESyncOperation")
            local entry = import("AvatarSyncData")()
            entry.SlotID = slotID
            entry.ItemId = hatRes
            entry.ItemID = hatRes
            entry.FakeItemID = hatRes
            entry.OperationType = ESyncOperation.PutOn
            applyData:Add(entry)
            ok = true
        end
        
    end)
    return ok
end

local _avatarItemsRegistered = false

function F.getDesiredWeaponSkins()
    if PERF.desiredSkins then return PERF.desiredSkins end
    F.syncWeaponCacheFromLobby()
    local out, seen = {}, {}
    local function add(res)
        res = tonumber(res)
        if res and res > 0 and not seen[res] then seen[res] = true; out[#out+1] = res end
    end
    for wid, w in pairs(F.cache().weapons) do
        if w and w.resID then add(w.resID) end
    end
    if MATCH_CONFIG.weaponSkins then
        for _, res in pairs(MATCH_CONFIG.weaponSkins) do add(res) end
    end
    PERF.desiredSkins = out
    return out
end

function F._cacheSkinTarget(weaponResID, skin)
    if skin and skin > 0 then PERF.skinTarget[weaponResID] = skin else PERF.skinTarget[weaponResID] = 0 end
    return skin
end

local GUN_MASTER_SYN_SLOT = 7

function F.findSkinSlotInSynData(weapon)
    if not slua.isValid(weapon) then return GUN_MASTER_SYN_SLOT, 0 end
    local arr = weapon.synData
    if not arr or not slua.isValid(arr) then return GUN_MASTER_SYN_SLOT, 0 end
    local count = 0
    pcall(function() count = arr:Num() end)
    for i = 0, math.min(count - 1, 15) do
        local ok2, att = pcall(function() return arr:Get(i) end)
        if ok2 and att then
            local ok3, defRef = pcall(slua.IndexReference, att, "defineID")
            if ok3 and defRef then
                local tid = 0
                pcall(function() tid = tonumber(defRef.TypeSpecificID) or 0 end)
                if tid >= 1000000 then
                    return i, tid
                end
            end
        end
    end
    return GUN_MASTER_SYN_SLOT, 0
end

function F.resolveWeaponTypeID(weaponResID)
    weaponResID = tonumber(weaponResID) or 0
    if weaponResID <= 0 then return 0 end
    local found = 0
    pcall(function()
        local wc = CDataTable.GetTableData("WeaponConfig", weaponResID)
        if wc then found = tonumber(wc.WeaponID or wc.WeaponId or wc.weaponID or 0) end
    end)
    if found > 0 then return found end
    pcall(function()
        local ic = CDataTable.GetTableData("Item", weaponResID)
        if ic then found = tonumber(ic.WeaponID or ic.weaponId or 0) end
    end)
    return found > 0 and found or weaponResID
end

function F.findTargetSkinForWeaponRes(weaponResID)
    weaponResID = tonumber(weaponResID) or 0
    if weaponResID <= 0 then return nil end
    local cached = PERF.skinTarget[weaponResID]
    if cached ~= nil then return cached == 0 and nil or cached end

    local memSkin = F.getMatchWeaponSkin(weaponResID)
    if memSkin then return F._cacheSkinTarget(weaponResID, memSkin) end
    local typeID = F.resolveWeaponTypeID(weaponResID)
    if typeID > 0 and typeID ~= weaponResID then
        memSkin = F.getMatchWeaponSkin(typeID)
        if memSkin then return F._cacheSkinTarget(weaponResID, memSkin) end
    end

    if MATCH_CONFIG.weaponSkins and MATCH_CONFIG.weaponSkins[weaponResID] then
        local fixed = tonumber(MATCH_CONFIG.weaponSkins[weaponResID])
        if fixed and fixed > 0 then return F._cacheSkinTarget(weaponResID, fixed) end
    end

    for _, skinRes in ipairs(F.getDesiredWeaponSkins()) do
        local wid = F.weaponIdFromSkin(skinRes)
        if wid and tonumber(wid) == weaponResID then return F._cacheSkinTarget(weaponResID, skinRes) end
    end

    local typeID = F.resolveWeaponTypeID(weaponResID)
    if typeID > 0 and typeID ~= weaponResID then
        if MATCH_CONFIG.weaponSkins and MATCH_CONFIG.weaponSkins[typeID] then
            local fixed = tonumber(MATCH_CONFIG.weaponSkins[typeID])
            if fixed and fixed > 0 then return F._cacheSkinTarget(weaponResID, fixed) end
        end
        for _, skinRes in ipairs(F.getDesiredWeaponSkins()) do
            local wid = F.weaponIdFromSkin(skinRes)
            if wid and tonumber(wid) == typeID then return F._cacheSkinTarget(weaponResID, skinRes) end
        end
    end

    local avatarMatch = nil
    pcall(function()
        local AU = import("AvatarUtils")
        local weaponBase = AU.GetWeaponAvatarParentID(AU.GetBPIDByResID(weaponResID), false)
        if not weaponBase or weaponBase <= 0 then return end
        for _, skinRes in ipairs(F.getDesiredWeaponSkins()) do
            local skinBase = AU.GetWeaponAvatarParentID(AU.GetBPIDByResID(skinRes), false)
            if skinBase and skinBase > 0 and skinBase == weaponBase then
                avatarMatch = skinRes
                return
            end
        end
    end)
    if avatarMatch then return F._cacheSkinTarget(weaponResID, avatarMatch) end

    local c = F.cfg(weaponResID)
    local st = F.subType(c)
    if st and GUN_SUB[st] and MATCH_CONFIG.weaponSkins then
        for _, skinRes in pairs(MATCH_CONFIG.weaponSkins) do
            local skinWid = F.weaponIdFromSkin(skinRes)
            if skinWid then
                local sc = F.cfg(tonumber(skinWid))
                if sc and F.subType(sc) == st then return F._cacheSkinTarget(weaponResID, skinRes) end
            end
            local sc = F.cfg(skinRes)
            if sc and GUN_SUB[F.subType(sc)] and F.subType(sc) == st then return F._cacheSkinTarget(weaponResID, skinRes) end
        end
    end

    PERF.skinTarget[weaponResID] = 0
    return nil
end

function F.getSynMasterSkinID(weapon)
    if not slua.isValid(weapon) then return 0 end
    local id = 0
    pcall(function()
        local slot, tid = F.findSkinSlotInSynData(weapon)
        id = tid
        if id == 0 then
            local arr = weapon.synData
            if not arr or not slua.isValid(arr) then return end
            local att = arr:Get(GUN_MASTER_SYN_SLOT)
            if not att then return end
            id = slua.IndexReference(att, "defineID").TypeSpecificID or 0
        end
    end)
    return id
end

_G.AddOutfitSkinIdMappings = _G.AddOutfitSkinIdMappings or {}
_G.AddOutfitLastAppliedSkin = _G.AddOutfitLastAppliedSkin or {}

function F.buildSkinMappings()
    if not PERF.mappingsDirty then return end
    F.syncWeaponCacheFromLobby()
    PERF.mappingsDirty = false
    local m = _G.AddOutfitSkinIdMappings
    for k in pairs(m) do m[k] = nil end
    for wid, w in pairs(F.cache().weapons) do
        wid = tonumber(wid)
        if wid and w.resID and w.resID > 0 then
            m[wid] = { tonumber(w.resID) }
            if wid == MELEE_ID then
                local mapped = tonumber(F.weaponIdFromSkin(w.resID))
                if mapped and mapped > 0 and mapped ~= MELEE_ID then
                    m[mapped] = { tonumber(w.resID) }
                end
            end
        end
    end
    if MATCH_CONFIG.weaponSkins then
        for weaponKey, skinRes in pairs(MATCH_CONFIG.weaponSkins) do
            weaponKey = tonumber(weaponKey)
            skinRes = tonumber(skinRes)
            if weaponKey and skinRes and skinRes > 0 and not m[weaponKey] then
                m[weaponKey] = { skinRes }
                if weaponKey == MELEE_ID then
                    local mapped = tonumber(F.weaponIdFromSkin(skinRes))
                    if mapped and mapped > 0 and mapped ~= MELEE_ID and not m[mapped] then
                        m[mapped] = { skinRes }
                    end
                end
            end
        end
    end
end

function F.get_skin_id(currentGunId, maxIt)
    currentGunId = tonumber(currentGunId) or 0
    maxIt = tonumber(maxIt) or 0
    if currentGunId <= 0 and maxIt <= 0 then return 0 end
    F.buildSkinMappings()
    if maxIt > 0 then
        local fromMem = F.getMatchWeaponSkin(maxIt)
        if fromMem then return fromMem end
    end
    local fromMem2 = F.getMatchWeaponSkin(F.resolveWeaponTypeID(currentGunId))
    if fromMem2 then return fromMem2 end
    local m = _G.AddOutfitSkinIdMappings
    if maxIt > 0 and m[maxIt] and m[maxIt][1] then return tonumber(m[maxIt][1]) end
    local list = m[currentGunId]
    if list and list[1] then return tonumber(list[1]) end
    local typeId = F.resolveWeaponTypeID(currentGunId)
    if typeId > 0 and m[typeId] and m[typeId][1] then return tonumber(m[typeId][1]) end
    local target = F.findTargetSkinForWeaponRes(maxIt > 0 and maxIt or currentGunId)
    if target then return target end
    return currentGunId
end

-- P23-FIX attachments FULL OLD (Extra/TrailEffect file InitParts + GetPartsDic + AttachmentSkinIDList + DefaultAttachmentSkin)
-- Master maps neeche fallback me rahenge. Ye primary hai (old me sab guns par kaam karta tha).
_G.g_parts = _G.g_parts or {}
_G.g_parts_subtype = _G.g_parts_subtype or {}
_G._p23_attachKnown = _G._p23_attachKnown or nil
pcall(function()
    if not _G._p23_attachKnown then
        _G._p23_attachKnown = {}
        local function reg(id) if id and id > 0 then _G._p23_attachKnown[id] = true end end
        -- vanilla attachment base IDs (muzzle/grip/mag/scope/stock) - chhota set, baaki subtype se resolve hoga
        for _, id in ipairs({201002,201003,201004,201005,201006,201007,201009,201010,201011,201012,201050,201051,201052,201053,201054,201055,202001,202002,202004,202005,202006,202007,202051,203001,203002,203003,203004,203005,203014,203015,203018,203051,203052,203053,203054,203055,203056,203057,204004,204005,204006,204007,204008,204009,204011,204012,204013,204014,204015,205001,205002,205003,205010}) do reg(id) end
    end
end)
_G.InitParts_Old = _G.InitParts_Old or function(groupId, itemId)
    if not itemId then return _G.g_parts end
    if _G.g_parts[itemId] and next(_G.g_parts[itemId]) then return _G.g_parts end
    if not _G.g_parts[itemId] then _G.g_parts[itemId] = {} end
    if not _G.g_parts_subtype[itemId] then _G.g_parts_subtype[itemId] = {} end
    local function savePart(skinId, baseId, skinPartId)
        if not skinId or not baseId or not skinPartId or baseId <= 0 or skinPartId <= 0 then return end
        _G.g_parts[skinId][baseId] = skinPartId
    end
    local function saveBySubType(skinId, subType, skinPartId)
        if not skinId or not subType or not skinPartId or skinPartId <= 0 then return end
        if not _G.g_parts_subtype[skinId] then _G.g_parts_subtype[skinId] = {} end
        _G.g_parts_subtype[skinId][subType] = skinPartId
    end
    -- 1) WeaponAttrBPTable AttachmentSkinIDList (base-skin pairs)
    pcall(function()
        local function splitStr(str, sep)
            local tt = {}
            if not str or str == '' then return tt end
            for part in string.gmatch(str, '([^' .. sep .. ']+)') do table.insert(tt, part) end
            return tt
        end
        local bpId = itemId
        pcall(function()
            local UAvatarUtils = import('AvatarUtils')
            if UAvatarUtils and UAvatarUtils.GetBPIDByResID then
                local v = UAvatarUtils.GetBPIDByResID(itemId)
                if v and v > 0 then bpId = v end
            end
        end)
        for _, tid in ipairs({bpId, itemId}) do
            pcall(function()
                local cfgA = CDataTable.GetTableData('WeaponAttrBPTable', tid)
                if cfgA and cfgA.AttachmentSkinIDList and cfgA.AttachmentSkinIDList ~= '' then
                    for _, pair in ipairs(splitStr(cfgA.AttachmentSkinIDList, '|')) do
                        local nums = splitStr(pair, '-')
                        local b, s = tonumber(nums[1]), tonumber(nums[2])
                        if b and s then savePart(itemId, b, s) end
                    end
                end
            end)
        end
    end)
    -- 2) ItemUpgradeSystem:GetPartsDic (group based, old primary)
    pcall(function()
        local ModuleManager = require('client.module_framework.ModuleManager')
        local ItemUpgradeSystem = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.ItemUpgradeModule)
        if not ItemUpgradeSystem then return end
        local gid = groupId
        if not gid then
            pcall(function()
                local c = ItemUpgradeSystem:GetUpgradeCfg(itemId)
                gid = c and c.GroupID or nil
            end)
        end
        if ItemUpgradeSystem.IsWeaponIsRefit and ItemUpgradeSystem:IsWeaponIsRefit(itemId) then
            if ItemUpgradeSystem.GetNormalGroupID then gid = ItemUpgradeSystem:GetNormalGroupID(gid) end
        end
        if not gid then return end
        local partsDic = ItemUpgradeSystem:GetPartsDic(gid)
        if not partsDic then return end
        for subType, partList in pairs(partsDic) do
            for _, partId in ipairs(partList) do
                local skinPartId = partId
                if ItemUpgradeSystem.IsWeaponIsRefit and ItemUpgradeSystem:IsWeaponIsRefit(itemId) and ItemUpgradeSystem.PartIDSwitch then
                    pcall(function()
                        local sw = ItemUpgradeSystem:PartIDSwitch(partId, true)
                        if sw and sw ~= partId then skinPartId = sw end
                    end)
                end
                saveBySubType(itemId, subType, skinPartId)
                -- parent base resolve
                local parent = 0
                pcall(function()
                    local cfgP = CDataTable.GetTableData('WeaponAttachAttrBPTable', skinPartId)
                    if cfgP and cfgP.ParentID and cfgP.ParentID > 0 then parent = cfgP.ParentID end
                end)
                if parent == 0 then
                    pcall(function()
                        local cfgP2 = CDataTable.GetTableData('WeaponAttachAttrBPTable', partId)
                        if cfgP2 and cfgP2.ParentID and cfgP2.ParentID > 0 then parent = cfgP2.ParentID end
                    end)
                end
                if parent and parent > 0 then savePart(itemId, parent, skinPartId)
                elseif _G._p23_attachKnown[partId] then savePart(itemId, partId, skinPartId) end
            end
        end
    end)
    -- 3) AvatarUtils default attachment skin fallback
    pcall(function()
        local UAvatarUtils = import('AvatarUtils')
        if UAvatarUtils and UAvatarUtils.GetWeaponAvatarDefaultAttachmentSkin then
            local list = UAvatarUtils.GetWeaponAvatarDefaultAttachmentSkin(itemId, {}, false) or {}
            for baseId, skinPartId in pairs(list) do
                if baseId and skinPartId and skinPartId > 0 then
                    if _G._p23_attachKnown[baseId] then savePart(itemId, baseId, skinPartId)
                    else
                        local parent = 0
                        pcall(function()
                            local cfgP = CDataTable.GetTableData('WeaponAttachAttrBPTable', skinPartId)
                            if cfgP and cfgP.ParentID then parent = cfgP.ParentID end
                        end)
                        if parent and parent > 0 then savePart(itemId, parent, skinPartId)
                        else _G.g_parts[itemId][baseId] = skinPartId end
                    end
                end
            end
        end
    end)
    return _G.g_parts
end
_G.ApplyOldAttachments = _G.ApplyOldAttachments or function(AttachmentArray, avatarid)
    if not AttachmentArray or not slua.isValid(AttachmentArray) then return false end
    avatarid = tonumber(avatarid) or 0
    if avatarid <= 0 then return false end
    pcall(function() _G.InitParts_Old(nil, avatarid) end)
    local pmap = _G.g_parts[avatarid]
    if not pmap or not next(pmap) then return false end
    local numSlots = 0
    pcall(function() numSlots = AttachmentArray:Num() end)
    if numSlots <= 0 then return false end
    local changed = false
    for slotIdx = 0, numSlots - 1 do
        if slotIdx ~= 7 then
            local slotData = AttachmentArray:Get(slotIdx)
            if slotData then
                local curID = 0
                pcall(function() curID = slua.IndexReference(slotData, "defineID").TypeSpecificID or 0 end)
                curID = tonumber(curID) or 0
                if curID and curID > 0 and curID < 10000000 then
                    -- base vanilla attachment hai -> skin wala lagao
                    local target = pmap[curID]
                    if target and target ~= 0 and target ~= curID then
                        pcall(function()
                            local defRef = slua.IndexReference(slotData, "defineID")
                            defRef.TypeSpecificID = target
                            slotData.operationType = 0
                            AttachmentArray:Set(slotIdx, slotData)
                        end)
                        changed = true
                    end
                elseif curID and curID >= 10000000 then
                    -- already skinned (dusri skin ka) -> is skin wala dhoondo via Master maps base
                    pcall(function()
                        if _G._MasterAttachMaps and _G._MasterAttachMaps.attachToSkin then
                            local rIt = _G._MasterAttachMaps.attachToSkin[curID]
                            local baseId = rIt and rIt[2] or 0
                            if baseId and baseId ~= 0 then
                                local target2 = pmap[baseId]
                                if target2 and target2 ~= 0 and target2 ~= curID then
                                    local defRef2 = slua.IndexReference(slotData, "defineID")
                                    defRef2.TypeSpecificID = target2
                                    slotData.operationType = 0
                                    AttachmentArray:Set(slotIdx, slotData)
                                    changed = true
                                end
                            end
                        end
                    end)
                end
            end
        end
    end
    return changed
end

function F.applySkinToWeaponRef(CurWeapon)
    if not slua.isValid(CurWeapon) then return false end
    local AttachmentArray = CurWeapon.synData
    if not AttachmentArray or not slua.isValid(AttachmentArray) then return false end

    local skinSlot = GUN_MASTER_SYN_SLOT
    local foundSlot, foundTid = F.findSkinSlotInSynData(CurWeapon)
    local AttachmentData = AttachmentArray:Get(skinSlot)
    if not AttachmentData then
        if foundSlot and foundSlot ~= skinSlot then
            skinSlot = foundSlot
            AttachmentData = AttachmentArray:Get(skinSlot)
        end
    end
    if not AttachmentData then
        for _, s in ipairs({ 0, 1, 7 }) do
            local okA, att = pcall(function() return AttachmentArray:Get(s) end)
            if okA and att then
                skinSlot = s
                AttachmentData = att
                break
            end
        end
    elseif foundTid and foundTid >= 1000000 and foundSlot ~= skinSlot then
        local okA, att = pcall(function() return AttachmentArray:Get(foundSlot) end)
        if okA and att then
            skinSlot = foundSlot
            AttachmentData = att
        end
    end
    if not AttachmentData then return false end

    local current_gunid = 0
    pcall(function() current_gunid = slua.IndexReference(AttachmentData, "defineID").TypeSpecificID or 0 end)
    if not current_gunid or current_gunid <= 0 then return false end

    local MaxIt = 0
    pcall(function()
        if CurWeapon.GetWeaponID then MaxIt = CurWeapon:GetWeaponID() end
        if MaxIt <= 0 then MaxIt = CurWeapon:GetItemDefineID().TypeSpecificID end
    end)
    MaxIt = tonumber(MaxIt) or 0
    local tmp_id = F.get_skin_id(current_gunid, MaxIt)
    tmp_id = tonumber(tmp_id) or 0
    if tmp_id <= 0 or MaxIt <= 0 then return false end
    -- P23-FIX pickup lag: agar slot pehle se correct skin hai to mesh reload ZERO (sirf mismatch par kaam)
    -- _G.AddOutfitLastAppliedSkin dedup (per-weapon) - dobara pickup par storm nahi
    pcall(function()
        if _G.AddOutfitLastAppliedSkin and _G.AddOutfitLastAppliedSkin[MaxIt] == tmp_id and current_gunid == tmp_id then
            -- attachments bhi correct? quick check bina mesh touch kiye
            local needAtt = false
            pcall(function()
                local maps = _G._MasterAttachMaps
                if maps and maps.skinAttachments and maps.skinAttachments[tmp_id] then
                    -- check sirf, change nahi
                    local arr = AttachmentArray
                    local n = 0
                    pcall(function() n = arr:Num() end)
                    for s = 0, math.min(n-1, 6) do
                        if s ~= 7 then
                            local sd = arr:Get(s)
                            if sd then
                                local cid = 0
                                pcall(function() cid = slua.IndexReference(sd, "defineID").TypeSpecificID or 0 end)
                                cid = tonumber(cid) or 0
                                if cid > 0 and cid < 10000000 then
                                    -- vanilla base abhi bhi hai matlab skin nahi laga
                                    if _G.g_parts and _G.g_parts[tmp_id] and _G.g_parts[tmp_id][cid] then
                                        needAtt = true break
                                    end
                                end
                            end
                        end
                    end
                end
            end)
            if not needAtt then
                -- fully correct, kuch mat karo (lag fix, no new bug)
                tmp_id = -1 -- marker for early return below
            end
        end
    end)
    if tmp_id == -1 then return false end
    -- re-resolve after marker check
    tmp_id = F.get_skin_id(current_gunid, MaxIt)
    tmp_id = tonumber(tmp_id) or 0
    if tmp_id <= 0 then return false end
    local changedAny = false

    -- LOGIC 1: LẤY ID HÌNH ẢNH ĐANG HIỂN THỊ THỰC TẾ
    local wac = CurWeapon.WeaponAvatarComponent
    local currentVisualID = 0
    if slua.isValid(wac) then currentVisualID = wac.CachedLoadedID or 0 end

    -- NẾU SÚNG CHÍNH CHƯA PHẢI LÀ SKIN VIP -> THAY ĐỔI DATA
    if currentVisualID ~= tmp_id then
        changedAny = true
        pcall(function()
            local defRef = slua.IndexReference(AttachmentData, "defineID")
            defRef.TypeSpecificID = tmp_id
            local c0 = F.cfg(tmp_id)
            if c0 and c0.ItemType and defRef.Type ~= nil then defRef.Type = c0.ItemType end
            AttachmentData.operationType = 0
            AttachmentArray:Set(skinSlot, AttachmentData)
        end)
    end

    -- P23-AUTO ATTACHMENTS (Extra/Code.lua + old/6.lua method, NO hardcoded IDs)
    -- Master maps se skin ke dedicated attachments auto-resolve. BaseAttachToIndex/string-sub math REMOVED (glitch tha).
    -- Old parity: master slot 7 ko kabhi touch nahi, weapon mismatch par skip, delayed re-apply 0.4s.
    if _G.KuttaVaiConfig.SkinAttachment and tmp_id and tmp_id >= 1000000 then
        -- weapon mismatch guard (old/6.lua): galat gun par dusri gun ki skin kabhi mat lagao
        local _mismatch = false
        pcall(function()
            if F.isInjectedRes and F.isInjectedRes(tmp_id) then
                local _skinWid = F.weaponIdFromSkin and F.weaponIdFromSkin(tmp_id) or nil
                if not _skinWid and _G._MasterAttachMaps and _G._MasterAttachMaps.skinToBaseWeapon then
                    _skinWid = _G._MasterAttachMaps.skinToBaseWeapon[tmp_id]
                end
                if not _skinWid and F.resolveWeaponTypeID then _skinWid = F.resolveWeaponTypeID(tmp_id) end
                _skinWid = tonumber(_skinWid) or 0
                if _skinWid > 0 and F.resolveWeaponTypeID then
                    local _maxT = tonumber(F.resolveWeaponTypeID(MaxIt)) or MaxIt
                    local _skinT = tonumber(F.resolveWeaponTypeID(_skinWid)) or _skinWid
                    if _skinWid ~= MaxIt and _skinT ~= _maxT and _skinT ~= MaxIt and _skinWid ~= _maxT then _mismatch = true end
                end
            end
        end)
        if not _mismatch then
            -- P23-FIX old primary + master fallback (dono chalao, koi miss na ho)
            local function _applyBoth()
                local c1 = false
                pcall(function()
                    if _G.ApplyOldAttachments and _G.ApplyOldAttachments(AttachmentArray, tmp_id) then c1 = true end
                end)
                pcall(function()
                    if _G.ApplyMasterAttachmentSkins and _G.ApplyMasterAttachmentSkins(AttachmentArray, tmp_id) then c1 = true end
                end)
                return c1
            end
            -- already correct skin: sirf attachments refresh (no mesh flicker)
            if current_gunid == tmp_id and F.isInjectedRes and F.isInjectedRes(tmp_id) then
                pcall(function()
                    if _applyBoth() then changedAny = true end
                end)
            else
                pcall(function()
                    if _applyBoth() then changedAny = true end
                end)
                -- delayed re-apply: weapon default attachments load hone ke baad skin lagao (old fix)
                pcall(function()
                    local char0 = F.getLocalChar and F.getLocalChar() or nil
                    if char0 and char0.AddGameTimer then
                        char0:AddGameTimer(0.4, false, function()
                            if slua.isValid(CurWeapon) then
                                local aa = CurWeapon.synData
                                if aa and slua.isValid(aa) and _G.ApplyMasterAttachmentSkins then
                                    pcall(_G.ApplyMasterAttachmentSkins, aa, tmp_id)
                                end
                            end
                        end)
                    end
                end)
            end
            -- per-weapon dedup cache update yahi hoga (neeche LOGIC3 me), yaha sirf attachments
            -- P23-FIX lag: 0-6 full clear storm hataya (pickup par lag ka reason). Master maps already slot-wise set karta hai.
            pcall(function()
                if slua.isValid(wac) and changedAny then
                    -- sirf master slot clear (skin change par), attachments game khud reload karega
                    if current_gunid ~= tmp_id then
                        if wac.ClearMeshPathCacheBySlot then wac:ClearMeshPathCacheBySlot(0) end
                    end
                end
            end)
        end
    end

    -- LOGIC 3: LỆNH THẦN THÁNH ÉP GAME VẼ LẠI MESH NGAY TRÊN TAY
    if changedAny then
        pcall(function()
            if slua.isValid(wac) then
                -- Nếu là súng mới nhặt, xóa cái vỏ súng cũ kĩ đi
                if currentVisualID ~= tmp_id then
                    if wac.ClearMeshPathCacheBySlot then wac:ClearMeshPathCacheBySlot(0) end
                    if wac.ClearMeshBySlot then wac:ClearMeshBySlot(0, true, true) end
                end
                
                if CurWeapon.DelayHandleAvatarMeshChanged then
                    CurWeapon:DelayHandleAvatarMeshChanged()
                end
                if wac.ReloadAllEquippedAvatar then
                    wac:ReloadAllEquippedAvatar(1) 
                end
            end
        end)
        _G.AddOutfitLastAppliedSkin[MaxIt] = tmp_id
        return true
    end
    
    return false
end

function _G.equip_weapon_avatar(uCharacter)
    if not uCharacter or not slua.isValid(uCharacter) then return false end
    F.buildSkinMappings()
    local WeaponManager = uCharacter:GetWeaponManager()
    if not WeaponManager or not slua.isValid(WeaponManager) then return false end
    local uWeaponList = WeaponManager:GetAllInventoryWeaponList(false)
    if not uWeaponList or not slua.isValid(uWeaponList) then return false end

    local appliedAny = false
    for i = 0, uWeaponList:Num() - 1 do
        local CurWeapon = uWeaponList:Get(i)
        if slua.isValid(CurWeapon) and F.applySkinToWeaponRef(CurWeapon) then
            appliedAny = true
        end
    end
    return appliedAny
end

function F.equipWeaponAvatarSynData(char)
    return _G.equip_weapon_avatar(char)
end

F.applySkinToWeapon = F.applySkinToWeaponRef

function F.registerWeaponAvatarItems(char)
    local pc = char.GetPlayerControllerSafety and char:GetPlayerControllerSafety()
    if not slua.isValid(pc) then return false end
    local AU = import("AvatarUtils")
    local BU = import("BackpackUtils")
    local addedCount = 0

    for _, resID in ipairs(F.getDesiredWeaponSkins()) do
        local doneDirect = false
        pcall(function()
            if pc.AddWeaponAvatarItem then
                pc:AddWeaponAvatarItem(tonumber(resID))
                doneDirect = true
                addedCount = addedCount + 1
            end
        end)
        if not doneDirect then
            pcall(function()
                local skinBPID = BU.GetBPIDByResID(tonumber(resID))
                local arr = slua.Array(UEnums.EPropertyClass.Int)
                local parents = AU.GetWeaponAvatarParentIDList(skinBPID, arr, false)
                if parents and parents.Num and parents:Num() > 0 and pc.WeaponAvatarItemList then
                    for _, parentID in pairs(parents) do
                        pc.WeaponAvatarItemList:Add(parentID, skinBPID)
                    end
                    addedCount = addedCount + 1
                end
            end)
        end
    end

    if addedCount == 0 then return false end

    pcall(function() if pc.InitWeaponAvatarItems then pc:InitWeaponAvatarItems() end end)
    pcall(function() if pc.OnWeaponAvatarUpdate then pc:OnWeaponAvatarUpdate() end end)
    return true
end

function F.reloadCurrentWeaponAvatar(char)
    pcall(function()
        local weapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
        if not slua.isValid(weapon) then return end
        local wac = weapon.WeaponAvatarComponent
        if slua.isValid(wac) then
            local ES = import("EWeaponAttachmentSocketType")
            pcall(function() wac:ClearMeshPathCacheBySlot(ES.MasterGun) end)
            pcall(function() wac:ClearMeshBySlot(ES.MasterGun, true, true) end)
        end
        if weapon.DelayHandleAvatarMeshChanged then
            weapon:DelayHandleAvatarMeshChanged()
        elseif slua.isValid(wac) and wac.ReloadAllEquippedAvatar then
            local ESlotDescDiff = import("ESlotDescDiff")
            wac:ReloadAllEquippedAvatar(ESlotDescDiff.MeshDiff)
        end
    end)
end

local _weaponDiagDone = false
local _weaponApplied = false
local _lastWeaponResID = 0
local _weaponSpawnHooked = false

function F.onWeaponLuaInit(_, _, weapon)
    if not weapon or not slua.isValid(weapon) then return end
    local char = F.getLocalChar()
    if not char then return end
    local owner = nil
    pcall(function()
        if weapon.GetOwnerPawn then owner = weapon:GetOwnerPawn() end
    end)
    if not slua.isValid(owner) or owner ~= char then return end
    pcall(function()
        char:AddGameTimer(0.15, false, function()
            local c = F.getLocalChar()
            if c and slua.isValid(weapon) then
                F.applySkinToWeapon(weapon)
                pcall(F.applyGrenadeSkinToHeldWeapon, weapon)
                _weaponApplied = false
            end
        end)
    end)
end

function F.hookWeaponSpawn()
    if _weaponSpawnHooked then return end
    pcall(function()
        if EventSystem and EventSystem.registEvent and EVENTTYPE_PLAYEREVENT_WEAPON and EVENTID_PLAYEREVENT_WEAPON_LUA_INIT then
            EventSystem:registEvent(EVENTTYPE_PLAYEREVENT_WEAPON, EVENTID_PLAYEREVENT_WEAPON_LUA_INIT, F.onWeaponLuaInit)
            _weaponSpawnHooked = true
        end
    end)
end

function F.matchApplyWeaponSkin(char)
    if not F.skinFeat("SkinMatchWeapon") then return true end
    if not _avatarItemsRegistered then
        _avatarItemsRegistered = F.registerWeaponAvatarItems(char)
    end

    local curWeapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
    if not slua.isValid(curWeapon) then return false end

    local currentVisualID = 0
    pcall(function()
        local wac = curWeapon.WeaponAvatarComponent
        if slua.isValid(wac) then currentVisualID = wac.CachedLoadedID or 0 end
    end)

    local curWeaponResID = 0
    pcall(function() curWeaponResID = curWeapon:GetItemDefineID().TypeSpecificID end)
    local targetSkin = F.findTargetSkinForWeaponRes(curWeaponResID) or curWeaponResID

    local isVisualMatched = false
    if currentVisualID > 0 and currentVisualID == targetSkin then
        isVisualMatched = true
    end

    -- Smart watcher: chỉ apply khi synData lệch — tắt bằng SkinWeaponWatcher
    if F.skinFeat("SkinWeaponWatcher") and _G.SmartWeaponWatcherVer ~= 3 then
        pcall(function()
            local ticker = require("common.time_ticker")
            if not ticker or not ticker.AddTimerLoop then return end
            if _G.SmartWeaponWatcherId and ticker.RemoveTimer then
                pcall(function() ticker.RemoveTimer(_G.SmartWeaponWatcherId) end)
                _G.SmartWeaponWatcherId = nil
            end
            _G.SmartWeaponWatcherVer = 3
            _G.SmartWeaponWatcherActive = true
            _G.SmartWeaponWatcherId = ticker.AddTimerLoop(0, function()
                if not F.skinFeat("SkinWeaponWatcher") then return end
                if _G.AddOutfit and not _G.AddOutfit.isInRealMatch() then return end

                local pController = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                if not pController or not slua.isValid(pController) then return end
                local pChar = pController:GetPlayerCharacterSafety()
                if not pChar or not slua.isValid(pChar) then return end

                local WeaponManager = pChar:GetWeaponManager()
                if not WeaponManager or not slua.isValid(WeaponManager) then return end
                local uWeaponList = WeaponManager:GetAllInventoryWeaponList(false)
                if not uWeaponList or not slua.isValid(uWeaponList) then return end

                local count = uWeaponList:Num()
                for i = 0, count - 1 do
                    local wep = uWeaponList:Get(i)
                    if slua.isValid(wep) then
                        local synSkinID = F.getSynMasterSkinID(wep)
                        local baseID = 0
                        pcall(function() baseID = wep:GetItemDefineID().TypeSpecificID end)
                        local tSkin = F.findTargetSkinForWeaponRes(baseID) or baseID
                        if synSkinID ~= tSkin then
                            if _G.AddOutfit and _G.AddOutfit.applySkinToWeapon then
                                _G.AddOutfit.applySkinToWeapon(wep)
                            end
                        end
                    end
                end
            end, -1, 5.0)
        end)
    elseif not F.skinFeat("SkinWeaponWatcher") then
        pcall(function()
            local ticker = require("common.time_ticker")
            if _G.SmartWeaponWatcherId and ticker and ticker.RemoveTimer then
                ticker.RemoveTimer(_G.SmartWeaponWatcherId)
            end
            _G.SmartWeaponWatcherId = nil
            _G.SmartWeaponWatcherVer = nil
            _G.SmartWeaponWatcherActive = false
        end)
    end

    -- BÁO CÁO HOÀN THÀNH: Nếu súng cầm trên tay đã xong xuôi thì khóa luồng gốc của Engine
    if isVisualMatched and not _G.KuttaVaiConfig.SkinAttachment then
        _weaponApplied = true
        return true
    end

    F.buildSkinMappings()
    local okSyn = F.applySkinToWeapon(curWeapon)

    return okSyn
end

local _matchTimer = nil
local _matchWearDone = false

function F.startMatchWatcher(char)
    if _matchTimer or PERF.matchActive then return end
    if not F.skinFeat("SkinMatchWatcher") then
        -- Không chạy timer: đánh dấu wear done để MainLoop không spam full apply
        PERF.wearDoneThisMatch = true
        _G.KuttaCheatTG_WearDoneThisMatch = true
        return
    end
    PERF.matchActive = true
    local skipWear = PERF.wearDoneThisMatch
    _matchWearDone = skipWear or (not F.skinFeat("SkinMatchOutfit"))
    _avatarItemsRegistered = false
    _weaponDiagDone = false
    _weaponApplied = skipWear or (not F.skinFeat("SkinMatchWeapon"))
    _lastWeaponResID = 0
    local elapsed = 0

    _matchTimer = char:AddGameTimer(MATCH_TICK_SEC, true, function()
        elapsed = elapsed + MATCH_TICK_SEC
        local cur = F.getLocalChar()
        if not cur or not slua.isValid(cur) then return end
        if not F.skinFeat("SkinMatchWatcher") then
            if _matchTimer and cur.RemoveGameTimer then
                pcall(function() cur:RemoveGameTimer(_matchTimer) end)
            end
            _matchTimer = nil
            PERF.matchActive = false
            return
        end

        if not _matchWearDone and F.skinFeat("SkinMatchOutfit") then
            _matchWearDone = F.matchApplyAllSlots(cur)
        elseif not F.skinFeat("SkinMatchOutfit") then
            _matchWearDone = true
        end
        if not _matchWearDone and F.skinFeat("SkinMatchOutfit") then
            F.matchApplyHat(cur)
            if F.skinFeat("SkinMatchFace") then F.matchApplyFaceWear(cur) end
            F.matchApplyGloves(cur)
            pcall(function()
                local bagRes = F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes")
                local helmetRes = F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes")
                if (tonumber(bagRes) or 0) > 0 or (tonumber(helmetRes) or 0) > 0 then
                    F.matchApplyEquipmentSkin(cur, bagRes, helmetRes)
                end
            end)
        end
        if not _weaponApplied and F.skinFeat("SkinMatchWeapon") then
            F.matchApplyWeaponSkin(cur)
        elseif not F.skinFeat("SkinMatchWeapon") then
            _weaponApplied = true
        end
        pcall(F.matchApplyGrenadeSkin)
        -- Chỉ apply dù/cánh khi vừa nhảy (không mỗi 3s lúc đang bay)
        pcall(function() F.tryApplyAirborneOnEnter(cur) end)

        if (_matchWearDone and _weaponApplied) or elapsed >= MATCH_MAX_SEC then
            if _matchWearDone then
                PERF.wearDoneThisMatch = true
                _G.KuttaCheatTG_WearDoneThisMatch = true
            end
            if _matchTimer and cur.RemoveGameTimer then
                pcall(function() cur:RemoveGameTimer(_matchTimer) end)
            end
            _matchTimer = nil
            PERF.matchActive = false
        end
    end)
end

function F.stopMatchWatcher()
    if _matchTimer then
        pcall(function()
            local char = F.getLocalChar()
            if char and char.RemoveGameTimer then char:RemoveGameTimer(_matchTimer) end
        end)
        _matchTimer = nil
    end
    if PERF._airEdgeTicker and _ticker and _ticker.RemoveTimer then
        pcall(function() _ticker.RemoveTimer(PERF._airEdgeTicker) end)
        PERF._airEdgeTicker = nil
    end
    PERF.matchActive = false
    PERF.wearDoneThisMatch = false
    PERF._wasAirborne = false
    PERF._airDataSynced = false
    F._airApplied = nil
    _G.KuttaCheatTG_WearDoneThisMatch = false
    _matchWearDone = false
    _avatarItemsRegistered = false
    _weaponApplied = false
    _weaponDiagDone = false
    _lastWeaponResID = 0
    _G.GlovesWearStateCache = nil
end

function F.hookAirborneCache()
    if _G.AddOutfitAirborneHooked then return end
    _G.AddOutfitAirborneHooked = true
    pcall(function()
        if not EventSystem or not EventSystem.registEvent then return end
        if EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_ITEM_LIST then
            EventSystem:registEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST, function()
                F.syncAirborneCacheFromLobby()
            end)
        end
    end)
end

function F.hookPutOnRsp()
    pcall(function()
        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
        local o = wl.on_puton_rsp
        wl.on_puton_rsp = function(self, res, item, olditem, index, extra)
            o(self, res, item, olditem, index, extra)
            if not item or not item.instid then return end
            local resID = tonumber(item.res_id)
            local insID = tonumber(item.instid)
            if not resID or not insID then return end
            local c = F.cfg(resID)
            local st = F.subType(c)
            if st == OUTFIT_SUB then
                F.saveEquip(resID, insID)
            elseif st == HAT_SUB or FACE_SUBS[st] or BODY_SUBS[st] or HELMET_SUBS[st]
                or st == PARACHUTE_SUB or F.isGlideRes(resID) or st == GLOVES_SUB then
                F.saveEquip(resID, insID)
            elseif F.isParachuteRes(resID) or F.isGlideRes(resID) then
                F.saveEquip(resID, insID)
            elseif HEAD_SUBS[st] then
                F.saveEquip(resID, insID)
            elseif GUN_SUB[st] then
                local wid = F.weaponIdFromSkin(resID)
                if wid then F.cacheWeaponSkinFromIns(wid, insID) end
            elseif st == MELEE_ID then
                local wid = tonumber(F.weaponIdFromSkin(resID))
                F.cacheWeaponSkinFromIns((wid and wid > 0) and wid or MELEE_ID, insID)
            elseif GRENADE_SUB[st] then
                local base = F.grenadeBaseFromSkin(resID)
                if base then F.saveGrenadeToCache(base, resID, insID) end
            elseif F.isInjectedIns(insID) then
                F.saveEquip(resID, insID)
            end
        end
    end)
end

function F.hookLobbyWeaponCache()
    if _G.AddOutfitLobbyWeaponCacheHooked then return end
    _G.AddOutfitLobbyWeaponCacheHooked = true
    pcall(function()
        local Arm = require("client.logic.armory.logic_armory")
        local oRsp = Arm.install_weapon_skin_rsp
        Arm.install_weapon_skin_rsp = function(client_data, errorCode, weapon_id, instanceID)
            oRsp(client_data, errorCode, weapon_id, instanceID)
            if (errorCode == 0 or errorCode == NET_OK) and F.isWeaponSkinIns(instanceID) then
                F.cacheWeaponSkinFromIns(weapon_id, instanceID)
            end
        end
        local oH = Arm.HandleWeaponSkinChange
        Arm.HandleWeaponSkinChange = function(client_data, weapon_id, instanceID)
            oH(client_data, weapon_id, instanceID)
            if F.isWeaponSkinIns(instanceID) then
                F.cacheWeaponSkinFromIns(weapon_id, instanceID)
            end
        end
    end)
    pcall(function()
        local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
        local o = wgl.on_put_on_weapon_wear_rsp
        wgl.on_put_on_weapon_wear_rsp = function(self, client_data, res, weapon_id, new_skin_id, extra_weapon_list)
            o(self, client_data, res, weapon_id, new_skin_id, extra_weapon_list)
            if res == 0 or res == NET_OK then
                F.cacheWeaponSkinFromIns(weapon_id, new_skin_id)
            end
        end
    end)
    pcall(function()
        if not EventSystem or not EventSystem.registEvent then return end
        if EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
            EventSystem:registEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN, function(_, _, resOrFlag, weapon_id)
                weapon_id = tonumber(weapon_id)
                if weapon_id and weapon_id > 0 then
                    pcall(function()
                        local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
                        local insID = tonumber(wgl:GetSkinIdByWeaponID(weapon_id)) or 0
                        if insID > 0 then F.cacheWeaponSkinFromIns(weapon_id, insID) end
                    end)
                elseif tonumber(resOrFlag) and tonumber(resOrFlag) > 100000 then
                    pcall(function()
                        local wid = F.weaponIdFromSkin(resOrFlag)
                        if wid then
                            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                            local ins = wd.GetWardrobeInsIdByResId and wd:GetWardrobeInsIdByResId(resOrFlag)
                            if ins and ins > 0 then F.cacheWeaponSkinFromIns(wid, ins) end
                        end
                    end)
                end
            end)
        end
    end)
    pcall(function()
        local WRH = require("client.network.Protocol.WardRobeHandler")
        local oHeadReq = WRH.send_depot_set_head_show_req
        WRH.send_depot_set_head_show_req = function(insID)
            insID = tonumber(insID) or 0
            if insID > 0 and F.isInjectedIns(insID) then
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local d = wd:GetHallDepotItemDataByInsID(insID)
                if d and d.resID then
                    F.saveEquip(tonumber(d.resID), insID)
                end
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                fbd:SetHeadShow(insID)
                WRH.on_depot_set_head_show_rsp(NET_OK, insID)
                return
            end
            return oHeadReq(insID)
        end
        local oHead = WRH.on_depot_set_head_show_rsp
        WRH.on_depot_set_head_show_rsp = function(err_code, id)
            oHead(err_code, id)
            if err_code ~= 0 and err_code ~= NET_OK then return end
            id = tonumber(id) or 0
            if id <= 0 then return end
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d = wd:GetHallDepotItemDataByInsID(id)
            if d and d.resID then
                local st = tonumber(d.itemSubType or F.subType(F.cfg(d.resID)))
                if st == HAT_SUB or HELMET_SUBS[st] then
                    F.saveEquip(tonumber(d.resID), id)
                end
            end
        end
    end)
end

function F.hookWardrobePutOnReq()
    pcall(function()
        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
        if wl._AddOutfitPutOnReqHooked then return end
        wl._AddOutfitPutOnReqHooked = true
        local oReq = wl.wardrobe_puton_req
        wl.wardrobe_puton_req = function(self, insID, extra)
            insID = tonumber(insID)
            F.ensureDepotItemValid(insID)
            if F.tryLocalWearByIns(insID) then return end
            return oReq(self, insID, extra)
        end
        if not wl._AddOutfitPutOnDataHooked then
            wl._AddOutfitPutOnDataHooked = true
            local oData = wl.wardrobe_puton_data_req
            wl.wardrobe_puton_data_req = function(self, itemData)
                if itemData then
                    local insID = tonumber(itemData.ins_id or itemData.insID)
                    local resID = tonumber(itemData.res_id or itemData.resID)
                    F.clearItemExpire(itemData, insID, resID)
                    F.ensureDepotItemValid(insID, resID)
                end
                return oData(self, itemData)
            end
        end
    end)
end

local _bootstrapNotified = false

function F.bootstrapMatch(char)
    char = char or F.getLocalChar()
    if not char or not slua.isValid(char) then return false end
    if PERF.matchActive then return true end
    local now = os.clock()
    if (now - PERF.lastBootstrapAt) < BOOTSTRAP_COOLDOWN then return false end
    PERF.lastBootstrapAt = now
    F.syncWeaponCacheFromLobby(true)
    F.applyPersistSlotsToCache()
    F.cleanArmoryPollution()
    F.syncGlobalWearSkins()
    if F.skinFeat("SkinMatchAirborne") then
        -- Bootstrap: chỉ sync data; visual apply khi vừa nhảy (tránh hitch ngay đầu trận)
        pcall(function() F.syncAirborneToDataMgr() end)
        PERF._airDataSynced = true
        PERF._wasAirborne = F.isCharacterAirborne(char)
        if PERF._wasAirborne then
            pcall(function() F.applyAirborneSlots(char, true) end)
        end
    end
    if F.skinFeat("SkinMatchVehicle") then
        F.syncVehicleCacheFromDataMgr()
        F.syncVehicleSlotsToDataMgr()
        pcall(function() F.applyVehicleSkinsToPC(F.getPC()) end)
        F.startVehicleSkinTicker()
        pcall(function()
            local v = F.getMatchVehicle()
            if slua.isValid(v) then F.autoApplyVehicleSkinOnEnter(v) end
        end)
    end
    _weaponApplied = false
    _weaponDiagDone = false
    _matchApplied = false
    if not _bootstrapNotified then
        _bootstrapNotified = true
    end
    if F.skinFeat("SkinMatchWatcher") then
        F.startMatchWatcher(char)
    else
        PERF.wearDoneThisMatch = true
        _G.KuttaCheatTG_WearDoneThisMatch = true
    end
    -- Edge dù/cánh suốt trận (1Hz check, chỉ apply khi vừa nhảy)
    if F.skinFeat("SkinMatchAirborne") and not PERF._airEdgeTicker and _ticker and _ticker.AddTimerLoop then
        PERF._airEdgeTicker = _ticker.AddTimerLoop(1.0, function()
            if not F.skinFeat("SkinMatchAirborne") then return end
            if not F.isInRealMatch or not F.isInRealMatch() then return end
            local c = F.getLocalChar()
            if c then pcall(function() F.tryApplyAirborneOnEnter(c) end) end
        end, -1, 1.0)
    end
    return true
end

function F.hookMatchAvatar()
    pcall(function()
        local CAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.CharacterAvatarComponent")
        local o = CAC.OnAvatarAllMeshLoadedLua
        CAC.OnAvatarAllMeshLoadedLua = function(self)
            o(self)
            pcall(function()
                if self.IsLobbyActor and self:IsLobbyActor() then return end
                local isSelf = self.IsSelf and self:IsSelf()
                if not isSelf then return end
                if PERF.wearDoneThisMatch or PERF.matchActive then return end
                local char = F.getLocalChar()
                if char and char.AddGameTimer then
                    char:AddGameTimer(0.5, false, function() F.bootstrapMatch(char) end)
                end
            end)
        end
    end)
    pcall(function()
        local WAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.WeaponAvatarComponent")
        local oLoad = WAC.OnWeaponAvatarLoadedLua
        WAC.OnWeaponAvatarLoadedLua = function(self, slotID, definedID)
            oLoad(self, slotID, definedID)
            pcall(function()
                if self.IsLobbyActor and self:IsLobbyActor() then return end
                local isSelf = self.IsSelf and self:IsSelf()
                if not isSelf then return end
                local char = F.getLocalChar()
                if not char then return end
                _weaponApplied = false
                if not PERF.matchActive then F.bootstrapMatch(char)
                elseif char.AddGameTimer then
                    char:AddGameTimer(0.25, false, function()
                        local c = F.getLocalChar()
                        if c then F.matchApplyWeaponSkin(c) end
                    end)
                end
            end)
        end
    end)
end

function F.hookVehicleInfoInit()
