function F.hookVehicleSkinDataInit()
    pcall(function()
        if DataMgr._AddOutfitVehSkinDataHooked then return end
        DataMgr._AddOutfitVehSkinDataHooked = true
        local origInit = DataMgr.InitVehicleSkinData
        DataMgr.InitVehicleSkinData = function(data)
            data = F.mergeInjectedVehicleSkinTable(data)
            origInit(data)
            F.later(0.1, function()
                F.equipVehicleTypesFromConfig(PERSIST.configVehicleSlots)
            end)
        end
        local origUpd = DataMgr.UpdateVehicleSkin
        DataMgr.UpdateVehicleSkin = function(itemSubType, putOnId)
            origUpd(itemSubType, putOnId)
            putOnId = tonumber(putOnId) or 0
            if putOnId > 0 then
                DataMgr.vehicleSkinInsIDTable = DataMgr.vehicleSkinInsIDTable or {}
                if itemSubType then DataMgr.vehicleSkinInsIDTable[itemSubType] = putOnId end
                DataMgr.vst_skin = putOnId
            end
            if not _G.AddOutfitApplyingConfig and F.isInjectedIns(putOnId) then
                F.setLobbyVehicleManual(itemSubType, R.insToRes[putOnId], putOnId)
            end
        end
    end)
    pcall(function()
        local HT = require("client.logic.lobby.hall_theme_utils")
        if HT._AddOutfitLobbyVehHooked then return end
        HT._AddOutfitLobbyVehHooked = true
        local orig = HT.ProcPutOnVehicle
        HT.ProcPutOnVehicle = function(putOnItem, bShowVehicle)
            local ret = orig(putOnItem, bShowVehicle)
            if not _G.AddOutfitApplyingConfig and putOnItem then
                local ins = tonumber(putOnItem.instid)
                local res = tonumber(putOnItem.res_id)
                if ins and F.isInjectedIns(ins) then
                    res = res or R.insToRes[ins]
                    F.setLobbyVehicleManual(F.vehicleSubType(res), res, ins)
                    DataMgr.vst_skin = ins
                end
            end
            return ret
        end
        local oldGet = HT.GetThemeVehicleItemId
        if oldGet then
            HT.GetThemeVehicleItemId = function(...)
                local res = tonumber(oldGet(...)) or 0
                if res > 0 then
                    return F.resolveVehicleSkinForAvatar(res) or res
                end
                return F.resolveLobbyVehicleSkinRes() or res
            end
        end
        local oldGetSource = HT.GetThemeVehicleItemIdAndSource
        if oldGetSource then
            HT.GetThemeVehicleItemIdAndSource = function(...)
                local res, source = oldGetSource(...)
                res = tonumber(res) or 0
                if res > 0 then
                    return F.resolveVehicleSkinForAvatar(res) or res, source
                end
                return F.resolveLobbyVehicleSkinRes() or res, source
            end
        end
    end)
    pcall(function()
        local LV = require("client.lobby_ue_object.Actor.LobbyVehicle")
        local target = LV and (LV.__inner_impl or LV)
        if not target or target._AddOutfitLobbyVehAvatarHooked then return end
        target._AddOutfitLobbyVehAvatarHooked = true
        local oldPre = target.PreChangeVehicleAvatar
        if oldPre then
            target.PreChangeVehicleAvatar = function(self, InAvatarID, InAdvanceAvatarID)
                local desired = F.resolveVehicleSkinForAvatar(InAvatarID)
                return oldPre(self, desired or InAvatarID, InAdvanceAvatarID)
            end
        end
        local oldDefault = target.GetDefaultAvatarID
        if oldDefault then
            target.GetDefaultAvatarID = function(self, InAvatarID)
                local original = F.vehicleOriginalID(InAvatarID)
                if original and original > 0 then return original end
                return oldDefault(self, InAvatarID)
            end
        end
    end)
    pcall(function()
        local SV = require("client.slua.logic.lobby.Left.logic_social_bottom_vehicle")
        if not SV or SV._AddOutfitLobbyVehSocialHooked then return end
        SV._AddOutfitLobbyVehSocialHooked = true
        local oldUsing = SV.IsVehicleUsing
        if oldUsing then
            SV.IsVehicleUsing = function(ItemID, ...)
                ItemID = tonumber(ItemID)
                if ItemID and F.isInjectedRes(ItemID) then
                    local selected = F.resolveLobbyVehicleSkinRes()
                    if selected and selected == ItemID then return true end
                end
                return oldUsing(ItemID, ...)
            end
        end
        local oldSkinUsing = SV.IsSkinUsingByItemData
        if oldSkinUsing then
            SV.IsSkinUsingByItemData = function(itemSubType, ins_id, ...)
                ins_id = tonumber(ins_id)
                if F.isInjectedIns(ins_id) then
                    local selected = F.resolveLobbyVehicleSkinRes()
                    if selected and tonumber(R.insToRes[ins_id]) == selected then return true end
                end
                return oldSkinUsing(itemSubType, ins_id, ...)
            end
        end
    end)
end
function F.hookHallTheme()
    pcall(function()
        local HT = require("client.logic.lobby.hall_theme_utils")
        if HT._AddOutfitHallThemeHooked then return end
        HT._AddOutfitHallThemeHooked = true
        local orig = HT.ProcPutOnHallTheme
        HT.ProcPutOnHallTheme = function(putOnItem, putOffItem)
            orig(putOnItem, putOffItem)
            if not _G.AddOutfitApplyingTheme and putOnItem then
                local ins = tonumber(putOnItem.instid)
                local res = tonumber(putOnItem.res_id)
                if ins and F.isInjectedIns(ins) then
                    F.setHallThemeManual(res or R.insToRes[ins], ins)
                end
            end
        end
    end)
    -- P23-FIX Task3 (old/6.lua hookLobbyTheme): wardrobe click se injected theme lagao (glitch fix)
    pcall(function()
        local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
        if wl and not wl._p23_hooked_hall_theme then
            wl._p23_hooked_hall_theme = true
            local origPutOn = wl.wardrobe_puton_req
            if origPutOn then
                wl.wardrobe_puton_req = function(self, insID, extra)
                    insID = tonumber(insID)
                    if insID and F.isInjectedIns(insID) and F.isHallThemeRes(R.insToRes[insID]) then
                        F.putOnHallTheme(insID)
                        return
                    end
                    return origPutOn(self, insID, extra)
                end
            end
            -- P23-FIX bg/start-anim expired: koi bhi injected wardrobe_puton ko local success banao (This Exclusive item has expired fix)
            pcall(function()
                if wl and wl.wardrobe_puton_req and not wl._p23_genericPutonHooked then
                    wl._p23_genericPutonHooked = true
                    local oPut = wl.wardrobe_puton_req
                    wl.wardrobe_puton_req = function(self, insID, extra)
                        insID = tonumber(insID)
                        local isInj = false
                        pcall(function()
                            if F and F.isInjectedIns then isInj = F.isInjectedIns(insID) end
                        end)
                        if insID and isInj then
                            -- hall theme ko uske handler par bhejo, baaki ko generic putOn
                            local res = nil
                            pcall(function() if R and R.insToRes then res = R.insToRes[insID] end end)
                            res = tonumber(res) or 0
                            local handled = false
                            pcall(function()
                                if res > 0 and F.isHallThemeRes and F.isHallThemeRes(res) then
                                    if F.putOnHallTheme and F.putOnHallTheme(insID) then handled = true end
                                elseif res > 0 and F.isEmoteRes and F.isEmoteRes(res) then
                                    -- start/match animation (motion) ho to motion slot me lagao
                                    if F.localEquipMotion then
                                        -- pehla khaali motion slot dhoondo
                                        local dst = 1
                                        pcall(function()
                                            if DataMgr and DataMgr.MotionSlotList then
                                                for i, v in ipairs(DataMgr.MotionSlotList) do
                                                    if tonumber(v) == 0 then dst = i break end
                                                    dst = #DataMgr.MotionSlotList + 1
                                                end
                                            end
                                        end)
                                        if F.localEquipMotion(insID, dst) then handled = true end
                                    end
                                end
                            end)
                            if handled then return end
                            -- generic: depot valid + resource ensure + on_puton_rsp local
                            pcall(function() if F.ensureDepotItemValid then F.ensureDepotItemValid(insID, res) end end)
                            pcall(function()
                                if res > 0 and F.isResourcesReady and not F.isResourcesReady(res) and F.requestResourceDownload then
                                    F.requestResourceDownload(res)
                                end
                            end)
                            pcall(function()
                                local item = { res_id = res, count = 1, instid = insID }
                                -- background/start-anim aksar logic_wardrobe_new:on_puton_rsp se lagte hain
                                if self.on_puton_rsp then self:on_puton_rsp(NET_OK, item, nil, 1, insID, 0) end
                            end)
                            return
                        end
                        return oPut(self, insID, extra)
                    end
                end
            end)
            -- takeoff clear (old 2272-2281): theme utarne par bg glitch na ho
            if wl.take_off_item and not wl._p23_hooked_takeoff then
                wl._p23_hooked_takeoff = true
                local oOff = wl.take_off_item
                wl.take_off_item = function(self, ...)
                    local r = oOff(self, ...)
                    pcall(function()
                        local HT = require("client.logic.lobby.hall_theme_utils")
                        if HT then HT.homeThemeItemId = 0; if HT.SetThemeInstId then HT.SetThemeInstId(0) end end
                    end)
                    return r
                end
            end
        end
    end)
    -- delayed restore (old restorePersistedHallTheme 2.5s)
    pcall(function()
        local okT, tt = pcall(require, "common.time_ticker")
        if okT and tt and tt.AddTimerOnce then
            tt.AddTimerOnce(2.5, function() pcall(function() F.reapplyHallThemeFromConfig(true) end) end)
        end
    end)
end

-- ==============================================================================
-- P23-FIX Task4: Backpack skin icon (old/6.lua hookBackpackItemIcons verbatim, adapted to F.*)
-- Without glitch: backpack me SKIN icon dikhega, logic ke liye base ID rakhta hai.
-- ==============================================================================
function F.hookBackpackItemIcons()
    pcall(function()
        local WIIB = require("GameLua.Mod.BaseMod.Client.Backpack.WeaponInfoItemBase")
        local impl = WIIB and WIIB.__inner_impl
        if impl and impl.UpdateWeaponAppearanceInfo and not impl._p23_icon_hooked then
            impl._p23_icon_hooked = true
            local o_UWA = impl.UpdateWeaponAppearanceInfo
            impl.UpdateWeaponAppearanceInfo = function(self, TypeSpecificID, BattleData, DragOrigin)
                local skin_id = nil
                pcall(function()
                    if _G.get_skin_id then skin_id = _G.get_skin_id(TypeSpecificID, TypeSpecificID)
                    elseif F.get_skin_id then skin_id = F.get_skin_id(TypeSpecificID, TypeSpecificID) end
                end)
                if skin_id and skin_id ~= TypeSpecificID and F.isInjectedRes and F.isInjectedRes(skin_id) then
                    local ItemData = nil
                    pcall(function() ItemData = _ENV.CDataTable.GetTableData("Item", TypeSpecificID) end)
                    o_UWA(self, skin_id, BattleData, DragOrigin)
                    pcall(function()
                        self.TypeSpecificIDTemp = TypeSpecificID
                        self.ItemID = TypeSpecificID
                        if self.UIRoot then
                            self.UIRoot.ItemID = TypeSpecificID
                            if self.UIRoot.TextBlock_WeaponName and ItemData and ItemData.ItemName then
                                self.UIRoot.TextBlock_WeaponName:SetText(ItemData.ItemName)
                            end
                        end
                        if self.BindWeaponChangeEvent then self:BindWeaponChangeEvent() end
                        if self.UpdateBullet then self:UpdateBullet() end
                        if self.UpdateWeaponDurability then self:UpdateWeaponDurability() end
                        if self.UpdateWeaponAttachment then self:UpdateWeaponAttachment() end
                    end)
                    return
                end
                return o_UWA(self, TypeSpecificID, BattleData, DragOrigin)
            end
        end
    end)
    pcall(function()
        local BU = import("BackpackUtils")
        if BU and BU.GetEquipmentIconPathByResID and not BU._p23_icon_hooked then
            BU._p23_icon_hooked = true
            local o_Icon = BU.GetEquipmentIconPathByResID
            BU.GetEquipmentIconPathByResID = function(resID, ...)
                local skin = nil
                pcall(function()
                    local cch = F.cache()
                    if cch and cch.equip then
                        if tonumber(resID) and tonumber(resID) >= 501001 and tonumber(resID) <= 501999 and cch.equip.bag then
                            skin = cch.equip.bag
                        elseif tonumber(resID) and tonumber(resID) >= 502001 and tonumber(resID) <= 502999 and cch.equip.helmet then
                            skin = cch.equip.helmet
                        end
                    end
                end)
                if skin and skin > 0 then
                    local ok, p = pcall(o_Icon, skin, ...)
                    if ok and p and p ~= "" then return p end
                end
                return o_Icon(resID, ...)
            end
        end
    end)
end

