-- P23-FIX Task5: EliminationKing (619150001) + FinalKill (61950002), self-only (old/6.lua 7924-8201)
-- ==============================================================================
local P23_ELIM_KING = 619150001
local P23_FINAL_KILL = 61950002
local function p23_getLocalPlayerKey()
    local ok, GD = pcall(require, "GameLua.GameCore.Data.GameplayData")
    if ok and GD and GD.GetPlayerState then
        local ps = GD.GetPlayerState()
        if ps and slua.isValid(ps) and ps.PlayerKey then return tonumber(ps.PlayerKey) end
    end
    return nil
end
local function p23_getLocalUID()
    local uid
    pcall(function()
        local Sub = require("GameLua.GameCore.Module.Subsystem.SubsystemMgr")
        local Acc = Sub:Get("AccountSubsystem")
        if Acc and Acc.GetAccountUID then uid = Acc:GetAccountUID() end
    end)
    if not uid then
        pcall(function()
            local GD = require("GameLua.GameCore.Data.GameplayData")
            local ps = GD.GetPlayerState()
            if ps and slua.isValid(ps) and ps.UID then uid = tonumber(ps.UID) end
        end)
    end
    return uid
end
