                        end
                        if K.DeadKingEliminationInfo and tonumber(K.DeadKingEliminationInfo.KillerPlayerKey) == lk then
                            K.DeadKingEliminationInfo.EffectID = P23_ELIM_KING
                        end
                    end
                end)
            end
            return oS(self, DRD)
        end
    end)
    pcall(function()
        local KC = require("GameLua.Mod.BaseMod.Client.KillInfoTips.KingEliminationInfoItem")
        local impl = KC.__inner_impl
        if not impl or impl._p23_hooked_upd then return end
        impl._p23_hooked_upd = true
        local oU = impl.UpdateKingEliminationInfo
        impl.UpdateKingEliminationInfo = function(self, DRD, KEI)
            local lk = p23_getLocalPlayerKey()
            if lk and KEI then
                if KEI.NewKingEliminationInfo and tonumber(KEI.NewKingEliminationInfo.PlayerKey) == lk then
                    KEI.NewKingEliminationInfo.EffectID = P23_ELIM_KING
                end
                if KEI.DeadKingEliminationInfo and tonumber(KEI.DeadKingEliminationInfo.KillerPlayerKey) == lk then
                    KEI.DeadKingEliminationInfo.EffectID = P23_ELIM_KING
                end
            end
            return oU(self, DRD, KEI)
        end
    end)
    pcall(function()
        local PSB = require("GameLua.GameCore.Framework.PlayerStateBase")
        local impl = PSB.__inner_impl
        if not impl or impl._p23_hooked_team then return end
        impl._p23_hooked_team = true
        local oI = impl.InitTeamShowData
        impl.InitTeamShowData = function(self, ...)
            oI(self, ...)
            pcall(function()
                local lu = p23_getLocalUID()
                if lu and self.UID and tonumber(self.UID) == tonumber(lu) then
                    self.EliminationKingEffectID = P23_ELIM_KING
                end
            end)
        end
    end)
end
