function F.hookFinalKillEffect()
    if _G._p23_hooked_final_kill then return end
    _G._p23_hooked_final_kill = true
    pcall(function()
        local LS = require("GameLua.Mod.Library.GamePlay.Actor.FinalKillEffectLevelSequenceActor")
