                    local Cfg = _ENV.CDataTable.GetTableData("FinalKillEffectCfg", self.ItemId)
                    if not Cfg or not Cfg.Sequence or Cfg.Sequence == "" then
                        if self.Callback and self.Callback.OnPlay then self.Callback.OnPlay() end
