        local oT = Fe.TriggerParticleEffect
        if oT then
            Fe.TriggerParticleEffect = function(self, ItemId, Loc, Rot, Names)
                return oT(self, P23_FINAL_KILL, Loc, Rot, Names)
            end
        end
        local oP = Fe.PrepareItem
        if oP then
            Fe.PrepareItem = function(self, ItemId)
                return oP(self, P23_FINAL_KILL)
            end
        end
    end)
    local function triggerFinalKillEffect()
        pcall(function()
            local char = F.getLocalChar()
            if not char or not slua.isValid(char) then return end
            if _G._p23_fke_triggered then return end
            _G._p23_fke_triggered = true
            char:EnsureDynamicFeature("FinalKillEffect")
            if not char.FinalKillEffect then return end
            local Loc = char:K2_GetActorLocation()
            local Rot = FRotator(0, 0, 0)
            local Names = char.PlayerName or ""
            char.FinalKillEffect:TriggerParticleEffect(P23_FINAL_KILL, Loc, Rot, Names)
        end)
    end
    pcall(function()
        if BattleResult and BattleResult.on_game_result and not BattleResult._p23_hooked_fke then
            BattleResult._p23_hooked_fke = true
            local o = BattleResult.on_game_result
            BattleResult.on_game_result = function(br, res)
                triggerFinalKillEffect()
                return o(br, res)
            end
        end
    end)
    pcall(function()
        if BattleResult and BattleResult.on_game_over and not BattleResult._p23_hooked_over then
            BattleResult._p23_hooked_over = true
            local o = BattleResult.on_game_over
            BattleResult.on_game_over = function(gid)
                triggerFinalKillEffect()
                return o(gid)
            end
        end
    end)
    pcall(function()
        if EventSystem and EventSystem.registEvent and EVENTTYPE_STATE and EVENTID_GAMESTATE_ON_PRE_BATTLE_RESULT and not _G._p23_fke_evt then
            _G._p23_fke_evt = true
            EventSystem:registEvent(EVENTTYPE_STATE, EVENTID_GAMESTATE_ON_PRE_BATTLE_RESULT, triggerFinalKillEffect)
        end
    end)
end

-- ==============================================================================
-- P23-FIX Task6b: Projectile hook (old hookProjectileGrenadeAvatar) - inGame grenade skin+blast
-- NEW me ye missing tha isliye lobby me show hota tha, inGame nahi. orig pehle chalao (blast fix).
-- ==============================================================================
function F.hookProjectileGrenadeAvatar()
    pcall(function()
        local PB = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.ProjectileBase")
        local impl = PB and PB.__inner_impl
        if not impl or impl._p23_hooked_proj then return end
        if type(impl.UpdateGrenadeAvatar) ~= "function" then return end
        impl._p23_hooked_proj = true
        local origUpdate = impl.UpdateGrenadeAvatar
        local SUB = { [602001] = 614, [602002] = 613, [602003] = 615, [602004] = 612 }
        impl.UpdateGrenadeAvatar = function(self)
            pcall(origUpdate, self)
            pcall(function()
                local cch = F.cache()
                if not (cch and cch.grenadeSkins and slua.isValid(self.GrenadeAvatarComponent_BP)) then return end
                local itemID = nil
                if self.GetItemTypeID then itemID = tonumber(self:GetItemTypeID()) end
                if not itemID and self.ItemDefineID then itemID = tonumber(self.ItemDefineID.TypeSpecificID) end
                local sub = itemID and SUB[itemID]
                local sk = sub and cch.grenadeSkins[sub == 612 and 602004 or sub == 613 and 602002 or sub == 614 and 602001 or 602003]
                -- cch.grenadeSkins keys are base 60200x in NEW; fallback to sub-mapped throwObjects style
                if sk == nil and cch.throwObjects then
                    local info = cch.throwObjects[sub]
                    sk = info and (info.resID or info.res)
                end
                if type(sk) == "table" then sk = sk.resID or sk.res end
                sk = tonumber(sk) or 0
                if sk > 0 then
                    self.GrenadeAvatarComponent_BP:ChangeItemAvatar(sk, false)
                    pcall(function()
                        if self.CheckHasOverrideFxAndSound then
                            local uCtrl = self.GetInstigatorControllerSafety and self:GetInstigatorControllerSafety()
                            if slua.isValid(uCtrl) then self:CheckHasOverrideFxAndSound(uCtrl, sk) end
                        end
                    end)
                    -- NEW dead-code pipeline activate: custom explode FX
                    pcall(function() F.prepareGrenadeExplodeFx(self) end)
                    pcall(function()
                        local function _rst()
                            pcall(function()
                                if slua.isValid(self) and slua.isValid(self.GrenadeAvatarComponent_BP) then
                                    if self.ResetGrenadeAvatar then self:ResetGrenadeAvatar() end
                                    if self.OnGrenadeFxOverride then self:OnGrenadeFxOverride() end
                                end
                            end)
                        end
                        if self.AddGameTimer then self:AddGameTimer(0.2, false, _rst)
                        else local ch = F.getLocalChar(); if ch and ch.AddGameTimer then ch:AddGameTimer(0.2, false, _rst) else _rst() end end
                    end)
                end
            end)
            return
        end
    end)
end

-- ==============================================================================
-- P23-FIX Task7: Trail (GoldenLeaves 4531002) + GrenadeFX (FORCE_WEAPON 1101005098) + WeaponInspect
-- NO buttons - skin ke sath auto-apply. Trail: movement effect. GrenadeFX: blast force.
-- WeaponInspect: manual trigger par single PlayOnce (NO auto-play loop).
-- ==============================================================================
function F.hookP23TrailEffect()
    if _G._p23_trailHooked then return end
    _G._p23_trailHooked = true
    _G.GoldenLeavesTrail = _G.GoldenLeavesTrail or {}
    _G.GoldenLeavesTrail.Enabled = true
    _G.GoldenLeavesTrail.TRAIL_ITEM_ID = 4531002 -- 浮光金叶 (4531001 purple / 4541001 graffiti bhi supported)
    pcall(function()
        local PM = require("client.slua.logic.download.puffer.puffer_manager")
        local PC2 = require("client.slua.logic.download.puffer_const")
        if PM and PM.Download then PM.Download(PC2.ENUM_DownloadType.ODPAK, {4531001, 4531002, 4541001}) end
    end)
    local function isInMatch()
        local ok = false
        pcall(function()
            local GD = require("GameLua.GameCore.Data.GameplayData")
            if GD.IsInLobby then ok = (GD.IsInLobby() == false)
            elseif GD.IsInFightingStatus then ok = (GD.IsInFightingStatus() == true) end
            if not ok and GD.GetPlayerCharacter then
                local ch = GD.GetPlayerCharacter()
                ok = ch and slua.isValid(ch) or false
            end
        end)
        return ok
    end
    local function applyToComp(comp)
        if not comp or not slua.isValid(comp) then return false end
        local tid = _G.GoldenLeavesTrail.TRAIL_ITEM_ID or 4531002
        comp.MoveEffectItem = tid
        if comp.AdditionEffectMgr then comp.AdditionEffectMgr:SetMoveEffectItem(tid)
        elseif comp.OnRep_MoveEffectItem then comp:OnRep_MoveEffectItem(0) end
        return true
    end
    function _G.GoldenLeavesTrail.Apply()
        if not isInMatch() then return false end
        local ok, GD = pcall(require, "GameLua.GameCore.Data.GameplayData")
        local ch = ok and GD.GetPlayerCharacter and GD.GetPlayerCharacter()
        if ch and slua.isValid(ch) then
            local comp = nil
            pcall(function()
                local CAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.CharacterAvatarComponent")
                -- char se avatar comp nikalo
                if ch.GetAvatarComponent then comp = ch:GetAvatarComponent()
                elseif ch.CharacterAvatarComponent_BP and slua.isValid(ch.CharacterAvatarComponent_BP) then comp = ch.CharacterAvatarComponent_BP end
            end)
            if comp then return applyToComp(comp) end
        end
        return false
    end
    function _G.GoldenLeavesTrail.Stop()
        pcall(function()
            local ok, GD = pcall(require, "GameLua.GameCore.Data.GameplayData")
            local ch = ok and GD.GetPlayerCharacter and GD.GetPlayerCharacter()
            if ch and slua.isValid(ch) then
                local comp = ch.GetAvatarComponent and ch:GetAvatarComponent()
                if comp and slua.isValid(comp) then
                    comp.MoveEffectItem = 0
                    if comp.AdditionEffectMgr then comp.AdditionEffectMgr:SetMoveEffectItem(0) end
                end
            end
        end)
    end
    pcall(function()
        local CAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.CharacterAvatarComponent")
        if CAC and not CAC._p23_trailInit then
            CAC._p23_trailInit = true
            local o = CAC.InitDepotCommonPutOn
            if o then CAC.InitDepotCommonPutOn = function(self)
                o(self)
                if _G.GoldenLeavesTrail.Enabled and self.IsSelf and self:IsSelf() then
                    local tid = _G.GoldenLeavesTrail.TRAIL_ITEM_ID or 4531002
                    self.MoveEffectItem = tid
                    if self.AdditionEffectMgr then pcall(function() self.AdditionEffectMgr:SetMoveEffectItem(tid) end) end
                end
            end end
        end
        if CAC and not CAC._p23_trailMesh then
            CAC._p23_trailMesh = true
            local o2 = CAC.OnAvatarAllMeshLoadedLua
            if o2 then CAC.OnAvatarAllMeshLoadedLua = function(self)
                o2(self)
                pcall(function()
                    if self.IsLobbyActor and self:IsLobbyActor() then return end
                    if self.IsSelf and not self:IsSelf() then return end
                    if _G.GoldenLeavesTrail.Enabled then
                        local tid = _G.GoldenLeavesTrail.TRAIL_ITEM_ID or 4531002
                        self.MoveEffectItem = tid
                        if self.AdditionEffectMgr then self.AdditionEffectMgr:SetMoveEffectItem(tid) end
                    end
                end)
            end end
        end
        if CAC and not CAC._p23_trailValid then
            CAC._p23_trailValid = true
            local o3 = CAC.CheckItemValid
            if o3 then CAC.CheckItemValid = function(self, resID)
                local rid = tonumber(resID)
                if rid == 4531001 or rid == 4531002 or rid == 4541001 then return true end
                -- P23-FIX trail lobby expired: injected trail hamesha valid
                if F.isInjectedRes and F.isInjectedRes(rid) then
                    local c = F.cfg and F.cfg(rid)
                    -- trail/foot-effect subtype wale sab valid
                    return true
                end
                return o3(self, resID)
            end end
            -- P23-FIX: lobby me trail equip allow (PutOnCustomEquipmentByID bypass, old hookAvatarValid jaisa)
            if not CAC._p23_trailPuton then
                CAC._p23_trailPuton = true
                local origPutOn = CAC.PutOnCustomEquipmentByID
                if origPutOn then
                    CAC.PutOnCustomEquipmentByID = function(self, resID, CustomData)
                        if self.IsSelf and not self:IsSelf() then return origPutOn(self, resID, CustomData) end
                        resID = tonumber(resID)
                        if resID and (resID == 4531001 or resID == 4531002 or resID == 4541001) then
                            local ok, result = pcall(function()
                                local ItemDefineID = FItemDefineID(4, resID)
                                local EAvatarCustomType = import("EAvatarCustomType")
                                local AvatarCustom = FAvatarCustomDefault()
                                if CustomData then AvatarCustom = CustomData end
                                AvatarCustom.CustomType = EAvatarCustomType.AvatarCustomCharacter
                                return self:HandleEquipItem(ItemDefineID, AvatarCustom)
                            end)
                            if ok and result == true then return true end
                            if ok and result ~= false and result ~= nil then return result end
                        end
                        return origPutOn(self, resID, CustomData)
                    end
                end
            end
        end
        -- P23-FIX: trail items ko depot me inject + unexpire (lobby equip expired fix)
        pcall(function()
            if F and F.isInjectedRes and R and R.resToIns then
                for _, tid in ipairs({4531001, 4531002, 4541001}) do
                    if not R.resToIns[tid] then
                        -- depot inject ke liye mark: injectAll me auto aayega, yaha sirf download + valid
                        if F.requestResourceDownload then F.requestResourceDownload(tid) end
                        if F.ensureInjectedResources then F.ensureInjectedResources() end
                    end
                    -- expire sanitize: depot me ho to 0 karo
                    pcall(function()
                        local entity = F.getEntity and F.getEntity() or nil
                        if entity and entity._data then
                            for i = 1, (entity._DataCount or #entity._data) do
                                local d = entity._data[i]
                                if d then
                                    local res = tonumber(d.resID or d.res_id)
                                    if res == tid then d.expire_ts = 0 if d.expireTS ~= nil then d.expireTS = 0 end end
                                end
                            end
                        end
                    end)
                end
            end
        end)
    end)
    pcall(function()
        local ECPB = require("GameLua.Mod.Library.GamePlay.Avatar.Component.EffectProc.EffectContionProcessorBase")
        if ECPB and not ECPB._p23_trailFx then
            ECPB._p23_trailFx = true
            local o = ECPB.AdditionEffectCheck
            if o then ECPB.AdditionEffectCheck = function(self, character)
                if _G.GoldenLeavesTrail.Enabled then
                    local mgr = self.OwnerEffectMgr
                    local comp = mgr and mgr.GetOwnerAvatarComponent and mgr:GetOwnerAvatarComponent()
                    if comp and slua.isValid(comp) and comp.IsSelf and comp:IsSelf() then return true end
                end
                return o(self, character)
            end end
        end
    end)
end
function F.hookP23GrenadeFX()
    if _G._p23_grenadeFXHooked then return end
    _G._p23_grenadeFXHooked = true
    _G.GrenadeFX = _G.GrenadeFX or {}
    _G.GrenadeFX.FORCE_WEAPON_ID = 1101005098 -- max weapon blast (auto, no button)
    _G.GrenadeFX.BindMaxWeapon = _G.GrenadeFX.BindMaxWeapon or function(idx)
        idx = tonumber(idx) or _G.GrenadeFX.FORCE_WEAPON_ID
        _G.GrenadeFX.FORCE_WEAPON_ID = idx
        pcall(function()
            -- GrenadeKillGunBindMap se grenade skin nikalo + PC par set karo
            local ok, tbl = pcall(function() return _ENV.CDataTable.GetTable("GrenadeKillGunBindMap") end)
            if ok and tbl then
                for gid, cfg in pairs(tbl) do
                    if cfg and cfg.GunIDList_a and cfg.GunIDList_a.Num then
                        for i = 0, cfg.GunIDList_a:Num() - 1 do
                            if cfg.GunIDList_a:Get(i) == idx then
                                local fxGun = idx
                                if cfg.UnlockFxGunIDList_a and cfg.UnlockFxGunIDList_a.Num and cfg.UnlockFxGunIDList_a:Num() > 0 then
                                    fxGun = cfg.UnlockFxGunIDList_a:Get(0)
                                end
                                _G.GrenadeFX.FORCE_WEAPON_ID = fxGun
                                pcall(function()
                                    local GD = require("GameLua.GameCore.Data.GameplayData")
                                    local pc = GD.GetPlayerController()
                                    if slua.isValid(pc) and slua.isValid(pc.InitialConsumableAvatar) then
                                        pc.InitialConsumableAvatar.GrenadeAvatarShoulei = tonumber(gid) or pc.InitialConsumableAvatar.GrenadeAvatarShoulei
                                    end
                                    if pc.InitGrenadeAvatarList then pc:InitGrenadeAvatarList(true) end
                                end)
                                break
                            end
                        end
                    end
                end
            end
        end)
        -- override FX index force (TRAIL hookCheckHasOverrideFx logic, auto)
        pcall(function()
            local ok, mod = pcall(require, "GameLua.Mod.Library.GamePlay.Avatar.Component.GrenadeAvatarComponent")
            local impl = ok and mod and mod.__inner_impl
            if impl and type(impl.CheckHasOverrideFx) == "function" and not impl._p23_fxHooked then
                impl._p23_fxHooked = true
                local orig = impl.CheckHasOverrideFx
                -- class() forbid rawset on some builds -> assign via impl table (pcall)
                pcall(function() impl.CheckHasOverrideFx = function(comp, PC2, skinID)
                    local wid = tonumber(_G.GrenadeFX.FORCE_WEAPON_ID)
                    if wid and wid > 0 then
                        if comp.SetOverrideFxIndex then comp:SetOverrideFxIndex(wid) end
                        if comp.SetOverrideSoundIndex then comp:SetOverrideSoundIndex(wid) end
                        return
                    end
                    return orig(comp, PC2, skinID)
                end end)
            end
        end)
        return true
    end
    -- auto-bind at match (no UI): PC ready hone par call hoga matchApply se
end
function F.hookP23WeaponInspect()
    -- P23-FULL INSPECTION (Extra/Code.lua WeaponAnimationModule, NO IDs, fully auto)
    -- Old single-shot MANUAL-only REMOVED (full play nahi hota tha). Ab full LOOP + AUTO-START + WeaponCheckSkill fallback.
    -- Glitch-free: sirf standing/!vehicle/!dead par, sequence alive check, duration-0.3 par replay, TOTAL 60s.
    if _G._p23_inspectHooked and _G.WeaponAnimationModule then return end
    _G._p23_inspectHooked = true
    if not _G.WeaponAnimationModule then
        _G.WeaponAnimationModule = {}
        local WAM = _G.WeaponAnimationModule
        WAM.LOOP = true
        WAM.TOTAL_SEC = 60
        WAM.AUTO_START = true
        WAM.DEBUG = false
        local function IsWeaponAnimEnabled()
            local configValue = nil
            if _G.YDMH_Config and _G.YDMH_Config.Get then configValue = _G.YDMH_Config.Get("WEAPON_ANIM", nil) end
            if configValue ~= nil then return configValue == 1 end
            return WAM.AUTO_START
        end
        WAM._enabled = IsWeaponAnimEnabled()
        function WAM.SetEnabled(enabled)
            WAM._enabled = enabled == true
            WAM.AUTO_START = WAM._enabled
            if not WAM._enabled then WAM.Stop() else WAM.Start() end
            if _G.YDMH_Config and _G.YDMH_Config.Set then _G.YDMH_Config.Set("WEAPON_ANIM", WAM._enabled and 1 or 0) end
        end
        function WAM.IsEnabled() return WAM._enabled end
        WAM._running = false WAM._lastSeqActor = nil WAM._timer = nil WAM._currentChar = nil
        WAM._seqPath = nil WAM._actorPath = nil WAM._duration = 0 WAM._origLoc = nil WAM._origRot = nil
        local DEFAULT_ACTOR = "/Game/Mod/EvoBase/BluePrints/Actor/BP_CharacterLevelSequenceActor.BP_CharacterLevelSequenceActor_C"
        local function log(msg) if WAM.DEBUG then print("[WeaponAnim] " .. tostring(msg)) end end
        function WAM.GetCharacter()
            local ok, GameplayData = pcall(require, "GameLua.GameCore.Data.GameplayData")
            if not ok or not GameplayData then return nil end
            return GameplayData.GetPlayerCharacter()
        end
        function WAM.IsCharacterReady(char)
            if not char or not slua.isValid(char) then return false end
            local ok, EP = pcall(import, "EPawnState")
            if not ok then return false end
            local isStanding = (char.CurrentStates == (1 << EP.Stand))
            if isStanding and char.IsHandleInFold and char:IsHandleInFold() then isStanding = false end
            local inVehicle = char:HasState(EP.InVehicle) or char:HasState(EP.DriveVehicle)
            local isDead = char:HasState(EP.Save) or char:HasState(EP.Pick)
            return isStanding and not inVehicle and not isDead
        end
        function WAM.GetWeaponAvatarComponent(char)
            if not char or not slua.isValid(char) then return nil end
            local weapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
            if slua.isValid(weapon) and slua.isValid(weapon.WeaponAvatarComponent) then return weapon.WeaponAvatarComponent end
            return nil
        end
        local function softToString(softObj)
            local result = nil
            pcall(function()
                if not softObj then return end
                if softObj.ToSoftObjectPath then
                    local sp = softObj:ToSoftObjectPath()
                    if sp and sp.ToString then result = sp:ToString() end
                    if (not result) and sp and sp.GetAssetPathString then result = sp:GetAssetPathString() end
                end
                if (not result) and softObj.ToString then result = softObj:ToString() end
            end)
            return result
        end
        function WAM.ResolveAnimationConfig(char)
            local seqPath, actorPath, duration = nil, nil, 0
            pcall(function()
                local wac = WAM.GetWeaponAvatarComponent(char)
                if not wac then return end
                local ES = import("EWeaponAttachmentSocketType")
                local ET = import("ECharSpecialLevelSequenceType")
                local handle = wac:GetEquippedHandle(ES.MasterGun)
                if handle and slua.isValid(handle) and handle.WeaponSpecialLevelSequenceList then
                    for _, seq in pairs(handle.WeaponSpecialLevelSequenceList) do
                        if seq.LevelSequenceType == ET.ECharSpecLvSeq_WeaponCheck and seq.LevelSequenceConfig then
                            local cfg = seq.LevelSequenceConfig
                            seqPath = softToString(cfg.LevelSequence)
                            actorPath = softToString(cfg.SequenceActorTemplate)
                            duration = cfg.LevelSequenceDuration or 0
                            break
                        end
                    end
                end
                if not actorPath or actorPath == "" then
                    local AU = import("AvatarUtils")
                    local ES2 = import("EWeaponAttachmentSocketType")
                    local skinID = wac:GetEquippedItemDefineID(ES2.MasterGun).TypeSpecificID
                    if skinID <= 0 then
                        local weapon = char:GetCurrentWeapon()
                        if weapon then skinID = weapon:GetItemDefineID().TypeSpecificID end
                    end
                    local base = AU.GetWeaponAvatarParentID(AU.GetBPIDByResID(skinID), false)
                    local data = CDataTable.GetTableData("WeaponCheckSkill", base)
                    if data and data.SequenceActorPath and data.SequenceActorPath ~= "" then actorPath = data.SequenceActorPath end
                end
            end)
            if not actorPath or actorPath == "" then actorPath = DEFAULT_ACTOR end
            return seqPath, actorPath, duration
        end
        function WAM.PlayOnce(char)
            if not WAM._seqPath or WAM._seqPath == "" then log("No sequence path available") return false end
            local ok = false
            pcall(function()
                -- P23-FIX camera: hamesha CURRENT loc/rot use karo (stale orig se 3s baad FPP->TPP cut hota tha)
                WAM._origLoc = char:K2_GetActorLocation()
                WAM._origRot = char:K2_GetActorRotation()
                local UKismetMathLibrary = import("KismetMathLibrary")
                local transform = UKismetMathLibrary.MakeTransform(WAM._origLoc, WAM._origRot, FVector(1, 1, 1))
                local seqActor = Game:PlayLevelSequence(char, WAM._seqPath, transform, WAM._actorPath or DEFAULT_ACTOR, false, nil, char)
                if slua.isValid(seqActor) then
                    if seqActor.SetCharacterAndPlay then seqActor:SetCharacterAndPlay(char) end
                    char.CurrentLevelSequence = seqActor
                    WAM._lastSeqActor = seqActor
                    ok = true
                    log("Sequence played successfully")
                end
            end)
            return ok
        end
        function WAM.IsSequenceAlive() return WAM._lastSeqActor and slua.isValid(WAM._lastSeqActor) end
        function WAM.Stop()
            if WAM._timer and WAM._currentChar and slua.isValid(WAM._currentChar) then pcall(function() WAM._currentChar:RemoveGameTimer(WAM._timer) end) end
            WAM._running = false WAM._timer = nil WAM._lastSeqActor = nil
            log("Animation stopped")
        end
        function WAM.Start()
            if not WAM._enabled then log("Disabled by config") return false end
            if WAM._running then log("Already running") return false end
            local char = WAM.GetCharacter()
            if not char or not slua.isValid(char) then log("No valid character") return false end
            if not WAM.IsCharacterReady(char) then log("Character not ready") return false end
            WAM._seqPath, WAM._actorPath, WAM._duration = WAM.ResolveAnimationConfig(char)
            if not WAM._seqPath or WAM._seqPath == "" then log("No weapon check animation for current weapon") return false end
            if WAM._duration <= 0 then WAM._duration = 9 end
            WAM._running = true WAM._currentChar = char
            WAM._origLoc = char:K2_GetActorLocation()
            WAM._origRot = char:K2_GetActorRotation()
            local firstSuccess = WAM.PlayOnce(char)
            if not firstSuccess then WAM._running = false log("Failed to play initial sequence") return false end
            local elapsed = 0 local sinceReplay = 0 local started = false
            pcall(function()
                WAM._timer = char:AddGameTimer(0.2, true, function()
                    elapsed = elapsed + 0.2 sinceReplay = sinceReplay + 0.2
                    local cur = WAM.GetCharacter()
                    if not cur or not slua.isValid(cur) then WAM.Stop() return end
                    if not WAM.IsCharacterReady(cur) then log("Character state changed, stopping") WAM.Stop() return end
                    if WAM.IsSequenceAlive() then started = true end
                    if WAM.LOOP then
                        -- P23-FIX camera: sirf dead hone par replay (duration timeout par force restart se camera cut hota tha)
                        if (not WAM.IsSequenceAlive()) then
                            sinceReplay = 0
                            if WAM._enabled then WAM.PlayOnce(cur) else WAM.Stop() end
                        end
                        if elapsed >= WAM.TOTAL_SEC then log("Total time elapsed, stopping") WAM.Stop() end
                    else
                        if (started and not WAM.IsSequenceAlive()) or elapsed >= (WAM._duration + 1) then log("Sequence completed, stopping") WAM.Stop() end
                    end
                end)
            end)
            log("Animation started, duration=" .. tostring(WAM._duration) .. "s, loop=" .. tostring(WAM.LOOP))
            return true
        end
        function WAM.Restart() WAM.Stop() return WAM.Start() end
        function WAM.BindToWeaponSwitch()
            if not WAM._originalOnWeaponChanged and _G.WeaponEvents and _G.WeaponEvents.onWeaponChanged then
                WAM._originalOnWeaponChanged = _G.WeaponEvents.onWeaponChanged
                _G.WeaponEvents.onWeaponChanged = function(weaponId)
                    if WAM._originalOnWeaponChanged then WAM._originalOnWeaponChanged(weaponId) end
                    if WAM._enabled then pcall(function() WAM.Restart() end) end
                end
                log("Bound to weapon switch event")
            end
        end
        function WAM.AutoStartLoop()
            if not WAM._enabled then return end
            local timeTicker = nil
            pcall(function() timeTicker = require("common.time_ticker") end)
            if timeTicker and timeTicker.AddTimerOnce then
                local function wamTick()
                    pcall(function()
                        if not WAM._running and WAM._enabled then
                            local char = WAM.GetCharacter()
                            if char and slua.isValid(char) and WAM.IsCharacterReady(char) then
                                local seqPath, _, _ = WAM.ResolveAnimationConfig(char)
                                if seqPath and seqPath ~= "" then WAM.Start() end
                            end
                        end
                    end)
                    timeTicker.AddTimerOnce(3.0, wamTick)
                end
                timeTicker.AddTimerOnce(3.0, wamTick)
            elseif _G.Mytimer_ticker then
                _G.Mytimer_ticker.AddTimerLoop(3, function()
                    pcall(function()
                        if not WAM._running and WAM._enabled then
                            local char = WAM.GetCharacter()
                            if char and slua.isValid(char) and WAM.IsCharacterReady(char) then
                                local seqPath, _, _ = WAM.ResolveAnimationConfig(char)
                                if seqPath and seqPath ~= "" then WAM.Start() end
                            end
                        end
                    end)
                end, -1, 1)
            end
            pcall(function() WAM.Start() end)
        end
        _G.StartWeaponAnimation = WAM.Start
        _G.StopWeaponAnimation = WAM.Stop
        _G.RestartWeaponAnimation = WAM.Restart
        _G.SetWeaponAnimation = WAM.SetEnabled
        -- compat for old single-shot callers: full play once via module
        _G.PlayWeaponInspectOnce = function() return WAM.Restart() end
        _G._p23_inspectEnabled = true
        WAM.BindToWeaponSwitch()
        WAM.AutoStartLoop()
        log("Weapon Animation Module loaded, enabled=" .. tostring(WAM._enabled))
    else
        -- already loaded (e.g., Extra/Code.lua): just ensure auto-start + switch bind
        pcall(function() _G.WeaponAnimationModule.BindToWeaponSwitch() end)
        pcall(function() _G.WeaponAnimationModule.AutoStartLoop() end)
    end
    -- patch InitializeSkinModSystem to also install new hooks (Code.lua parity, no glitch)
    pcall(function()
        if not _G._p23_initSkinPatched then
            _G._p23_initSkinPatched = true
            local _origInit = _G.InitializeSkinModSystem
            _G.InitializeSkinModSystem = function()
                if _origInit then _origInit() end
                pcall(function() if _G.BuildMasterAttachmentMaps then _G.BuildMasterAttachmentMaps() end end)
            end
        end
    end)
end

function F.hookEnterGame()
    if _G.AddOutfitEnterGameHooked then return end
    _G.AddOutfitEnterGameHooked = true
    pcall(function()
        if EventSystem and EventSystem.registEvent and EVENTTYPE_LOBBY and EVENTID_ENTER_GAME_BEGIN then
            EventSystem:registEvent(EVENTTYPE_LOBBY, EVENTID_ENTER_GAME_BEGIN, function()
                F.perfInvalidateLobby()
                F.applyLocalMotionSlots()
                F.invalidateInGameEmoteCache()
                F.syncWeaponCacheFromLobby(true)
                F.reapplyVehicleSlotsFromConfig(true)
                F.reapplyHallThemeFromConfig(true)
                pcall(F.applyVehicleSkinsToPC)
                if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModPet then
                    pcall(F.injectAllPets)
                    pcall(F.applyPersistedPet)
                end
                pcall(F.hookGrenadeAvatarLookup)
                pcall(F.matchApplyGrenadeSkin)
                pcall(function()
                    local ok, ticker = pcall(require, "common.time_ticker")
                    if ok and ticker and ticker.AddTimerOnce then
                        for _, d in ipairs({0.5, 1.5, 3.0, 6.0}) do
                            ticker.AddTimerOnce(d, function()
                                pcall(F.matchApplyGrenadeSkin)
                            end)
                        end
                    end
                end)
                F.stopMatchWatcher()
                _bootstrapNotified = false
            end)
        end
    end)
end

function F.afterInjectApply(firstTime)
    F.mergeInjectedArmorySkins()
    F.cleanArmoryPollution()
    if firstTime then
        F.refreshWardrobeOnce()
        F.persistApplyLoaded()
        F.syncLobbyVehicleResFromIns()
        F.reapplyVehicleSlotsFromConfig(true)
        F.reapplyHallThemeFromConfig(true)
        F.reapplyWeaponsFromConfig()
        F.scheduleLobbyReapplyOnce()
    else
        F.reapplyWeaponsFromConfig()
    end
    pcall(F.applyPersistedMotionSlots)
    if _G.KuttaVaiConfig and _G.KuttaVaiConfig.ModPet then
        pcall(F.injectAllPets)
        _G.AddOutfitPetsInjected = true
        pcall(F.applyPersistedPet)
    end
end

function F.start()
