    local function GetOptimizedEmoteList(baseList, useEquipped)
        local baseCount = baseList and #baseList or 0
        local isEmoteModEnabled = _G.KuttaVaiConfig.ModEmote == true
        useEquipped = useEquipped == true

        if CachedInGameEmotes and not _G.__EMOTE_INGAME_CACHE_DIRTY
