            and LastEmoteSwitchState == isEmoteModEnabled
            and LastUseEquipped == useEquipped then
            return CachedInGameEmotes
        end

        local compact = {}
        local seen = {}

        if baseList then
            for _, data in pairs(baseList) do
                if data and data.DefineID and data.DefineID.TypeSpecificID then
                    local id = data.DefineID.TypeSpecificID
                    if not seen[id] then
