            end
        end)
        return m
    end
    local function wrap(tbl, name, fn)
        if not tbl or type(tbl[name]) ~= "function" then return end
        local k = "__rx_" .. name
        if tbl[k] then return end
        tbl[k] = tbl[name]
        tbl[name] = fn(tbl[k])
    end
    local function save(key, val)
        if val == nil then return end
        E[key] = val
        pcall(function() if F and F.persistProfileCustomSave then F.persistProfileCustomSave() end end)
