                    if tonumber(s) == SUB then
                        local n = tonumber(id)
                        if n then DataMgr.roleData.nameFrameData[n] = { is_used = 0, expire_ts = 0 } end
                    end
                end
            end)
        end
        local function applyBrand()
            if not E.brand then return end
            local id = tonumber(E.brand)
            if not id or id <= 0 then return end
            pcall(function()
                unlockAll()
                DataMgr.roleData.nameFrameData = DataMgr.roleData.nameFrameData or {}
                DataMgr.roleData.nameFrameData[id] = { is_used = 0, expire_ts = 0 }
                if DataMgr.UseNameFrame then DataMgr.UseNameFrame(id) end
                for k, v in pairs(DataMgr.roleData.nameFrameData) do
                    if type(v) == "table" then
                        v.is_used = (tonumber(k) == id) and 1 or 0
                    end
                end
                local RNS = require("client.slua.logic.person_space.logic_roleinfo_nameframe")
                if RNS then RNS.nUsedID = id end
                local TU = require("client.slua.logic.teamup.logic_team_up")
                if TU and TU.GetMemberInfo then
                    local mi = TU.GetMemberInfo(DataMgr.roleData.uid)
                    if mi then mi.brand_id = id end
                end
                if EventSystem and EVENTTYPE_ROLEINFO and EVENTID_ROLEINFO_USE_NAME_FRAME then
                    EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_USE_NAME_FRAME, id)
                end
            end)
        end
        pcall(unlockAll)
        pcall(applyBrand)

        local RNS = require("client.slua.logic.person_space.logic_roleinfo_nameframe")
        wrap(RNS, "IsValidNameFrame", function(old) return function() return true end end)
        wrap(RNS, "use_brand", function(orig)
            return function(id)
                id = tonumber(id)
                if id and id > 0 then
                    save("brand", id)
                    pcall(unlockAll)
                    pcall(applyBrand)
                    return
                end
                if orig then return orig(id) end
            end
        end)
        wrap(RNS, "use_brand_rsp", function(orig)
            return function(res, id)
                id = tonumber(id)
                if id and id > 0 then
                    pcall(unlockAll)
                    if DataMgr and DataMgr.roleData then
                        DataMgr.roleData.nameFrameData = DataMgr.roleData.nameFrameData or {}
                        DataMgr.roleData.nameFrameData[id] = { is_used = 0, expire_ts = 0 }
                    end
                    if res ~= 0 then res = 0 end
                    save("brand", id)
                end
                return orig(res, id)
            end
        end)

        -- DataMgr deep
        wrap(DataMgr, "GetNameFrame", function(orig)
            return function(id)
                local r = orig(id)
                if r then return r end
                if DataMgr.roleData then
                    DataMgr.roleData.nameFrameData = DataMgr.roleData.nameFrameData or {}
                    if not DataMgr.roleData.nameFrameData[id] then
                        DataMgr.roleData.nameFrameData[id] = { is_used = 0, expire_ts = 0 }
                    end
                    return DataMgr.roleData.nameFrameData[id]
                end
            end
        end)
        wrap(DataMgr, "InitRoleData", function(orig)
            return function(roleDataTb)
                if E.brand and roleDataTb then
                    local id = tonumber(E.brand)
                    if id and id > 0 then
                        roleDataTb.brand = roleDataTb.brand or {}
                        for k, v in pairs(roleDataTb.brand) do
                            if type(v) == "table" then v.is_used = 0 end
                        end
                        roleDataTb.brand[id] = { is_used = 1, expire_ts = 0 }
                    end
                end
                local r = orig(roleDataTb)
                pcall(unlockAll)
                pcall(applyBrand)
                return r
            end
        end)
        wrap(DataMgr, "UpdateMyRoleProfileData", function(orig)
            return function(data, ...)
                pcall(function()
                    if data and E.brand and tonumber(E.brand) > 0 then
                        data.brand_id = E.brand
                    end
                end)
                local r = orig(data, ...)
                pcall(applyBrand)
                return r
            end
        end)
    end)

    -- ────────────────────────────────────────────────────────────────────────
    -- 5. PROFILE PAYLOAD PATCH (batch rsp)
    -- ────────────────────────────────────────────────────────────────────────
    pcall(function()
        local function patch(data)
            if not data or type(data) ~= "table" then return data end
            if E.avatarBox then data.cur_avatar_box_id = tonumber(E.avatarBox) end
            if E.nickname  then data.friend_nickname_skin = E.nickname end
            if E.chat      then data.chat_bubble = E.chat end
            if E.teamSkin  then data.cur_team_notify_skin_id = E.teamSkin end
            if E.brand and tonumber(E.brand) > 0 then data.brand_id = E.brand end
            if E.alias and tonumber(E.alias) > 0 then
                data.alias = data.alias or {}
                data.alias.id = tonumber(E.alias)
                data.alias_id = tonumber(E.alias)
                if DataMgr and DataMgr.roleData and DataMgr.roleData.alias then
                    data.alias.title = DataMgr.roleData.alias.title
                    data.alias_title = DataMgr.roleData.alias.title
                end
            end
            if E.roleInfoBg and tonumber(E.roleInfoBg) > 0 then
                data.social_card = data.social_card or {}
                data.social_card.social_info_bg = data.social_card.social_info_bg or {}
                pcall(function()
                    if ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.RoleInfoBG then
                        data.social_card.social_info_bg[ENUM_ITEM_SUBTYPE.RoleInfoBG] = tonumber(E.roleInfoBg)
                    end
                end)
            end
            return data
        end

        local logic_profile = getMod("logic_profile")
        if logic_profile then
            wrap(logic_profile, "proc_batch_get_bin_profile_rsp", function(orig)
                return function(self, seq, list, hasRank)
                    if DataMgr and DataMgr.roleData and DataMgr.roleData.uid then
                        local my = tostring(DataMgr.roleData.uid)
                        for k, v in pairs(list or {}) do
                            if tostring(k) == my and type(v) == "table" then
                                patch(v)
                            end
                        end
                    end
                    return orig(self, seq, list, hasRank)
                end
            end)
        end

        wrap(DataMgr, "UpdateMyRoleProfileData", function(orig)
            return function(data, ...)
                patch(data)
                return orig(data, ...)
            end
        end)
    end)

    pcall(function()
        print("[ROXZ_ADDON] 5 missing features installed: TeamSkin, Opening, SocialCardBG, Brand, PayloadPatch")
    end)
end
